-- Narrador Co-op: datos del generador de vidas. ARCHIVO GENERADO por herramientas/vidas.py desde
-- personajes/secundarios/datos/*.json: no editarlo a mano. Lo usa server/Narrador/NarradorVidas.lua.
-- Textos sin tildes a proposito.

Narrador = Narrador or {}
Narrador.VidasDatos = {}
local D = Narrador.VidasDatos

-- Los vecinos hechos a mano: id, nombre, sexo, edad (julio de 1993), pueblo, oficio, lazos y textos.
D.SECUNDARIOS = {
    { id = "s001", nombre = "Eugene", apellido = "Patrick", apodo = "Gene", sexo = "h", edad = 18, pueblo = "Muldraugh", oficio = "mecanico", vive = true, lazos = {"cabo", "pereira", "valentina"}, textos = { llegada = "A ver, a ver. Si viene por un motor, pase. Si viene por mi, pase tambien, pero despacio.", rescate = "Llego rapido, senor. Yo me hago el muerto debajo de los autos, pero esta vez no alcanzaba.", gracias = "Justo lo que faltaba. Facil. Le debo una, y yo las anoto todas.", revelacion1 = "Eugene Patrick, mecanico del Kinnard's Garage, en la 31W. En Muldraugh me dicen el nino del cancer. Lo tuve a los doce. Ahora arreglo frenos acostado.", revelacion2 = "En el Kosair leia manuales Chilton entre quimio y quimio. Misty me ganaba al Uno con trampa y se murio. En el taller atendia la camioneta de Amos Pruitt, el vecino del Cabo.", revelacion3 = "Los sabados le arreglo las camionetas a los del patio de trenes. Cuatro latas y medio bidon. Se lo que hacen con ellas. Las dejo andando igual, porque Tara come.", diario_conocer = "Conoci a Eugene Patrick en un taller de la 31W. Flaco, manos frias, chistes de hospital. Dice que ya se murio una vez de prueba.", diario_final = "Eugene le arregla las camionetas a la banda del patio de trenes para darle de comer a su hermana. No se si eso lo hace traidor o hermano.", mudanza = "Me vine a la comisaria con Tara y Darcy. El Cabo me dio un rincon del patio para arreglar lo que llegue, y cuando le ofreci pagar la comida me dijo negativo. Duermo en el garaje de atras con la cortina abajo, como en el taller. La profesora Mandados le hace clases a Tara en la sala de interrogatorios, y Tara ya no me odia tanto. A Brisco le deje dicho que no vuelva. Si vuelve, le voy a tener que contar al Cabo. Lo bueno de aqui es que nadie me dice valiente. Me dicen Patrick, como si fuera soldado. Me gusta.", muerte = "Eugene Patrick murio debajo de un auto, como vivio. Le prometi a Tara terminar el Chevelle. Se llama Misty." } },
    { id = "s002", nombre = "Winnie", apellido = "Caldwell", apodo = "Miss Winnie", sexo = "m", edad = 55, pueblo = "West Point", oficio = "costurera", vive = true, lazos = {"chela"}, textos = { llegada = "Pico alguien. Suba despacio, corazon, que la escalera es de estanque y yo ya no la sujeto.", rescate = "Bueno, bueno. Me saco del agua como a un bagre. Asi es el rio: hoy usted, otro dia yo.", gracias = "Hilo de nylon del bueno. Con esto remiendo media orilla. Gracias, corazon. No se lo repito.", revelacion1 = "Winnie Caldwell. Tuve la tienda de carnada del camino del rio del 62 al 91. El hilo de pescar se lo compraba a la Chela, cuando era cajera de la Haskins. Ahora remiendo redes.", revelacion2 = "Dieciocho veranos quise a un piloto de remolcador, Harlis. Mi marido lo supo siempre. Lo ultimo que me dijo fue: que Harlis te pague las lombrices.", revelacion3 = "La segunda semana paso el remolcador de Harlis y se llevo a la Verlinda y a los ninos rio abajo. Habia lugar para mi. Harlis me estiro la mano y le dije que no. No quise deberle eso.", diario_conocer = "Winnie Caldwell vive arriba de una tienda de carnada cerrada, con la escalera adentro. Huele a bagre y a nylon. Me dijo corazon como insulto.", diario_final = "Winnie tenia lugar en el remolcador que se llevo a su hija y no subio, para no deberle nada a Harlis. Dice que no saber es lo peor que tiene.", mudanza = "Me vine al cuartel porque la espalda ya no me dejaba subir la escalera. La Chela me dio una banca, una mesa y trabajo antes de saludarme. Coso lonas para juntar agua de lluvia y les pongo parches a las mangueras, que no es lo mio pero sale. Los domingos bajo al rio con un muchacho del cuartel y ponemos espineles. Nadie me pregunta por Harlis. A la Chela le conte lo del remolcador una noche, lavando ollas. No me dijo nada. Me paso un trapo seco y siguio lavando al lado mio. Eso fue todo, y fue harto.", muerte = "A Winnie Caldwell se la llevo el rio que conocia. Deje sus espineles puestos. Alguien tiene que sacar el bagre." } },
    { id = "s003", nombre = "Ike", apellido = "Justice", apodo = "Ike", sexo = "h", edad = 30, pueblo = "Riverside", oficio = "electricista", vive = true, lazos = {"nacho"}, textos = { llegada = "Si, senor. Ike Justice. Le cuento derecho: aqui no hay nada que valga la pena robar, salvo la radio.", rescate = "Esta bien. Ya esta bien. Gracias. Le debo una, y yo las deudas las pago completas.", gracias = "Fusibles y cable del bueno. Con esto la senora Nola tiene radio una semana. Gracias, senor.", revelacion1 = "Ike Justice, electricista de Riverside, sin licencia. Aprendi en la carcel de Burgin. Al salir, el unico que me dio trabajo fue el Padre: la casa parroquial, en el 91.", revelacion2 = "En junio del 85 maneje borracho y mate a Corky Mullins, mi mejor amigo. Estuve cinco inviernos preso. Su mama no me hablo hasta la primera noche. Ahi me dijo Isaac.", revelacion3 = "En la misma curva donde murio Corky encontre una caja de Falls City. Me tomo una cada domingo detras del galpon. Quedan cuatro. La senora Nola dice que Isaac no toma.", diario_conocer = "Ike Justice prueba tres veces cada cable con un buscapolo. Habla poco y derecho. Tiene un tatuaje de carcel: C.M. y una fecha.", diario_final = "Ike se toma una cerveza cada domingo en la curva de su muerto, y la madre del muerto cree que esta sobrio. Le guarde el secreto. No se si hice bien.", mudanza = "Nos vinimos los tres a la iglesia: mi mama, la senora Nola y yo. El Padre no pregunto nada, como en el 91. Me dio un encargo antes de que dejara la mochila: la luz de la sacristia. Ahora hay una ampolleta que prende dos horas en la noche con baterias de auto, y la misa sigue a las once, con luz o sin luz. La senora Nola se sienta al fondo y me guarda el lugar. Antes de entrar le di al Padre las latas de Falls City que quedaban. Las anoto en el libro y no dijo nada mas. Le cuento derecho: dormi bien.", muerte = "Ike Justice murio en un cuarto oscuro, entrando primero, como siempre. Le lleve su buscapolo a la senora Nola. Ella dijo Isaac." } },
    { id = "s004", nombre = "Bernice", apellido = "Marchetti", apodo = "la oficial Marchetti", sexo = "m", edad = 67, pueblo = "Rosewood", oficio = "policia", vive = true, lazos = {"rosa"}, textos = { llegada = "Pase, querido, sientese. Primero digame como esta su familia. Despues hablamos de lo que vino a buscar.", rescate = "Fijate tu. Sesenta y siete y todavia me rescatan. Eso no estaba en ninguna poliza, querido.", gracias = "Pastillas para la presion. Dios te lo pague, querido, que yo ya no cobro ni pago. Eso esta cubierto.", revelacion1 = "Bernice Marchetti, oficial auxiliar de la policia de Rosewood. Vendi biblias y entierros de puerta en puerta. El plan de Hector Bencina, el de la gasolinera, se lo vendi yo en el 66.", revelacion2 = "En el 71 a Cyrus Satterwhite se le vencio la poliza por cuarenta y cinco centavos. Yo los tenia en la cartera. Lo enterraron sin nombre. Desde entonces junto monedas en un tarro.", revelacion3 = "A cada viejo que se me muere le saco la escopeta antes que un bandido. Llevo diecinueve armas. Estan en mi nicho del cementerio, el que tiene mi nombre y la fecha en blanco.", diario_conocer = "La oficial Marchetti me pregunto por mi familia antes que por mi nombre. Lleva una libreta con los muertos de Rosewood y la fecha de cada uno.", diario_final = "Bernice guarda diecinueve armas en su propia tumba, esperando al cliente correcto. No se si me lo conto porque soy yo o porque ya no le queda tiempo.", mudanza = "Me vine a la gasolinera porque la Rosa me lo pidio tres veces, y a la tercera una ya no es vendedora, es clienta. Duermo detras del taller, con una frazada y mi libreta. En la noche le dicto a la Rosa las vidas de mis difuntos y ella las escribe atras del cuaderno de los Moon Pies, al lado de las de sus camioneros. Le dije donde estan las armas. Se quedo callada un rato y me sirvio cafe recalentado, como debe ser. Despues me pregunto si queria azucar. Le dije que si. Ya no tengo que esperar al cliente correcto.", muerte = "La oficial Marchetti murio haciendo su ruta. Le cerre la libreta con su propio nombre y la fecha. Ella siempre decia: eso esta cubierto." } },
    { id = "s005", nombre = "Chester", apellido = "Zornes", apodo = "el profe Zornes", sexo = "h", edad = 42, pueblo = "Muldraugh", oficio = "profesora", vive = true, lazos = {"cabo", "gladys", "valentina"}, textos = { llegada = "Pase, joven. Cuidado con Historia universal, que esta clavada. Y hableme por la derecha, que por la izquierda no lo veo.", rescate = "Gracias. Dicho de otro modo: me salvo usted. Yo seguia esperando la campana y esta vez no sono.", gracias = "En limpio: es justo lo que pedi. La senora Lovell va a poder leer otra vez. Gracias, joven.", revelacion1 = "Chester Zornes, profesor de ingles de la secundaria de Muldraugh. Boxee en la Marina. Le hice clases a la hija del Cabo y le escribi la carta para la universidad.", revelacion2 = "En el 74 se me desprendio la retina en un sparring. No le dije a nadie y pelee la final igual. Perdi la pelea y el ojo. Mi exmujer dice que solo peleo cuando suena la campana.", revelacion3 = "La primera noche mi hija me llamo sola desde Elizabethtown. Le dije manana a las seis, porque no manejo de noche. A las seis ya estaba el cordon. A todos les digo que esta con su madre.", diario_conocer = "El profesor Zornes vive en la biblioteca de la secundaria con una bibliotecaria de 68 y una escopeta. Me corrigio la gramatica antes de saludarme.", diario_final = "Chester tiene un poema que se llama Manana a las seis. Me lo leyo en voz alta. Tardo veinte minutos en empezar y uno en terminarlo.", mudanza = "Me vine a la comisaria con la senora Lovell y doce cajas de libros. La senorita Mandados me reconocio en la puerta: me dijo profe y me corrigio una coma del letrero. Ahora le ayudo con los ninos en la sala de interrogatorios: ella pone los numeros y yo las palabras. El Cabo me pidio que le ensene a un guardia a pegar sin quebrarse la mano. Le dije que yo era el peor maestro para eso. Me dijo: por eso mismo, civil. De noche, a veces, miro la 31 hacia el sur. Ya no espero la campana.", muerte = "Chester Zornes cayo peleando sin que nadie tocara la campana. Guarde sus fichas. El poema veintitres se lo voy a leer a alguien." } },
    { id = "s006", nombre = "Halina", apellido = "Nunley", apodo = "la enfermera Nunley", sexo = "m", edad = 79, pueblo = "West Point", oficio = "enfermera", vive = true, lazos = {"chela"}, textos = { llegada = "Vamos por partes, nino. Sientese, muestreme eso y no me hable fuerte, que el audifono ya no tiene pila.", rescate = "Jezus Maria. Setenta y nueve y todavia me sacan de los lios. Anotelo: usted tiene una curacion gratis.", gracias = "Hilo de sutura. Anotelo, nino: con esto coso a medio West Point. Annabeth, ven a enhebrarme.", revelacion1 = "Halina Nunley. Fui enfermera del Ejercito en Francia y maneje el bibliobus hasta el 79. En el 63 le cosi once puntos en el brazo a la Chela, en el banco del cuartel.", revelacion2 = "En el 46 se me murio un muchacho de Hazard, Leland Sowders, por una dosis de morfina. La orden estaba mal escrita o yo la lei mal. Nunca supe. Colgue la cofia.", revelacion3 = "Tengo la morfina de una muerta. Tres mordidos me pidieron no volverse eso. Medi la dosis con el pulso firme. En mi libreta tienen una cruz chica. Esta vez no me equivoque.", diario_conocer = "La enfermera Nunley tiene 79, baston, un gato que se llama abuelo en polaco y una libreta con mas de mil trescientas curaciones.", diario_final = "Halina me mostro las tres cruces chicas de su libreta. No me pidio que la perdonara. Me pidio que le enhebrara una aguja.", mudanza = "Me vine al cuartel con Annabeth y el gato. La Chela me hizo un lugar en el banco de al lado de la cocina, el mismo donde le cosi el brazo en el 63. Se acordaba de la multa de Las uvas de la ira y me la quiso pagar con un plato. Curo en la mesa de atras con agua hervida de la Colorina. No pongo inyecciones; eso lo sabe todo el cuartel. La morfina la tengo en la caja del Ejercito, con llave, y la llave se la di a la Chela. Que decida otra. Yo ya decidi bastante.", muerte = "Halina Nunley murio con el botiquin del 44 en la falda. Su libreta pasaba de las mil trescientas curaciones. La ultima la anote yo." } },
    { id = "s007", nombre = "Ferrell", apellido = "Underwood", sexo = "h", edad = 54, pueblo = "Riverside", oficio = "cocinera", vive = true, lazos = {"nacho", "yvonne_bell"}, textos = { llegada = "Pues fijese, compadre. Sientese, que hay frijoles. Yo hablo con pausas. No es por pensar, es el pulmon.", rescate = "Gracias, compadre. Yo no corro desde el 82. Usted corrio por los dos, calculo yo.", gracias = "Un inhalador. Mire usted. Esta noche duermo sin silbar como tetera. Que Dios se lo pague.", revelacion1 = "Ferrell Underwood, de Evarts, en Harlan. Saque carbon veintiseis inviernos. Hacia los desayunos de Vesta's con el pan de los Hollis, el que horneaba la panadera de los rollos de canela.", revelacion2 = "En la huelga del 73 cruce la linea once dias para pagar la operacion de mi hija. Despues cocine frijoles en la carpa. La primera semana nadie se comio los mios.", revelacion3 = "El estofado no es conejo, compadre. En Riverside ya no quedan gatos ni perros sueltos. Solo el del cura, que ese tiene santo. Los ninos estan mas gorditos que en julio.", diario_conocer = "Ferrell Underwood cocina sentado y silba al respirar. Tiene cicatrices azules de carbon en los nudillos. Su estofado es bueno.", diario_final = "Ya se de que es el estofado de Ferrell. Me lo comi igual. Los ninos de su cuadra estan vivos y gorditos. No pienso decirles nada.", mudanza = "Me vine a la iglesia con la Coralee y los ninos de la cuadra. El Padre me dio la cocina de la casa parroquial y un piso alto, porque ya le habian contado que cocino sentado. Hago porotos, como dice el, y pan de maiz los domingos despues de la misa de las once. El perro de la oreja mordida se me echa a los pies cuando cocino y yo le doy la primera cucharada. Es lo menos que le debo. Aqui no le digo a nadie que es conejo: aqui es lo que traen. Respiro igual de mal, pero con la puerta abierta.", muerte = "Ferrell Underwood dejo de silbar. Lo enterre con su delantal. Su cuadra comio cinco meses de su olla y nunca pregunto de que era." } },
    { id = "s008", nombre = "Alma", apellido = "Isom", apodo = "la hermana Alma", sexo = "m", edad = 29, pueblo = "Rosewood", oficio = "pastora", vive = true, lazos = {"rosa", "wade_bell"}, textos = { llegada = "Un momento, por favor... Perdon, costumbre. Pase, hermano. Aqui no se le cierra a nadie, aunque la puerta sea de fierro.", rescate = "Gloria a Dios. Y a usted, hermano, que Dios a veces manda gente en vez de milagros.", gracias = "Le comunico que mi papa esta noche duerme seco. Gracias, hermano. Lo voy a nombrar en el culto.", revelacion1 = "Alma Isom, de la Capilla de Santidad del Calvario, en Rosewood. Fui telefonista de noche en Brandenburg. Desde el techo de la capilla se ve la luz de la Misia Rosa.", revelacion2 = "En el 88, en la central, escuche una llamada que no debia: un hombre de Ekron iba a arreglar lo de su mujer. Ella aparecio ahogada en Otter Creek. Me calle para no perder el puesto.", revelacion3 = "Ese hombre llego a mi capilla en septiembre. En noviembre quedo colgado del puente de Otter Creek, mirandome. Yo tenia la mano libre. No se la estire. Dije que Dios se lo llevo.", diario_conocer = "La hermana Alma predica en una capilla de cemento en Rosewood. Tiene el pelo cortado disparejo y adivina de que pueblo soy por la voz.", diario_final = "Alma no le estiro la mano al hombre del puente. Me lo conto como quien confiesa. No me pregunto que pensaba yo.", mudanza = "Me vine a la gasolinera con mi papa en su silla. La Misia Rosa le puso un catre cerca de la caja, donde hay luz toda la noche, y el le dijo amen. Ella le contesto amen tambien, aunque es bautista. Los domingos hago el culto en el taller, entre las herramientas, y en la semana les enseno a leer la Biblia a los ninos del campamento. Con el nino que cuenta, contamos los salmos. De noche me siento un rato con la Rosa detras de la caja. Ella habla y yo escucho. Es lo que sabemos hacer las dos.", muerte = "La hermana Alma murio sin que Dios le hablara claro. O tal vez le hablo. Le deje a su papa el pedazo de trenza que guardaba." } },
    { id = "s009", nombre = "Mose", apellido = "LeBlanc", apodo = "el viejo Mose", sexo = "h", edad = 66, pueblo = "Muldraugh", oficio = "carpintero", vive = true, lazos = {"cabo"}, textos = { llegada = "Mais, entre, cher. Cuidado con la tabla del porche, que esa la clave mal a proposito.", rescate = "C'est ca, cher. Me saco del agua. Al viejo Mose todavia le quedan unas noches.", gracias = "Clavos de los buenos, cher. Con esto aguantan cuatro ventanas mas. El whisky es agua que espero, y los clavos tambien.", revelacion1 = "Mose LeBlanc, de Breaux Bridge, Louisiana. Trabaje de noche en la destileria Stone Branch hasta el 89. Jugaba domino con Ernesto Mandados, el papa del Cabo.", revelacion2 = "En mayo del 61 se quemo la bodega G con nueve mil barriles. Dijeron que fue un rayo. Fue mi cigarro. Echaron a cuarenta hombres y yo me quede callado.", revelacion3 = "De cada diez latas que reparto, una se va a mi pirogue. La parte del angel, cher. Llevo treinta y una. No se para que. Para cuando el whisky termine de esperar.", diario_conocer = "El viejo Mose LeBlanc habla mitad en frances y le clava las ventanas a toda su cuadra. Muerde una pipa vacia. Me dijo cher.", diario_final = "Mose esconde latas de la despensa comun en su pirogue. No tiene plan, me dijo: es miedo. Le pregunte miedo a que. Me dijo: a que se acabe.", mudanza = "Me vine a la comisaria con los Ritchey y la viuda Mayhew. Antes de entrar, le devolvi las treinta y una latas a la despensa. La cocinera las conto delante mio y no pregunto nada. El hijo de Ernesto me dio el galpon de atras para la carpinteria. Hago camas, marcos de puerta y una mesa larga para que coman todos juntos, como en un fais do-do. La pirogue la traje tambien: esta en el patio, boca abajo, por la lluvia. A veces me siento encima con la pipa vacia. Ya no cuento latas, cher. Cuento platos.", muerte = "Mose LeBlanc murio en Kentucky, lejos del Atchafalaya. Lo enterre con la pipa. La pirogue quedo en el patio, boca abajo." } },
    { id = "s010", nombre = "Sybil", apellido = "Hall", apodo = "la cazadora", sexo = "m", edad = 41, pueblo = "West Point", oficio = "cazador", vive = true, lazos = {"chela"}, textos = { llegada = "Aja. Las manos donde las vea, oiga. Si viene por la cabra, se devuelve. Si viene por otra cosa, hable.", rescate = "Como sea. Me salvo el pellejo, oiga. Eso pesa como media Holstein. Se lo debo.", gracias = "Sal y balas. Con esto paso el invierno. Gracias, oiga. Le guardo un tarro de leche.", revelacion1 = "Sybil Hall, la cazadora de West Point. Guie a los oficiales del Fuerte en la temporada de ciervos. Antes saque leche dieciocho veranos en la lecheria Hardesty.", revelacion2 = "En el 86 el gobierno compro las vacas de la lecheria para el matadero. Las subi yo al camion, una por una. La noche antes escondi una ternera, Trebol. Merle, el lechero de Ekron, nunca lo supo.", revelacion3 = "La Holstein se me murio de mastitis en septiembre y no lo dije. La leche que les llevo a los ninos es de una cabra, estirada con agua y harina. Me dan las gracias.", diario_conocer = "Sybil Hall vive en una lecheria abandonada y huele a monte. Me apunto antes de saludarme. Se despierta a las cuatro sin despertador.", diario_final = "La leche que reparte Sybil es de cabra, aguada con harina. La Holstein se murio en septiembre. Los ninos le dan las gracias y ella no puede mirarlos.", mudanza = "Me vine al cuartel con la cabra y los perros por el camino del rio, de noche, como cuando saque a Trebol. La Chela miro la cabra y dijo: leche para los ninos, mija, y usted a la guardia. Le dije la verdad: que es poca y que yo la estiraba con agua y harina. Me dijo: aqui se estira todo, pero se dice. Duermo en el galpon de atras con los perros. Ordeno la cabra a las cuatro y a las cuatro, y hago guardia en el techo con la escopeta. Si alguien trae una vaca, ya se que hacer con ella.", muerte = "Sybil Hall murio con la escopeta en la mano. Alguien tiene que sacarle la leche a la cabra a las cuatro." } },
    { id = "s011", nombre = "Clint", apellido = "Kincaid", apodo = "el senor del siete", sexo = "h", edad = 78, pueblo = "Riverside", oficio = "granjero", vive = true, lazos = {"nacho"}, textos = { llegada = "Sientese y no saque los brazos. Hobie, quien es? ... Si el nino dice que es gente, es gente.", rescate = "En orden, muchacho, en orden. Esta noche usted maneja mejor que yo.", gracias = "Gracias. Lo anoto en la parada que le toca. Usted queda pasada la diecinueve.", revelacion1 = "Treinta temporadas maneje el bus escolar de Riverside, cuarenta y dos paradas. A las siete y cuarenta, frente a la iglesia de piedra, Delbert Moody tocaba las campanas para el siete.", revelacion2 = "Mi Merritt se sento en el asiento uno desde primero hasta el ultimo curso. Lo mataron en Hue en el 68. Nunca deje que nadie se sentara ahi. Ahora se sienta Hobie, y lo dejo.", revelacion3 = "No veo, muchacho. Desde octubre, ni de dia. En noviembre le dispare a un bulto en la tranquera y era Hobie. Le erre por un metro. El nino me dio las gracias.", diario_conocer = "Un viejo de 78 duerme en un bus escolar con dos ninos y las gallinas. El nino de once le cuenta lo que pasa por la ventana.", diario_final = "Clint le paso la escopeta a Hobie y le conto lo de la tranquera. El nino no la solto en toda la tarde. Despues le dijo: 'Yo le cuento la ventana'.", mudanza = "Llegamos al atrio de la iglesia de piedra a las siete y diez, en orden: Hobie adelante, la Marlo con la gallina colorada en brazos y yo al ultimo, con la mano en el hombro del nino. El Padre me pregunto que sabia hacer. Le dije que ordeno filas. Ahora la cola del agua y la de la sopa son mias: nadie se cuela y nadie saca los brazos. No veo las caras, pero conozco los pasos. Hobie me dice quien llega. Las vacas pastan detras del cementerio. El siete se quedo en la granja, con las llaves en mi cinturon. Un dia de estos lo traemos.", muerte = "Clint Kincaid murio con las llaves del siete en el cinturon. Hobie le dijo: 'Parada final, senor Kincaid'." } },
    { id = "s012", nombre = "Flossie", apellido = "Middleton", apodo = "Polka", sexo = "m", edad = 53, pueblo = "Rosewood", oficio = "camionero", vive = true, lazos = {"earl", "rosa"}, textos = { llegada = "Polka al habla. Pasa, Kowalski, pero no me toques la radio, que es lo unico que me dejaron.", rescate = "Matko Boska! Ya, ya. Te debo una ruta limpia, Kowalski. Y yo pago mis rutas.", gracias = "Esto lo digo en el parte de manana: hay un Kowalski bueno en Rosewood. Gracias, carino.", revelacion1 = "Soy la Polka, camionera de Rosewood sin camion. Con dos baterias de tractor digo por el 19 donde hay horda. El Gordo Whitaker me dice Polaca desde el 68.", revelacion2 = "Soy de Chicago, de los corrales. Me vine en el 62 detras de un camionero, Roy. En el 79 se dio vuelta en la I-65, borracho. Yo le habia pasado las llaves. Al patrullero le menti.", revelacion3 = "La Babcia no me la robaron. En septiembre dos del patio de trenes me hicieron senas en la 31 y les pase las llaves antes de que levantaran el fusil. Otra vez, como en el 79.", diario_conocer = "Conoci a la Polka, la voz de las rutas del 19. Habla como camionero, insulta en polaco y da el parte desde una cocina con baterias de tractor.", diario_final = "Flossie dio el parte de hoy y al final dijo al aire que la Babcia no se la robaron: la entrego. Despues se quedo oyendo pasar un motor por la 31.", mudanza = "Le traje a la Rosa la radio en brazos y las dos baterias en una carretilla. El Junior me subio la antena al techo del taller. Doy el parte de rutas tres veces al dia desde un cajon al lado de la caja. La Rosa me pregunto lleno o normal y le dije que yo ya no lleno nada, que no tengo camion. Me sirvio achicoria igual. Cuando el 19 esta callado le cuento de Chicago, de los corrales, de mi papa partiendo novillos. No lo anota en el cuaderno. Se lo pedi. A veces de noche pasa un Kenworth por la 31 y las dos nos quedamos calladas.", muerte = "Flossie Middleton murio dando el parte. Lo ultimo que dijo por el 19: 'Si ven a la Babcia, Kowalskis, diganle que era mia'." } },
    { id = "s013", nombre = "Duc", apellido = "Halcomb", apodo = "Dukey", sexo = "h", edad = 28, pueblo = "Muldraugh", oficio = "mecanico", vive = true, lazos = {"cabo", "pereira"}, textos = { llegada = "Okey, okey, no dispare. Soy Duc. Mecanico. A veces payaso. Hoy solo mecanico.", rescate = "Tres naranjas, cuatro horas, ninguna al suelo. Hoy usted fue mi cuarta naranja, hermano grande.", gracias = "Esto vale una bicicleta arreglada y un show gratis. Sin pintura, porque es usted.", revelacion1 = "Arreglo transmisiones en el taller Halcomb, en la 31W. Aprendi con motos Honda en Saigon, a los doce. Los domingos me pinto de payaso para los ninos de Muldraugh.", revelacion2 = "Garland Halcomb es mi papa. Sargento en Saigon, en el 64. Me dio trabajo y me pidio que no se lo dijera a nadie. Kelli, la que vive conmigo, es mi hermana y no lo sabe.", revelacion3 = "Garland esta vivo, en el patio de trenes, con la sargento. Los domingos me pasa un inhalador por el alambrado si no digo nada. Kelli lo llora como muerto. Yo vuelvo con el remedio.", diario_conocer = "En el taller Halcomb vive un mecanico vietnamita que se pinta de payaso para los ninos. Sonrie todo el tiempo y silba al respirar.", diario_final = "Duc le conto todo a Kelli. Ella no lloro. Le pregunto: 'Y tu eres mi hermano?'. El dijo okey. Esta vez si era okey.", mudanza = "El Cabo me pregunto el nombre para la libreta. Le dije Duc Halcomb y lo anoto asi, con tinta, sin preguntar nada. Mi mama lloro un poco. Kelli tambien. Ahora arreglo lo que tenga ruedas en el patio de la comisaria: patrullas, bicicletas, un carro de supermercado. Los domingos me pinto la cara y hago malabares con lo que haya: papas, pilas, tapas de frasco. Mi mama hace sopa con hierbas del patio y los guardias le dicen senora Hoa. Kelli me dice hermano delante de la gente. Okey. Esta vez si es okey.", muerte = "Duc Halcomb murio sonriendo. En el bolsillo del overol tenia la lata de te con la foto del sargento Halcomb." } },
    { id = "s014", nombre = "Minnie", apellido = "Creech", apodo = "Tia Minnie", sexo = "m", edad = 65, pueblo = "West Point", oficio = "costurera", vive = true, lazos = {"cabo", "chela", "gladys"}, textos = { llegada = "Sientate derecho, querido, que encorvado no te puedo medir. Y habla bajito, que hay una nina durmiendo.", rescate = "Medido dos veces y salvado una. Gracias, querido. Ahora suelta, que me arrugas la manga.", gracias = "Esto vale un ruedo, un parche y una oracion bautista. Medido dos veces, pagado una.", revelacion1 = "Cosi treinta y siete temporadas en la sastreria del Fuerte Knox. A mi lado planchaba Mildred Quinn, la mama del Cabo, con el nino debajo de la mesa. Ahora coso panales.", revelacion2 = "En el 66 a mi Dovie le llego una beca para estudiar vestuario en Cincinnati. Rompi la carta y la eche a la estufa. La sente a coser a mi lado. No me habla desde el 81.", revelacion3 = "Escondi otra carta. En octubre un tarro en el muelle decia que Bo, el marido de Lacey, estaba vivo en un remolcador. La guarde con la de Dovie. Deje pasar la fecha.", diario_conocer = "Una costurera vieja de West Point me tomo las medidas antes de saludarme. En su casa hay una enfermera, una guagua y un ciego.", diario_final = "Minnie le paso a Lacey el papel del tarro. Lacey ya lo sabia. Se quedaron calladas cosiendo el mismo panal, una de cada punta.", mudanza = "La Chela me dio el banco de atras y un rincon con luz para la Singer. Le dije que yo no cocino, que yo coso. 'Aqui trabaja el que trabaja', me dijo, y me paso los pantalones de todo el cuartel. Les tome la medida a los veintitantos, uno por uno, derechos. A la Chela le subi el ruedo del delantal, que lo pisaba. No me dio las gracias y yo no se las pedi. Somos parecidas, querida: las dos mandamos. En la noche le escribo a Dovie cartas que no mando y las guardo en la caja de galletas, pero ahora con la tapa abierta.", muerte = "Minnie Creech murio con la huincha de medir al cuello. En la caja de galletas ya no quedaba ninguna carta escondida." } },
    { id = "s015", nombre = "Felix", apellido = "Dupree", apodo = "Fox", sexo = "h", edad = 40, pueblo = "Riverside", oficio = "electricista", vive = true, lazos = {"hector", "rosa"}, textos = { llegada = "Te copio, te copio. Fuerte y claro. Pasa, pero no toques el banco de baterias, que muerde.", rescate = "Setenta y tres, amigo. Eso es saludos. En radio no tenemos palabra para gracias, asi que gracias.", gracias = "QSL. Recibido y confirmado. Te debo una tarjeta para la pared, la primera del fin del mundo.", revelacion1 = "Soy Felix, WB4FDX, Fox. Electricista de Riverside, con 241 paises en la pared. A Hector Jr., el sobrino de la Misia Rosa, le ensene a soldar cuando tenia ocho.", revelacion2 = "Fui socio de Ramon Bencina catorce temporadas. D&B Electric. En el 85 lei que el aceite de unos transformadores daba cancer. No se lo dije. Ramon murio en el 90.", revelacion3 = "En julio Atilio me paso una noticia: la familia de Nolan Sturgill murio en la barricada. Nolan viene cada manana. Le digo 'nada todavia'. No subo la torre para no tener mas noticias.", diario_conocer = "Un electricista cojo vive al pie de una torre de radio en Riverside. Le da luz a medio pueblo y habla en codigos.", diario_final = "Felix bajo con la bitacora a la calle del rio y le leyo a Nolan la linea del 18 de julio. Despues se quedaron sentados en la vereda, sin decir nada.", mudanza = "El Padre me dio el techo de la sacristia para la antena. Doce metros. Subo con una cuerda amarrada a la cintura y el Padre me la sostiene desde abajo, rezando o insultando, no se cual. Le hice un banco de baterias para la luz del altar y otro para la despensa. Mi mama vino con la olla y ayuda en la cocina. Ahora, cuando llega una noticia, la doy el mismo dia, en la escalera de la iglesia, en voz alta. Buena o mala. Nolan viene a misa. Se sienta atras, con la gorra en la mano. Setenta y tres.", muerte = "Felix Dupree murio al pie de su torre. En la bitacora, la ultima linea: 'Mensaje entregado. Setenta y tres'." } },
    { id = "s016", nombre = "Ora", apellido = "Click", apodo = "Miss Ora", sexo = "m", edad = 77, pueblo = "Rosewood", oficio = "policia", vive = true, lazos = {"rosa"}, textos = { llegada = "Numero, por favor. Digame lo que quiere, joven, que a mi edad no se gasta el tiempo en saludos.", rescate = "Anotado. Usted me salvo, joven. No se me acerque tanto: dicen que traigo mala suerte.", gracias = "Queda en el libro rojo, del lado de las cosas que se pagaron. Hay pocas, joven.", revelacion1 = "Soy la constable Click, electa del distrito de Rosewood. Ora. Setenta y siete. Resuelvo quien se queda con la casa del muerto. Uso de baston la luma de mi marido.", revelacion2 = "Tres maridos. Tilden murio en Normandia, Pleas de un infarto. Otha se fugo en el 56 con la plata del techo: la Rosa Lindell se caso con goteras. La carta de su muerte la escribi yo.", revelacion3 = "En noviembre hice elecciones. Arlie Penrod saco veintiuno y yo diecisiete. Conte sola, dije veinte a dieciocho y queme las papeletas. Un marido falso y una eleccion falsa.", diario_conocer = "Conoci a la constable de Rosewood: 77, baston de policia, bifocales rotos. La gente se cruza la calle para no pasarle cerca, y despues le pide favores.", diario_final = "Ora junto a todos en la escuela y dijo la cuenta verdadera: veintiuno a diecisiete. Le paso la luma a Arlie. 'Numero, por favor', le dijo.", mudanza = "La Rosa me dejo un cajon al lado de la caja, donde da la luz. Dice que la mala suerte no entra en su bomba porque esta todo prendido. Me siento ahi con el libro rojo y anoto a los que llegan y a los que se van. A los que pelean les resuelvo en dos minutos, sin placa. La gente ya no se cruza la calle; se cruza la pista. A las tres de la manana la Rosa pone dos tazas. Una no es para mi. Igual me la tomo, por costumbre. Ella no dice nada. Somos dos viudas que no apagan nada.", muerte = "Ora Click murio de pie, con la luma en la mano. En el libro rojo, su ultima linea: 'Click, Ora. Cuenta cerrada'." } },
    { id = "s017", nombre = "Ezra", apellido = "Freeman", apodo = "Mister Free", sexo = "h", edad = 52, pueblo = "Muldraugh", oficio = "profesora", vive = true, lazos = {"cabo", "valentina"}, textos = { llegada = "Mira, chico, sientate. Aqui se habla bajito y nadie sale solo. Esa es la unica regla.", rescate = "Que cosa mas grande, chico. Me salvaste. Te pongo un diez y una racion de frijoles.", gracias = "Correcto. Aprobado con honores. Lo anoto en la pizarra, al lado de la tabla del siete.", revelacion1 = "Soy Ezra Freeman, profesor de espanol de la secundaria de Muldraugh. Cubano, del Mariel. Valentina, la hija del Cabo, fue mi alumna. La primera noche abri el gimnasio.", revelacion2 = "Me llamaba Esdras Montoto. En Cuba me mandaron a la zafra en un campo con alambre. Sali por el Mariel diciendo lo que habia que decir. Rolando no lo dijo y se quedo.", revelacion3 = "Wick Darnall leyo las cartas de Rolando. Desde septiembre le doy la mitad de mi racion y la de Mattie para que no cuente que soy homosexual. Me fui de Cuba para no esconderme.", diario_conocer = "Un profesor cubano lleva un refugio en la secundaria de Muldraugh como si fuera una clase. Cuida a una vieja ciega que no es su madre.", diario_final = "Ezra se paro frente a los once y lo dijo. Wick se quedo sin nada que cobrar. Mattie le busco la mano y le dijo: 'Ya sabia, Esdras'.", mudanza = "El Cabo me anoto en la libreta como Freeman, Ezra, profesor. Le dije que tambien Montoto, Esdras, y lo anoto debajo, sin preguntar. La senorita Valentina me presto la pizarra de los partes: ella hace la manana y yo la tarde. Tiene mi Larousse en la mesa. Mattie duerme en una oficina de abajo y cree que la comisaria es un hotel de Louisville. La dejo creerlo. A los guardias les enseno a contar en espanol para no dormirse en la guardia: uno, dos, tres. Dicen que suena a cancion. Tienen razon, chico.", muerte = "Ezra Freeman murio con la tiza en la mano. En la pizarra quedo escrito: 'Tarea: decir su nombre en voz alta'." } },
    { id = "s018", nombre = "Lacey", apellido = "Swafford", apodo = "Lace", sexo = "m", edad = 27, pueblo = "West Point", oficio = "enfermera", vive = true, lazos = {"chela", "eduardo"}, textos = { llegada = "A ver, respira, corazon. Dame la mano, que te tomo el pulso. Y no despiertes a la nina.", rescate = "Ciento veinte de pulso, corazon. El tuyo, no el mio. Gracias. Ahora despacio, que la espalda me cobra.", gracias = "Con esto la Mavis come una semana. Gracias, corazon. Te debo un parto, si algun dia lo necesitas.", revelacion1 = "Soy Lacey, enfermera de urgencias del Fuerte Knox. Me crie en West Point: Eduardo Giovanns, el de la Chela, iba dos cursos abajo mio. Hoy atiendo desde la casa de la senora Creech.", revelacion2 = "En el 90 me rompi la espalda levantando a un paciente. Dos temporadas robe Demerol de las jeringas que tenia que botar. Lo deje de golpe cuando supe de la Mavis.", revelacion3 = "Bo esta vivo. Lo lei en un papel que Minnie esconde en la caja de galletas. Tenia siete dias para ir al rio y no fui. No queria que me viera asi. Minnie cree que no se.", diario_conocer = "Una enfermera con una bebe de tres meses atiende West Point en la casa de una costurera. Me tomo el pulso antes de saludarme.", diario_final = "Lacey abrio la caja de galletas delante de Minnie y saco el papel. 'Lo sabia', le dijo. Minnie se sento. Despues rompimos las seis ampollas en el patio.", mudanza = "La Chela me miro la guata vacia y la nina en el rebozo y me dijo: 'Aqui nadie se para a mirar, mija. Se trabaja'. Me dio el cuarto de las mangueras para enfermeria. Pongo puntos, bajo fiebres, saco astillas. La Mavis duerme en un canasto al lado de la olla, y la Chela le canta unas canciones de huasos que no entiendo. Minnie vino conmigo. Las seis ampollas las rompi en el patio antes de venirme. En la noche cuento las respiraciones de la nina y las anoto en la pared con tiza: cuarenta.", muerte = "Lacey Swafford murio con la mano en el pecho de la Mavis, contando. La nina seguia respirando: cuarenta por minuto." } },
    { id = "s019", nombre = "Irvin", apellido = "Dotson", apodo = "el Veintinueve", sexo = "h", edad = 64, pueblo = "Riverside", oficio = "cocinera", vive = true, lazos = {"duggan", "nacho"}, textos = { llegada = "Sientate, campeon. Plancha caliente desde las cinco. El que trae lena come. Revueltos o fritos? Mentira, hay sopa.", rescate = "Bandera verde, campeon! Me sacaste de la curva tres. Comes gratis hasta que se acabe la papa.", gracias = "Esto da para una semana de plancha. Gracias, campeon. Tu plato va primero, antes que los del Martillo.", revelacion1 = "Soy Irvin Dotson, el Veintinueve. Corri en tierra del 53 al 71. Cocino en el Dotson's Grill de la calle Front; el pan se lo compre a Walt Hollis desde el 72. El que trae lena come.", revelacion2 = "Del 66 al 87 le mande el desayuno gratis a Royce Tinsley, el de la silla de ruedas. Lo choque yo en la curva tres. A proposito. El lo supo y siguio comiendo.", revelacion3 = "Los viernes la sopa de los del Martillo la hago con agua del pozo malo de la vega, el de la disenteria del 37. Se enferman uno tras otro. Nadie sospecha del cocinero cojo.", diario_conocer = "En Riverside cocinan con lena para el que trae lena. El cocinero cojo grita como locutor de carreras y le da de comer gratis a la banda los viernes.", diario_final = "Irvin dio vuelta el balde del pozo malo delante de mi y lo tapo con tablas. 'Como en la curva tres, campeon. Pero esta vez frene.'", mudanza = "El Padre me dio la cocina del salon parroquial y me dijo que ahi no se cobra. Le dije que yo tampoco cobro desde el 9 de julio. Arme una plancha de fierro sobre ladrillos y la prendo a las cinco, como siempre. El Padre me trae lo de la despensa contado y yo se lo devuelvo en platos. Una sola olla, para todos. El agua la saco del pozo de la iglesia y la hiervo dos veces. El Chevy del 29 lo arrastramos entre seis hasta el patio, sin motor. Los ninos juegan a correr adentro y yo les grito la carrera desde la cocina.", muerte = "Irvin Dotson murio frente a la plancha. Antes dijo: 'Bandera a cuadros'. El pozo de la vega quedo tapado con tablas." } },
    { id = "s020", nombre = "Lula", apellido = "Rose", apodo = "la Hermana Lula", sexo = "m", edad = 39, pueblo = "Rosewood", oficio = "pastora", vive = true, lazos = {"hector", "rosa"}, textos = { llegada = "Paz, hermano. Pase a la banca, que el Senor no cobra la entrada. Yo tampoco. Limpiese las botas.", rescate = "Amen y gracias, hermano. Dios proveyo, pero esta vez proveyo con sus manos.", gracias = "Esto es un milagro chico, de los que se cargan al hombro. Lleve una hoja de burley, que aqui es plata.", revelacion1 = "Soy Lula Rose, pastora de Monte Horeb, en la loma de Rosewood. Once en la capilla, tabaco colgado. El diesel del tractor lo cargabamos donde la Misia Rosa desde que yo era nina.", revelacion2 = "Mi papa me dijo antes de morir: 'Repartelo parejo, Lula'. No se lo dije al abogado. Me quede con todo y mi hermano Elvert se fue a Bardstown sin nada.", revelacion3 = "Duermo con Lemmie, el viudo de mi prima, y el domingo predico de la fidelidad. Y la noche que se murio la Oma senti alivio. Del porte de un boton. No se lo digo ni a Dios.", diario_conocer = "En la loma de Rosewood una pastora de sombrero de paja guarda a once vecinos en su capilla y paga todo con hojas de tabaco.", diario_final = "Lula lo dijo desde el pulpito, entero. Nadie se fue. Lemmie se paro a su lado. Despues colgaron juntos la ultima vara del galpon.", mudanza = "Le traje a la Misia Rosa cuatro carretillas de burley y le dije que eso es plata, que lo guarde en la bodega. Me miro raro y no dijo nada. Los domingos hago el culto en el taller, entre las llantas, con jugo de lo que haya y galletas de soda. Los lunes les enseno a leer a los ninos con la Biblia de mi papa, pegada con cinta. Lemmie trabaja con el Junior en la bomba del pozo. Nos casamos en la isla dos, con la Rosa de testigo. Me pregunto lleno o normal. Le dije: parejo, misia. Repartido parejo.", muerte = "Lula Rose murio en la loma, con la soga del galpon en la mano. Lemmie la enterro al lado de la Oma, parejo." } },
    { id = "s021", nombre = "Terrell", apellido = "Strunk", apodo = "el Starlite", sexo = "h", edad = 76, pueblo = "Muldraugh", oficio = "carpintero", vive = true, lazos = {"cabo"}, textos = { llegada = "Pase, hijo, despacio. Billie se asusta con la gente nueva. Le voy a decir que usted es el acomodador.", rescate = "Uno mas, nomas. Gracias, hijo. A los setenta y seis uno ya no corre: se despide caminando.", gracias = "Esto vale una funcion entera. El sabado hay pelicula en la cocina. Traiga su silla.", revelacion1 = "Terrell Strunk, carpintero de Muldraugh. Tuve el Starlite, el autocine de la 31W. La pantalla la clave yo solo en el 51 y sigue parada.", revelacion2 = "Mi hijo Rodney salio de la funcion de medianoche en el 65 y le erro a la curva. La cerveza se la vendi yo, por la ventanilla de la caseta.", revelacion3 = "Orino sangre desde agosto. Me voy antes que Billie. En una tabla de la cocina escribo lo que hay que saber de ella. Cuando no pueda, se la llevo al Cabo. Usted lee la tabla.", diario_conocer = "Conoci a Terrell Strunk, 76, carpintero, junto a un autocine muerto en la 31W. El Cabo lo tiene anotado sin cruz. Su mujer pregunta que dan hoy.", diario_final = "Terrell se esta muriendo y nadie lo sabe. Me mostro la tabla con las manias de Billie. Me pidio que la memorizara. Ya me la se.", mudanza = "Terrell llega empujando una carretilla con el proyector, la sabana y la tabla de pino, y Billie del brazo con el cascabel en el tobillo. Pide un rincon con enchufe de bateria y una pared blanca. Arregla puertas, hace bancas, y los sabados pasa Que bello es vivir para todo el campamento, aunque la ampolleta se este gastando. Billie le pregunta a cada uno que dan esta noche y alguien siempre le contesta. La tabla de pino queda colgada en la cocina, a la vista. Ya no es un secreto: es un horario.", muerte = "Terrell Strunk murio en el camino. Alguien tiene que leer la tabla de la cocina y contestarle a Billie que dan esta noche." } },
    { id = "s022", nombre = "Ruby", apellido = "Duncan", apodo = "la del Deposito", sexo = "m", edad = 51, pueblo = "West Point", oficio = "cazador", vive = true, lazos = {"chela", "pereira"}, textos = { llegada = "Quieto ahi. Lo tengo en la mira hace rato. Hable claro y despacio.", rescate = "Bien tirado. No lo digo seguido. Y hasta ahi.", gracias = "Cumplio. Le debo un cuarto de venado. Yo pago en carne.", revelacion1 = "Ruby Duncan, cazadora de West Point. Los martes le llevo venado al cuartel de la Chela. Antes escribia a maquina al lado del oro de Fort Knox. Nunca lo vi.", revelacion2 = "En el 80, con neblina, le dispare a mi sobrino Doyce. Sabia que andaba ahi. Despues la unica que me siguio dando sopa en el casino del Fuerte fue la Mae, la mama de la Chela.", revelacion3 = "Doyce esta vivo. Anda con los del patio de trenes. En noviembre lo tuve en la mira y le dispare al de al lado. Wilma Jean lo llora todos los domingos y yo no le digo nada.", diario_conocer = "Ruby Duncan, cazadora de West Point. Me apunto antes de saludarme. Le lleva carne a la Chela y no acepta plato.", diario_final = "Ruby sabe que su sobrino anda con los del patio de trenes y no se lo dice a la madre. La mejor tiradora de Knox no puede apuntarle a eso.", mudanza = "Ruby llega al cuartel con el rifle al hombro, un cuarto de venado y los dos perros del vecino. No pide cama: pide el techo, al lado de Jody, para mirar el camino. Ahuma en un tambor detras del cuartel y los martes ya no baja: el venado esta ahi. La Chela le sirve plato y Ruby dice que ya comio, y las dos se quedan mirando la olla. Los domingos sigue llevando carne al porche de su hermana. Un domingo de estos va a golpear.", muerte = "Ruby Duncan cayo en el monte. Los martes ya no va a llegar venado al cuartel. Wilma Jean no sabe lo de Doyce." } },
    { id = "s023", nombre = "Willis", apellido = "Prater", apodo = "Will", sexo = "h", edad = 26, pueblo = "Riverside", oficio = "granjero", vive = true, lazos = {"nacho", "yvonne_bell"}, textos = { llegada = "A ver, a ver, despacio que hay ninos. Boone, adentro. Birdie, suelta esa gallina.", rescate = "Gracias, compadre. Si me pasa algo, los mellizos... no. No me pasa nada. Vamos.", gracias = "Esto es leche para un mes. Le guardo un galon, compadre. Y huevos.", revelacion1 = "Willis Prater, granjero del camino del rio, en Riverside. Cuarenta acres, doce vacas, un pozo y dos mellizos de cuatro. Les hago panqueques con forma de Kentucky.", revelacion2 = "La mama de los ninos no se fue sola. Le pague con la plata del seguro del tractor para que firmara y se fuera. A ellos les dije que no los quiso.", revelacion3 = "En agosto Shawna vino a buscarlos. Iba al cordon con otros cinco. Los ninos dormian la siesta. La eche con la escopeta. No se si llego. Ellos no saben que vino.", diario_conocer = "Willis Prater, granjero, padre solo de mellizos. Le da leche al Padre Nacho para la despensa. La panadera de los Hollis les regalaba canela.", diario_final = "Willis echo a la madre de sus hijos a punta de escopeta. Dice que los salvo. Los mellizos siguen sin saber nada.", mudanza = "Willis llega a la iglesia con los mellizos en la carretilla, dos vacas de la cuerda y Dallas atras con la muleta. Pide un pedazo de patio para las vacas y un rincon tibio para los ninos. Desde el primer dia hay leche en la despensa. Duerme por fin una noche entera, porque alguien mas vigila. Una tarde, ordenando, se sienta con Birdie y Boone y les dice que su mama los vino a buscar una vez. No dice lo demas. Todavia.", muerte = "Willis Prater murio en el camino. Dallas se quedo con los mellizos. Ellos siguen esperando a alguien en la cerca." } },
    { id = "s024", nombre = "Thelma", apellido = "Collins", apodo = "Mama Gansa", sexo = "m", edad = 63, pueblo = "Rosewood", oficio = "camionero", vive = true, lazos = {"earl", "rosa"}, textos = { llegada = "Diez-cuatro, corazon, te veo. Baja la voz, que Floyd esta durmiendo en la pieza de adelante.", rescate = "Cuarenta inviernos de ruta y nunca me tuvieron que sacar de una zanja. Hasta hoy. Gracias, corazon.", gracias = "Eso es entregar a tiempo, corazon. Te ganaste un cafe donde la Rosa. Achicoria, digo.", revelacion1 = "Thelma Collins, camionera de Rosewood. En el 19 me dicen Mama Gansa. Me case en junio con Floyd y la fiesta fue en el taller de la Rosa. El Gordo Whitaker mando saludos.", revelacion2 = "Mi primer marido murio en la litera en el 75. Me llamo dos veces: Thelma, para un poco. Yo iba con pastillas y la carga atrasada. No pare. Dije que murio dormido.", revelacion3 = "Floyd no se cayo de la escalerilla. Llevaba tres noches despierta con pastillas, vi una sombra en el patio y le pegue con el tubo de la gata. Era el. No se acuerda. Todavia las tomo.", diario_conocer = "Thelma Collins, 63, camionera recien casada. Cuida a su marido en cama y toma achicoria donde la Misia Rosa.", diario_final = "Thelma le quebro la cadera a Floyd en la oscuridad, drogada de guardia. El cree que se cayo. Le pedi el frasco. No me lo dio todavia.", mudanza = "Thelma llega a la gasolinera con Floyd acostado en una puerta, cargado entre ella y dos muchachos de la Rosa. Pide un catre al lado de la caja, donde no le de el frio, y se ofrece para las guardias de la madrugada. La Rosa le guarda achicoria caliente para la guardia. Thelma da clases de manejo en el patio a los muchachos con una camioneta sin ruedas traseras: el volante, los cambios, la paciencia. Una noche, delante de la Rosa, bota el frasco de pastillas en el balde. No explica por que.", muerte = "Thelma Collins murio en un encargo. Floyd pregunto por ella toda la noche. Nadie le supo decir diez-cuatro." } },
    { id = "s025", nombre = "Odell", apellido = "Branham", apodo = "Rodeo", sexo = "h", edad = 38, pueblo = "Muldraugh", oficio = "mecanico", vive = true, lazos = {"cabo"}, textos = { llegada = "Epa, amigazo. Si viene por un auto, tiene ocho segundos para decirme que trae.", rescate = "Usted no se quedo pegado. Eso vale mas que una hebilla, amigazo. Gracias.", gracias = "Con esto le hago andar lo que sea. Pase cuando quiera, el taller no cierra.", revelacion1 = "Odell Branham, mecanico del taller de Whisman, en la 31W de Muldraugh. Monte toros diez temporadas. Esta hebilla la gane en Freedom Hall en el 79.", revelacion2 = "No me retiro la pelvis. En el 84 me quede tieso en el cajon, arriba del mismo toro que me quebro la clavicula. Me baje por la reja. A todos les cuento lo del doctor.", revelacion3 = "La escopeta no se trabo. Me trabe yo. Vi como agarraban a Jarrod a quince yardas y conte ocho segundos antes de moverme. Al Cabo le menti y el lo anoto con tinta.", diario_conocer = "Odell Branham, mecanico de la 31W. Le arregla las patrullas al Cabo de vez en cuando. Hebilla de rodeo y chistes de ocho segundos.", diario_final = "Odell se congela cuando hay que disparar. Asi murio un muchacho en su patio. Le dije que igual lo quiero cuidandome la espalda.", mudanza = "Odell llega a la comisaria con la caja de herramientas, la hebilla puesta y la escopeta descargada en la mano. Pide el garaje de las patrullas y se queda a vivir ahi, entre las llantas. Arregla todo lo que tenga ruedas. Una noche le pide al Cabo la libreta, busca la linea de Jarrod Haddock y le dicta otra cosa: me quede tieso. El Cabo la corrige con tinta, sin decir nada. Desde ese dia Odell no hace guardia solo, y no le da verguenza pedirlo.", muerte = "Odell Branham murio en un encargo. Esta vez no se quedo quieto. Duro mas de ocho segundos." } },
    { id = "s026", nombre = "Lan", apellido = "Turpin", apodo = "la senora Lan", sexo = "m", edad = 75, pueblo = "West Point", oficio = "costurera", vive = true, lazos = {"chela"}, textos = { llegada = "Pase, mi alma, y no me pise los alfileres. Le estoy tomando la medida con la vista.", rescate = "Ay, el corazon. Deme la pastilla de la lata. Gracias, mi alma. Hilvanado nomas, pero viva.", gracias = "Esto vale un ruedo, mi alma. O una mortaja, si me la pide para alguien. Ojala no.", revelacion1 = "Lan Turpin, costurera de la calle Locust, en West Point. Le hacia los ruedos al jefe Booker. Ahora coso mortajas y les bordo las iniciales por dentro.", revelacion2 = "Soy adoptada. Llegue con un gorrito bordado C. M. R. En el 72 una mujer de Brandenburg me contesto: No me busque mas. Escondi la carta y segui escribiendo como si nada.", revelacion3 = "El sobre de Frankfort lo abri en agosto. Se llama Cora Mae Rowlett. En el 91 estaba en el hogar de ancianos de Brandenburg. Tendria noventa y dos. No he ido. Me da miedo que me reconozca.", diario_conocer = "Lan Turpin, costurera de 75, cose mortajas en West Point. Me midio el brazo con los ojos antes de saludarme.", diario_final = "Lan sabe el nombre de su madre y donde puede estar: diez millas. La busco toda la vida y ahora no se atreve a ir.", mudanza = "Lan llega al cuartel con la Singer de pedal en una carretilla y la lata de galletas danesas en la falda. Pide una silla junto a la ventana, por la luz. Cose ruedos, remienda frazadas, y cuando hay un muerto cose la mortaja y le borda las iniciales por dentro. A la Chela le toma la medida con la vista y le dice que esa chaqueta no da para otro invierno. Una noche abre la lata delante de todos y lee en voz alta un nombre: Cora Mae Rowlett.", muerte = "Lan Turpin murio con el sobre de Frankfort en la lata. Alguien tiene que coserle su mortaja y bordarle L. T. por dentro." } },
    { id = "s027", nombre = "Tobias", apellido = "Gilley", sexo = "h", edad = 50, pueblo = "Riverside", oficio = "electricista", vive = true, lazos = {"nacho"}, textos = { llegada = "Pase, joven, y no se siente ahi, que esa es la silla de ella. Marvella, es visita, pon otra taza.", rescate = "Gracias, joven. El corazon se me fue a destiempo. Ya vuelve a fase. Deme un minuto.", gracias = "Esto me pone a tierra una semana. Le debo una luz, joven. Usted elija donde.", revelacion1 = "Tobias Gilley, electricista de Riverside. Marina, liniero, y en el 74 me pasaron siete mil voltios. Ahora armo luces de bateria para la cuadra.", revelacion2 = "Marvella no se fue a cuidar a ninguna hermana. Se fue con un vendedor de alimento a Tampa en el 88. Murio alla. Yo le sigo poniendo su taza.", revelacion3 = "El forastero de la casa de la esquina es Lasco Fyffe, el hombre con que se fue Marvella. Llego con la pierna rota y una caja de cosas de ella. Lo cuido. Hablamos de ella.", diario_conocer = "Tobias Gilley, electricista de Riverside. Pone dos tazas en la mesa. Los jueves el Padre Nacho le pregunta cuantos son en la casa. Dice dos.", diario_final = "Tobias cuida al hombre que le quito a su mujer. Le lleva sopa y luz. Los dos la extranan igual.", mudanza = "Tobias llega a la iglesia con un banco de baterias en una carretilla y, detras, en una silla de ruedas que armo el mismo, a Lasco Fyffe. Pide la sacristia chica para Lasco y un rincon para trabajar. Arma luces para el patio y un timbre para la puerta. La primera noche pone una sola taza en la mesa. La segunda, se sienta con Lasco y le cuenta al Padre, delante de todos, quien es ese hombre. Nadie le tiene lastima. Le pasan el pan.", muerte = "Tobias Gilley murio en un encargo. Lasco Fyffe pregunto toda la noche por la luz de las ocho." } },
    { id = "s028", nombre = "Ina", apellido = "Lyons", apodo = "Diccionario", sexo = "m", edad = 25, pueblo = "Rosewood", oficio = "policia", vive = true, lazos = {"hector", "rosa"}, textos = { llegada = "Alto. Policia de Rosewood. Nombre completo, y deletreelo si es raro.", rescate = "Gracias. Se escribe g-r-a-c-i-a-s y no se dice lo suficiente. Lo anoto en la libreta.", gracias = "Recibido conforme. Lo pongo en mi libreta con su nombre bien escrito.", revelacion1 = "Ina Lyons, policia de Rosewood, una de seis. Campeona estatal de ortografia en el 81, como mi mama en el 62. A las seis le saco el crucigrama a la Misia Rosa.", revelacion2 = "Mi copa del 81 es falsa. En la final lei la carpeta del pronunciador en el receso. Por eso no la toco. Por eso no dejo pasar ni una falta.", revelacion3 = "Tengo la bolsa del correo de mi papa. Abro las cartas de Rosewood con vapor y las leo. Algunas las entrego. Otras las quemo. Decido yo lo que la gente alcanza a saber.", diario_conocer = "Ina Lyons, policia de Rosewood. Le saca el crucigrama a la Misia Rosa y en el 92 le puso una multa a Hector Jr. Corrige los letreros.", diario_final = "Ina lee el correo de todo Rosewood y decide que cartas llegan. Le pedi que me dejara entregar una. Me dio la de la calle Pine.", mudanza = "Ina llega a la gasolinera con el uniforme planchado, su libreta y una bolsa de correo de lona. Pide hacer las guardias de la manana y un cajon para archivar. A las seis toma achicoria con la Rosa y le saca el crucigrama de memoria. Abre la bolsa delante de todos y reparte las cartas que quedan, cerradas, sin leer. Las que no tienen a quien, las deja en la caja, en orden alfabetico. Por si alguien vuelve. La de la calle Pine la lleva ella misma.", muerte = "La oficial Ina Lyons murio de servicio. Escribi su nombre con cuidado: I-n-a. Las cartas quedaron sin repartir." } },
    { id = "s029", nombre = "Thaddeus", apellido = "Hacker", apodo = "Mister Chuletas", sexo = "h", edad = 62, pueblo = "Muldraugh", oficio = "profesora", vive = true, lazos = {"cabo"}, textos = { llegada = "Joven. Pase. Anatomicamente hablando, esta usted entero. Eso ya es mucho.", rescate = "Gracias, joven. A los sesenta y dos uno corre como un lomo con nervio: mal y tarde.", gracias = "Esto, para la comisaria. El Cabo paga lo que promete y yo corto lo que me traen.", revelacion1 = "Thaddeus Hacker, profesor de biologia de Muldraugh y carnicero treinta inviernos. Le vendia huesos para caldo a don Ernesto Mandados, el papa del Cabo.", revelacion2 = "En la primavera del 73 la carne se fue a las nubes. Seis semanas mezcle caballo en la carne molida. Medio Muldraugh comio caballo. Mi mujer no lo sabe.", revelacion3 = "La camara de frio de la carniceria no esta vacia. Desde agosto cuelga de la cadena un soldado muerto, de los que caminan. Lo estudio de noche. El Cabo no sabe. Hettie tampoco.", diario_conocer = "Thaddeus Hacker, profesor y ex carnicero de Muldraugh. Les explica a los ninos donde esta el higado. Habla como un libro de anatomia.", diario_final = "Thaddeus tiene un muerto colgado en la camara de frio y lo estudia con una vela. Dice que es ciencia. Le pedi que lo bajara. Lo pensara.", mudanza = "Thaddeus llega a la comisaria con la hachuela de su padre envuelta en un delantal, Hettie del brazo y una caja de libretas. Pide el patio de atras para despiezar y un pizarron. Los miercoles da clases de anatomia a los ninos, con un conejo en la mesa. La noche antes de venirse bajo a la camara de frio con la hachuela y una vela. Volvio sin la libreta y con la hachuela limpia. Hettie no pregunto. El tampoco dijo nada. Desde esa noche duerme de corrido, por primera vez desde julio.", muerte = "Thaddeus Hacker murio en el camino. Hettie pidio que lo enterraran con el delantal puesto." } },
    { id = "s030", nombre = "Etta", apellido = "Castle", apodo = "la senorita Castle", sexo = "m", edad = 37, pueblo = "West Point", oficio = "enfermera", vive = true, lazos = {"chela", "eduardo"}, textos = { llegada = "Respire. No, mas hondo. Asi. Ahora digame donde le duele.", rescate = "Un, dos, tres. Ya. Gracias. Tengo el pulso en ciento veinte. Se me pasa.", gracias = "Con esto hago tres curaciones y una semana de presiones. Gracias, desde el principio.", revelacion1 = "Etta Castle, enfermera de West Point. Le puse la antitetanica a medio cuartel, al hijo de la Chela tambien. Le di piano a medio pueblo. Hago las rondas a pie.", revelacion2 = "Mi novio murio en Beirut en el 83. La noche antes leyo mi carta: le decia que no me iba a casar con el. Su mama me dice nuera hasta hoy. Yo la dejo.", revelacion3 = "En octubre encontre en la caja de Corliss su ultima carta, sin mandar. Aceptaba que lo dejara. Velma nunca abrio esa caja. La queme en la estufa para que siga creyendo.", diario_conocer = "Etta Castle, enfermera de West Point. Me tomo el pulso antes de saludarme y me dijo que respirara.", diario_final = "Etta quemo la ultima carta de un muerto para que su madre no supiera la verdad. Dice que lo hizo por ella. No se si le creo.", mudanza = "Etta llega al cuartel con su maletin, Velma del brazo y el metronomo de su mama en el bolsillo. Pide un rincon con buena luz para curar y una silla para Velma junto a la olla. Hace la ronda del campamento todas las mananas, toma presiones y obliga a la Chela a mostrarle las manos. Una noche, cuando hay musica de radio, se sienta al lado de Velma y le cuenta lo de la carta. Velma le toma la mano y no la suelta.", muerte = "La enfermera Etta Castle murio en la ronda. Velma Embry sigue preguntando por su nuera." } },
    { id = "s031", nombre = "Luther", apellido = "Sandoval", apodo = "Cookie", sexo = "h", edad = 74, pueblo = "Riverside", oficio = "cocinera", vive = true, lazos = {"duggan", "nacho"}, textos = { llegada = "Pase, muchacho, y no me revuelva la olla. Esto va a fuego lento, como todo lo que sirve.", rescate = "Me sacaste del fuego, muchacho. Mi papa diria que fue cosa de Dios. Yo digo que fuiste tu.", gracias = "Con esto hay olla para el jueves. Dios te lo pague, que yo pago en caldo.", revelacion1 = "Soy Luther Sandoval, el cocinero de Riverside. Treinta inviernos con el cafe de la esquina del rio. Ahora cocino para el que traiga tarro, y los viernes para el Padre.", revelacion2 = "Mi papa predicaba con culebras en la mano, alla en Bell County. Yo les daba de comer. A los diez me mordio una en pleno culto. Por eso no entro a las iglesias.", revelacion3 = "De nino le sacaba el veneno a las culebras de mi papa antes de cada culto. El creia que lo cuidaba la fe. Me fui de la casa y la primera culebra con veneno lo mato.", diario_conocer = "Luther Sandoval, cocinero viejo de Riverside. Le cocina los viernes al Padre Nacho. Cojea, no oye de un lado y nadie le revuelve la olla.", diario_final = "Luther le sacaba el veneno a las culebras de su padre para que la fe no lo matara. Todavia le paga a alguien para que nada lo muerda.", mudanza = "Me traje la caldera, Padre, y el remo. La caldera va en el patio y no en su cocina, que el burgoo humea. Quint duerme donde usted diga; yo, cerca del fuego, que los pies ya no me calientan solos. Los jueves sigo haciendo la olla para la calle del correo: eso no se corta, y no me pregunte por que. Y otra cosa. El domingo pasado me sente en la ultima banca. No oi nada, que de ese lado estoy sordo. Pero me sente. No se le ocurra echarme la bendicion, que me paro y me voy.", muerte = "Luther Sandoval murio en el encargo. Nadie mas sabe el burgoo. El jueves la olla no hierve." } },
    { id = "s032", nombre = "Johanna", apellido = "Hatfield", apodo = "Pastora Jo", sexo = "m", edad = 49, pueblo = "Rosewood", oficio = "pastora", vive = true, lazos = {"lucia", "rosa"}, textos = { llegada = "Pase, hermano. Si viene a la clase, sientese adelante. Si viene a robar, tambien: aqui nadie se queda sin leccion.", rescate = "Ave Maria Purisima... digo, Senor bendito. Llego a tiempo. Los ninos estan bien? Primero los ninos.", gracias = "Dios se lo pague. Y si Dios anda ocupado, le pago yo con una clase de lectura, que nunca sobra.", revelacion1 = "Soy la pastora de la metodista de Rosewood. Ahora mas bien la maestra: siete ninos y una pizarra. La Misia Rosa me manda un tarro de leche para ellos cuando puede.", revelacion2 = "Fui la hermana Maria Columba, maestra de cuarto en Covington. Colgue el habito en el 70. A todos les digo que Dios me llamo a predicar. No digo con que voz me llamo.", revelacion3 = "En agosto vino el papa de Tansy y Sonny a buscarlos. Le dije que la Guardia se habia llevado a los ninos al cordon. Se fue a pie a Brandenburg. Ellos dormian en la pieza de al lado.", diario_conocer = "La pastora Jo, de la metodista de Rosewood. Ex monja, flaca, con rodillas que suenan. Le hace clase a siete ninos en la iglesia.", diario_final = "Johanna le mintio al padre de los ninos para quedarselos. Dice que Dios se la cobre a ella. No se si Dios cobra, pero ella ya esta pagando.", mudanza = "Me traje la pizarra y a los dos ninos, Misia Rosa. Tansy ya suma; Sonny todavia no, pero aprende. Si me da un rincon detras del mostrador, hago clase todas las mananas, una hora, y despues me pongo a lo que usted mande. La escuela dominical la hago diaria, que los domingos ya no se notan. No le voy a predicar a nadie que no quiera; con los ninos me basta. Dicen que en March Ridge hay una monjita que canta para los muertos; yo enseno a los vivos, que es mas facil. Y si alguien de su gente necesita confesarse, no soy cura, pero oigo bien y no repito.", muerte = "La pastora Jo murio en el encargo. Tansy y Sonny se quedaron sin nadie por segunda vez. Alguien tiene que decirles." } },
    { id = "s033", nombre = "Jimmy", apellido = "Burkhart", apodo = "el Tieso", sexo = "h", edad = 24, pueblo = "Muldraugh", oficio = "carpintero", vive = true, lazos = {"cabo", "valentina"}, textos = { llegada = "No se mueva rapido, senor. Aqui todo esta quieto y me gusta asi. Que necesita?", rescate = "Gracias, senor. Me quede quieto como siempre, pero esta vez no alcanzaba. No tendra un inhalador?", gracias = "Con esto respiro el mes. Le hago un cajon cuando lo necesite. Perdon, no quise decir eso.", revelacion1 = "Soy Jimmy Burkhart, el carpintero de Muldraugh. Hago cajones y tablas para ventanas; el Cabo me paga con inhaladores. Antes disecaba animales con mi abuelo.", revelacion2 = "En el 91 se me pudrio en el congelador el perro de una viuda. Le diseque otro igual, recogido en la carretera. Ella lo supo siempre y lo quiso igual. Me lo dijo antes de morir.", revelacion3 = "La senora Docia murio en septiembre y se levanto en la manana. No pude. La amarre a su sillon con el perro en la falda. Voy todas las tardes a peinarla. Me ayuda a enterrarla?", diario_conocer = "Jimmy Burkhart, carpintero de Muldraugh. Flaco, con asma, hace cajones para el Cabo. Fue a la escuela con Valentina. Se queda tan quieto que da miedo.", diario_final = "Jimmy tenia a la senora Docia amarrada en su sillon, muerta y levantada, con el perro en la falda. La enterramos al lado del perro de verdad.", mudanza = "Me traje las herramientas, Cabo. A Buford lo deje en la puerta del taller, que alguien tiene que cuidarla. Puedo dormir en el galpon de las patrullas; no molesto. Le hago tablas para las ventanas, cajones, lo que me anote. Solo le pido que no me toquen por la espalda, y que si me da el asma de noche alguien golpee dos veces la pared. Y no me pida que despida a los muertos. Les hago el cajon a medida, eso si, con las esquinas a cola de milano. Ellos no se quejan.", muerte = "Jimmy Burkhart murio en el encargo. Le hicimos el cajon nosotros y nos quedo chueco. El se habria reido para adentro." } },
    { id = "s034", nombre = "Rhoda", apellido = "Griffith", apodo = "Ma Griffith", sexo = "m", edad = 61, pueblo = "West Point", oficio = "cazador", vive = true, lazos = {"chela"}, textos = { llegada = "Criatura. Hable despacio y no pise las trampas. Lo que se mata se come; lo que no, se deja quieto.", rescate = "Mm-jm. Las gracias no se usan en mi casa. Tome: una ardilla limpia. Vale mas.", gracias = "Cartuchos. Con esto Tolan come un mes. Le quedo debiendo carne, criatura, y yo pago.", revelacion1 = "Rhoda Griffith, de West Point. Cazo, curto pieles y pongo trampas. A la Tia Chela le cambio cueros por sal. Tuve nueve hijos; hoy tengo seis bocas en el cerro.", revelacion2 = "A Clell lo mato un roble en el 65. Me quede con ocho en la casa, uno en la panza y la escopeta de un tiro de mi papa. Ese invierno comimos mapache. Nadie se murio de hambre.", revelacion3 = "La novena no se murio: se la di a mi hermana en Owensboro, como se da un cachorro. Y la primera noche mi hijo Farris me pidio un minuto para despedirse. No se lo di. Una bala.", diario_conocer = "Rhoda Griffith, cazadora vieja de West Point. Casi tuerta, seca, con tabaco en el cachete. Seis bocas dependen de su escopeta.", diario_final = "Rhoda no le dio a su hijo el minuto para despedirse, y regalo una hija. Dice que todo fue para que alguien comiera.", mudanza = "Vine con la escopeta, la sal y la familia, senora Chela. Wilda cocina, si usted la deja tocar la olla. Mabel cose. Tolan y Pip ponen trampas conmigo en el cerro de atras. Yo no me siento a la mesa con nadie: como de pie, en la puerta, como siempre. Por la carne no me de las gracias, que no se usa. Y si un dia no vuelvo del cerro, no me busque. El ojo malo es el izquierdo; el cerro lo conozco con el otro.", muerte = "Rhoda Griffith murio en el encargo. Dejo la escopeta de un tiro limpia, como cada domingo. Tolan ya sabe usarla." } },
    { id = "s035", nombre = "Jethro", apellido = "Thibodeaux", apodo = "Jet", sexo = "h", edad = 36, pueblo = "Riverside", oficio = "granjero", vive = true, lazos = {"cabo", "duggan"}, textos = { llegada = "Copiado, lo veo. Identifiquese despacio, que en persona me trabo. Por radio no.", rescate = "Diez-cuatro... gracias. Si no llega usted, nadie contestaba. Otra vez nadie.", gracias = "Copiado. Con esto la antena aguanta el invierno. Lo anoto con la hora, como todo.", revelacion1 = "Jethro Thibodeaux, granjero de Riverside. Cajun de Houma. Doce inviernos de operador en el Puesto 4 de la Policia Estatal. Ahora soy la radio de Riverside, desde el granero.", revelacion2 = "Una noche del 88 sali a fumar y un trooper pidio auxilio. Nueve minutos sin respuesta. Le dieron dos balazos. En el registro escribi que se cayo el receptor.", revelacion3 = "Por radio hago de Guardia: unidad Bravo, control en el puente. Por eso los del taller no bajan al camino del rio. En octubre una familia oyo mi control y se devolvio a Louisville.", diario_conocer = "Jethro, el granjero de la antena en el silo. En persona tartamudea; por radio habla como un reloj. El Cabo le conoce la voz.", diario_final = "La Guardia del puente de Riverside es Jethro con un microfono. Cuida a su gente y le cierra el camino a la ajena. No sabe con cual quedarse.", mudanza = "Me traje la radio, Padre, y la antena, si me deja subirla al campanario, que es lo mas alto de Riverside. La familia trae las vacas que quedan. Yo hago guardia de radio de noche: anoto quien llama y a que hora, como en el Puesto. No le voy a pedir que rece por mi. Le pido una sola cosa: si alguna vez me oye hablar con otra voz, no me pregunte todavia. Ya le voy a contar, con la mia, cuando me salga sin trabarme. Diez-cuatro.", muerte = "Jethro Thibodeaux murio en el encargo. Esta noche nadie contesta en el granero. La Guardia del puente tampoco." } },
    { id = "s036", nombre = "Aurelia", apellido = "Gayheart", apodo = "la Campeona", sexo = "m", edad = 73, pueblo = "Rosewood", oficio = "camionero", vive = true, lazos = {"rosa"}, textos = { llegada = "Pull! Asi pido las cosas, chiquillo. Hable fuerte, que de este lado no oigo nada.", rescate = "Me sacaste del techo de la cabina. Bien tirado, chiquillo. Para ser hombre, digo.", gracias = "Esto vale un campeonato. No te lo pago con trofeo: te lo pago con punteria cuando la necesites.", revelacion1 = "Aurelia Gayheart, camionera de Rosewood. La Tillie es mia. Cargo en la bomba de la Rosa desde el 59; el finado Hector me hacia los frenos. Y fui campeona de tiro al plato.", revelacion2 = "Me case con Garrard Holbrook, que tiraba bien y tomaba mejor. En el desempate del 50 falle el ultimo plato a proposito para que ganara el. Esa noche me pidio matrimonio.", revelacion3 = "En agosto tuve en la mira al que me robaba el diesel. Tenia la nuca de mi nieto Jason. Falle a proposito. Volvio con cuatro y se llevaron todo. Dije que llegaron mientras yo dormia.", diario_conocer = "Aurelia Gayheart, camionera de 73 y campeona de tiro. Sorda de un lado, grita Pull para pedir las cosas.", diario_final = "Aurelia fallo dos platos a proposito en su vida: uno por un marido y otro por un nieto que tal vez no era. Los dos le salieron caros.", mudanza = "Me vine con la Model 12 y sin la Tillie, Rosa, que esta seca. Si algun dia aparece diesel, la Tillie carga treinta parados en la caja, y manejo yo: el doctor ya no me lo prohibe, porque no hay doctor. Mientras, ponme en el techo del taller con una caja de cartuchos y nadie entra por la 31 sin que yo lo vea. Duermo poco, como poco y no te pago el cafe, que tu no cobras. Y no me digas senora mayor.", muerte = "Aurelia Gayheart murio en el encargo, tirando. Conto los tiros hasta el final. No fallo ninguno." } },
    { id = "s037", nombre = "Marvin", apellido = "Stacy", apodo = "el Mandolinas", sexo = "h", edad = 48, pueblo = "Muldraugh", oficio = "mecanico", vive = true, lazos = {"cabo", "duarte"}, textos = { llegada = "Hermanito, hable bajo. Aqui la musica se acabo el nueve de julio. Que necesita, una correa o un milagro?", rescate = "Como dice la cancion... ya no me acuerdo cual. Gracias, hermanito. Esta vez no tuve que tocar.", gracias = "Esto era lo que faltaba. Le arreglo lo que quiera y no le pregunto de donde viene. Eso se lo hago gratis.", revelacion1 = "Marvin Stacy, mecanico de Muldraugh. Stacy's Garage, en la 31W. El Cabo me trae la camioneta. Antes tocaba mandolina con los Rolling Fork Boys. Casi grabamos en Nashville.", revelacion2 = "La primera noche me subi al techo y toque tres horas para que los muertos me miraran a mi y no a una senora con dos chicos. Me sangraron los dedos. No he vuelto a tocar.", revelacion3 = "El tanque de diesel bajo mi taller no se fuga. Se lo vendo de a bidon al Tecolote, por cigarros y cuerdas. Al Cabo le digo que se lo traga la tierra. Como la cancion de Ancel: lo ajeno.", diario_conocer = "Marvin Stacy, mecanico de la 31W. Habla como cancion, tiene la mano izquierda torcida y ya no toca.", diario_final = "Marvin le robo una cancion a su hermano y el diesel a su pueblo, de a bidon. Pero una noche toco tres horas por una desconocida.", mudanza = "Me traje la caja de herramientas y la mandolina, Cabo, aunque no la toco. Le arreglo las camionetas que tenga, las que andan y las que no. Y le debo una cosa, para que la anote con tinta: el tanque de abajo del taller no se fuga. Lo vendi de a bidon al Tecolote. Lo que queda es del pueblo y desde hoy no lo toca nadie, ni yo. Si quiere borrarme de la libreta, esta en su derecho. Si no, anoteme como mecanico.", muerte = "Marvin Stacy murio en el encargo. Dejo la mandolina en su estuche, con cuerdas nuevas y plata adentro. Nadie sabe la cancion entera." } },
    { id = "s038", nombre = "Mabel", apellido = "Farmer", apodo = "Farmer", sexo = "m", edad = 23, pueblo = "West Point", oficio = "costurera", vive = true, lazos = {"gladys"}, textos = { llegada = "Perdon, perdon, pase. Cuidado con las pieles, que estan recien curtidas. Le hago un gorro?", rescate = "Dios te salve Maria... perdon. Gracias. Gracias. No le cuente a la senora Rhoda que llore.", gracias = "Con estas agujas le coso el invierno entero a la familia. Perdon que no tenga como pagarle. Le debo un gorro.", revelacion1 = "Soy Mabel Farmer, costurera de West Point. Ahora coso pieles en la casa del cerro, con mi suegra. Aprendi con las monjas y con dona Gladys, en Muldraugh.", revelacion2 = "Me crie en el Hogar del Sagrado Corazon, en Louisville. Me dejaron a los tres con un abrigo amarillo. Despues encontre a mi mama, cajera en un Kroger. Nunca le dije quien era.", revelacion3 = "En octubre fui sola a Louisville. Dije que por remedios, pero fui por ella. Estaba vuelta, detras de la caja 4, con su delantal. Le dije Soy Mabel por el vidrio. Lo dije bien.", diario_conocer = "Mabel Farmer, costurera de West Point. Pide perdon por todo, ve poco y cose gorros de mapache para la familia de su suegra.", diario_final = "Mabel le dijo a su madre quien era. La madre ya no podia oirla. Ella dice que se acerco al vidrio. Yo le creo.", mudanza = "Perdon por las cajas, senora Chela. Son pieles, agujas y la Singer chica que me regalo dona Gladys cuando me case. Le coso lo que necesite el cuartel: chaquetas, frazadas, guantes para las mangueras. No necesito pieza; me acomodo en cualquier rincon con luz para la aguja. Y si alguien va a Muldraugh, que pregunte por dona Gladys, arriba de su taller. Que le digan que la Mabel vive, que cose para el cuartel de bomberos y que el ruedo invisible todavia me sale.", muerte = "Mabel Farmer murio en el encargo. Dejo un gorro a medio coser. Nadie mas sabe el ruedo invisible." } },
    { id = "s039", nombre = "Silas", apellido = "Carver", apodo = "el Campeon", sexo = "h", edad = 60, pueblo = "Riverside", oficio = "electricista", vive = true, lazos = {"hector", "nacho"}, textos = { llegada = "Campeon. Pase, y no me de la espalda, que tengo reflejos viejos. Que se le corto?", rescate = "Me tenian contra el colchon, campeon. Esta vez toque la lona y alguien me levanto. Gracias.", gracias = "Con esto la casa tiene luz hasta enero. Hay que hacer tierra, campeon, y usted me la hizo.", revelacion1 = "Silas Carver, electricista de Riverside desde el 61. Mi mejor aprendiz fue Ramon Bencina, el papa del Junior de la bomba de Rosewood. Y fui campeon de lucha en el 51.", revelacion2 = "En el 51 me gano Lucius Mayes, el campeon de los colegios negros, a escondidas, en un gimnasio de iglesia. Un minuto cuarenta. La medalla dice campeon. Miente.", revelacion3 = "Mi yerno no esta enterrado en la orilla. Le pegaba a mi hija. Lo saque de la cama con una llave y lo eche al camino sin botas. A Janelle le dije que lo mordieron. Me dio las gracias.", diario_conocer = "Silas Carver, electricista viejo de Riverside, con oreja de coliflor. Aprieta la mano como si fuera a inmovilizarte.", diario_final = "Silas echo a su yerno al camino y le dijo a su hija que lo habia matado mordido. Su nieto llora a un padre que esta vivo.", mudanza = "Me vine con la familia y con las baterias, Padre. Le armo luz en la iglesia si me deja, sin tocar lo que ya esta hecho: los cables de otro se respetan. A misa no voy, pero le barro la escalera si quiere. Una cosa: usted boxeaba y yo luchaba. Si un dia me ve agarrar a alguien y no soltarlo, peguele a mi, y fuerte. Mi hija cree que soy bueno, y mis nietos tambien. Usted ayudeme a que sea verdad.", muerte = "Silas Carver murio en el encargo, agarrado a algo que no solto. Janelle sigue creyendo que su marido esta en la orilla." } },
    { id = "s040", nombre = "Pansy", apellido = "Rosales", apodo = "la Recepcionista", sexo = "m", edad = 35, pueblo = "Rosewood", oficio = "policia", vive = true, lazos = {"rosa"}, textos = { llegada = "No me cuentes, carino, dejame adivinar: vienes de paso. Todos dicen eso. Nombre para el registro?", rescate = "Bien, carino. Te anoto en el registro como huesped de honor. Tarifa cero, como a todos.", gracias = "Esto va derecho a la pieza 6. Crystal te lo va a agradecer mas que yo, y yo ya te lo agradezco harto.", revelacion1 = "Pansy Rosales, policia de Rosewood, patrullero 2, aunque ya no hay patrullero. Me crie en el Dixie Star, el motel de la 31. Ahora es mio otra vez, sin papeles.", revelacion2 = "A Rudy, mi marido, lo agarro la Estatal en el 89 por una llamada anonima. El cree que fue su primo Beto. La llamada la hice yo, desde el Kroger de Brandenburg.", revelacion3 = "Los rifles de la pieza 9 no salieron de un camion de la Guardia. Eran de Rudy, robados del Fuerte, enterrados detras de la maquina de hielo. Yo lo sabia desde el 89 y me lo calle.", diario_conocer = "Pansy Rosales, policia de Rosewood. Lleva el registro de un motel donde nadie paga y les manda los hambrientos a la Misia Rosa.", diario_final = "Pansy entrego a su marido y se quedo con sus rifles. Con esos rifles cuida a nueve desconocidos. No se si eso la absuelve.", mudanza = "Me traje el libro de registro y a Crystal, Misia Rosa. Los rifles tambien, pero esos van donde usted diga y con llave. Yo anoto a cada uno que llega: nombre, de donde viene, cuantas noches. Usted pregunta lleno o normal; yo pregunto de paso o se queda. Nos vamos a entender. Hago guardia en la entrada de la 31 con el uniforme puesto, que todavia asusta a alguno. Y si me ve leyendo el registro viejo de noche, no me pregunte. Son treinta y cinco tomos de chismes y no los suelto.", muerte = "Pansy Rosales murio en el encargo. Crystal anoto su nombre en el registro del Dixie Star. Check-out: hoy." } },
    { id = "s041", nombre = "Elmo", apellido = "Pace", apodo = "el Profesor", sexo = "h", edad = 72, pueblo = "Muldraugh", oficio = "profesora", vive = true, lazos = {"cabo"}, textos = { llegada = "Veamos. Llego usted a las... da igual, yo lo anoto. Pase, joven, y no me toque los relojes.", rescate = "Un minuto mas y no lo cuento. Un minuto, joven, que en un reloj es una verguenza.", gracias = "Pilas nuevas. Desde hoy Colorado me vuelve a dar la hora. Usted no sabe lo que eso vale aqui adentro.", revelacion1 = "Fui profesor de fisica treinta y tres inviernos en la secundaria de Muldraugh. Hoy doy clases en mi cocina y pongo en hora el pueblo con una radio de onda corta.", revelacion2 = "Le puse un 58 a un muchacho en 1967. Con 60 se iba a la universidad. Lo llamaron a Vietnam y volvio en un cajon. Dos puntos, joven. Desde entonces no pongo notas rojas.", revelacion3 = "La mama de Wren toco la bocina a las nueve y cinco. Yo le pedi diez minutos mas, por una ecuacion. Wren cree que su mama llego tarde. No llego tarde. Yo la hice esperar.", diario_conocer = "Conoci al Profesor Pace en la calle Hill. Once relojes en hora y uno parado. El cabo lo tiene anotado en su libreta con la hora exacta.", diario_final = "El Profesor por fin le conto a Wren lo de los diez minutos. Ella no se fue. Le dio cuerda al reloj de su padre. Seguia parado, pero el le dio cuerda.", mudanza = "Me traje los relojes, joven, los once, y el que no anda tambien. Los colgue en la pared mas larga de la comisaria y les quite las campanadas, que el ruido aqui adentro no ayuda a nadie. Cada manana pongo la radio de Colorado y pongo en hora al campamento entero. El cabo dice que es la primera vez que la comisaria tiene la hora correcta. Wren da clases conmigo a los mas chicos. Yo les explico la fisica con un pendulo hecho con un perno y un cordon de zapato. Me tiemblan las manos, pero el pendulo no.", muerte = "El Profesor Pace murio a la hora exacta, como le habria gustado. Pare sus relojes. Wren se quedo con la lupa." } },
    { id = "s042", nombre = "Sadie", apellido = "Petrov", sexo = "m", edad = 47, pueblo = "West Point", oficio = "enfermera", vive = true, lazos = {"chela", "nacho"}, textos = { llegada = "Pasa, corazon, pasa. Sientate en el baul de Hamlet, que el otro tiene ratones. Que te duele?", rescate = "Ay, cielo, que entrada. Llegaste justo antes del telon. Dame la mano, que me tiembla y no me gusta.", gracias = "Antibioticos de verdad. Esto no lo actua nadie, corazon. Esto salva gente. Gracias.", revelacion1 = "Soy enfermera, cielo. Catorce inviernos de noche en el hospital de Fort Knox. Ahora curo sobre un escenario en West Point, entre los trajes de los River Players.", revelacion2 = "A los dieciocho me fui a Nueva York a ser actriz. Me llamaron para una teleserie y yo iba en un bus de vuelta a Kentucky, embarazada. Nunca supe si era buena.", revelacion3 = "La regla de los tres dias sin fiebre la invente yo, para que un hombre dejara de llorar. Su mujer se volvio al quinto dia. Y la gente la sigue repitiendo. Por mi.", diario_conocer = "Conoci a Sadie Petrov, la enfermera de West Point. Cura en un escenario y habla como si hubiera publico. Hay publico: los heridos.", diario_final = "Sadie le dijo a todo West Point que la regla de los tres dias es mentira. No hubo aplausos. Se quedo sentada en el borde del escenario, sin actuar nada.", mudanza = "Me traje un baul de vestuario y el botiquin, corazon, nada mas. En el cuartel me dieron un rincon al lado de la cocina y la Chela me dijo que aqui come el que trabaja, asi que trabajo. Curo en la mesa larga despues de la comida. La primera noche les explique a todos que no hay regla, que una mordida es una mordida, y no actue nada. Me costo mas que cualquier estreno. Los domingos les hago una escena chica a los ninos, bajito, sin ruido. Le pregunto a cada uno que llega por mi Natalie. Y si alguien va al University Hospital, que busque a la Charo Pegas, la zurda que desafina con Johnny Cash. Hicimos juntas el curso de quemados.", muerte = "Sadie Petrov murio en el encargo. Sin telon y sin publico. Le deje los labios pintados, como se los pintaba antes del turno." } },
    { id = "s043", nombre = "Ozzie", apellido = "Ward", apodo = "Ozzie", sexo = "h", edad = 22, pueblo = "Riverside", oficio = "cocinera", vive = true, lazos = {"nacho"}, textos = { llegada = "Jefe! Suba despacito, que la escalera del silo no perdona. Llega justo para la polenta.", rescate = "Uf, jefe, eso fue una pasada a ras. Yo no corro, ya sabe. Gracias por correr por mi.", gracias = "Sal de verdad. Con esto la polenta pasa de castigo a comida. Le guardo el primer plato, jefe.", revelacion1 = "Soy el cocinero de la bodega de granos de Riverside. Antes la segunda plancha del Bluebird, con el pan de la panaderia Hollis. Cocino de pie, con baston.", revelacion2 = "Fui piloto fumigador. A los dieciocho volaba sobre el tabaco con mi tio. En el noventa y dos me comi un cable y quede con un fierro en la pierna.", revelacion3 = "El agua mala de la vega fui yo, jefe. Vacie dos bidones de paration en el arroyo para parar a los muertos. No respiran. Se murio el viejo Bratcher.", diario_conocer = "Conoci a Ozzie Ward arriba de un silo en Riverside. Cojea, cocina maiz para nueve y mira el cielo como si le debiera algo.", diario_final = "Ozzie bajo a la vega y les dijo que no sacaran agua del arroyo, y por que. Despues le conto a su tio lo del cable. El tio no le hablo en una semana.", mudanza = "Me traje la piedra de moler y el baston, jefe. En la iglesia de piedra la cocina es chica pero tiene una ventana que mira al cielo, y con eso me basta. Le hago al Padre pan de maiz los domingos y los ninos me piden cabritas. El agua la hiervo dos veces y la saco del pozo, nunca del arroyo. Mi mama vino conmigo; el tio se quedo en la bodega con los demas, por el maiz. Cocino de pie, siempre. Si me siento, me quedo pensando, y la polenta se quema.", muerte = "Ozzie Ward murio en el encargo. No podia correr y no corrio. Le deje el baston colgado en la barra de la cocina." } },
    { id = "s044", nombre = "Krystyna", apellido = "Trujillo", apodo = "la Pastora", sexo = "m", edad = 59, pueblo = "Rosewood", oficio = "pastora", vive = true, lazos = {"nacho", "rosa"}, textos = { llegada = "Mireme cuando hable. Asi, de frente. Si se tapa la boca, usted no existe.", rescate = "No los oi venir. Nunca los oigo. Usted si. Gracias. Mireme: gracias.", gracias = "Gotas para los ojos. Ahora puedo seguir mirandole la boca a la gente un tiempo mas. Dios se lo pague.", revelacion1 = "Soy la pastora del camino viejo de Rosewood. Sorda de nacimiento. Le doy ordenes a mis perros con silbidos que nunca he oido. Los domingos hago la catequesis.", revelacion2 = "Le lei en los labios al doctor que el corazon de mi marido no aguantaba otra esquila. No le dije nada. Esquilamos igual. Se murio en la oveja numero once.", revelacion3 = "Nunca me confirme. Mi mama me saco del catecismo porque no oigo. Lo que enseno lo lei en los labios del cura. Los ninos rezan el fruto de tu viento. No se cual esta mal.", diario_conocer = "Conoci a la Pastora de Rosewood. Sorda. Hay que hablarle de frente. Me leyo la boca antes de que yo terminara de hablar.", diario_final = "Le lei a la Pastora el Ave Maria de un libro, despacio, de frente. Se rio de su viento. Los ninos ahora rezan las dos versiones.", mudanza = "Me traje veinte ovejas, a Lucero y a Brujo. En la gasolinera la luz nunca se apaga, y eso para mi es una bendicion: con luz les leo la boca a todos, tambien de noche. La Misia Rosa me sento al lado de la caja, de frente, y me hablo despacio una hora entera. Yo esquilo y hilo. Los domingos hago la catequesis detras del taller, con senas, sin ruido, y un muchacho que oye me lee el catecismo en voz alta para que yo le mire la boca. Las ovejas pastan al lado de la bomba.", muerte = "La Pastora murio en el encargo. No oyo nada; nunca oyo nada. Los perros la esperaron toda la noche." } },
    { id = "s045", nombre = "Burl", apellido = "Meade", sexo = "h", edad = 34, pueblo = "Muldraugh", oficio = "carpintero", vive = true, lazos = {"cabo"}, textos = { llegada = "A ver, mire. Usted entro por la calle Walnut, por donde estaba la casa de los Coombs. Pase. Cuidado el escalon.", rescate = "Gracias. Yo se donde esta cada casa del pueblo, pero no sabia por donde salir de esta. Ahora si.", gracias = "Clavos de verdad. Con esto le hago cajon a tres familias que estan esperando. Dios se lo pague.", revelacion1 = "Soy el carpintero de Muldraugh. Hago cajones, cruces y postigos. Antes dibujaba los mapas del condado en el subsuelo del juzgado. Se el nombre de cada arroyo.", revelacion2 = "En el ochenta y nueve corri una linea doce metros en un plano por mil quinientos dolares. Una viuda perdio su vertiente. Ahora todo el pueblo toma agua de esa vertiente.", revelacion3 = "De los treinta y un cajones que enterre, nueve van vacios o con piedras. Las familias rezan encima. En mi mapa del cementerio tienen una v chiquita, con lapiz.", diario_conocer = "Conoci a Burl Meade, el carpintero de Muldraugh. Me dio direcciones por casas que ya no existen. Tiene el pueblo entero dibujado a mano.", diario_final = "Burl me mostro las v del mapa del cementerio. Me pidio que no se lo dijera a nadie. Despues borro una con el pulgar y escribio un nombre.", mudanza = "Me traje las herramientas de mi papa y el mapa, enrollado en un tubo. En la comisaria el cabo me dio el patio de los patrulleros para taller. Arme en el pasillo una pared entera con el mapa de Muldraugh, casa por casa, y el cabo pone las cruces con tinta. Yo arreglo puertas, techo y escaleras. La primera semana le conte al cabo lo de los cajones vacios. Me miro un rato largo, anoto algo y me dijo: anotado. No se que anoto. Duermo mejor.", muerte = "Burl Meade murio en el encargo. Le hice yo el cajon, con sus herramientas. Este no va vacio." } },
    { id = "s046", nombre = "Twila", apellido = "Fairchild", apodo = "la Coronela", sexo = "m", edad = 71, pueblo = "West Point", oficio = "cazador", vive = true, lazos = {"chela", "hartmann"}, textos = { llegada = "Alto ahi, muchacho. Manos donde las vea. Bien. Ahora suba despacio, que corriendo no se sube a mi loma.", rescate = "Limpio. Bien hecho, muchacho. A mi edad una ya no corre; espera. Usted llego antes que la espera.", gracias = "Balas treinta-treinta. Con esto comen cuatro viudas hasta marzo. Limpio, muchacho. Limpio.", revelacion1 = "Me dicen la Coronela. Fui enfermera del Ejercito veintiocho inviernos, en Leyte y en Vietnam. Hoy cazo y reparto la carne en West Point.", revelacion2 = "En el Tet tenia dos mesas y tres heridos. Mande a un muchacho de diecinueve al final para operar a un capitan. El muchacho podia vivir. En la ficha escribi que llego sin pulso.", revelacion3 = "Cazo en el area de tiro del Fuerte, por un hueco del alambrado. Jerrod Haslett me siguio una noche. La Guardia le disparo. A su madre le dije que no lo habia visto.", diario_conocer = "Conoci a la Coronela en la loma de West Point. Me apunto antes de saludarme. Despues me dio charqui y me reviso las manos.", diario_final = "Traje a Jerrod Haslett desde el alambrado. La Coronela fue con su madre a enterrarlo. Le dijo la verdad junto al hoyo. Ardelle no le solto la mano.", mudanza = "Baje de la loma, muchacho, con el rifle de mi papa y la Biblia. Nada mas. En el cuartel la Chela me puso a cargo del botiquin y de la carne, y me dejo sentarme cerca de la estufa por las rodillas. No me discute; yo tampoco a ella. Salgo a cazar de dia con los muchachos y les enseno a esperar y a tirar una sola vez. Al alambrado del Fuerte no los llevo. A ese lugar no vuelve nadie conmigo.", muerte = "La Coronela murio en el encargo. Una bala, sin sufrir. Como ella le enseno a todos." } },
    { id = "s047", nombre = "Delmer", apellido = "Hurt", apodo = "el Millonario", sexo = "h", edad = 46, pueblo = "Riverside", oficio = "granjero", vive = true, lazos = {"duggan", "nacho"}, textos = { llegada = "Pase, compadre, pase. Bienvenido a la casa grande. Fue mia, despues no, ahora otra vez. Fijese usted.", rescate = "Como le digo, compadre: me salvo el pellejo. Esa tirada la gano usted, no yo.", gracias = "Maiz. Maiz de verdad. Con esto la Kayla come en enero. Usted no sabe lo que me saco de encima.", revelacion1 = "Soy Delmer Hurt, granjero de Riverside. Tabaco, soya y dos chanchos. Vivo en la casa grande de los Pickering, la granja que mi papa trabajo de peon.", revelacion2 = "En el ochenta y cinco me gane un millon doscientos mil en la loteria de Ohio. Me compre esta granja, un bote y un Lincoln blanco. En el noventa el banco se quedo con todo.", revelacion3 = "Los del taller del Martillo no me robaron el maiz, compadre. Me lo ganaron a los dados. En tres noches. A la Wanetta le dije que vinieron con escopetas. Medio Riverside lo cree.", diario_conocer = "Conoci a Delmer Hurt, el Millonario de Riverside. Vive en la granja que perdio. Se rie de si mismo antes que nadie.", diario_final = "Delmer le conto a Wanetta lo de los dados. Ella le tiro la lata de los boletos a la estufa. Despues le sirvio la cena igual.", mudanza = "Me traje a la Wanetta, a la Kayla y un fardo de tabaco, compadre, que en el campamento vale mas que la plata. En la iglesia de piedra me toco dormir en el salon parroquial, debajo del techo que pague en el ochenta y seis. La placa sigue ahi. Ya no la tapo. Trabajo el huerto del Padre y le enseno a los muchachos a colgar tabaco. La Kayla ayuda a curar. No juego. Cuando me dan ganas, saco una moneda y la miro. Nomas la miro.", muerte = "Delmer Hurt murio en el encargo. Le deje una moneda en el bolsillo, sin tirarla. Esa no la perdio." } },
    { id = "s048", nombre = "Ofelia", apellido = "Cantrell", apodo = "Rulos", sexo = "m", edad = 21, pueblo = "Rosewood", oficio = "camionero", vive = true, lazos = {"hector", "rosa"}, textos = { llegada = "Ay, amiga, mira ese pelo! Sientate, que el fin del mundo no es excusa. Te lo juro por la laca.", rescate = "Mi amor, me salvaste el peinado y la vida. En ese orden no, pero casi. Gracias.", gracias = "Tijeras de verdad! Con estas le corto el pelo a todo Rosewood. Y a los muertos, que tambien merecen.", revelacion1 = "Soy Ofelia, Rulos en el canal 19. Peluquera y camionera de Rosewood. El salon era de mi mama, el camion es de mi papa. Ahora el camion es una pared.", revelacion2 = "Una vez una clienta me conto que juntaba plata para irse de su marido. Yo se lo conte riendome a su suegra. El marido encontro la plata. Ella no se fue nunca.", revelacion3 = "Le lave el pelo a Sanford Kincer para el cajon. Tenia la nuca hundida, del porte de un sarten. Ni una mordida. Arbutus me pidio que no contara. Esta vez no conte.", diario_conocer = "Conoci a Ofelia Cantrell en Rosewood. Me corto el pelo antes de preguntarme el nombre. Tambien se lo corta a la Misia Rosa. Sabe todo.", diario_final = "Ofelia me conto lo de Sanford Kincer y me hizo jurar por la laca. Dice que es el primer secreto que guarda bien. Le creo.", mudanza = "Me traje a mi papa, a la tia Gaynell, las tijeras y la base de radio, amiga. El Mack lo dejamos en el patio, de pared, por si acaso. En la gasolinera mi papa se instalo al lado de la caja con su radio y ya le cuenta a todo el mundo como era la ruta a Laredo. La Misia Rosa le guarda cafe. Yo corto el pelo detras del taller los sabados, y peino a los que se van. Por fin hay luz para trabajar de noche. Y una con quien hablar que habla mas que yo.", muerte = "Ofelia Cantrell murio en el encargo. La peine yo, como ella peinaba a los muertos. Mal, pero la peine." } },
    { id = "s049", nombre = "Stanislaw", apellido = "McCoy", apodo = "Stosh", sexo = "h", edad = 58, pueblo = "Muldraugh", oficio = "mecanico", vive = true, lazos = {"cabo", "pereira"}, textos = { llegada = "Hable por la derecha, recluta, que la izquierda no oye. Que se le rompio? Un motor no pregunta.", rescate = "Copiado, recluta. Me saco de esa. Otra vez estaba donde no debia. Gracias.", gracias = "Un carburador entero. Con esto anda el generador de la cuadra. Buen trabajo, recluta. Copiado.", revelacion1 = "Stanislaw McCoy, Stosh. Treinta inviernos de mecanico en los Marines. Despues el Damron Garage, en la 31. Le arreglaba las patrullas a la comisaria de Muldraugh.", revelacion2 = "Beirut, ochenta y tres. El edificio de mis muchachos se vino abajo a las seis y veintidos. Yo no estaba en mi catre. Estaba borracho en un camion. Por eso estoy vivo.", revelacion3 = "La primera noche no estaba en el taller. Estaba en el Rebel Spur. Llegue tarde y la Mozelle ya no era ella. La mate yo. Al cabo le menti, y el lo anoto con tinta.", diario_conocer = "Conoci a Stosh McCoy en la calle Pine. Me hablo a gritos y me arreglo la linterna sin que se la pidiera. Olia a whisky.", diario_final = "Stosh se paro junto al cordel de la ropa y dijo la verdad en voz alta. Despues vacio la botella en la tierra. No se si dura.", mudanza = "Me traje la caja de herramientas y nada para tomar, recluta. Se lo pedi al cabo: que me revise los bolsillos, como a todos. En la comisaria me dieron el patio de los patrulleros y les tengo andando el generador y las bombas. Le dije al cabo la verdad de la primera noche. Tacho lo que habia anotado y escribio otra cosa. Duermo en el taller, con la cabeza del lado sordo contra la almohada, para oir con la buena. Los muchachos me traen motores muertos y yo les enseno a revivirlos.", muerte = "Stosh McCoy murio en el encargo, sobrio. Le deje el cuchillo de marine en el pecho, enfundado." } },
    { id = "s050", nombre = "Verna", apellido = "Rice", sexo = "m", edad = 33, pueblo = "West Point", oficio = "costurera", vive = true, lazos = {"chela", "gladys"}, textos = { llegada = "Al paso, senor, al paso. No me asuste la yegua. Asi. Ahora si, buenas tardes.", rescate = "Mire, eso estuvo cerca. Usted llego como caballo bueno: sin que lo llamaran. Gracias.", gracias = "Avena. Con esto la Pepper pasa el invierno. Y nosotras tambien, senor. Usted no sabe.", revelacion1 = "Soy Verna Rice, costurera de West Point. Antes criaba caballos de carrera. Ahora vivo en un establo con mi hija y una yegua vieja, y coso alforjas para el pueblo.", revelacion2 = "En el noventa hice matar a mi propio padrillo para cobrar el seguro. Mi marido cree que fue colico. Igual perdimos todo al otro invierno.", revelacion3 = "De noche, cuando Amy duerme, subo a caballo a la loma y saqueo las casas de los ricos. Lo escondo bajo el piso. En el pueblo digo que ya estaban vacias. Es para nosotras.", diario_conocer = "Conoci a Verna Rice en el establo de West Point. Me midio la pierna a ojo para unas polainas. No se equivoco.", diario_final = "Verna saco lo que tenia bajo el piso de la talabarteria y lo repartio en West Point. Esa noche durmio en el pajar con Amy. Toda la noche.", mudanza = "Me traje a la Pepper, la maquina de coser de mano y a la Amy, senor. Y un saco que tenia escondido: lo puse en la mesa larga de la Chela, latas y remedios, y no explique de donde venia. Ella no pregunto. En el cuartel la yegua duerme en el patio del camion rojo. Yo coso las mantas y las chaquetas de todos. Salgo a caballo con los que buscan cosas, de dia, porque un caballo no hace ruido de motor. De noche duermo al lado de mi hija.", muerte = "Verna Rice murio en el encargo. La Pepper volvio sola al establo, con la montura puesta. Amy la desensillo." } },
    { id = "s051", nombre = "Ned", apellido = "Perkins", apodo = "el viejo de los perros", sexo = "h", edad = 70, pueblo = "Riverside", oficio = "electricista", vive = true, lazos = {"nacho"}, textos = { llegada = "Por la izquierda no le oigo, mijo. Por la derecha. Y no prenda esa linterna aqui afuera.", rescate = "Le debo una, mijo. Dele un pedazo de pan a la perra, que ella tambien se asusto.", gracias = "Pilas nuevas. Mire como prende. Con esto no le cobro nada en lo que me quede de vida.", revelacion1 = "Ned Perkins, electricista de Riverside. Medio Riverside tiene mis enchufes. Con Delbert Moody medi la viga del campanario en el 91. La linea nunca esta muerta.", revelacion2 = "En el 52 le dije a un muchacho \"sube, la linea esta muerta\". Estaba viva desde atras, por el generador de un granjero. Se llamaba Dewitt Coomer.", revelacion3 = "Cuando baja la manada suelto un perro y sale ladrando al rio. Asi salve la casa tres veces. El perro del Padre es mi Dodge. Volvio dos veces. Yo lo bote igual.", diario_conocer = "Ned Perkins, viejo electricista de la curva del molino, en Riverside. Sordo de un lado, vive a oscuras con dos perros y una bocina en un alambre.", diario_final = "Ned soltaba a sus perros de carnada para salvar la casa. Lazaro, el de la iglesia, era suyo. Dice que no tiene cara para ir a pedirlo.", mudanza = "Me traje a Impala y a Bel Air, y el rollo de cobre. Al Padre ya le dije lo de Lazaro. Se quedo callado un rato largo y despues me dijo que el perro sabe volver, que por algo se llama asi. Ahora Lazaro duerme en la primera fila y a veces viene a echarse a mis pies, y yo no se si me perdona o si se le olvido. Les arregle las linternas a todos y deje una alarma de tarros en la reja. La luz la apagamos temprano. Dice el Padre que a Dios lo encuentran igual.", muerte = "Ned Perkins murio en el camino. Los perros se quedaron echados junto a el y no hubo como moverlos." } },
    { id = "s052", nombre = "Nadine", apellido = "Yonts", apodo = "Nadine, la de Sonora", sexo = "m", edad = 45, pueblo = "Rosewood", oficio = "policia", vive = true, lazos = {"pereira", "rosa"}, textos = { llegada = "Alto ahi, corazon. Manos donde las vea. Ah, eres tu. Pasa, pero no hables fuerte, que los ninos duermen.", rescate = "Gracias, corazon. Hace mucho que nadie me sacaba de un lio. Desde el Rebel Spur, creo.", gracias = "Esto alcanza para los chicos de la cuadra una semana. Te lo canto si quieres. No? Mejor, con esta voz.", revelacion1 = "Nadine Yonts, policia de Rosewood. Una de seis, y la mas vieja. Esta cuadra la cuido yo. Al que grita le canto bajito y se calma. Siempre funciona.", revelacion2 = "Yo cantaba en el Rebel Spur, en la 31W. El humo me rompio la voz en el 78. Por eso me dieron la radio, y el cafe de las tres me lo servia la Misia Rosa.", revelacion3 = "Los sabados no patrullo la 31. Me llevan al Rebel Spur y les canto a los del patio de trenes. Me pagan en latas y pilas. Con eso come la cuadra. Y me aplauden, corazon.", diario_conocer = "Nadine Yonts, policia de Rosewood. Cuida seis casas detras de la escuela con un revolver y una voz ronca que calma a los ninos.", diario_final = "Nadine les canta los sabados a los de la banda en el Rebel Spur a cambio de latas. Dice que patrulla la 31. Espera el sabado toda la semana.", mudanza = "Le dije a la cuadra de donde salian las latas. Varner Hux me escupio a los pies y despues se comio la sopa igual. Le entregue las seis casas. Al Rebel Spur no volvi; la camioneta verde paro dos sabados en el cruce y siguio de largo. Aqui en la gasolinera no mando a nadie y es raro. La Misia Rosa me hizo lavar tazas el primer dia. En la noche, cuando los ninos no se duermen, me piden que cante. Canto bajito, detras de la caja, y nadie aplaude. Esta bien asi.", muerte = "Nadine Yonts murio con el uniforme puesto. La ultima cancion la canto bajito, para que no la oyeran." } },
    { id = "s053", nombre = "Emmett", apellido = "Stamper", apodo = "el Jockey", sexo = "h", edad = 20, pueblo = "Muldraugh", oficio = "profesora", vive = true, lazos = {"gladys", "valentina"}, textos = { llegada = "Profe! Perdon, le digo profe a todos. Pase rapido, que los ninos estan en clase de lectura.", rescate = "O sea... gracias. Yo corro, pero no tanto. Peso poco y eso a veces no alcanza.", gracias = "Cuadernos! Tobin va a llorar. Y esto para la abuela. Lo voy a repartir, profe, se lo juro.", revelacion1 = "Emmett Stamper, profesor suplente de la primaria de Muldraugh. La senora Gladys me achicaba los pantalones: todo me queda grande. Tengo dos alumnos en la cocina.", revelacion2 = "Fui jockey aprendiz en Churchill. Para dar el peso vomitaba dos veces al dia. En el 90 la yegua se quebro en Turfway y la sacrificaron en la pista, detras de una pantalla verde.", revelacion3 = "La carne de octubre no era venado. Era Bendita, la yegua que los ninos peinaban. Yo le hable al oido y le dispare. Ellos creen que se fue. No se lo diga.", diario_conocer = "Emmett Stamper, ex jockey, profesor suplente en Muldraugh. Flaco como un nino; cuida a dos alumnos y a su abuela.", diario_final = "Emmett mato a la yegua de los ninos para darles de comer y les dijo que era venado. Come menos que todos y lo llama costumbre.", mudanza = "La abuela acepto salir cuando le dije que en la comisaria hay una profesora de verdad. La trajimos en una carretilla con su almohada. Sarah Jo y Tobin ya tienen bancos y una pizarra. La Miss Mandados me deja ayudarle con la lectura en la sala de interrogatorios, y yo les enseno a contar con caballos. A Sarah Jo le dije lo de Bendita. Lloro una tarde entera y despues me pregunto si le dolio. Le dije que no. Esa vez no mentia. Hattie me sirve el plato lleno y se queda mirando hasta que me lo termino.", muerte = "Emmett Stamper murio en el camino. Era tan liviano que lo cargue solo. Los ninos preguntaron por el toda la noche." } },
    { id = "s054", nombre = "Thuy", apellido = "Cavanaugh", apodo = "la senora de las abejas", sexo = "m", edad = 57, pueblo = "West Point", oficio = "enfermera", vive = true, lazos = {"chela"}, textos = { llegada = "Lavese las manos antes de entrar. No me importa el fin del mundo. Las manos.", rescate = "Gracias, con. Usted se quedo quieto cuando habia que quedarse quieto. Eso salva mas que correr.", gracias = "Hilo de sutura. Bien. Y azucar para las abejas. Usted entiende lo que es importante.", revelacion1 = "Thuy Cavanaugh, enfermera titulada, West Point. Curo con miel: el jefe Booker me llamaba para las quemaduras del cuartel. Si le pica una abeja, no corra.", revelacion2 = "Vengo de Phat Diem, en el norte de Vietnam. En el 54 mi madre me dijo \"para Navidad venimos\" y se quedo alla con mi hermana. Nunca mas las vi.", revelacion3 = "A cuatro mordidos les corte la mano o el pie antes de la hora. Les dije a sus familias que habia una posibilidad. Cuatro de cuatro murieron. Al quinto le voy a decir lo mismo.", diario_conocer = "Thuy Cavanaugh, enfermera vietnamita de West Point. Vive en una loma con nueve colmenas y me hizo lavarme las manos dos veces.", diario_final = "Thuy les corta el miembro mordido y promete una posibilidad. Nunca funciono. Dice que nadie puede decirle a una familia que no hay nada.", mudanza = "Traje cuatro colmenas en una carretilla, de noche, cuando las abejas duermen. Las otras se quedaron con Hartsel. La Chela me dio el banco del fondo para curar y una lampara. Cuando sube alguien mordido, ahora le digo la verdad: que no hay remedio, que se puede quedar con el hasta el final. Es mas dificil que cortar. Le ensene a Jody a no correr de las abejas. Nadie aqui sabe decir mi nombre. Me dicen Miss Twee. Ya no lo corrijo.", muerte = "Thuy Cavanaugh murio sin moverse, como ensenaba. Sus abejas no salieron en tres dias." } },
    { id = "s055", nombre = "Ralph", apellido = "Spencer", apodo = "Ralphie", sexo = "h", edad = 32, pueblo = "Riverside", oficio = "cocinera", vive = true, lazos = {"reyes"}, textos = { llegada = "Mira quien llego. Sientate, compadre, que la sopa esta caliente y es jueves. Los jueves hay sopa.", rescate = "Te debo una olla entera, compadre. Cuando quieras, pasa por el callejon y pide por Ralphie.", gracias = "Sal! Mira, esto vale mas que el whisky. Con esto como medio Riverside una semana.", revelacion1 = "Ralph Spencer, cocinero del Vesta's Kitchen, en Riverside. El almuerzo lo hacia con el pan tibio de Walt Hollis. Los jueves hago sopa. Lo primero que sale, lo boto.", revelacion2 = "Mi familia hace whisky en el hollow desde la Ley Seca. En el 78 no bote la cabeza de una tanda, por apuro. Mi primo Tarvin quedo casi ciego.", revelacion3 = "Los jueves a las cinco, en el callejon, le paso seis frascos a uno del Diacono. Es el diezmo de mi familia. Con eso no suben al hollow. Y con eso se emborrachan antes de ir a cobrar.", diario_conocer = "Ralph Spencer, cocinero de Riverside. Baja del cerro los jueves y reparte sopa de porotos en tarros. Huele a humo y a algo mas fuerte.", diario_final = "Ralph le paga el diezmo al patio de trenes con whisky de su familia. La misma mano que hace la sopa le da valor a los que roban.", mudanza = "Le dije a mi papa que el diezmo se acabo. Se enojo una semana y despues me pregunto si en la iglesia necesitaban cocinero. Bajo los jueves igual, ahora con la familia detras. Tarvin se sienta en la escalera de la iglesia y avisa antes que nadie cuando viene algo; dice que los muertos arrastran el pie izquierdo. Yo cocino en el patio, a lena. El whisky que queda lo uso para limpiar heridas. El primer chorro lo boto, como siempre. Dos veces.", muerte = "Ralph Spencer murio con el delantal puesto. Esa semana nadie hizo la sopa de los jueves." } },
    { id = "s056", nombre = "Hester", apellido = "Tolliver", apodo = "Sister Hester", sexo = "m", edad = 69, pueblo = "Rosewood", oficio = "pastora", vive = true, lazos = {"reyes", "rosa"}, textos = { llegada = "Pase, hijo, y cierre despacio. Aqui todo se hace despacio. Yo camino al paso de Dios, que es el mas lento.", rescate = "Gracias, hijo. Dios me hizo coja para que la gente me esperara. Hoy le toco a usted. Amen y siga.", gracias = "Muletas. Con esto llego al pulpito sin que me carguen. El domingo predico de pie, aunque sea un rato.", revelacion1 = "Hester Tolliver, pastora de la capilla metodista de Sardis, a la salida de Rosewood. Desde el 71 en el pulpito. Aqui consagramos agua de pozo.", revelacion2 = "En el 35, en la carpa de un sanador, me saque el aparato de la pierna para creer. Me cai de cara. Dicen que en Riverside hay un diacono que cobra. Lo conozco desde el 35.", revelacion3 = "La noche del 9 toque la campana para llamar a los vecinos. Los muertos vinieron detras, siguiendola. Cuatro de los mios murieron en el patio. La cuerda no esta podrida.", diario_conocer = "Hester Tolliver, pastora coja de Sardis, cerca de Rosewood. Seis personas viven en su capilla. Habla como si cada frase fuera la ultima del sermon.", diario_final = "Hester toco la campana la primera noche y los muertos la siguieron hasta la capilla. Todos creen que la campana los salvo. Ella no la toca mas.", mudanza = "Les dije la verdad un domingo, desde el pulpito, sentada. Nadie se fue. La Kissel me dijo que su marido habria muerto en el camino igual, con campana o sin ella. No se si es cierto, pero se lo agradezco. El muchacho Asberry quedo a cargo de la capilla. Yo me vine a la bomba de la Misia Rosa, que es bautista, pero aqui no se cobra por rezar. Le escribo los avisos a maquina. La luz nunca se apaga y yo leo de noche. A mi edad eso es un lujo.", muerte = "La pastora Hester murio sentada, con la Biblia abierta en el salmo 121. Nadie toco la campana." } },
    { id = "s057", nombre = "Benny", apellido = "Watts", apodo = "Treinta y Dos", sexo = "h", edad = 44, pueblo = "Muldraugh", oficio = "carpintero", vive = true, lazos = {"cabo"}, textos = { llegada = "Campeon! Pasa, pasa. Cuidado con el tablon suelto, que la rodilla mia ya lo conoce.", rescate = "En serio te digo, campeon, otra jugada mas y no la cuento. Te debo una escalera. O dos.", gracias = "Bisagras! Te juro que con esto le cierro las ventanas a media cuadra. Mide dos veces, corta una.", revelacion1 = "Benny Watts, carpintero de Muldraugh. Treinta y dos, fullback, un curso arriba del Cabo. Le hice las repisas de evidencias en el 84. Hago escaleras. Y cruces.", revelacion2 = "En el 67 me pusieron 4-F por la rodilla y senti alivio. Mi mejor amigo, Olen Gabehart, murio en Khe Sanh en el 68. Yo cargue el cajon cojeando.", revelacion3 = "Las cartas de JoAnn las escribo yo, de noche, copiando su letra de las tarjetas de recetas. A Shelly le digo que me las da el soldado del Doe Run. De JoAnn no se nada.", diario_conocer = "Benny Watts, carpintero grandote de Muldraugh. Cojea, cuenta todo como un partido y tiene a su hija lanzadora cuidandole la espalda.", diario_final = "Benny le escribe a su hija cartas falsas de su madre, con la letra copiada. Shelly ya noto que huelen a cedro.", mudanza = "Shelly fue sola al Doe Run. Volvio callada y me dejo las nueve cartas en el banco. Le dije la verdad: que de su mama no se nada y que la letra la copie de las recetas. Me pego en el pecho con las dos manos y despues se quedo apoyada ahi. En la comisaria el Cabo me tenia una pagina con los doce tablones. Le hice repisas nuevas a la cocina de Hattie, sin cobrar, y lo anoto tambien. Shelly hace guardia con Jamal. Ahora las cartas para JoAnn las escribimos los dos. Con mi letra.", muerte = "Benny Watts murio sin poder correr, como siempre supo. Shelly le hizo la cruz con el formon de el." } },
    { id = "s058", nombre = "Maxine", apellido = "Sloan", apodo = "Daniel Boone", sexo = "m", edad = 19, pueblo = "West Point", oficio = "cazador", vive = true, lazos = {"chela"}, textos = { llegada = "Quieto ahi. Diga algo. Fuerte. Bueno. Pase.", rescate = "No se. Gracias. Da igual... no. No da igual. Gracias.", gracias = "Cartuchos. Asi esta semana no tengo que bajar al puente. Gracias. De verdad.", revelacion1 = "Maxine Sloan, de la tienda de carnada de West Point. Pesco, crio lombrices y cazo sola. En el monte nadie me ve antes de que yo lo vea.", revelacion2 = "Mi papaw Sim me enseno a tirar en Leslie County, a los ocho. A la ardilla se le tira a la cabeza o no se le tira. Me dejo su rifle.", revelacion3 = "Los cartuchos me los dan los soldados del puente del Salt. Creen que soy un muchacho, Max. Me corte el pelo. Si se me cae la gorra, se lo que me espera. La tia no sabe.", diario_conocer = "Maxine Sloan, cazadora de West Point, vive en una tienda de carnada con su tia abuela. Me hizo hablar fuerte antes de dejarme pasar.", diario_final = "Maxine se hace pasar por un muchacho, Max, para cambiar carne por cartuchos con los soldados del rio Salt. Nadie lo sabe, ni su tia.", mudanza = "La tia Zelda vino en el bote, sentada como reina, con las tinas de lombrices. La Chela le dio el sillon de la cocina. Yo pesco para el cuartel y le enseno a Jody a limpiar pescado. Al puente del Salt no volvi. Una noche, en la cocina, le conte a la Chela lo de Max. No me dijo nada bonito. Me dio una taza de cafe y se quedo sentada conmigo hasta tarde. Eso fue mejor. El pelo me esta creciendo. Todavia no se si dejarlo.", muerte = "Maxine Sloan murio en el monte, donde nadie la veia. La tia Zelda pregunto por ella todos los dias." } },
    { id = "s059", nombre = "Quincy", apellido = "Wisniewski", apodo = "el polaco", sexo = "h", edad = 56, pueblo = "Riverside", oficio = "granjero", vive = true, lazos = {"nacho", "yvonne_bell"}, textos = { llegada = "Buenas tardes, senor. Con todo respeto, si trae a alguien, digame primero el nombre. Despues el resto.", rescate = "Muy amable, senor. Por un momento pense que iba a tener que escribir mi propia tarjeta.", gracias = "Sabanas limpias y cal. Con todo respeto, es lo mejor que me han traido desde julio. Ellos se lo agradecen.", revelacion1 = "Quincy Wisniewski, granjero de Riverside. Le vendia la leche a la panaderia Hollis; Yvonne Bell me pagaba con rollos de canela. Si se le muere alguien, traigamelo.", revelacion2 = "Mi familia tenia una funeraria polaca en Germantown. Prepare a mi propia madre en el 68. A mi padre, en el 79, no lo toque. El decia que yo hui de los muertos.", revelacion3 = "No los entierro. Estan en el granero del tabaco, veintisiete, envueltos en lonas, cada uno con su tarjeta. Clova cree que estan en el potrero. Un pozo comun no es para gente con nombre.", diario_conocer = "Quincy Wisniewski, granjero de Riverside, ex funerario. Habla de los muertos sin bajar la voz y me pidio el nombre antes que el saludo.", diario_final = "Quincy guarda veintisiete muertos con nombre en su granero de tabaco, esperando la primavera para enterrarlos uno por uno.", mudanza = "Cuando se ablando la tierra, en primavera, El Padre me presto a su carpintero y a dos muchachos, y Clova vino con el rosario. Enterramos a los veintisiete en el potrero de abajo, uno por uno, con su tarjeta clavada en una estaca de nogal. Tardamos once dias. A Clova le pedi perdon por la mentira. Me dijo que ya lo sabia, que el granero olia a otra cosa. Ahora vivo cerca de la iglesia y llevo el libro de los muertos del campamento. Afeito a los que se van. Sigo sin cobrar.", muerte = "Quincy Wisniewski murio con las manos limpias. Le pusimos una tarjeta con su nombre en el pecho, como el hacia." } },
    { id = "s060", nombre = "Kay", apellido = "Harmon", apodo = "Golondrina", sexo = "m", edad = 31, pueblo = "Rosewood", oficio = "camionero", vive = true, lazos = {"earl", "rosa"}, textos = { llegada = "Si viene por leche, tengo. Si viene por otra cosa, la puerta del camion tiene seguro.", rescate = "Bueno. Gracias. No se lo cuente a nadie, que tengo una reputacion de no necesitar a nadie.", gracias = "Una bateria. Con esto la cabina aguanta el invierno. Usted no me vio, eh. Nunca me ve nadie.", revelacion1 = "Kay Harmon, camionera, de Rosewood. Carga seca de Louisville a Memphis. Earl Whitaker me enseno la 31. En el 19 me dicen Golondrina. Tengo leche para guagua.", revelacion2 = "Kay Harmon no existe. Me llamo Margo Pacella, de Youngstown, Ohio. Vi un asesinato de la mafia en el 87 y testifique. Me dieron este nombre y una viuda de Paducah.", revelacion3 = "En octubre una voz me llamo Margo por el canal 7 del camion, con acento de Youngstown. Alguien de alla sabe que estoy en Knox. Duermo con el revolver y ya no voy donde la Misia Rosa.", diario_conocer = "Kay Harmon, camionera de Rosewood. Vive en la cabina detras del molino y reparte leche para guaguas. No contesto nada de su vida dos veces seguidas.", diario_final = "Kay es Margo, testigo protegida. Una voz de Youngstown la llamo por su nombre en la radio del camion. Duerme con el revolver.", mudanza = "Le dije a la Misia Rosa que me llamo Margo, y lo de la voz del canal 7. Se quedo mirandome y despues saco el cuaderno, tacho Paducah con una raya fina y escribio Youngstown arriba, con su letra chica. Me dijo que si alguien viene a buscarme, va a tener que pasar por delante de la caja. Junior escucha el canal 7 todas las noches. No ha vuelto a sonar. El remolque esta atras del taller. A las tres de la manana me tomo un cafe con leche evaporada y nadie me pregunta nada.", muerte = "Margo Pacella, alias Kay Harmon, murio en la 31. En el cuaderno de la Misia Rosa quedo con su nombre verdadero." } },
    { id = "s061", nombre = "Waylon", apellido = "Damron", apodo = "el Exaltado", sexo = "h", edad = 68, pueblo = "Muldraugh", oficio = "mecanico", vive = true, lazos = {"cabo"}, textos = { llegada = "Escuche, hermano, hableme fuerte y por la derecha. El oido izquierdo lo deje en Belgica.", rescate = "Me saco como se saca un perno oxidado: con paciencia y con fuerza. Gracias, hermano.", gracias = "Queda en el acta de la logia, con su nombre completo. Eso, aqui, todavia vale algo.", revelacion1 = "Waylon Damron, mecanico de la 31 desde el 49 y Exaltado Gobernante de los Elks de Muldraugh. Si, asi se llama el cargo. Duermo en un auto subido al elevador.", revelacion2 = "Cuando me llamaron a la guerra le deje mi lampara de minero a mi hermano Orlie. En el 47 se le vino el techo encima. No fui al entierro: tenia un camion desarmado.", revelacion3 = "Esa noche sali por la cocina con el mazo y con la caja de la logia: el fondo de las viudas, billetes y dolares de plata. A las viudas les dije que se quemo. Esta en mi rueda de repuesto.", diario_conocer = "Conoci a Waylon Damron, un mecanico viejo y medio sordo de Muldraugh que duerme en un auto levantado y habla como presidente de club.", diario_final = "Waylon abrio la caja de la logia delante de las tres viudas y repartio los dolares de plata. Dijo que la sesion quedaba abierta.", mudanza = "Me traje la caja de herramientas, el mazo y seis tazas del taller. Quedamos tres hermanos, asi que sobran tres tazas para las visitas. Al Cabo le mantuve los patrulleros desde el 71, cuando era el muchacho de Mildred y traia el cenicero limpio; ahora le arreglo lo que tenga tuercas: la bomba del agua, las bicicletas, la radio si me la deja abrir. Aqui no tengo elevador, asi que duermo en el suelo y me cuesta media hora pararme. Los viernes a las once hago el brindis por los ausentes. El que quiera, que venga. Hay una mocion nueva: que en este campamento las mujeres voten. Ya se que aqui votan. Yo la presento igual, para ganar una vez.", muerte = "Waylon Damron murio con la llave de cruz en la mano. Debajo del asiento dejo una lata verde y una nota: para las viudas." } },
    { id = "s062", nombre = "Goldie", apellido = "Helton", apodo = "la del correo", sexo = "m", edad = 43, pueblo = "West Point", oficio = "costurera", vive = true, lazos = {"chela"}, textos = { llegada = "Pase. Si viene por un recado, levante la bandera del buzon y espereme. Me sigue?", rescate = "Usted salio de un camino que no estaba en mi ruta. Gracias. Lo anoto en el mapa con su nombre.", gracias = "Entregado. Eso es lo que mas me gusta oir en el mundo, y casi nadie me lo dice ya.", revelacion1 = "Goldie Helton, costurera de West Point. Dieciocho temporadas de cartera rural. Cuatrocientos doce buzones. Ahora reparto papelitos en bicicleta.", revelacion2 = "Una senora de mi ruta le escribia a un hijo que no contestaba. Le guarde las cartas y le escribi las respuestas yo. Se murio con mi ultima carta en el pecho.", revelacion3 = "Le dibuje a un soldado de la reja todos los caminos de tierra que salen de Meade, por una caja de raciones. En septiembre cerraron los catorce. Dos no se los dibuje.", diario_conocer = "Goldie Helton anda en bicicleta con un canasto lleno de papeles. Se sabe todos los caminos de tierra entre West Point y el rio Salt.", diario_final = "Goldie me dibujo los dos caminos que no le dio a la Guardia. Dijo que ese mapa no se cambia por nada. Ese se regala.", mudanza = "Me traje la Singer, la caja de botas y el mapa de la cocina con los buzones marcados. La Chela ya me conocia: yo le dejaba a Pearl, en la puerta del cuartel, los papelitos de los que buscan gente, y ella me daba un plato sin preguntar. Aqui hay mas buzones de los que parece: cajas, latas, un clavo en la puerta. Si alguien quiere mandarle algo a otro campamento, me lo da y yo veo por donde. No cobro. Ya cambie bastante por comida. La cadera no me deja hacer guardia, pero de noche coso y escucho, que es casi lo mismo. Y si alguien va a Valley Station, que pregunte por una peluquera rubia que se llama Starla.", muerte = "Goldie Helton murio en un camino de tierra que solo ella conocia. El canasto quedo lleno. Nadie va a saber a quien eran." } },
    { id = "s063", nombre = "Norris", apellido = "Terry", apodo = "el chico Terry", sexo = "h", edad = 18, pueblo = "Riverside", oficio = "electricista", vive = true, lazos = {"nacho", "yvonne_bell"}, textos = { llegada = "Hola. Si trae un animal herido, dejelo en la paja. Si trae una persona herida... deme un minuto.", rescate = "Tecnicamente me salvo usted. Yo ya estaba con los ojos dando vuelta. Gracias.", gracias = "Con esto puedo coser tres terneros y un cristiano. Gracias, de verdad.", revelacion1 = "Norris Terry, de Riverside. Me dicen electricista porque hacia los trabajos de mi papa: con el le arregle el horno a Walt en la panaderia Hollis. Iba a estudiar veterinaria. Me desmayo con la sangre.", revelacion2 = "En marzo me llamaron a un parto de una vaca. Vi la sangre y desperte en la paja. Murieron la vaca y el ternero. Dije que no me partio la camioneta.", revelacion3 = "Ya no me desmayo porque antes de coser me tomo dos tragos del alambique de don Wilford. Mi mama cree que soy valiente. Me tiemblan las manos hasta el primer trago.", diario_conocer = "Norris Terry tiene 18, un beagle y un frasco de jarabe para la tos. Cura vacas y gente en la granja de los Grubbs.", diario_final = "Norris coso a un herido sin el frasco. Se puso blanco, se sento en el suelo y siguio cosiendo sentado. No se desmayo.", mudanza = "Me traje a Reds, el maletin del doctor Fife y mi mama, que dice que si yo me venia ella tambien. Kasey trajo su guante de softbol. Aqui me toca de todo: perros, una cabra, cortes, una muela. Le pedi al campamento una cosa: si alguien me ve con un frasco, que me lo quite. Ya van once dias sin el. Coso sentado, por si acaso, con un balde al lado. Tambien hago lo de electricista: no me desmayo con los cables. Si algun dia hay universidad otra vez, me voy a Lexington. Mientras, la universidad es esto.", muerte = "Norris Terry murio con las manos firmes. No tenia el frasco. Tenia dieciocho y ya era doctor." } },
    { id = "s064", nombre = "Elsie", apellido = "Blevins", apodo = "la oficial Blevins", sexo = "m", edad = 55, pueblo = "Rosewood", oficio = "policia", vive = true, lazos = {"rosa"}, textos = { llegada = "Oficial Blevins. Limpiese los pies, siente los codos lejos de mi mesa y digame que necesita, carino.", rescate = "Bien hecho. Usted tiene manos de cocina: rapidas y sin temblar. Le debo un plato.", gracias = "Justo lo que faltaba. Hoy la sopa queda en su punto, y usted come primero.", revelacion1 = "Elsie Blevins, policia de Rosewood. Fui jefa de cocina en Louisville treinta temporadas. Los presos de aqui son los unicos de Kentucky que comieron beurre blanc.", revelacion2 = "Vivi catorce temporadas con Betty, la pastelera. Companeras de cuarto, deciamos. Cuando se murio, en el hospital no me dejaron entrar. Solo familia.", revelacion3 = "Tawny no es mi sobrina. Es una presa que yo traia esposada la primera noche. Me salvo la vida con una barreta. Su expediente esta en mi horno, y ahi se queda.", diario_conocer = "Elsie Blevins patrulla Rosewood con uniforme planchado y doce balas. Cocina mejor que nadie que haya conocido en Knox.", diario_final = "Elsie quemo el expediente de Tawny en la estufa y despues hizo pan de maiz con ese fuego. Dice que asi se cierra una causa.", mudanza = "Me traje la sarten de cobre, los cuchillos y a Tawny, que no es mi sobrina, ya lo saben todos. La Misia Rosa me recalienta la achicoria, yo le digo que es un crimen y me la tomo igual: asi nos queremos. En su cocina mando yo o no me quedo: la mise en place a las dos, y el que toque una olla sin lavarse las manos friega toda la semana. Tawny parte la madera y hace guardia, tiene mejor brazo que yo. La placa la llevo en el delantal, por costumbre. Si hay pleitos, los arreglo en la mesa: con hambre nadie razona. Y los domingos alguien me acompana a dejarle sopa a la Reverenda.", muerte = "Elsie Blevins murio con el delantal puesto. Dejo la olla al fuego y una nota: \"Le falta sal\"." } },
    { id = "s065", nombre = "Milo", apellido = "Kidd", apodo = "Profe Kidd", sexo = "h", edad = 30, pueblo = "Muldraugh", oficio = "profesora", vive = true, lazos = {"gladys", "pereira"}, textos = { llegada = "Pasa, hermano. Despacio y sin polvo, que el pecho no me da. Nia, la vitrola, por favor.", rescate = "Ahi esta. Llegaste a tiempo, como en el compas que uno no ensaya. Gracias.", gracias = "Esto me compra un mes de respirar. No sabes lo que vale un mes de respirar.", revelacion1 = "Milo Kidd, profesor de musica de Muldraugh. Dona Gladys le cosio los uniformes a mi banda de veintitres ninos y me cobro la mitad por un bolero. Ahora tengo una vitrola y una alumna: Nia.", revelacion2 = "Mi papa tenia un Kind of Blue que crujia en la entrada de So What. Lo vendi para pagar un hospital. Antes de morir me dijo: este no cruje donde crujia el mio.", revelacion3 = "Dicen que me lleve a los muertos con la trompeta. Mentira. Tocaba para respirar, y por el sonido doblaron hacia los papas de Nia. Ella cree que la salve. Y yo dejo que lo crea.", diario_conocer = "Milo Kidd es profesor, asmatico y vive con una nina de ocho que no es suya. Tiene una vitrola de manivela y discos viejos.", diario_final = "Milo le conto la verdad a Nia. Ella no dijo nada. Saco la trompeta del ropero y se la paso. El toco tres notas cortas.", mudanza = "Me traje la vitrola, los veintidos discos y a Nia, que trajo su cuaderno de partituras dibujadas a mano. Aqui hay ninos, asi que hay escuela: en la manana letras y numeros, en la tarde palmas y compas. Si el campamento quiere, los sabados en la noche pongo un disco para todos, bajito. Bessie Smith no atrae muertos, solo viejos. La trompeta queda guardada. Nia dice que algun dia la va a tocar ella. Yo le digo que primero hay que aprender a respirar. Y para eso, hermano, necesito un inhalador.", muerte = "Milo Kidd murio sin aire y sin miedo. Nia guardo la trompeta. Dice que la va a tocar cuando aprenda a respirar." } },
    { id = "s066", nombre = "Reba", apellido = "Elam", apodo = "la enfermera Elam", sexo = "m", edad = 67, pueblo = "West Point", oficio = "enfermera", vive = true, lazos = {"chela", "pereira"}, textos = { llegada = "Pasa, potrillo. Si sangras, sientate en la silla de la cocina. Si tienes fiebre, en la del patio.", rescate = "Me sacaste por una cabeza, potrillo. Foto final. Te debo dos dolares y un cigarro.", gracias = "A dos dolares la apuesta, y gane. Con esto coso a medio West Point otra semana.", revelacion1 = "Reba Elam, enfermera de West Point, treinta y seis temporadas en el hospital del Fuerte. Desde el 69 el jefe Booker me manda a los del cuartel que se cortan. Naci el dia del Derby del 26.", revelacion2 = "Mataron a mi Thurman en Vietnam. Aposte el seguro en Churchill y perdi seis mil quinientos. Mi Judy encontro la libreta del banco. No me ha vuelto a mirar igual.", revelacion3 = "De noche vienen los del patio de trenes y yo los coso. Me pagan con plata vieja y fichas de casino, y junto lo que le debo a mi Judy. Hablan del cuartel. Yo no aviso.", diario_conocer = "Reba Elam cose heridas en su cocina de West Point. Tiene un letrero que dice golpee fuerte y una libreta de carreras con la fiebre de los mordidos.", diario_final = "Reba le conto al cuartel lo que oia en su cocina. Despues tiro las fichas al fuego. Los billetes no: dice que esos son de Judy.", mudanza = "Me traje el maletin, la lupa, la libreta de las carreras y el letrero, que lo clave en la puerta de la cocina: Inyecciones y puntos. Golpee fuerte. Aqui coso a todos, del lado que vengan, pero ya no me callo lo que oigo. Fumo afuera, para no ahogar a nadie. Los domingos hago apuestas de dos dolares: quien saca el agua mas rapido, cuantos huevos ponen las gallinas, cuando llega la nieve. Gana el que acierta, y el premio es no lavar platos. Si un dia llega un muchacho de Louisville que se llama Lanny, avisenme primero a mi.", muerte = "Reba Elam murio con la aguja en la mano. El punto quedo bien hecho. Fue su ultima apuesta: aposto a que el herido vivia." } },
    { id = "s067", nombre = "Forrest", apellido = "Stanfill", apodo = "Himno", sexo = "h", edad = 42, pueblo = "Riverside", oficio = "cocinera", vive = true, lazos = {"yvonne_bell"}, textos = { llegada = "Pase, querida, que la sopa esta a dos estrofas de estar lista. Sientese. Yo me quedo de pie, por el tobillo.", rescate = "Bendito sea. Pense que hoy me tocaba la tercera estrofa a mi. Gracias, tesoro.", gracias = "Con esto como Riverside entera una semana. Bendito sea usted y sus piernas.", revelacion1 = "Forrest Stanfill, cocinero del Bluebird de Riverside desde el 69 y organista de la capilla metodista. Mido los huevos en himnos: blando, dos estrofas; duro, tres.", revelacion2 = "En el 69 tenia una audicion con beca en Louisville. La noche antes se quemo la cocina de mi mama. Cuando vi el humo senti alivio. Tenia miedo de tocar delante de gente.", revelacion3 = "Mi tobillo esta sano. Me lo vende para no irme con la congregacion el 13 de julio. Mi hermana Luanne se fue cantando adelante, en mi lugar. Llevo cinco meses cojeando de mentira.", diario_conocer = "Forrest Stanfill cocina en el Bluebird de Riverside tarareando himnos. Compraba los bollos de la panaderia Hollis a las cinco. Cojea y no toca el organo.", diario_final = "Forrest dejo el baston en la puerta y camino derecho hasta la barricada de la 31. Volvio y toco el organo. Fuerte.", mudanza = "Me traje la sarten de fierro, el gato Wesley y el himnario de la capilla. Aqui cocino yo, si me dejan: sopa de lo que traigan, pan de maiz y los domingos algo dulce, aunque sea de bellotas. Ya no cojeo. Eso tambien lo saben todos. Si alguien me consigue un generador y un organo, aunque sea uno de juguete, toco los domingos. Fuerte, para que se oiga en Riverside. Y si un dia pasa una mujer de Ekron con cara de maestra, que me llamen a la plancha: se llama Luanne y le debo una estrofa.", muerte = "Forrest Stanfill murio caminando derecho, sin cojear. Alguien canto la tercera estrofa por el." } },
    { id = "s068", nombre = "Beulah", apellido = "Okonkwo", apodo = "la Reverenda", sexo = "m", edad = 79, pueblo = "Rosewood", oficio = "pastora", vive = true, lazos = {"rosa"}, textos = { llegada = "Pase, criatura de Dios. Hombros atras, que el Senor lo esta mirando. Y yo tambien.", rescate = "Me cargaste como a un saco de harina, criatura. Dios te lo pague. Yo te pago con una oracion.", gracias = "Esto es pan para once. Dios lo ve todo, y hoy te vio a ti. Digame si miento.", revelacion1 = "Beulah Okonkwo, pastora de Monte Sion en Rosewood. Predico sentada y le enseno la Biblia a los ninos. Fui modelo del catalogo de Sears. Pagina 381, delantales.", revelacion2 = "Mi Emeka me pidio que lo enterrara en Nigeria, en su tierra. Lo enterre en Chicago. Dije que era por la plata. Era por no quedarme sin una tumba que visitar.", revelacion3 = "El Senor no me hablo esa noche de agosto. Me lo invente para que no se fueran sin mi. Once almas siguen aqui por una vieja que no podia caminar. Digame si miento. No miento.", diario_conocer = "Beulah Okonkwo tiene 79, predica sentada y se pinta los labios con remolacha. Once personas la escuchan como si fuera la radio.", diario_final = "Beulah le conto la verdad a su congregacion. Nadie se fue. El diacono dijo que ya lo sabia y que se quedaban igual.", mudanza = "Me trajeron en una silla, como una reina, y no me averguenzo. Me traje la Biblia grande, el catalogo del 66 y a los once de Monte Sion, que vinieron porque esta vez les pregunte. La Misia Rosa me fia el cafe desde el 81: le pago con oraciones y ella me dice que Dios no cobra. Aqui predico los domingos, sentada, y en la semana le enseno a leer a los ninos, que es lo mismo que predicar pero con premio. Corrijo la postura de todos: hombros atras. Y si un dia llega un ingeniero de Atlanta preguntando por su mama, digale que lo estoy esperando, pintada.", muerte = "Beulah Okonkwo murio sentada, con la barbilla arriba. Como en la foto. No se movio." } },
    { id = "s069", nombre = "Homer", apellido = "Reynolds", apodo = "el Guardabosques", sexo = "h", edad = 54, pueblo = "Muldraugh", oficio = "carpintero", vive = true, lazos = {"cabo"}, textos = { llegada = "Buenas, compadre. Hable bajo, que la nina duerme. Y mire donde pisa: esa tabla la clave yo y no aguanta mentiras.", rescate = "Me saco del fuego, compadre. No es la primera vez que me pasa. Es la primera que me sacan.", gracias = "Con esto hago un cajon, dos muletas y una cuna. Asi es la madera: rinde si uno la respeta.", revelacion1 = "Homer Reynolds, carpintero de Muldraugh. Fui guardabosques del Kentucky Ridge veinticinco temporadas. Vigilo el humo desde una garita en mi techo, con rampa, porque no subo escaleras.", revelacion2 = "En el 85 se prendio Pine Mountain. Mande a mi cunado Ozro a subir solo a ver el fuego. En la investigacion dije que el viento cambio. Cambio, si. Pero yo lo mande.", revelacion3 = "A mi yerno no lo mordieron en el monte. Se fue con la camioneta y la comida y dejo a mi hija y a la nina. Le dije que yo lo mande solo al monte. Prefiero que me odie a mi.", diario_conocer = "Homer Reynolds cojea, habla con la madera y vigila Muldraugh desde una garita con rampa. Hace cajones para los muertos.", diario_final = "Homer le dijo a Sue Ellen que Troy esta vivo. Ella lloro y despues le paso la nina. Esa noche Lois dijo el nombre de Ozro en la mesa.", mudanza = "Me traje las herramientas, las once tablas de castano y a mi familia: Lois, Sue Ellen y la nina. Al Cabo ya le conozco el trato: en agosto le hice el cajon del cartero Grady, me pago en el dia y me dio la mano como si fuera un tramite. Aqui no hay garita, asi que la voy a hacer, con rampa, que yo no subo escaleras. Hago trancas, postigos, catres, cajones y cunas, en ese orden de urgencia. Si alguien tiene una tabla que no sabe que es, que me la traiga: el pino miente. Con las tablas de castano voy a hacer una banca. Ya saben para quien. Se pone al lado del fuego, para que se siente el que necesite.", muerte = "Homer Reynolds murio en la garita, mirando el humo. Lois dijo los dos nombres en la tumba. Por fin." } },
    { id = "s070", nombre = "Imogene", apellido = "Pham", apodo = "la cazadora", sexo = "m", edad = 29, pueblo = "West Point", oficio = "cazador", vive = true, lazos = {"chela"}, textos = { llegada = "Quieto. Respire. Muestreme las manos y los brazos. Bien. Ahora si, pase.", rescate = "Usted respira bien bajo presion. Eso no se ensena. Gracias.", gracias = "Con esto como yo, come mi papa y comen dos casas de West Point. Le guardo una pierna de venado.", revelacion1 = "Imogene Pham, cazadora de West Point. Fui enfermera auxiliar en un asilo de Brandenburg. Ahora faeno venados en la hondonada del rio Salt, con faja, por la espalda.", revelacion2 = "En el 91 saque a un viejo del asilo a morir al monte, como el me pidio. Lo firme como paseo. Espere dos horas antes de llamar. Me echaron. No me arrepiento.", revelacion3 = "Los mordidos que todavia piensan me buscan. Los llevo al monte, los siento, les tomo el pulso. Antes de que se den vuelta, disparo. Son seis. A sus familias les dije que se fueron caminando.", diario_conocer = "Imogene Pham caza en la hondonada del rio Salt. Le toma el pulso a todo el que le da la mano, sin darse cuenta.", diario_final = "Imogene le conto la verdad a una de las seis familias. La senora le dio las gracias y le pidio el nombre del arbol.", mudanza = "Me traje el rifle, la piedra de afilar de mi papa y a mi papa, que dice que donde va la escopeta va el. Aqui cazo, faeno y le tomo la presion a quien quiera. Al jefe Booker lo vi el 11 de julio bajando solo hacia el rio, ya mordido. Me levanto la mano y lo deje ir. Fue el primero que entendi. Si alguien del campamento sale mordido y todavia piensa, que me busque. No es obligacion. Pero nadie se muere solo si yo estoy. Duermo con un termo viejo al lado. Es de mi marido. Si un dia llega un hombre que se llama Tuan, que me despierten.", muerte = "Imogene Pham murio en el monte. Nadie la llevo: fue sola. Le tomaron el pulso. Ya no tenia." } },
    { id = "s071", nombre = "Rollie", apellido = "Dixon", apodo = "Rollie", sexo = "h", edad = 66, pueblo = "Riverside", oficio = "granjero", vive = true, lazos = {"nacho"}, textos = { llegada = "Quieto ahi, joven. Las vacas ya lo vieron. Jamie, cuantas son? Bueno. Diga a que viene.", rescate = "Ya, ya. Jamie, deja de llorar, el joven nos saco. Asi es la cosa. Le debo una vaca.", gracias = "Gracias, joven. No soy de decirlo dos veces. Lleve carne salada, que aqui sobra mas que palabras.", revelacion1 = "Granjero de Riverside, tabaco y Angus. Este es mi hijo Jamie, veintiseis, el nino. Los domingos vamos a la misa de las once del Padre y el pregunta por las campanas.", revelacion2 = "Cuando nacio Jamie, el doctor me hablo del hogar de Frankfort. No lo lleve, pero seis veranos no lo saque de la casa. Lo saco Delbert, el de las campanas.", revelacion3 = "Ando con dos cartuchos aparte. El de la cruz es para Jamie, si a mi me muerden. Nadie lo iba a cuidar. O eso pensaba yo, joven. Que piensa usted?", diario_conocer = "Conoci a Rollie Dixon y a su hijo Jamie en una granja de Riverside. El viejo no puede cargar nada. El hijo me conto las vacas dos veces.", diario_final = "Rollie me mostro dos cartuchos y uno tenia una cruz. Le dije que en el campamento alguien puede cuidar a Jamie. Me pidio que se lo jurara. Lo jure.", mudanza = "Rollie llega caminando con Jamie y dos vacas amarradas de una cuerda. Pide un rincon cerca del corral y una sola cosa: que si a el le pasa algo, alguien le de a Jamie la pastilla de la manana y lo deje contar los animales. Esa noche, antes de dormir, saca dos cartuchos del bolsillo de la camisa, los mira un rato y los deja en la caja comun de municion. Jamie cuenta a la gente del campamento como cuenta las vacas y no se equivoca nunca. Los domingos pregunta si hoy van a sonar las campanas.", muerte = "Rollie Dixon murio en el camino. Jamie no dejo de preguntar por el. Le prometi que alguien le daria la pastilla de la manana." } },
    { id = "s072", nombre = "Eula", apellido = "Keeton", apodo = "la Comadreja", sexo = "m", edad = 41, pueblo = "Rosewood", oficio = "camionero", vive = true, lazos = {"rosa"}, textos = { llegada = "Vaya, cara nueva. Si viene a pedir que le escriba algo, cobro en latas. Si es otra cosa, cierre la puerta.", rescate = "Ay, carino, llego justo. Le debo una y yo pago. No en efectivo, pero pago.", gracias = "Eso es, carino. Lo anoto con mi letra mas bonita, que es la de verdad.", revelacion1 = "Eula Keeton, camionera de Rosewood. Mi Peterbilt se llama la Comadreja. La primera noche pase frente a la bomba de la Misia Rosa, la unica luz del pueblo, y no pare.", revelacion2 = "En Louisville firme titulos de autos que no eran de nadie. Bucky Tussey se comio cuatro inviernos de carcel solo. Nunca le escribi una linea. Me daba miedo la letra.", revelacion3 = "La Comadreja no esta en Louisville. Esta en el granero del tio Alvis, con medio estanque. Y tengo un salvoconducto de la Guardia con una firma que hice yo. No se lo diga a nadie.", diario_conocer = "Eula Keeton, camionera de Rosewood. Escribe recados para la gente a cambio de latas. Tiene la letra mas linda que he visto y miente con ella.", diario_final = "Eula tiene un camion escondido y un papel falso para cruzar el cordon. Le pregunte si cabia alguien mas. Se rio. No me contesto.", mudanza = "Eula llega a la gasolinera sin camion, con una caja de lapices y la Biblia de la familia. Se ofrece de escribana: anota quien llega, quien se va y los recados para los que no estan. Escribe los letreros del campamento con letra Palmer. Una noche, sin chiste, deja en el mostrador un papel doblado con la direccion de un granero en Ekron y dice: Tiene medio estanque. Para cuando haga falta uno grande. Despues se va a dormir como si no hubiera dicho nada.", muerte = "Eula Keeton murio en el camino. Le escribi el nombre en la cruz con mi peor letra. Ella se habria reido." } },
    { id = "s073", nombre = "Stanley", apellido = "Schaefer", apodo = "el Testigo", sexo = "h", edad = 78, pueblo = "Muldraugh", oficio = "mecanico", vive = true, lazos = {"cabo"}, textos = { llegada = "Buenas, joven. Usted esta vivo, eso lo anoto. Tiene un minuto para la palabra de Jehova? Tambien arreglo bombas.", rescate = "Gracias, joven. No crea que fue suerte. Pero tampoco fue mi merito, eso seguro.", gracias = "Muy amable. Le dejo La Atalaya, que es gratis, y el carburador, que tampoco le cobro.", revelacion1 = "Stanley Schaefer, mecanico de Muldraugh y testigo de Jehova. Cuarenta y un mil puertas desde el treinta y cuatro. Ahora anoto quien vive y le dejo la libreta al cabo Mandados.", revelacion2 = "En el cuarenta y dos no fui a la guerra. Tres veranos preso en Ashland. Ahi aprendi mecanica. En el setenta y cinco esperaba el fin. Me equivoque de fecha.", revelacion3 = "En agosto el profesor Bowman me puso su sangre mientras yo dormia. Tenia mi tarjeta en el bolsillo. Lo se y no le he dicho nada. A las hermanas tampoco.", diario_conocer = "Stanley Schaefer, un viejo testigo de Jehova de Muldraugh, sigue tocando puertas para anotar quien vive. Me dio una revista y me arreglo la bomba.", diario_final = "Stanley sabe que Bowman le puso sangre. No sabe si eso lo salvo o lo condeno. Le dije que estar vivo tambien puede ser una respuesta.", mudanza = "Stanley llega a la comisaria con su maletin mordido, las libretas de puertas y una caja de herramientas. Pide un banco de trabajo y un rincon para estudiar la Biblia los miercoles, aunque vaya uno solo. Arregla el generador, la bomba y dos linternas el primer dia. No acepta que le celebren nada. Cada manana sale a tocar una puerta del campamento, aunque ya sepa quien vive ahi, y anota: vive. Dice que asi practica para el Paraiso, y que una puerta que se abre de buena gana tambien es una respuesta de Jehova.", muerte = "Stanley Schaefer murio en una puerta que nadie abrio. Llevaba la libreta en el bolsillo. La ultima linea decia: vive." } },
    { id = "s074", nombre = "Selma", apellido = "Uribe", apodo = "la Selma de los parches", sexo = "m", edad = 53, pueblo = "West Point", oficio = "costurera", vive = true, lazos = {"chela"}, textos = { llegada = "A ver, a ver, mijo, pase. Sientese primero, que yo siempre me siento primero. Que se le rompio?", rescate = "Ay, mijo. Me cai? No me diga. Gracias por quedarse. Pongame la cabeza de lado, asi.", gracias = "Que Dios se lo pague, mijo. Le debo un ruedo, una chaqueta y lo que haga falta.", revelacion1 = "Selma Uribe, costurera de West Point. Coso los parches del cuartel de la Chela desde el setenta y tres. Tengo epilepsia y nunca me dieron licencia de manejar.", revelacion2 = "En el sesenta y cinco me cai con mi Fito en brazos. Tres puntos en la frente del nino. Desde ese dia no tomo a una guagua de pie. Sentada en el suelo, nomas.", revelacion3 = "Mi viejo no esta en el Fuerte. Lo encontre afuera del porton del Doe Run con mis remedios en la mano. Fui manejando yo, mijo. Yo. La camioneta esta en mi garaje.", diario_conocer = "Selma Uribe, costurera de West Point. Tiene epilepsia y se sienta antes de hablar. Dice que su marido esta en el Fuerte.", diario_final = "Selma manejo de noche hasta el porton del Doe Run y encontro a su marido muerto con sus pastillas. La camioneta sigue en su garaje. Ahora alguien mas lo sabe.", mudanza = "Selma llega al cuartel con su Singer en una carretilla y un colchon que pone en el suelo. Pide una mesa sin escalones cerca y que le avisen si la luz parpadea. Arregla ponchos, frazadas y botas en la mesa larga. Un dia le entrega a la Chela una llave con un llavero del Ejercito y le dice: La Ford de mi viejo, en la calle Spring. Usted maneja sin licencia y yo tambien. Esa noche pide que le guarden un lugar en el cementerio para el Abundio.", muerte = "Selma Uribe murio en el camino. Le cerramos la mano sobre el dedal de plata. Nunca le dio la licencia nadie, y manejo igual." } },
    { id = "s075", nombre = "Orval", apellido = "Quintero", apodo = "el Fischer", sexo = "h", edad = 28, pueblo = "Riverside", oficio = "electricista", vive = true, lazos = {"duggan"}, textos = { llegada = "Peon cuatro rey. Perdon, costumbre. Que necesita? Si es luz, tengo baterias. Si es suerte, no.", rescate = "Eso no lo calcule. Gracias. Me debia esa jugada el tablero, o se la debo yo a usted.", gracias = "Bien jugado. Eso ya esta jugado y salio. Pocas veces me pasa.", revelacion1 = "Orval Quintero, electricista de Riverside. Armo luz con baterias de auto. De nino fui campeon de ajedrez de Kentucky. Ahora juego los jueves en Gabbard's.", revelacion2 = "A los trece me quede helado en un torneo y perdi cinco seguidas. Mi papa no me hablo en todo el viaje. En el ochenta y ocho me pidio una partida en el hospital. Le dije otro dia.", revelacion3 = "Pierdo a proposito contra Shuffett. La unica vez que le gane, le rompio los vidrios a mi mama. Pago doble con mis latas. Puedo ganarle con los ojos cerrados.", diario_conocer = "Orval Quintero, electricista de Riverside, arma luz con baterias. Habla en jugadas de ajedrez y se come los dedos. Dice que nunca juega en serio.", diario_final = "Orval pierde a proposito para proteger a su mama de la banda de Duggan. Me pidio que estuviera en el meson el jueves en que gane. Voy a estar.", mudanza = "Orval llega a la iglesia con su mama, un cajon de baterias y el tablero de su papa, el del fusible en vez del alfil. Arma un foco en la sacristia y otro en la escalera, para que la puerta abierta se vea de noche. Pide una mesa y una silla vacia enfrente. Juega con quien se siente, ninos incluidos, y por primera vez juega en serio. Dice que ya no tiene nada que perder, y que eso es la mejor apertura que conoce.", muerte = "Orval Quintero murio en el camino. Dejo una partida a medias anotada en la palma. Le tocaba mover a el." } },
    { id = "s076", nombre = "Yolanda", apellido = "Crabtree", apodo = "Oficial Crabtree", sexo = "m", edad = 65, pueblo = "Rosewood", oficio = "policia", vive = true, lazos = {"rosa"}, textos = { llegada = "Alto ahi, mijito. Oficial Crabtree, policia de Rosewood. Baje la voz, que la nina duerme.", rescate = "Sientese, mijito, que esto va para largo. Me salvo a mi y a la nina. Eso no se olvida.", gracias = "Bien hecho. Lo anoto en el parte, aunque ya no haya a quien mandarselo.", revelacion1 = "Yolanda Crabtree, policia de Rosewood desde el setenta y cuatro. Nieta de partera de los cerros de Leslie. Llevo yerbas en la guantera y una guagua en el chal.", revelacion2 = "En el sesenta y uno un borracho atropello a mi marido en la 31. A la manana limpie la sangre yo sola, con lejia y escoba. Nadie me ayudo. Todavia se donde quedo la mancha.", revelacion3 = "Sudie no es mi bisnieta. La recibi la primera noche en la patrulla. La abuela la busco en la gasolinera y le menti con la placa puesta. Vive en Ekron, en la casa amarilla.", diario_conocer = "La oficial Yolanda Crabtree sigue de policia en Rosewood a los 65, con una guagua en el chal. Fue la primera en llegar cuando murio el marido de la Misia Rosa.", diario_final = "Sudie tiene una abuela en Ekron que la busca. Yolanda lo sabe desde octubre. Me pidio que fuera con ella a la casa amarilla. Que no la dejara arrepentirse.", mudanza = "Yolanda llega a la gasolinera con Sudie en el chal, el bolso de cuero de su abuela y la placa prendida en el chaleco. Pide un rincon tibio para la nina y una mesa para secar yerbas. Atiende cortes, toses y peleas con la misma voz baja. Les mira las manos a todos los que llegan. En las noches le cuenta a la Misia Rosa partos de los cerros, y Rosa le cuenta camioneros. Las dos dejan la luz prendida. Dice que al fin hay una comisaria que no cierra.", muerte = "La oficial Yolanda Crabtree murio en el camino. Sudie quedo en el campamento. Alguien tiene que llevarla a la casa amarilla." } },
    { id = "s077", nombre = "Vance", apellido = "Bowman", apodo = "el profe Bowman", sexo = "h", edad = 40, pueblo = "Muldraugh", oficio = "profesora", vive = true, lazos = {"cabo", "reyes"}, textos = { llegada = "Pase, amigo, pase. Hay silla y hay sopa. Despues le explico la leccion, con dibujo. Me sigue?", rescate = "Gracias, hermano. Dios manda ayuda de las formas mas raras. Hoy le toco a usted. Me sigue?", gracias = "Perfecto. Esto alcanza para el garaje una semana. Lo anoto en el pizarron, con su nombre.", revelacion1 = "Vance Bowman, profesor de biologia de Muldraugh. Predico en mi garaje con pizarron y tiza. Nunca paso el platillo, no como el Diacono del patio de trenes.", revelacion2 = "En el ochenta y dos murio mi hermano Royal en la 31W. El parte dice que se nos cruzo un ciervo. Yo manejaba y habia tomado. No habia ningun ciervo.", revelacion3 = "En agosto le puse mi sangre a Stanley Schaefer mientras se desangraba. Lei su tarjeta: nada de sangre. Lo hice igual. El cree que la herida cerro sola.", diario_conocer = "Vance Bowman, profesor de Muldraugh, tiene treinta personas en su garaje y les explica a Dios con tiza. No pasa el platillo. Habla de un ciervo.", diario_final = "Vance salvo a Stanley con su sangre contra su voluntad, y su hermano murio en un choque que el parte le culpa a un ciervo. Dos verdades que no dice.", mudanza = "Vance llega a la comisaria con su mama del brazo, Leigh Ann con la mochila y el pizarron en la espalda. Pide una pared para colgarlo. Arma clases de manana para los ninos: sumas, plantas que se comen, como hervir el agua. En la noche dice una oracion corta, sin platillo. Un miercoles cuenta, delante de todos y con su hija en la primera fila, que no hubo ciervo. Leigh Ann se queda sentada. Despues le corrige la ortografia del pizarron.", muerte = "Vance Bowman murio en el camino. En el pizarron del garaje quedo la fecha, escrita en la esquina, como siempre." } },
    { id = "s078", nombre = "Vonda", apellido = "Lindgren", apodo = "la enfermera Vonda", sexo = "m", edad = 77, pueblo = "West Point", oficio = "enfermera", vive = true, lazos = {"chela"}, textos = { llegada = "Brazo. No, el otro. Aigo, estas palido. Comiste? Sientate. Despues me dices que quieres.", rescate = "Llegaste tarde, babo. Pero llegaste. Dame la mano, que no me puedo levantar sola.", gracias = "Bien. Esto me sirve. Ahora brazo, que te tomo la presion. No se paga de otra forma.", revelacion1 = "Vonda Lindgren, enfermera de West Point. Me llamo Han Bong-ja. En el hospital del Fuerte conoci a Mae, la mama de la Chela. Ahora le coso los bomberos a la hija.", revelacion2 = "En el cincuenta los del norte se llevaron a mi primer marido con una camisa blanca. Nunca supe si estaba viuda cuando me case con Arne. El dijo: si llega, hago cafe.", revelacion3 = "Debajo de la tinaja grande hay seis frascos de Dilantin. La Selma se raciona y se cae, y yo la recojo. Si sabe que hay mas, se va al cuartel. No quiero estar sola.", diario_conocer = "Vonda Lindgren, enfermera coreana de West Point, me tomo la presion antes de saludarme. Tiene setenta y siete y manos firmes. Vive con una vecina.", diario_final = "Vonda escondia los remedios de Selma para que no se fuera. Le dije que nadie se va de una mujer que cose bomberos. Saco los frascos de la tinaja.", mudanza = "Vonda llega al cuartel en la carretilla, con el baston de Arne, una caja de hilos y una tinaja de kimchi que nadie le pidio. Pone una mesa de curar al lado de la puerta y les toma la presion a todos los que entran. Pelea con el curandero por las agujas y gana. En la noche duerme cerca de Selma, sin esconder nada. Dice que el cuartel huele a humo y a sopa, y que eso es mejor que un sotano lleno de cosas guardadas.", muerte = "Vonda Lindgren murio en el camino. Tenia el baston de Arne en una mano y una aguja enhebrada en la otra." } },
    { id = "s079", nombre = "Cletus", apellido = "Gabbard", apodo = "Cleet", sexo = "h", edad = 52, pueblo = "Riverside", oficio = "cocinera", vive = true, lazos = {"nacho"}, textos = { llegada = "Sientese, soldado. Coma primero y despues me cuenta. Hay bizcochos y porotos. Mas cafe?", rescate = "Uf. Gracias, joven. Con este pie no corro ni detras de un bizcocho. Le debo un plato por semana.", gracias = "Eso es harina para un mes. Venga el domingo, que le guardo el primer plato. Mas cafe?", revelacion1 = "Cletus Gabbard, cocinero de Riverside. Gabbard's Lunch, a media cuadra de la Hollis. Fui cocinero de tropa en Alemania. El Padre toma cafe en mi meson.", revelacion2 = "Mi papa desembarco en Omaha, eso cuento. En el ochenta y cuatro lei su papel de baja: llego en agosto, en camiones. Nunca piso la playa. Sigo contando la historia igual.", revelacion3 = "En septiembre le pegue ocho correazos a un cabro que me robo harina. Con la correa de mi papa, contando como el. Desde esa noche le dejo bizcochos en la ventana.", diario_conocer = "Cletus Gabbard le da de comer a cualquiera en su meson de Riverside. Le compraba el pan a Walt Hollis cada manana. Cuenta lo de Normandia demasiado bien.", diario_final = "Cletus le pego a un chico con la correa de su padre y desde entonces le deja bizcochos en la ventana. Me pidio que buscara al cabro. Se saco la correa.", mudanza = "Cletus llega a la iglesia con dos sacos de harina, su sarten mas grande y un delantal limpio. Pide la cocina y nada mas. Cocina para todos en ollas de cuarenta, como en Baumholder, y deja una fuente de bizcochos en la ventana de la sacristia todas las noches, por si acaso. Ya no cuenta la historia de Omaha. Si un nino le pregunta por la guerra, le dice que el estuvo en la cocina, y que sin la cocina no se gana ninguna.", muerte = "Cletus Gabbard murio en el camino. Esa noche alguien dejo bizcochos en la ventana de atras de su meson, por costumbre." } },
    { id = "s080", nombre = "Mai", apellido = "Hammonds", apodo = "la pastora", sexo = "m", edad = 27, pueblo = "Rosewood", oficio = "granjero", vive = true, lazos = {"rosa"}, textos = { llegada = "Tranquila, tranquila. No, a usted no, al perro. Bueno, a usted tambien. Que necesita?", rescate = "Gracias. Deacon, quieto, es amigo. Se me ahogaban todas. Le debo un cordero.", gracias = "Bien. Con esto paso la paricion. Lleve lana, que en la noche hiela.", revelacion1 = "Mai Hammonds, granjera de Rosewood. Crio ovejas en el campo de mi abuelo Rufus. A la Misia Rosa le cambio cordero por pilas, y le llevo leche a una guagua.", revelacion2 = "Tengo un hermano gemelo, Asa. A los siete le dije al juez que Asa se fuera con papa. Por una corderita muerta. Se fue a Dayton y no nos hablamos desde entonces.", revelacion3 = "La primera noche llame a Asa. Contesto: Mai? Le colgue. A las nueve y media ya no habia tono. A todos les digo que nunca lo llame.", diario_conocer = "Mai Hammonds cria ovejas en Rosewood y les habla igual que a la gente. Tiene un perro que se llama Deacon y no me miro a los ojos.", diario_final = "Mai llamo a su gemelo la primera noche y le colgo cuando dijo su nombre. Me lo conto a mi. Dice que es como si se lo hubiera dicho a el.", mudanza = "Mai llega a la gasolinera con Deacon, una docena de ovejas y un fardo de lana. Pide un corral detras del taller y nada mas. Ordena, esquila y carnea para todos, y le lleva la leche a la guagua de la oficial Crabtree. Habla poco. Una noche se sienta junto a la radio de Junior, mira el microfono un rato largo y dice Asa, una sola vez, a nadie. Despues vuelve al corral a contar las ovejas, dos veces, como siempre, y revisa todas las trancas.", muerte = "Mai Hammonds murio en el camino. Deacon volvio solo al corral y se echo en la esquina del cerco." } },
    { id = "s081", nombre = "Gideon", apellido = "Kowalczyk", apodo = "el Polaco", sexo = "h", edad = 64, pueblo = "Muldraugh", oficio = "carpintero", vive = true, lazos = {"cabo", "wade_bell"}, textos = { llegada = "P-p-pase. Despacito. No me apure la palabra, que la madera tampoco se apura.", rescate = "D-dos golpes es si. Gracias. Escrito se lo digo mejor. Tiene un lapiz?", gracias = "Esto vale. Se lo dejo anotado en la madera, que dura mas que yo.", revelacion1 = "Gideon Kowalczyk, carpintero de Muldraugh desde el 36. Mi padre hizo la boveda del oro del Fuerte. Yo hice la tarima del gimnasio de la escuela. Y tartamudeo, ya se dio cuenta.", revelacion2 = "En Corea contestaba con el martillo: dos golpes es si. Mi Phil nunca me termino una palabra. Esperaba con el cafe. Treinta y dos inviernos esperando.", revelacion3 = "La viga del porton tenia una grieta. La vi. Quise decirlo y me trabe. Verlon me termino la frase: perfecta. Dije que si con la cabeza. Murieron cuatro. No fueron los muertos. Fue mi boca.", diario_conocer = "Gideon, carpintero de Muldraugh. Tartamudea en las p y silba en vez de hablar. Antes de decirme su nombre me paso una tabla tallada.", diario_final = "Gideon me conto lo de la viga por escrito. Cuatro nombres tallados en nogal. No fue la horda: fue una palabra que no le salio a tiempo.", mudanza = "Gideon llega a la comisaria con su caja de herramientas y cinco tablas envueltas en una frazada. No pide nada. Escribe en el pizarron de los partes: \"Arreglo lo que se rompa. No me apuren\". Al dia siguiente la puerta de atras tiene bisagras nuevas y no chilla. El Cabo le pregunta algo y el espera, y el Cabo espera tambien, sin terminarle la frase. Esa noche Gideon le dice en voz alta, trabandose, los cuatro nombres del almacen. El Cabo los anota con tinta. Gideon duerme en el galpon del patio, entre aserrin, silbando.", muerte = "Gideon Kowalczyk murio silbando. Le quedo una tabla sin terminar. Le escribi el nombre yo, con lapiz, y me trabe." } },
    { id = "s082", nombre = "Cassie", apellido = "Bryant", apodo = "Cam", sexo = "m", edad = 39, pueblo = "West Point", oficio = "cazador", vive = true, lazos = {"chela"}, textos = { llegada = "Despacio. Las manos donde las vea. Bueno. Usted no es de aqui, se nota en como camina.", rescate = "Usted espero. Bien. Los hombres de aqui no saben esperar. Gracias.", gracias = "Bueno. Esto es para Lien. Le doy un conejo limpio. No lo desperdicie.", revelacion1 = "Me llamo Cam, aqui dicen Cassie. Cazo en West Point. Cambio conejos limpios por agua de la Colorina de la Chela. Me la trae el nino de los binoculares.", revelacion2 = "Junio del 79. Un bote de rio, cincuenta y nueve personas, agua para cinco. Mi hermano Thanh tenia dieciseis. El dia seis lo pusimos en el mar con su camisa.", revelacion3 = "Tengo un bote para dos en el rio Salt. En septiembre cruce el Ohio con Lien y nos dispararon. Voy a probar con la niebla. Omie no cabe. Ella no sabe.", diario_conocer = "Cassie Bryant, cazadora de West Point. Vietnamita, llego en bote en el 79. Lleva siempre una cantimplora llena. No me quito los ojos de las manos.", diario_final = "Cassie tiene un bote escondido y un plan para dos. La suegra no sabe que no cabe. Ella ya cruzo un mar asi una vez y no quiere elegir otra vez.", mudanza = "Cassie llega al cuartel con Lien de la mano y Omie en una carretilla con frazadas. Trae tres conejos limpios y los deja en la mesa sin decir nada. La Chela le dice \"mija\" y ella la corrige: \"Cam\". Se sube al techo con Jody a vigilar, porque sabe esperar. Le ensena a Lien a escribir los nombres de todos en la lista de platos, con faltas. El bote sigue en el sauce del rio Salt, tapado con ramas. Cada noche de niebla, Cassie mira el rio desde el techo y despues baja a dormir.", muerte = "Cassie Bryant murio esperando, sin hacer ruido. La cantimplora estaba llena. Se la lleve a Lien." } },
    { id = "s083", nombre = "Hans", apellido = "Thacker", sexo = "h", edad = 76, pueblo = "Riverside", oficio = "granjero", vive = true, lazos = {"duggan", "nacho"}, textos = { llegada = "Hable fuerte, companero, que el oido izquierdo me lo dejo la Ford. Que trae y quien lo manda?", rescate = "Herrgott. Gracias, companero. Ayudeme a pararme, que el pecho no me da.", gracias = "Trato cumplido. Eso decia el papel y esta vez el papel no miente.", revelacion1 = "Hans Thacker. Cuarenta y un inviernos en la Ford de Louisville, delegado de la 862. Ahora tengo vacas en Riverside. Pocas.", revelacion2 = "A mi hermano Fritz lo mataron en Alemania en el 44. Yo hacia jeeps. En la estacion le dije imbecil. Fue lo ultimo que le dije.", revelacion3 = "Arme la asamblea del camino para no pagarle al Martillo. Cuando Curtis vino con el bidon, le dije donde guardabamos el maiz: el galpon de los Gividen. Salve el mio. Creen que adivino.", diario_conocer = "Hans Thacker, granjero viejo de Riverside, ex sindicalista de la Ford. Sordo de un oido, me llama companero y desconfia de mi libreta.", diario_final = "Hans armo a sus vecinos para no pagar y despues le dio a Curtis el galpon de los Gividen para salvar el suyo. Se paso al otro lado de la mesa.", mudanza = "Hans llega a la iglesia de piedra con una vaca de una cuerda y el barril de chucrut en la carretilla. \"No vengo a rezar, vengo a trabajar\", le dice al Padre. Ruth le recibe la leche en la puerta de la cocina, como todos los domingos, pero esta vez lo hace pasar. Arma turnos de ordena y de guardia en una libreta de la Ford y discute con todos. Un viernes, cuando Curtis pasa por la calle con la tiza, Hans junta a los del camino en el atrio y les cuenta lo del galpon de los Gividen. Despues se sienta y se toma el cafe.", muerte = "Hans Thacker murio ahogado en su cocina, con la libreta de la Ford abierta en la pagina de la asamblea." } },
    { id = "s084", nombre = "Charlene", apellido = "Cooksey", apodo = "la Comisaria", sexo = "m", edad = 51, pueblo = "Rosewood", oficio = "camionero", vive = true, lazos = {"earl", "rosa"}, textos = { llegada = "Alto ahi, carino. Cuanto pesas y que traes? Ni una libra de mas en mi patio.", rescate = "Diez-cuatro. Te debo una, carino, y yo pago lo que debo. Sin sobre.", gracias = "Copiado. Esto pesa lo justo. Ni una libra de mas, ni una de menos.", revelacion1 = "Charlene Cooksey, camionera de Rosewood. Llevaba vacas a Louisville. Don Hector Bencina me arreglo el freno gratis en el 78. En la radio me dicen la Comisaria.", revelacion2 = "Mi papa era el sheriff Haskell Cooksey. A los nueve yo le repartia sobres en bicicleta. A los dieciseis vi uno con una G, la semana que mataron a Noreen Sallee.", revelacion3 = "Tengo la libreta de mi papa. Abril del 58: Gatewood, 2.000. Con esa linea le saco diesel a Buddy cada viernes y lo dejo en las puertas. Un sobre, carino. Igualito que el.", diario_conocer = "Charlene Cooksey, camionera de Rosewood. Hija de un sheriff. Duerme en la cabina de su Peterbilt y me peso la mochila antes de dejarme pasar.", diario_final = "Charlene chantajea a Gatewood con la libreta de su padre y reparte lo que le saca. Hace lo que el sheriff, pero al reves. Ella no cree que sea al reves.", mudanza = "Charlene llega a la gasolinera manejando el Peterbilt con los ultimos novillos en el remolque. Rosa le pregunta lleno o normal y ella dice: \"Lleno de vacas, dona Rosa\". Estaciona el camion detras del taller y duerme en la cabina. Faena en el galpon y le pasa la carne salada a Rosa para la olla. Una noche le confiesa que los sacos sin nombre eran suyos. Rosa no le pregunta de donde salian. Charlene quema una pagina de la libreta en el tarro de la basura. Le quedan veinte.", muerte = "Charlene Cooksey murio con la libreta en el bolsillo de la camisa. No alcanzo a leerla en voz alta. La lei yo." } },
    { id = "s085", nombre = "Cornelius", apellido = "Minix", sexo = "h", edad = 26, pueblo = "Muldraugh", oficio = "mecanico", vive = true, lazos = {"cabo"}, textos = { llegada = "Jefe! Pase, pase. Que necesita? Abro cualquier cosa en nueve segundos, para ser honesto.", rescate = "Uf, socio, me salvo la vida. Esa se la debo. Y yo las deudas las conozco bien.", gracias = "Trato hecho, jefe. Ni le cobro la propina. Bueno, un poquito.", revelacion1 = "Cornelius Minix, mecanico de Muldraugh. Trabajaba en el taller de Zollie Pettibone, en la 31W. Ahora la grua es mia y le despejo las calles al Cabo.", revelacion2 = "Fui cobrador en la Dixie Highway seis veranos. Un viejo, el senor Huckaby, me pago con el anillo de su senora muerta. Y yo lo agarre, con la sonrisa.", revelacion3 = "Mire la billetera. Ahi esta la licencia. Detras, nada. Cambie el anillo por amoxicilina para Zollie y Zollie se murio igual. Le quite el anillo a ese viejo dos veces.", diario_conocer = "Cornelius Minix, mecanico de Muldraugh, ex cobrador. Habla rapido, me dice jefe y abrio una camioneta en nueve segundos para mostrarme.", diario_final = "El anillo que Cornelius muestra en la billetera no existe. Lo cambio por remedios para un viejo que se murio igual. Me lo dijo sin sonreir.", mudanza = "Cornelius llega a la comisaria con la grua remolcando un auto lleno de repuestos. \"Para el campamento, jefe. Gratis. Bueno, casi\". El Cabo lo anota en la libreta y le asigna el patio de los patrulleros. Cornelius les abre autos a todos y cuenta chistes en la cocina. Una noche, lavando platos, le muestra la billetera vacia a Hattie y le cuenta lo del anillo. Desde ahi sonrie menos y trabaja mas. Duerme en la grua, con la radio apagada.", muerte = "Cornelius Minix murio debajo de un auto que estaba abriendo para otro. La billetera tenia la licencia y nada mas." } },
    { id = "s086", nombre = "Geneva", apellido = "Lawson", apodo = "la Hippie", sexo = "m", edad = 63, pueblo = "West Point", oficio = "costurera", vive = true, lazos = {"chela", "gladys"}, textos = { llegada = "Ay, hermano, pasa, pasa. Paz. Mira esa manga rota, ven que te la coso mientras hablamos.", rescate = "Ay, hermano, que energia la tuya. Gracias. Pasame el dedal, que me tiemblan las manos.", gracias = "Esto es una bendicion, hermano. Te coso una chaqueta que no la atraviesa ni un diente.", revelacion1 = "Geneva Lawson, costurera de West Point. Le subia el ruedo a los soldados del Fuerte. Ahora coso chaquetas acolchadas, tres capas, contra las mordidas.", revelacion2 = "En el 71, a los cuarenta y uno, me fui a una comuna en Tennessee con mi Singer. Mi Michael estaba en Vietnam. Volvio y yo no estaba. No me lo perdono.", revelacion3 = "En agosto Michael paso por mi calle con su familia, a pie, rumbo a Brandenburg. Yo estaba detras de la cortina con la colcha en las manos. No sali. Digo que era uno parecido. Era el.", diario_conocer = "Geneva Lawson, costurera de West Point con trenza blanca. Me dice hermano. Me coso la manga sin preguntarme el nombre.", diario_final = "Geneva vio pasar a su hijo y no salio de detras de la cortina. Le puso a la colcha un cuadro negro con una puntada blanca: ella.", mudanza = "Geneva llega al cuartel con la Singer portatil, una bolsa de retazos y la colcha doblada. La Chela le da el rincon de las mangueras y ella lo llena de chaquetas acolchadas. Cose para todos, de dia, cerca de la ventana. A la Chela le hace una chaqueta con los bolsillos donde ella los quiere. Pregunta a cada uno que llega si viene de Brandenburg. Una noche le cuenta a la Chela lo de la cortina. La Chela le dice: \"Mija, la cortina no es una puerta. Todavia se puede salir\".", muerte = "Geneva Lawson murio con el dedal puesto. La colcha estaba casi terminada. Le falta el ultimo cuadro." } },
    { id = "s087", nombre = "Harvey", apellido = "Kirby", apodo = "Zurdo", sexo = "h", edad = 38, pueblo = "Riverside", oficio = "electricista", vive = true, lazos = {"nacho"}, textos = { llegada = "Que tal, amigo. Pase por el portoncito, el de la izquierda, que las latas del alambre suenan.", rescate = "Fuera del parque, amigo! Me salvaste en la novena. Te debo una cerveza que ya no existe.", gracias = "Strike tres. Asi es el juego, amigo. Gracias, de verdad.", revelacion1 = "Harvey Kirby, electricista de Riverside. Puse las luces de la cancha de la liga infantil de la parroquia. Trabajo con la izquierda: el hombro derecho no sube.", revelacion2 = "Jugue cuatro temporadas en las menores, con los Rojos. La noche que murio mi papa yo lance igual. Perdi cuatro a uno. Llegue despues del entierro.", revelacion3 = "Mi mama esta sola en la granja, a dos millas. Desde septiembre no cruzo el potrero: habia once en el tabacal. A Lynette le digo que fui y que ella no quiere venir. Veo el humo y nada mas.", diario_conocer = "Harvey Kirby, electricista de Riverside y ex lanzador. Me explico su patio como si fuera un conteo de bolas y strikes.", diario_final = "Harvey no va a ver a su madre desde septiembre por miedo al tabacal y miente que ella no quiere venir. Llego tarde a su padre; a ella no llega.", mudanza = "Harvey llega a la iglesia de piedra con Lynette, los ninos y la camioneta llena de baterias. Atras, envuelta en una frazada, viene su mama, Ona: la fueron a buscar contigo, cruzando el potrero de dia, y Harvey no solto la escopeta en las dos millas. La luz de la iglesia ya tiene dueno, asi que le arma al campamento un cargador de baterias con el alternador de la camioneta, para las linternas y la radio. Le ensena a Joey a soldar cables y juegan a tirarse la pelota en el atrio, despacio, con la izquierda. Ona los mira desde la escalera.", muerte = "Harvey Kirby murio con un cable en la mano izquierda. Joey le cerro los ojos. No lloro hasta despues." } },
    { id = "s088", nombre = "Juanita", apellido = "Jablonski", apodo = "Oficial J", sexo = "m", edad = 75, pueblo = "Rosewood", oficio = "policia", vive = true, lazos = {"rosa"}, textos = { llegada = "Alto ahi, jovencito. Pies juntos. Asi. Ahora digame quien es y que quiere.", rescate = "Cinco, seis, siete, ocho... Gracias, jovencito. No me ofrezca el brazo. Bueno, ofrezcamelo.", gracias = "Asi. Bien hecho. Usted tiene buenos pies, jovencito.", revelacion1 = "Juanita Jablonski. Hago el cruce de la escuela de Rosewood y la fila del agua de los ninos. Fui veintisiete inviernos policia de menores en Louisville.", revelacion2 = "A los dieciocho me fui a Chicago a bailar. Iba a llegar a Nueva York. En Cincinnati una tabla suelta me rompio la rodilla. Termine el numero sentada.", revelacion3 = "Me tomo el jarabe con codeina de los ninos de la fila. Una cucharada, ahora dos, para estar de pie contando en ocho. A la nieta de la vecina le di media y le dije que esa era la dosis.", diario_conocer = "Juanita Jablonski, setenta y cinco, guardia de cruce de Rosewood. Me hizo pararme derecho antes de hablarme. Los ninos le obedecen el pito.", diario_final = "Juanita se toma el jarabe de los ninos para que la rodilla aguante la fila del agua. Mintio en la dosis. Dice que sin ella no hay fila.", mudanza = "Juanita llega a la gasolinera de tu brazo, aunque dice que no lo necesita. Rosa le pregunta lleno o normal y ella dice: \"Un cafe, senora; la bencina no baila\". Se sienta junto a la caja y ordena a los ninos del campamento con el pito: fila para el agua, fila para la sopa. Elige a un nino de la fila, el mas serio, y le ensena a tocar el pito y a contar en ocho. Una manana le entrega el frasco de jarabe a Rosa, a medio terminar, y se sienta a mirar la fila desde la silla.", muerte = "Juanita Jablonski murio derecha, contando en ocho. No le alcanzo para llegar al ocho." } },
    { id = "s089", nombre = "Quentin", apellido = "Tipton", apodo = "el Profe Tipton", sexo = "h", edad = 50, pueblo = "Muldraugh", oficio = "profesora", vive = true, lazos = {"cabo", "valentina"}, textos = { llegada = "Como les decia a mis alumnos: toque dos veces y espere. No salgo, pero escucho. Quien es usted?", rescate = "Estoy afuera. Afuera de mi casa. Como les decia a mis alumnos: siempre hay una primera vez.", gracias = "Muy bien. Sobresaliente. Se lo anotaria en el libro de clases, si todavia hubiera clases.", revelacion1 = "Quentin Tipton, profesor de Historia de la secundaria de Muldraugh desde el 65. Nunca he salido del condado de Knox. Louisville cuenta.", revelacion2 = "Tuve de alumno al Cabo Mandados en el 68. Se sentaba de cara a la puerta. Yo tenia un pasaje a Gulfport para el 17 de julio. Queria ver si el mar es azul.", revelacion3 = "Corbin Haws tenia catorce. Le pagaba con revistas para que fuera a la farmacia por mis pastillas. La cuarta vez no volvio. Llevaba mi receta. Su mama cree que salio solo.", diario_conocer = "Quentin Tipton, profesor de Muldraugh. No sale de su casa desde julio. Me hablo por la ventana de atras con un mapa pegado al reves.", diario_final = "Quentin mando a un nino a buscarle remedios para no salir el. El nino no volvio. La madre le llora en el porche y el le sirve te.", mudanza = "Quentin cruza Muldraugh hasta la comisaria de tu brazo, contando las cuadras en voz baja. Seis. En la puerta de atras se detiene un minuto entero. El Cabo le dice: \"Pase, profesor. Aqui nadie se queda afuera\". Quentin le pide la sala de interrogatorios para hacer clases a los ninos con Valentina, y ella le deja la mitad de la pizarra. Ensena los rios del condado. Una noche le cuenta al Cabo lo de Corbin y el Cabo lo anota, con tinta.", muerte = "Quentin Tipton murio afuera de su casa, por fin. No vio el mar. Le quedaban once pastillas en el frasco." } },
    { id = "s090", nombre = "Inez", apellido = "Wells", apodo = "Nez", sexo = "m", edad = 25, pueblo = "West Point", oficio = "enfermera", vive = true, lazos = {"chela", "eduardo"}, textos = { llegada = "Corazon, sientate. Te tomo el pulso mientras me cuentas. Comiste algo hoy?", rescate = "Gracias, mi amor. Para ser exacta, me salvaste la vida y la de cuatro viejitos.", gracias = "Esto me alcanza para una semana, para ser exacta. Dalton, dale las gracias.", revelacion1 = "Inez Wells, enfermera auxiliar de West Point. Turno de noche en el Ohio Bend, el hogar de ancianos. Quedan cuatro viejitos. Los martes curo en el cuartel.", revelacion2 = "Tuve a Dalton a los quince, en la camioneta de los bomberos, con aguanieve. La Chela iba atras y me dijo: puje, que gritar es pa los que no tienen nada que hacer.", revelacion3 = "Le dije a Dalton que vi muerta a mi mama en la cuneta. No la vi. No se nada. Al tercer dia me dijo mama. Hay noches que rezo para que ella no aparezca.", diario_conocer = "Inez Wells, enfermera de West Point. Vive en un hogar de ancianos con su hijo y cuatro viejitos. Me tomo el pulso antes de saludarme.", diario_final = "Inez le mintio a su hijo sobre la abuela para que dejara de esperar. Desde entonces el le dice mama. Ella sabe lo que costo.", mudanza = "Inez llega al cuartel con Dalton, la maleta de enfermeria del Ohio Bend y los ultimos viejitos en una carretilla con frazadas. La Chela le arma una enfermeria en el banco de las mangueras: \"Aqui cura usted y yo cocino, mija. Y come\". Inez pone un horario de curaciones en la puerta. Dalton ayuda a Jody en el techo. Una noche Inez le pregunta a la Chela si alguien llego de Brandenburg con una cajera del IGA. La Chela no le contesta, le sirve plato.", muerte = "Inez Wells murio cuidando a otro. Dalton dijo mama una vez mas. No supo nunca lo de la abuela." } },
    { id = "s091", nombre = "Pete", apellido = "Taulbee", apodo = "la senora Pete", sexo = "h", edad = 62, pueblo = "Riverside", oficio = "cocinera", vive = true, lazos = {"nacho", "wade_bell"}, textos = { llegada = "Permitame, estimado, pase por la cocina y no por el gimnasio: ahi duermen. Hay biscuits, o habia.", rescate = "Gracias, joven. Tomo S, de Salvado. Ahora cuente conmigo: uno, dos, tres, cuatro, cinco. Estan todos.", gracias = "Esto alcanza para una semana de almuerzos. Le debo un tomo entero, estimado. Con letras doradas.", revelacion1 = "Fui el mejor vendedor de enciclopedias de Kentucky. Hoy soy la senora Pete: cocino en la escuela de Riverside para cinco ninos que nadie vino a buscar.", revelacion2 = "Mi Jewel se cayo en la cocina en el 79 y paso seis horas en el piso. Yo estaba en Owensboro vendiendo la letra V. Desde entonces no me muevo de una cocina.", revelacion3 = "Me he caido tres veces desde octubre. Se me tuerce la boca y se me van las palabras. En la puerta de la camara hay un sobre para Shiloh. Que no se quede conmigo en el piso.", diario_conocer = "Un viejo con malla en el pelo me ofrecio biscuits en la escuela de Riverside. Le cocinaba a Wade Bell. Cinco ninos lo llaman \"senora Pete\".", diario_final = "Pete lleva un sobre pegado en la camara para el dia que se caiga. No quiere que los ninos lo esperen. Yo tampoco quiero que lo esperen.", mudanza = "Me traigo a los cinco, estimado, y el cucharon, que se me pierde la palabra pero no el cucharon. Al Padre le pido una sola cosa: que me ponga en la cocina y que me mire de vez en cuando. Si me ve en el piso, que no espere. Los ninos ya saben su lista: Shiloh lleva a Precious, los mellizos van juntos, Tywan lleva el tarro de la mantequilla de mani. Yo llevo el tomo D, por si algun dia hay Dayton. En la iglesia hay puerta abierta. En mi cocina habia ventana abierta. Es casi lo mismo.", muerte = "Pete Taulbee murio con el delantal puesto. Abri el sobre de la camara. Llevamos a los cinco ninos a la iglesia, como el pidio." } },
    { id = "s092", nombre = "Orlena", apellido = "Jent", apodo = "la pastora", sexo = "m", edad = 37, pueblo = "Rosewood", oficio = "pastora", vive = true, lazos = {"rosa"}, textos = { llegada = "Pasa, hermano. Aqui hay reunion los viernes y culto el domingo. El cafe es malo a proposito.", rescate = "Gracias, hermano. Eso tambien es oracion: llegar a tiempo. Diselo a Dios, que anda distraido.", gracias = "Con esto pasamos otra semana. Un dia a la vez, hermano. Hoy el dia vino con tu nombre.", revelacion1 = "Soy la pastora del Nazareno de Rosewood y soy alcoholica. Cada manana digo cuantos dias llevo sin tomar. La Misia Rosa me manda achicoria, y no me cobra el rezo.", revelacion2 = "En el 88 fui borracha a la casa de mi ex y saque a mi hija del brazo hasta el auto. Le quebre la muneca. No lloro. Ya sabia no llorar conmigo.", revelacion3 = "En julio le di cucharadas de bourbon a Arbie para que no se muriera de los temblores. Despues me tome un trago. Uno. El numero que digo cada manana es mentira.", diario_conocer = "Una pastora flaca, que fuma tabaco de pipa, dice cada manana cuantos dias lleva sobria. Los fieles aplauden. Ella no.", diario_final = "Orlena tomo un trago en julio para salvar a un borracho. Sigue diciendo el numero viejo. Le dije que el nuevo tambien vale.", mudanza = "Me llevo a mis nueve y la reunion de los viernes. La senora Rosa dice que en su bomba hay luz toda la noche: a un borracho la luz le sirve, porque a oscuras es donde se toma. Que Arbie duerma cerca de la caja. Yo puedo dar clase a los ninos, barrer y escuchar a cualquiera que no pueda dormir. Y le pido una cosa: el primer viernes, delante de todos, voy a decir un numero nuevo. Ciento y tantos. Que nadie aplauda. Que alguien me pase el cafe malo.", muerte = "La pastora Orlena murio en un encargo. Arbie dijo el numero verdadero en el culto: el que ella contaba por dentro." } },
    { id = "s093", nombre = "Newt", apellido = "Arnett", apodo = "el papa del amarillo", sexo = "h", edad = 74, pueblo = "Muldraugh", oficio = "carpintero", vive = true, lazos = {"cabo", "pereira"}, textos = { llegada = "Hable fuerte, muchacho, del lado izquierdo. Y no toque esas cruces: estan recien lijadas.", rescate = "Llego a tiempo, muchacho. Mida dos veces la proxima vez, pero llegue igual de rapido.", gracias = "Clavos de los buenos. Con esto le hago una puerta que dure mas que yo. No es dificil.", revelacion1 = "Soy carpintero de Muldraugh. Hago cajones y cruces gratis; las de la comisaria tambien. El Cabo me tiene anotado: no quiere venir. El mio ya esta hecho, de nogal.", revelacion2 = "En el 45 hice puentes sobre el Rin para que cruzaran los muchachos. En el 70 cruce uno en Detroit para que mi hijo no fuera a Vietnam. Aqui me dicen el papa del amarillo.", revelacion3 = "Le hago las cruces a la banda del patio. Debajo, en lo que va enterrado, tallo el nombre de los que ellos mataron. Me los dice Brisco borracho. Si alguien da vuelta una, me matan.", diario_conocer = "Un carpintero viejo y medio sordo junto a las vias de Muldraugh. Hace cajones y cruces gratis. Me hablo del lado izquierdo.", diario_final = "Newt talla bajo las cruces de la banda los nombres de los que ellos mataron. Nadie los va a leer. Por eso los talla. Van diecinueve.", mudanza = "Voy, Cabo. Me traigo las herramientas de mano, la gubia chica y el cajon de nogal, que sirve de mesa hasta que sirva de cajon. Usted anota con tinta; yo anoto en madera. Al lado de las vias hay diecinueve cruces mias. Si algun dia esto se acaba, que alguien las saque, las de vuelta y lea lo de abajo. Ahi estan. Haga el parte sin adjetivos, como en el 77. Y un sabado al mes me lleva al cementerio a cortarle el pasto a Vinnie. Con tijera. Mida dos veces.", muerte = "Newt Arnett murio en un encargo. En su banco quedo la gubia chica. Bajo diecinueve cruces de las vias hay nombres tallados por el." } },
    { id = "s094", nombre = "Ivy", apellido = "Bailey", apodo = "Mamaw", sexo = "m", edad = 49, pueblo = "West Point", oficio = "cazador", vive = true, lazos = {"chela"}, textos = { llegada = "Quieto ahi, chiquillo. No subas al bote sin que te diga. Aqui arriba hay seis y yo las cuento.", rescate = "Me sacaste del barro, chiquillo. Eso se come. Ahora ayudame a llegar al bote antes que los ninos me vean asi.", gracias = "Balas de treinta-treinta. Con esto comen venado hasta marzo. Que Dios te lo pague, yo no tengo como.", revelacion1 = "Cazo para seis nietos en la casa flotante de mi papa, en la boca del Salt River. Los muertos no nadan. Ninguno de mis seis tiene una mordida.", revelacion2 = "Mi hija Rayanne estaba presa por pastillas. Las primeras se las di yo, en el 83, despues de una cesarea. Una mama le da lo que tiene, le dije.", revelacion3 = "En septiembre Rayanne llego de noche a la orilla, temblando. Le di el frasco de Percocet. Al amanecer estaba fria. Esta bajo el sauce. Los ninos no saben que vino.", diario_conocer = "Una mujer con trenza gris y un rifle viejo vive en una casa flotante con seis nietos. Me hizo esperar en la orilla hasta contarlos.", diario_final = "Ivy enterro a su hija bajo un sauce de la orilla y no se lo dijo a los nietos. Sigue cazando para ellos. Le mire las manos.", mudanza = "Si me voy al cuartel me llevo a los seis, el bote y el rifle de mi papa. La Chela da plato a todos; a mi me da un trabajo y no me pregunta, que eso es lo que necesito. Los grandes saben pescar y limpiar ardillas; los chicos acarrean agua. Yo puedo traer carne del lado del Fuerte. Una sola cosa: un domingo al mes vuelvo a la orilla del Salt River, sola. Hay un sauce que tengo que cuidar. No me acompanen. Eso no se come.", muerte = "Ivy Bailey murio en un encargo. Los seis nietos quedaron vivos. Alguien tiene que decirles lo del sauce." } },
    { id = "s095", nombre = "Arlo", apellido = "Conley", sexo = "h", edad = 24, pueblo = "Riverside", oficio = "granjero", vive = true, lazos = {"duggan", "nacho"}, textos = { llegada = "Buenas, senor. Con respeto, no se acerque al galpon sin avisar. Las vacas se asustan, y yo tambien.", rescate = "Gracias, senor. Me iba a ahogar, de asma o de lo otro. No se de cual primero. Perdon, me fui.", gracias = "Un inhalador. Con respeto, senor, eso vale mas que la Spencer. Que ya no tengo, pero igual.", revelacion1 = "Tengo la granja Conley, en el camino viejo a Muldraugh, y una coleccion de armas antiguas que no disparo. La Spencer era de un tatarabuelo de la Union.", revelacion2 = "Mi hermano Darrell era marine. Murio en Granada en el 83, el primer dia. La bandera esta arriba de la tele. Yo nunca fui a ninguna parte.", revelacion3 = "Les restauro armas viejas a los de Duggan y les cargo las balas en mi galpon, para que no nos cobren el tabaco. La Spencer la lleva uno de ellos. Cuando suenan tiros, conozco el ruido.", diario_conocer = "Un granjero alto y timido, con asma, me ofrecio leche en Riverside. Le manda leche al Padre Nacho. Sabe de armas viejas mas que de el.", diario_final = "Arlo arma a la banda de Duggan en su galpon para que no le cobren. Cuenta los tiros de noche. Dice que conoce el ruido de sus cargas.", mudanza = "Si nos vamos a la iglesia, el Padre tiene que saber que vienen dos vacas, mis papas, Christy y su papa con muletas. La leche es para todos, eso lo digo de entrada. La prensa de cargar la dejo en el galpon, desarmada, y le saco el resorte. Con respeto, Padre, quiero confesarme. Las balas de los de Duggan salen de mi galpon. Se lo digo una vez en voz alta y despues se lo digo a Christy. En ese orden. Y si un dia alguien me trae la Spencer, me la guarda usted.", muerte = "Arlo Conley murio en un encargo. Christy encontro en su cuaderno una pagina sin titulo, con fechas y calibres. Era la cuenta de la banda." } },
    { id = "s096", nombre = "Josie", apellido = "Mackey", apodo = "la Mantilla", sexo = "m", edad = 61, pueblo = "Rosewood", oficio = "camionero", vive = true, lazos = {"earl", "rosa"}, textos = { llegada = "Ay, carino, sube al patio despacito. La chiquilla duerme en la litera. Aqui la Mantilla, cambio.", rescate = "Me sacaste del barro, carino. Como en la 31: el que para, para. Gracias por parar.", gracias = "Pilas para la radio. Con esto la Mantilla vuelve al aire. Que se cuide la 31, que vuelve la chismosa.", revelacion1 = "Soy Josie Mackey, de Rosewood. Maneje camion veintiseis inviernos. En el 19 me dicen la Mantilla. Paro en la bomba de la Rosa desde el 67, cuando el Hector vivia.", revelacion2 = "En enero del 87 llame a mi Boyd por cobrar para que me trajera un filtro. Se mato en la curva de la cantera, viniendo. Desde entonces llevo tres filtros.", revelacion3 = "La primera noche fui a esa curva a tirarme con el camion, como el. La chiquilla aparecio en los focos, descalza. Por eso digo que la encontre en la 31.", diario_conocer = "Una camionera de dientes que silban vive en Rosewood con una nina ajena. Le dicen la Mantilla. Conoce al Gordo Whitaker de la radio.", diario_final = "Josie fue a matarse a la curva donde murio su hijo y una nina la detuvo. Ahora contesta cada llamada del 19. Contesto la mia.", mudanza = "Me voy donde la Rosa con la chiquilla, la radio y el Grover, si alguien me ayuda a manejarlo de noche, que sola no vuelvo. El camion tiene medio estanque: si un dia la Rosa necesita otro camion grande, ahi esta, carino, sin preguntar para que. Yo puedo estar en la radio de madrugada. A la Tassie que le den una cama cerca de la luz, que le tiene miedo al camino oscuro. A mi tambien. Y que la Rosa me pregunte \"lleno o normal\". Hace meses que no tengo que contestar nada.", muerte = "Josie Mackey murio en un encargo. Tassie tomo el microfono del 19 esa noche y dijo: aqui la Mantilla chica, cambio." } },
    { id = "s097", nombre = "Kenny", apellido = "Pennington", apodo = "Compuerta", sexo = "h", edad = 36, pueblo = "Muldraugh", oficio = "mecanico", vive = true, lazos = {"cabo", "pereira"}, textos = { llegada = "Pase, pero no toque nada que tenga aceite. Ni a mi, que tengo bastante. Todo es presion, sabe?", rescate = "Gracias. Estaba atrapado como una valvula sin salida. Ahora sale el agua. Respire usted tambien.", gracias = "Sinemet. Con esto mi papa traga por un mes. No le pregunte de donde saque el resto, por favor.", revelacion1 = "Soy Kenny, del taller Pennington de la 31W. Fui mecanico de la represa de Rough River. Volvi por mi papa, que tiene Parkinson. Al Cabo le arreglo la camioneta.", revelacion2 = "Por mi papa deje la represa y a la mujer que queria. Algunas noches, dandole la sopa, deseaba que se muriera para volver. Lo pensaba con fecha.", revelacion3 = "Los martes a las dos les arreglo los camiones a la Sargento, por las pastillas. Y mi papa escribio NO MAS en la pizarra. Lo borre. No lo dejo irse.", diario_conocer = "Un mecanico grande de Muldraugh le habla a los motores y a su papa con la misma voz. Me pidio pastillas, no comida.", diario_final = "Kenny trabaja para la Sargento para mantener vivo a su papa, que le pidio parar. Deseo verdad: que alguien decida por los dos.", mudanza = "Si el Cabo me recibe, me llevo a mi papa en la camilla que le arme y la caja de herramientas. Le arreglo lo que haya: la bomba, la camioneta, el generador. Pero antes le tengo que decir donde estuve los martes, y que el Cabo lo anote con tinta. Si despues de eso no me quiere, entiendo. Mi papa necesita una pieza con ventana. Le gusta ver pasar los autos, aunque ya no pase ninguno. Y una pizarra nueva, que la vieja la borre demasiadas veces.", muerte = "Kenny Pennington murio en un encargo. Su papa escribio en la pizarra, con letra muy chica: KENNY. Nada mas." } },
    { id = "s098", nombre = "Odessa", apellido = "Goforth", apodo = "dona Dessa", sexo = "m", edad = 73, pueblo = "West Point", oficio = "costurera", vive = true, lazos = {"chela"}, textos = { llegada = "Por la puerta de atras, mi alma, que la de adelante es para las visitas. Le duele la barriga?", rescate = "Gracias, mi alma. Una vieja de Goose Creek no se cae dos veces. Bueno, calculo yo.", gracias = "Nitroglicerina. Con esto el corazon me aguanta hasta la Navidad. Y yo le coso lo que quiera.", revelacion1 = "Coso en la calle Elm baja de West Point y curo con hierbas a los que no le creen a los doctores. Le cosi a la Chela el vestido de novia, con bolsillo.", revelacion2 = "En el 51 le di aceite de ricino a mi Ransom, de ocho, por una apendicitis. Se me murio al tercer dia. Desde entonces mando afuera al de la barriga dura.", revelacion3 = "En octubre trate a la nieta de Ivy con aceite de ricino, igual que a mi Ransom, en vez de mandarla al cuartel. Se salvo de casualidad. A Ivy le dije que nunca fue grave.", diario_conocer = "Una costurera chiquita de West Point me atendio por la puerta de atras. Huele a hierbas. Me pregunto si me dolia la barriga.", diario_final = "Odessa repitio con una nina lo que mato a su hijo, y la nina vivio. A Ivy le dijo que no fue grave. Ella no se lo perdona.", mudanza = "Me voy al cuartel de la Chela, mi alma, si me dejan un rincon con luz para coser y un fogon para mis teteras. Me llevo la Singer, el cuaderno de la Mamaw Tennie y las tijeras de sastre. La Chela me conoce desde el 63; sabe que no cobro las hierbas. Pero antes le voy a decir a Ivy lo de su Mandy, en la cara. Y a la Chela le pido una cosa: que al de la barriga dura no lo atienda yo. Que me lo quite de las manos.", muerte = "Odessa Goforth murio en un encargo. Su cuaderno decia en la ultima linea: no lo vuelvas a hacer, Dessa. Que la entierren con su colcha." } },
    { id = "s099", nombre = "Isaac", apellido = "Owens", apodo = "Lije", sexo = "h", edad = 48, pueblo = "Riverside", oficio = "electricista", vive = true, lazos = {"nacho"}, textos = { llegada = "Alto. No toque el alambre. Zumba. Aja. Ahora si, pase por el portoncito.", rescate = "Gracias. Siguiente. Vamos a la casa. Por el portoncito, no por el alambre.", gracias = "Baterias. Aja. Con esto hay luz un mes. Gracias. Eso es todo.", revelacion1 = "Electricista. Riverside. Owens Electric, desde el 75. Al Padre le puse la estufa del salon. Ahora tengo un cerco que zumba. No me gustan los cercos que zumban.", revelacion2 = "Corea. La zona desmilitarizada, el 67. Alla decian que no habia guerra. A Tis Merriweather lo cargue seiscientas yardas. Aqui nadie me creyo. Siguiente.", revelacion3 = "En octubre conecte el cerco al generador. Doscientos cuarenta. Un muchacho de quince se robaba los camotes. Esta bajo la higuera. Rilla cree que es un perro.", diario_conocer = "Un electricista callado de Riverside vive con su mama y su esposa detras de un cerco que zumba. Contesta con tres palabras.", diario_final = "Isaac mato a un muchacho vivo con su cerco y lo enterro bajo la higuera. No tiene perro. Me lo dijo con tres palabras.", mudanza = "Vamos tres. Mi mama, Rilla y yo. Mi mama trae la plancha de carbon. Rilla, los frascos. Yo, el alambre y las baterias. Al Padre le pongo luz en la iglesia con baterias de auto, si quiere. Sin cerco. No quiero mas cercos. Puedo hacer guardia de noche: duermo poco. Una cosa. Antes de irme saco al muchacho de la higuera y lo llevo al cementerio de la iglesia. Que el Padre le ponga un signo de pregunta en la lista. No se su nombre.", muerte = "Isaac Owens murio en un encargo. En su sotano habia una zapatilla de nino sin cordones. Nadie sabe de quien era." } },
    { id = "s100", nombre = "Dottie", apellido = "Hoskins", apodo = "la Profesora", sexo = "m", edad = 23, pueblo = "Rosewood", oficio = "policia", vive = true, lazos = {"hector", "rosa"}, textos = { llegada = "Para que conste: alto ahi. Nombre, procedencia y si viene mordido. Lo anoto igual, conteste lo que conteste.", rescate = "Gracias. Hora: ahora. Lugar: aqui. Hecho: me salvo usted. Lo anoto en el libro con su nombre.", gracias = "Municion del treinta y ocho. Para que conste, esto es lo primero que me regalan en este oficio.", revelacion1 = "Soy Dottie Hoskins, policia de Rosewood. Patrullo a pie y anoto los muertos en un libro. A las once tomo achicoria donde la Misia Rosa. Mi papa le hizo clases al Junior.", revelacion2 = "Antes ensenaba historia en la universidad, en Richmond. Reprobe a un plagiador y el me acuso de algo que no hice. Nadie probo nada. Igual me sacaron.", revelacion3 = "En septiembre mi hermano mato por la espalda a un ladron vivo. Escribi en mi libro que estaba transformado. Es el primer parte falso de mi vida. Con letra bonita.", diario_conocer = "Una policia joven de anteojos trizados me pidio nombre y procedencia en Rosewood. Lo anoto todo en un libro. Mi nombre tambien.", diario_final = "Dottie escribio un parte falso para cubrir a su hermano. Dice que va a corregirlo con su firma. Le crei. Le pedi que me deje leerlo.", mudanza = "Me voy a la bomba de la senora Rosa con el libro de Rosewood y mi escopeta. Puedo hacer guardia, revisar a los que llegan y anotarlos con nombre y fecha, que es lo que se hacer. Mis papas y Wiley vienen conmigo, si la senora Rosa nos da un rincon. Una cosa: el primer dia voy a corregir un parte viejo, delante de alguien que firme como testigo. No hace falta que lo lea. Solo que vea que lo corregi. Para que conste.", muerte = "Dottie Hoskins murio en un encargo. Su libro de Rosewood tenia un parte corregido, con su firma. La ultima linea era mi nombre." } },
}

-- Piezas por etapa (ver personajes/secundarios/README.md).
D.PIEZAS = {
    { id = "l01_ori_aparceros", etapa = "origen", texto = "Soy {hijo} de aparceros de tabaco. Nunca tuvimos tierra propia: arrendabamos el sudor y nos pagaban en deudas con el almacen.", da = {"rural", "tabaco", "pobre", "familia_grande"}, prohibe = {"urbano", "acomodado"}, edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l01_ori_campamento_minero", etapa = "origen", texto = "Naci en un campamento minero de Harlan, en una casa de la compania donde el polvo de carbon se metia hasta en el pan.", da = {"montana", "minero", "pobre", "forastero"}, prohibe = {"nunca_salio", "urbano"}, edad_min = 25, edad_max = 85 },
    { id = "l01_ori_capilla", etapa = "origen", texto = "Naci en la casa pegada a una capilla de Santidad. Mi papa predicaba, mi mama tocaba un piano desafinado y yo tocaba la pandereta.", da = {"religioso", "santidad", "rural"}, prohibe = {"sin_fe", "catolico"}, edad_min = 18, edad_max = 85 },
    { id = "l01_ori_germantown", etapa = "origen", texto = "Mis padres llegaron de Europa y se instalaron en Germantown, en Louisville. En la casa se hablaba otro idioma y se rezaba en latin.", da = {"inmigrante", "louisville", "urbano", "catolico"}, prohibe = {"rural", "nunca_salio"}, edad_min = 18, edad_max = 85 },
    { id = "l01_ori_louisiana", etapa = "origen", texto = "Vine de Louisiana con una maleta y un frances que aqui nadie entendia. Mi papa hacia botes de cipres para pescar cangrejos de rio.", da = {"forastero", "rio"}, prohibe = {"nunca_salio"}, edad_min = 35, edad_max = 85, peso = 5 },
    { id = "l01_ori_negocio_rio", etapa = "origen", texto = "Naci arriba de un negocio del camino del rio, con olor a lombriz y a gasolina de motor fuera de borda. El Ohio fue mi primer patio.", da = {"rio", "nunca_salio", "comerciante"}, prohibe = {"forastero"}, edad_min = 18, edad_max = 85, pueblos = {"West Point", "Riverside"} },
    { id = "l01_ori_sombra_fuerte", etapa = "origen", texto = "Me crie a la sombra de Fort Knox. Mi papa era civil del parque motorizado y yo aprendi a contar con los camiones que salian por el porton.", da = {"fort_knox"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh", "West Point"} },
    { id = "l02_ori_chicago", etapa = "origen", texto = "Naci en un barrio de Chicago que olia a sangre de los corrales. A Kentucky llegue a los veinte, detras de alguien que despues no valio el viaje.", da = {"urbano", "forastero"}, edad_min = 25, edad_max = 85 },
    { id = "l02_ori_fortknox", etapa = "origen", texto = "Soy {hijo} del Fuerte Knox: mi papa era sargento del motor pool y mi mama planchaba uniformes en la lavanderia, al lado de Mildred Quinn, la mama del Cabo.", da = {"fort_knox"}, edad_min = 18, edad_max = 53, lazo = "cabo" },
    { id = "l02_ori_harlan_chile", etapa = "origen", texto = "Mi abuelo vino de Chile a las minas de carbon de Harlan, como el viejo Aurelio Bencina. De el me quedo el apellido raro y la tos de la familia.", da = {"minero", "montana"}, edad_min = 18, edad_max = 60, lazo = "hector", peso = 5 },
    { id = "l02_ori_mariel", etapa = "origen", texto = "En la primavera del 80 sali de Cuba por el Mariel con una muda de ropa. Me sacaron de un catre de Arkansas unos metodistas de {pueblo}.", da = {"inmigrante", "refugiado", "metodista"}, edad_min = 32, edad_max = 85, peso = 5 },
    { id = "l02_ori_medieros", etapa = "origen", texto = "Mis padres eran medieros de tabaco en una loma de {pueblo}. Nada era nuestro: ni la casa, ni la mula, ni la cosecha.", da = {"rural", "tabaco", "pobre"}, edad_min = 18, edad_max = 85 },
    { id = "l02_ori_rio", etapa = "origen", texto = "Naci en una casa de tablas a la orilla del Ohio, {hijo} de un hombre de barcaza. Aprendi a nadar antes que a leer.", da = {"rio", "rural"}, edad_min = 18, edad_max = 85, pueblos = {"West Point", "Riverside"} },
    { id = "l02_ori_saigon", etapa = "origen", texto = "Naci en Saigon, {hijo} de una lavandera y de un soldado americano que se fue antes de verme. Llegue a Kentucky con una foto y un apellido prestado.", da = {"inmigrante", "refugiado", "fort_knox"}, edad_min = 18, edad_max = 30, peso = 5 },
    { id = "l03_ori_barcazas_ohio", etapa = "origen", texto = "Me crie a orillas del Ohio. Mi padre trabajaba en las barcazas con un chileno, Recabarren, el papa de la Chela del cuartel. Decia que el rio no perdona al que se distrae.", da = {"rio"}, edad_min = 30, edad_max = 70, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l03_ori_harlan_carbon", etapa = "origen", texto = "Soy de los cerros de Harlan. Mi padre bajaba a la mina antes del sol y subia negro. Nos vinimos al norte cuando cerro la veta.", da = {"montana", "minero", "forastero"}, edad_min = 30, edad_max = 85 },
    { id = "l03_ori_hijo_cuartel", etapa = "origen", texto = "Me crie en las casas del Fuerte Knox. Mi padre era sargento: cada dos inviernos otra escuela, otra casa, otra bandera en la puerta.", da = {"fort_knox", "forastero"}, edad_min = 18, edad_max = 60 },
    { id = "l03_ori_novia_guerra", etapa = "origen", texto = "Mi madre era una alemana que se caso con un soldado del Fuerte despues de la guerra. En la casa se rezaba en aleman y se comia chucrut los domingos.", da = {"inmigrante", "fort_knox"}, edad_min = 18, edad_max = 46 },
    { id = "l03_ori_nunca_salio", etapa = "origen", texto = "Naci en {pueblo} y nunca vivi en otra parte. Louisville la vi tres veces, y una fue para el dentista.", da = {"nunca_salio", "rural"}, edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l03_ori_portland_louisville", etapa = "origen", texto = "Naci en Portland, el barrio de Louisville pegado al rio, entre bodegas y bares. Llegue al campo ya crecid{o}, y todavia me asustan los grillos.", da = {"urbano", "louisville", "forastero"}, edad_min = 18, edad_max = 85 },
    { id = "l03_ori_tabaco_medieros", etapa = "origen", texto = "Naci en {ano_nac} en una casa de medieros, entre dos galpones de tabaco. El patron era dueno de la tierra, del galpon y casi de nosotros.", da = {"rural", "tabaco", "pobre"}, edad_min = 18, edad_max = 85 },
    { id = "l04_ori_hijo_fuerte", etapa = "origen", texto = "Soy {hijo} del Fuerte Knox. Mi papa era sargento y nos cambiaban de base cada dos inviernos, hasta que lo dejaron en Knox y nos quedamos. Aprendi a no echar raices y aqui las eche igual.", da = {"fort_knox", "forastero"}, edad_min = 18, edad_max = 85 },
    { id = "l04_ori_hondonada_carbon", etapa = "origen", texto = "Naci en una hondonada del este, entre carbon y Biblia. Mi papa bajaba a la mina y mi mama contaba los minutos hasta que volvia. Bajamos al condado buscando un trabajo que no matara.", da = {"montana", "minero", "rural", "forastero"}, edad_min = 30, edad_max = 85 },
    { id = "l04_ori_nunca_salio", etapa = "origen", texto = "Naci en {pueblo} y aqui me voy a morir, si me dejan elegir. Conozco cada perro por su nombre y cada pozo por su sabor. Louisville la vi dos veces y las dos me volvi antes de comer.", da = {"nunca_salio", "rural"}, prohibe = {"forastero"}, edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l04_ori_portland_rio", etapa = "origen", texto = "Me crie en Portland, el barrio del rio en Louisville, entre talleres del tren y bares de barcaceros. Llegue a {pueblo} ya grande, porque aqui el aire no olia a fierro.", da = {"urbano", "louisville", "rio", "forastero"}, edad_min = 18, edad_max = 85 },
    { id = "l04_ori_sur_lejano", etapa = "origen", texto = "No soy de aqui. Vengo del sur, de un pantano donde el agua es caliente y la gente habla otro idioma en la cocina. Llegue a {pueblo} por un trabajo y el acento se me fue gastando, no del todo.", da = {"forastero", "inmigrante"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l04_ori_tabaco_mediero", etapa = "origen", texto = "Soy de una familia de medieros de tabaco: la tierra era de otro, el sudor era nuestro. En agosto colgabamos el burley en el granero y la casa entera olia a hoja seca hasta Navidad.", da = {"rural", "tabaco", "granja", "pobre"}, edad_min = 18, edad_max = 85 },
    { id = "l05_ori_antracita", etapa = "origen", texto = "Mi familia vino de las minas de carbon de Pensilvania. Mi abuelo hablaba polaco y mi papa juraba que a el no lo iban a enterrar abajo.", da = {"forastero", "minero"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l05_ori_fuerte", etapa = "origen", texto = "Soy {hijo} del Fuerte: mi papa era sargento de tanques y nos cambiaron de casa seis veces antes de que yo cumpliera doce. Aqui fue donde nos quedamos.", da = {"fort_knox", "forastero"}, edad_min = 18, edad_max = 85 },
    { id = "l05_ori_louisville", etapa = "origen", texto = "Naci en Louisville, en una cuadra de casas pegadas donde de noche se oia el tren, y llegue a {pueblo} ya grande, con una maleta y sin conocer a nadie.", da = {"urbano", "louisville", "forastero"}, edad_min = 18, edad_max = 85 },
    { id = "l05_ori_medieros", etapa = "origen", texto = "Naci en {ano_nac} en una casa de peones, {hijo} de medieros que trabajaban tabaco ajeno a la mitad. La tierra nunca fue nuestra; el cansancio si.", da = {"rural", "tabaco", "pobre", "granja"}, edad_min = 18, edad_max = 85 },
    { id = "l05_ori_nunca", etapa = "origen", texto = "Naci en {pueblo} en {ano_nac} y nunca sali mas lejos que la feria de Elizabethtown. Para que, si todo lo que quiero esta a tres cuadras.", da = {"nunca_salio", "rural"}, edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l05_ori_orilla", etapa = "origen", texto = "Me crie en una casa de tablas en la orilla del Ohio. Cada primavera el rio nos subia al segundo piso y mi mama cocinaba igual, con el agua en la escalera.", da = {"rio", "rural", "pobre"}, edad_min = 18, edad_max = 85, pueblos = {"West Point", "Riverside"} },
    { id = "l06_ori_acerias", etapa = "origen", texto = "Soy de una ciudad de acerias de Ohio. Vine a Knox por trabajo y me quede porque aqui nadie pregunta de donde viene uno.", da = {"forastero", "urbano"}, prohibe = {"nunca_salio"}, edad_min = 18, edad_max = 85 },
    { id = "l06_ori_establos", etapa = "origen", texto = "Me crie en los establos de Churchill Downs, en Louisville, entre caballos calientes y apostadores que me daban una moneda por pasear un potro.", da = {"urbano", "louisville"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l06_ori_ferrocarril", etapa = "origen", texto = "Mi papa fue guardafrenos del L&N, igual que el papa de la Misia Rosa. Me crie oyendo pitar los trenes de noche detras de la casa.", edad_min = 33, edad_max = 85, lazo = "rosa" },
    { id = "l06_ori_hollow", etapa = "origen", texto = "Naci en un hollow de los cerros, donde el camino se acaba antes que la luz. En la casa habia mas primos que platos.", da = {"rural", "montana", "familia_grande"}, edad_min = 18, edad_max = 85 },
    { id = "l06_ori_medieros", etapa = "origen", texto = "Soy {hijo} de medieros de tabaco: la tierra era de otro, la cosecha era de otro, y la espalda cansada era de mi papa.", da = {"rural", "tabaco", "pobre"}, edad_min = 18, edad_max = 85 },
    { id = "l06_ori_rio", etapa = "origen", texto = "Mi familia vivio siempre a la orilla del Ohio. Aprendi a remar antes que a andar en bicicleta, y a leer la crecida en el color del agua.", da = {"rio", "rural"}, edad_min = 18, edad_max = 85 },
    { id = "l06_ori_soldado", etapa = "origen", texto = "Llegue a Kentucky casad{o} con un soldado del Fuerte Knox, con una maleta de carton y sin saber pedir pan en ingles.", da = {"inmigrante", "fort_knox", "casado"}, edad_min = 30, edad_max = 85 },
    { id = "l07_ori_caballerizas", etapa = "origen", texto = "Me crie a seis cuadras de Churchill Downs, entre caballerizas. Mi papa cuidaba caballos ajenos y yo aprendi a contar con las apuestas de los mozos.", da = {"louisville", "urbano"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l07_ori_calle_main", etapa = "origen", texto = "Naci en la calle Main de West Point. De {nino} veia a la Chela de los bomberos lavar el camion rojo los domingos, como quien reza.", da = {"rio", "nunca_salio"}, edad_min = 18, edad_max = 38, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l07_ori_campamento_minero", etapa = "origen", texto = "Naci en un campamento minero del este, donde todo se pagaba con fichas de la compania y el agua bajaba negra del cerro.", da = {"minero", "montana", "pobre"}, edad_min = 18, edad_max = 85 },
    { id = "l07_ori_detras_iglesia", etapa = "origen", texto = "Mi familia vive detras de la iglesia de {pueblo} desde antes de que hubiera calles. Mis abuelos estan enterrados a cien pasos de mi cocina.", da = {"rural", "nunca_salio", "religioso"}, edad_min = 18, edad_max = 85 },
    { id = "l07_ori_hijo_sargento", etapa = "origen", texto = "Soy {hijo} de un sargento de carrera. Antes de los diez habia vivido en cuatro bases, y en ninguna me dio tiempo de tener un amigo.", da = {"fort_knox", "forastero", "solitario"}, edad_min = 18, edad_max = 85 },
    { id = "l07_ori_refugiado", etapa = "origen", texto = "Llegue a Kentucky de {nino}, en un avion lleno de gente que no hablaba ingles, despues de meses en un campamento militar de Arkansas.", da = {"refugiado", "inmigrante", "forastero"}, edad_min = 18, edad_max = 30, peso = 5 },
    { id = "l07_ori_tabaco_meade", etapa = "origen", texto = "Soy de una granja de tabaco del condado de Meade. En agosto toda la familia colgaba hojas en el galpon hasta que oliamos a humo dulce.", da = {"rural", "tabaco", "granja", "familia_grande"}, edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l07_ori_west_end", etapa = "origen", texto = "Naci en el West End de Louisville, en una casa angosta donde siempre sonaba un disco y nunca alcanzaba la plata.", da = {"louisville", "urbano", "pobre"}, edad_min = 18, edad_max = 85 },
    { id = "l08_ori_bomba_bencina", etapa = "origen", texto = "Naci en Rosewood en {ano_nac}. Mi papa le compraba la bencina a los Bencina, y la Misia Rosa me regalaba un Moon Pie si me quedaba quiet{o} en el auto.", da = {"nunca_salio"}, edad_min = 18, edad_max = 34, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l08_ori_cerro_leslie", etapa = "origen", texto = "Naci en {ano_nac} en un cerro de Leslie County, donde el doctor llegaba a caballo o no llegaba. Bajamos a {pueblo} cuando cerro la mina de mi tio.", da = {"montana", "minero", "pobre", "forastero"}, edad_min = 18, edad_max = 85 },
    { id = "l08_ori_corneta", etapa = "origen", texto = "Mi papa era sargento del Fuerte Knox, de Texas, y mi mama de {pueblo}. Me crie oyendo la corneta al amanecer y rancheras en la cocina.", da = {"fort_knox", "familia_grande"}, edad_min = 18, edad_max = 85 },
    { id = "l08_ori_germantown", etapa = "origen", texto = "Naci en {ano_nac} en Germantown, en Louisville, {hijo} de un carnicero aleman. En mi casa se rezaba en dos idiomas y se peleaba en uno solo.", da = {"urbano", "louisville", "catolico", "forastero"}, prohibe = {"rural"}, edad_min = 18, edad_max = 85 },
    { id = "l08_ori_maleta_cuba", etapa = "origen", texto = "Mi papa llego de Cuba en el sesenta y uno con una maleta de carton y un diccionario. Yo naci en Louisville en {ano_nac}, entre el ingles de la calle y el castellano de la cocina.", da = {"inmigrante", "louisville", "urbano"}, edad_min = 18, edad_max = 32 },
    { id = "l08_ori_novia_mar", etapa = "origen", texto = "Naci del otro lado del mar. Llegue a Kentucky casada con un soldado del Fuerte Knox, con una maleta y sin saber decir ni gracias en ingles.", da = {"inmigrante", "fort_knox", "forastero", "casado"}, edad_min = 40, edad_max = 85, sexo = "m", peso = 5 },
    { id = "l08_ori_ordena", etapa = "origen", texto = "Naci en {ano_nac} en una casa de tablas pegada a la ordena de mi papa, a dos millas de {pueblo}. Antes de caminar ya conocia el olor de la leche tibia.", da = {"rural", "granja", "nunca_salio"}, prohibe = {"urbano"}, edad_min = 18, edad_max = 85 },
    { id = "l09_ori_alguacil", etapa = "origen", texto = "Mi padre era el que mandaba en el condado en su tiempo. En mi casa nunca falto nada, y recien de grande entendi de donde salia.", da = {"acomodado"}, edad_min = 30, edad_max = 85, peso = 5 },
    { id = "l09_ori_bote", etapa = "origen", texto = "Llegue a Kentucky despues de un bote de rio con mas gente de la que cabia y un campo de refugiados. Una parroquia de Louisville me consiguio una pieza y un trabajo.", da = {"refugiado", "inmigrante", "forastero", "catolico"}, edad_min = 25, edad_max = 65, peso = 5 },
    { id = "l09_ori_comuna", etapa = "origen", texto = "Me crie en una comuna de Tennessee, entre carpas, pan integral y guitarras. Llegue a {pueblo} de {nino}, cuando vendieron la tierra y cada uno agarro para su lado.", da = {"forastero", "rural"}, edad_min = 18, edad_max = 32, peso = 5 },
    { id = "l09_ori_esclusa", etapa = "origen", texto = "Soy de la orilla del Ohio. Mi padre era esclusero y yo aprendi a nadar antes que a leer.", da = {"rio"}, edad_min = 18, edad_max = 85, pueblos = {"West Point", "Riverside"} },
    { id = "l09_ori_granja_ford", etapa = "origen", texto = "Naci en una granja de {pueblo}, pero me crie a medias: mi padre bajaba cada lunes a la planta de la Ford en Louisville y volvia los sabados oliendo a grasa.", da = {"granja", "rural"}, edad_min = 25, edad_max = 80 },
    { id = "l09_ori_minas_fuerte", etapa = "origen", texto = "Mi familia vino de las minas de Pensilvania cuando en el Fuerte Knox pagaban al dia por clavar tablas. Llegue a {pueblo} de {nino}, cargando una lata de clavos.", da = {"minero", "forastero", "fort_knox"}, edad_min = 62, edad_max = 85 },
    { id = "l09_ori_moon_pie", etapa = "origen", texto = "Naci en Rosewood cuando la gasolinera de los Bencina ya tenia su letrero pintado a mano. Mi primera moneda la gaste en un Moon Pie de esa caja.", da = {"rural"}, edad_min = 18, edad_max = 34, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l09_ori_nunca_salio", etapa = "origen", texto = "Naci en {pueblo} y nunca sali del condado. Louisville cuenta, que tambien es Knox.", da = {"nunca_salio"}, edad_min = 18, edad_max = 85 },
    { id = "l09_ori_portland_boxeo", etapa = "origen", texto = "Me crie en Portland, el barrio del rio en Louisville. Los sabados ibamos a ver boxeo al gimnasio, y ahi vi pelear de muchacho a uno que despues le decian el Martillo.", da = {"louisville", "urbano"}, edad_min = 28, edad_max = 55, lazo = "duggan" },
    { id = "l10_ori_barriles", etapa = "origen", texto = "Me crie oliendo a bourbon: mi papa rodaba barriles en una destileria de Bardstown y se tomaba la parte de los angeles y la del diablo.", da = {"fabrica", "forastero"}, edad_min = 18, edad_max = 85 },
    { id = "l10_ori_casa_compania", etapa = "origen", texto = "Naci en {ano_nac} en una casa de la compania minera, en el este de Kentucky. Mi papa bajaba al carbon y volvia negro hasta las cejas.", da = {"minero", "montana", "rural"}, prohibe = {"urbano"}, edad_min = 40, edad_max = 85 },
    { id = "l10_ori_casa_flotante", etapa = "origen", texto = "Naci en una casa flotante amarrada en la boca de un rio. Antes de caminar ya sabia que el agua no perdona al que se distrae.", da = {"rio", "rural"}, prohibe = {"urbano"}, edad_min = 18, edad_max = 85 },
    { id = "l10_ori_exilio_chile", etapa = "origen", texto = "Llegue a Riverside de {nino}, en los setenta, patrocinad{o} por la misma parroquia que trajo a los Ferrada, chilenos como nosotros.", da = {"inmigrante", "refugiado", "catolico"}, edad_min = 21, edad_max = 31, pueblos = {"Riverside"}, lazo = "lucia", peso = 5 },
    { id = "l10_ori_hijo_sargento", etapa = "origen", texto = "Soy {hijo} de un sargento del Fuerte Knox. Hasta los doce cambie de escuela cada dos inviernos y aprendi a hacerme amigos en una semana.", da = {"fort_knox", "forastero"}, prohibe = {"nunca_salio"}, edad_min = 18, edad_max = 85 },
    { id = "l10_ori_medieros", etapa = "origen", texto = "Mis papas eran medieros de tabaco en {pueblo}: la tierra era del patron y la espalda era nuestra.", da = {"tabaco", "rural", "pobre", "nunca_salio"}, prohibe = {"acomodado", "urbano"}, edad_min = 18, edad_max = 85 },
    { id = "l10_ori_portland", etapa = "origen", texto = "Naci en Louisville, en el barrio Portland, a cuatro cuadras del rio y de las vias. Me vine a {pueblo} cuando me case.", da = {"louisville", "urbano", "casado"}, edad_min = 22, edad_max = 85 },
    { id = "l01_inf_asma", etapa = "infancia", texto = "De {nino} pase mas tiempo en cama que en la escuela. El asma no me dejaba correr ni detras de un perro.", da = {"enfermizo_nino", "asma"}, prohibe = {"atleta"}, edad_min = 18, edad_max = 85 },
    { id = "l01_inf_barcazas", etapa = "infancia", texto = "Mi papa trabajaba en las barcazas y llegaba borracho. Una vez le arme un timbre a la casa con un kit de catalogo y el lo arranco de un portazo.", da = {"padre_violento", "rio"}, edad_min = 18, edad_max = 85 },
    { id = "l01_inf_bibliobus", etapa = "infancia", texto = "Los martes pasaba el bibliobus del condado por la granja. Yo leia todo lo que me prestaban y lo devolvia tarde, con barro en las tapas.", da = {"rural"}, prohibe = {"urbano"}, edad_min = 25, edad_max = 85 },
    { id = "l01_inf_guantes_oro", etapa = "infancia", texto = "De {nino} me llevaron a Lexington a ver la final de los Guantes de Oro del 79. El que perdio con la ceja abierta despues puso un taller en Riverside.", edad_min = 18, edad_max = 30, lazo = "duggan" },
    { id = "l01_inf_inundacion", etapa = "infancia", texto = "Me acuerdo de la gran inundacion del Ohio: el agua llego al segundo piso y mi papa nos saco por la ventana en un bote prestado.", da = {"rio"}, edad_min = 62, edad_max = 85 },
    { id = "l01_inf_leucemia", etapa = "infancia", texto = "A los doce me dio leucemia. Pase dos inviernos y medio en el hospital de ninos de Louisville, entre quimio y quimio, leyendo lo que me trajeran.", da = {"enfermizo_nino", "supero_enfermedad", "louisville"}, prohibe = {"atleta", "fuerte"}, edad_min = 18, edad_max = 35, peso = 5 },
    { id = "l01_inf_rifle", etapa = "infancia", texto = "A los ocho me regalaron un rifle 22 y me dijeron: una bala, una ardilla, o no comemos. Comimos.", da = {"rural"}, prohibe = {"urbano"}, edad_min = 18, edad_max = 85 },
    { id = "l01_inf_techo_mina", etapa = "infancia", texto = "A mi papa lo aplasto el techo de la mina cuando yo tenia doce. Desde ese dia le pele papas a mi mama, que cocinaba para los solteros del campamento.", da = {"pobre"}, pide = {"minero"}, edad_min = 30, edad_max = 85 },
    { id = "l01_inf_tonico", etapa = "infancia", texto = "Mi mama nos daba cada manana una cucharada del tonico del doctor de la radio de Louisville. Sabia a clavo oxidado. Ella juraba que por eso no nos enfermabamos.", edad_min = 18, edad_max = 32, lazo = "hartmann" },
    { id = "l02_inf_bus", etapa = "infancia", texto = "El chofer del bus escolar me dejaba ir en el primer asiento. Me sabia las paradas en orden, como un rezo, y todavia me las se.", da = {"timido", "rural"}, prohibe = {"inmigrante", "forastero"}, edad_min = 18, edad_max = 85 },
    { id = "l02_inf_carrito", etapa = "infancia", texto = "Arme un carrito con el motor de una lavadora y lo baje por la cuesta de la iglesia. Primer choque, primera ceja rota y ganas de mas.", da = {"bromista", "valiente"}, prohibe = {"enfermizo_nino"}, edad_min = 18, edad_max = 85 },
    { id = "l02_inf_chicago", etapa = "infancia", texto = "Me crie en un departamento encima de una carniceria. Los sabados friamos donas en la panaderia de la esquina por veinte centavos la hora.", da = {"urbano"}, pide = {"forastero"}, edad_min = 18, edad_max = 85 },
    { id = "l02_inf_cuba", etapa = "infancia", texto = "De {nino} en Cuba vi entrar a los barbudos en camion y todo el barrio salio a aplaudir. Mi mama no aplaudio; cerro la ventana.", pide = {"inmigrante"}, edad_min = 42, edad_max = 50 },
    { id = "l02_inf_hollis", etapa = "infancia", texto = "De {nino} me mandaban a las seis a la panaderia Hollis de Riverside. El viejo Walt me regalaba la punta quemada del pan si llegaba antes que el sol.", prohibe = {"inmigrante", "forastero"}, edad_min = 18, edad_max = 70, pueblos = {"Riverside"}, lazo = "hector" },
    { id = "l02_inf_inundacion", etapa = "infancia", texto = "En la inundacion de enero del 37 el agua llego al segundo piso. Mi mama y yo subimos la maquina de coser al entretecho antes que la comida.", da = {"rio"}, prohibe = {"inmigrante", "forastero"}, edad_min = 62, edad_max = 85, pueblos = {"West Point", "Riverside"} },
    { id = "l02_inf_padre_sabados", etapa = "infancia", texto = "Mi papa tomaba los sabados y nos pegaba los domingos, despues de misa. Aprendi a leerle la cara desde la puerta antes de entrar.", da = {"padre_violento"}, edad_min = 18, edad_max = 85 },
    { id = "l02_inf_polio", etapa = "infancia", texto = "La polio me agarro a los seis. Me quede con una pierna mas flaca que la otra y un zapato con suela alta que me hacia el zapatero gratis.", da = {"enfermizo_nino", "lesion_pierna", "cojo"}, prohibe = {"atleta"}, edad_min = 44, edad_max = 85 },
    { id = "l02_inf_saigon", etapa = "infancia", texto = "De {nino} vivi casi en la calle; me decian polvo de la calle por la cara mezclada. A los doce ya arreglaba motos Honda por monedas.", da = {"pobre", "oficio_aprendido"}, pide = {"inmigrante"}, edad_min = 18, edad_max = 30 },
    { id = "l02_inf_tabaco", etapa = "infancia", texto = "Desde los ocho colgaba tabaco en el galpon. Cada agosto la hoja mojada me tumbaba con vomitos, y al otro dia volvia a la soga.", da = {"tabaco", "granja", "rural"}, prohibe = {"inmigrante", "forastero"}, edad_min = 18, edad_max = 85 },
    { id = "l02_inf_tia", etapa = "infancia", texto = "Mi mama murio cuando yo tenia dos y me crio una tia que no queria hijos. Me daba de comer bien y nunca me toco la cabeza.", da = {"huerfano"}, edad_min = 18, edad_max = 85 },
    { id = "l03_inf_abuela_crio", etapa = "infancia", texto = "Mis padres murieron en un choque cuando yo tenia cinco. Me crio una abuela que fumaba pipa, cantaba himnos y no le tenia miedo a nada.", da = {"huerfano", "religioso"}, prohibe = {"padre_violento", "hijo_unico"}, edad_min = 18, edad_max = 85 },
    { id = "l03_inf_asma_cama", etapa = "infancia", texto = "De {nino} pase mas tiempo en cama que en la escuela. El asma no me dejaba correr ni detras de un perro, y mi madre me ponia vapor de eucalipto.", da = {"enfermizo_nino", "asma"}, prohibe = {"atleta", "fuerte"}, edad_min = 18, edad_max = 85 },
    { id = "l03_inf_bautizo_rio", etapa = "infancia", texto = "Me bautizaron en el rio a los diez, en agosto, con el agua tibia y el pastor gritando. Sali convencid{o} de que habia visto algo.", da = {"religioso", "bautista"}, prohibe = {"catolico"}, edad_min = 18, edad_max = 85 },
    { id = "l03_inf_colgar_tabaco", etapa = "infancia", texto = "A los ocho ya colgaba tabaco en el galpon, con las manos verdes y pegajosas. Me pagaban un dolar por dia y me lo guardaba mi madre.", da = {"tabaco", "rural"}, prohibe = {"urbano"}, edad_min = 18, edad_max = 85 },
    { id = "l03_inf_fuegos_muldraugh", etapa = "infancia", texto = "Los 4 de julio nos subiamos al techo para ver los fuegos artificiales de Muldraugh. Ese olor a polvora todavia me suena a fiesta.", edad_min = 18, edad_max = 60 },
    { id = "l03_inf_hijo_unico_tienda", etapa = "infancia", texto = "Fui hij{o} unic{o} de los duenos del almacen. Me sentaba en un saco de harina a contar los clavos sueltos para que no me aburriera.", da = {"hijo_unico", "comerciante"}, prohibe = {"familia_grande", "huerfano"}, edad_min = 18, edad_max = 85 },
    { id = "l03_inf_inundacion_37", etapa = "infancia", texto = "En la inundacion del 37 el rio se metio a la casa hasta la segunda grada. Nos llevaron en bote a la escuela y dormimos sobre los pupitres.", da = {"rio"}, edad_min = 62, edad_max = 72 },
    { id = "l03_inf_once_hermanos", etapa = "infancia", texto = "Eramos once en tres piezas. Yo dormia atravesad{o} a los pies de la cama de mis hermanos, y el que llegaba ultimo a la mesa no comia carne.", da = {"familia_grande", "pobre"}, prohibe = {"hijo_unico"}, edad_min = 18, edad_max = 85 },
    { id = "l03_inf_padre_correa", etapa = "infancia", texto = "Mi padre tomaba los sabados y nos buscaba con la correa. Aprendi a oir el auto de lejos y a esconderme en el galpon antes de que apagara el motor.", da = {"padre_violento"}, prohibe = {"huerfano"}, edad_min = 18, edad_max = 85 },
    { id = "l04_inf_abuelos", etapa = "infancia", texto = "Mi mama se fue cuando yo tenia cinco y me criaron los abuelos, en una casa con olor a linimento. El abuelo me enseno su oficio con paciencia de viejo y nunca me pregunto por ella.", da = {"huerfano"}, prohibe = {"hijo_unico"}, edad_min = 18, edad_max = 85 },
    { id = "l04_inf_bautizo_rio", etapa = "infancia", texto = "Me bautizaron en el rio a los nueve, en la bautista, con el agua hasta la cintura y la mano del pastor en la nuca. Sali tosiendo y convencid{o} de que Dios estaba frio.", da = {"bautista", "religioso", "rio"}, edad_min = 18, edad_max = 85 },
    { id = "l04_inf_cama_asma", etapa = "infancia", texto = "De {nino} pase mas tiempo en cama que en la escuela. El asma no me dejaba correr ni detras de un perro, y mi mama me ponia una toalla con vapor de eucalipto en la cabeza.", da = {"enfermizo_nino", "asma"}, prohibe = {"atleta", "fuerte"}, edad_min = 18, edad_max = 85 },
    { id = "l04_inf_once_hermanos", etapa = "infancia", texto = "Eramos once en una casa de cuatro piezas. Dormiamos de a tres por cama y la ropa pasaba del mayor al menor hasta que era trapo. Nunca estuve {o} sol{o} ni un minuto. A veces lo extrano todavia.", da = {"familia_grande", "pobre"}, prohibe = {"hijo_unico"}, edad_min = 18, edad_max = 85 },
    { id = "l04_inf_padre_correa", etapa = "infancia", texto = "Mi papa tomaba los viernes y pegaba los sabados, con la correa del pantalon. Aprendi a leerle la cara desde la escalera y a esconder a mis hermanos chicos en el gallinero.", da = {"padre_violento", "familia_grande"}, edad_min = 18, edad_max = 85 },
    { id = "l04_inf_polio", etapa = "infancia", texto = "A los seis me dio la polio. Un verano en cama y la pierna izquierda me quedo mas flaca para siempre. Camino de lado desde entonces, pero camino.", da = {"lesion_pierna", "cojo", "enfermizo_nino"}, prohibe = {"atleta"}, edad_min = 40, edad_max = 85 },
    { id = "l04_inf_rollos_canela", etapa = "infancia", texto = "Los domingos mi papa me llevaba a la panaderia Hollis de Riverside por rollos de canela. La panadera me daba el mas quemado, que es el mejor, y me guinaba el ojo.", edad_min = 18, edad_max = 28, lazo = "yvonne_bell" },
    { id = "l04_inf_tonico_radio", etapa = "infancia", texto = "Mi mama compraba el tonico de la Hora de la Salud por la radio AM de Louisville, la del doctor ese de la voz suave. Sabia a menta y a nada. Ella juraba que me curaba la tos.", da = {"louisville"}, edad_min = 18, edad_max = 30, lazo = "hartmann" },
    { id = "l05_inf_ardillas", etapa = "infancia", texto = "A los diez mi papa me paso la veintidos: una bala, una ardilla, y si la dejabas sufriendo no se comia. Comimos poco al principio. Despues comimos bien.", da = {"montana", "pobre", "rural"}, prohibe = {"urbano"}, edad_min = 18, edad_max = 85 },
    { id = "l05_inf_bandera", etapa = "infancia", texto = "De {nino} me paraba con una bandera naranja en la punta del potrero para marcarle la pasada al avion fumigador. Quedaba empapad{o} en veneno y feliz.", da = {"granja", "tabaco"}, pide_alguno = {"rural", "granja", "tabaco"}, prohibe = {"urbano"}, edad_min = 18, edad_max = 85 },
    { id = "l05_inf_fiebre", etapa = "infancia", texto = "A los ocho me dio fiebre reumatica. Un invierno entero en cama mirando el techo, y el doctor le dijo a mi mama que el corazon me quedaba tocado.", da = {"enfermizo_nino", "corazon"}, prohibe = {"atleta"}, edad_min = 18, edad_max = 85 },
    { id = "l05_inf_nueve", etapa = "infancia", texto = "Eramos nueve en dos piezas. Yo era {el} del medio, a quien nadie miraba, y aprendi a hacerme util para que me vieran.", da = {"familia_grande", "pobre"}, edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l05_inf_potrillos", etapa = "infancia", texto = "De {nino} paseaba potrillos para enfriarlos en una granja de rejas blancas de Woodford County, donde mi papa era mozo de cuadra. Olia a caballo hasta en misa.", da = {"caballos", "rural", "pobre"}, prohibe = {"urbano"}, edad_min = 18, edad_max = 85 },
    { id = "l05_inf_salon", etapa = "infancia", texto = "Me crie debajo de los secadores del salon de belleza de mi mama, barriendo pelo y oyendo los secretos de medio pueblo. Aprendi a callar antes que a leer.", da = {"peluqueria"}, edad_min = 18, edad_max = 85 },
    { id = "l05_inf_sordo", etapa = "infancia", texto = "Naci sord{o}. En la escuela para sordos de Danville nos hacian sentarnos sobre las manos para que aprendieramos a leer los labios y no hicieramos senas.", da = {"sordo"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l05_inf_taller_relojes", etapa = "infancia", texto = "Me crie en el taller de mi padre, entre relojes desarmados. A los seis arme un despertador y me sobro una pieza que todavia guardo en una caja de fosforos.", da = {"oficio_aprendido", "hijo_unico"}, edad_min = 18, edad_max = 85 },
    { id = "l06_inf_ardillas", etapa = "infancia", texto = "Mi abuelo me enseno a tirar con una veintidos a los ocho: a la ardilla se le tira a la cabeza o no se le tira. Lo otro es crueldad.", da = {"tirador", "rural"}, edad_min = 18, edad_max = 85 },
    { id = "l06_inf_carpa_reyes", etapa = "infancia", texto = "Me llevaron a la carpa del diacono Reyes a que me sanara el asma. Me hizo toser delante de todos y paso la canasta dos veces. No me sano.", da = {"sin_fe"}, pide_alguno = {"asma", "enfermizo_nino"}, edad_min = 18, edad_max = 29, lazo = "reyes" },
    { id = "l06_inf_casino", etapa = "infancia", texto = "Mi mama lavaba ollas en el casino del Fuerte Knox. La cocinera era Mae, la mama de la Chela, que decia que la cocinera come al ultimo, si sobra.", da = {"fort_knox"}, edad_min = 18, edad_max = 48, lazo = "chela" },
    { id = "l06_inf_coro", etapa = "infancia", texto = "Cantaba en el coro de la iglesia y a los once gane cinco dolares en el concurso de talentos de la feria del condado.", da = {"religioso", "musico"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l06_inf_fardos", etapa = "infancia", texto = "Desde los nueve cargaba fardos de tabaco con mi papa. A los catorce levantaba lo mismo que un hombre y comia por dos.", da = {"fuerte", "tabaco"}, prohibe = {"enfermizo_nino", "cojo"}, edad_min = 18, edad_max = 85 },
    { id = "l06_inf_luna", etapa = "infancia", texto = "Vi la llegada a la Luna en la tele que el Hector de la gasolinera puso sobre un barril en el taller, con los camioneros. Me quede dormid{o} en una llanta.", edad_min = 28, edad_max = 36, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l06_inf_mina", etapa = "infancia", texto = "Mi papa volvia de la mina con la espalda rota y la botella abierta. Aprendi a leerle la cara desde la puerta, antes de que se sacara las botas.", da = {"padre_violento", "minero"}, edad_min = 18, edad_max = 85 },
    { id = "l06_inf_nevazon", etapa = "infancia", texto = "En la nevazon del 77 mi papa quedo atrapado en la gasolinera de Rosewood con otros once camioneros. Un tal Earl se comio cuatro huevos y despues lavo la sarten.", edad_min = 20, edad_max = 28, lazo = "earl" },
    { id = "l06_inf_polio", etapa = "infancia", texto = "La polio me agarro a los cinco y me dejo una pierna mas corta. Aprendi a caminar dos veces y aprendi que la gente me tenia que esperar.", da = {"cojo", "enfermizo_nino"}, prohibe = {"atleta", "fuerte"}, edad_min = 43, edad_max = 85 },
    { id = "l06_inf_radio", etapa = "infancia", texto = "A los diez desarme la radio de la casa para ver donde vivian las voces. La volvi a armar y me sobro un tornillo. Todavia funciona.", da = {"manos_habiles"}, edad_min = 18, edad_max = 85 },
    { id = "l07_inf_asma_disco", etapa = "infancia", texto = "Fui {nino} con asma. No podia correr, asi que me sentaba al lado del tocadiscos y aprendia a respirar con la musica.", da = {"asma", "enfermizo_nino", "musico"}, prohibe = {"atleta"}, edad_min = 18, edad_max = 85 },
    { id = "l07_inf_balde_mina", etapa = "infancia", texto = "A los seis le llevaba el balde del almuerzo a mi papa a la boca de la mina, y aprendi a contar con las fichas de la pulperia.", pide_alguno = {"minero"}, edad_min = 18, edad_max = 85 },
    { id = "l07_inf_bocina_earl", etapa = "infancia", texto = "De {nino} esperaba al borde de la 31 a que pasara el camionero gordo de Bowling Green, para que me tocara la bocina. Siempre la tocaba.", edad_min = 18, edad_max = 36, pueblos = {"Rosewood", "Muldraugh"}, lazo = "earl" },
    { id = "l07_inf_cinta_4h", etapa = "infancia", texto = "A los once gane una cinta azul en la feria del condado con el club 4-H. Mi mama la colgo en la cocina hasta que se puso amarilla.", pide_alguno = {"rural", "granja"}, edad_min = 18, edad_max = 85 },
    { id = "l07_inf_cocinar_hermanos", etapa = "infancia", texto = "A los nueve ya cocinaba para mis hermanos chicos, porque mi mama trabajaba de noche y llegaba oliendo a mosto y a lo otro.", da = {"familia_grande", "pobre"}, edad_min = 18, edad_max = 85 },
    { id = "l07_inf_desmayo", etapa = "infancia", texto = "Desde {nino} me desmayo con la sangre. La primera vez fue con un vidrio en la mano, y desperte con mi mama echandome agua en la cara.", da = {"se_desmaya", "timido"}, edad_min = 18, edad_max = 85 },
    { id = "l07_inf_escuelita", etapa = "infancia", texto = "Fui a una escuelita de una sola sala hasta que se acabaron los grados. Despues hubo que trabajar, y no volvi a abrir un libro hasta vieja la cabeza.", da = {"sin_estudios"}, prohibe = {"universidad"}, edad_min = 55, edad_max = 85 },
    { id = "l07_inf_gentry", etapa = "infancia", texto = "En el 63 vi desde la vereda como la Chela sacaba a un nino de cuatro por la ventana de una casa en llamas. Esa noche no dormi de puro querer ser como ella.", da = {"valiente"}, edad_min = 35, edad_max = 42, pueblos = {"West Point"}, lazo = "chela", peso = 5 },
    { id = "l07_inf_primer_venado", etapa = "infancia", texto = "A los doce mate mi primer venado y lo abri yo sol{o}, mientras mi papa miraba con las manos en los bolsillos.", da = {"rural", "fuerte"}, prohibe = {"se_desmaya", "enfermizo_nino"}, edad_min = 18, edad_max = 85 },
    { id = "l08_inf_ataques", etapa = "infancia", texto = "De {nino} me caia. Una fiebre a los siete me dejo los ataques, y en la escuela me metian un lapiz en la boca. Aprendi a sentarme antes de que llegaran.", da = {"enfermizo_nino", "epilepsia"}, prohibe = {"atleta", "fuerte"}, edad_min = 18, edad_max = 85 },
    { id = "l08_inf_campeon_helado", etapa = "infancia", texto = "A los diez sali en el diario de Louisville por ganar el campeonato escolar de ajedrez. A los trece me quede en blanco delante de todos y no volvi a jugar en serio.", da = {"timido"}, prohibe = {"sin_estudios"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l08_inf_correa", etapa = "infancia", texto = "Mi papa volvio de la guerra con historias y una correa. Las historias eran para los vecinos del almacen. La correa era para mi.", da = {"padre_violento"}, edad_min = 45, edad_max = 55 },
    { id = "l08_inf_inundacion", etapa = "infancia", texto = "En el treinta y siete el Ohio se subio hasta el segundo piso. Me acuerdo de mi mama remando sobre una puerta, con las gallinas en una caja de manzanas.", da = {"rio"}, edad_min = 60, edad_max = 85, pueblos = {"West Point", "Riverside"} },
    { id = "l08_inf_juez", etapa = "infancia", texto = "Cuando mis papas se separaron, el juez nos repartio como muebles. Yo me quede con mi mama y mi hermano se fue con mi papa a otro estado. No lo volvi a ver.", da = {"solitario", "rencoroso"}, edad_min = 18, edad_max = 85 },
    { id = "l08_inf_letra", etapa = "infancia", texto = "A los diez gane el concurso de caligrafia del condado. La maestra me ponia de ejemplo, y yo aprendi que una letra bonita convence a cualquiera.", da = {"buena_letra"}, edad_min = 18, edad_max = 85 },
    { id = "l08_inf_ordena_cinco", etapa = "infancia", texto = "A los seis ya ordenaba a las cinco de la manana. Mi papa decia que una vaca no sabe de domingos ni de fiebres.", da = {"fuerte"}, pide_alguno = {"granja", "rural"}, prohibe = {"enfermizo_nino"}, edad_min = 18, edad_max = 85 },
    { id = "l08_inf_pan_hollis", etapa = "infancia", texto = "De {nino} me mandaban a las seis a la panaderia Hollis de Riverside. La panadera de la trenza me regalaba la punta del rollo de canela si llegaba antes que los demas.", edad_min = 18, edad_max = 27, pueblos = {"Riverside"}, lazo = "yvonne_bell" },
    { id = "l08_inf_taller_bencina", etapa = "infancia", texto = "De {nino} me pasaba las tardes en el taller de los Bencina mirando a don Hector cambiar neumaticos. Me pagaba con una bebida helada y un apodo.", edad_min = 18, edad_max = 40, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l09_inf_academia_baile", etapa = "infancia", texto = "De {nino} mi madre lavaba ropa ajena para pagarme la academia de baile. Yo practicaba en la cocina, contando en ocho, con los zapatos de mi hermana mayor.", da = {"pobre", "atleta"}, prohibe = {"enfermizo_nino"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l09_inf_familia_grande", etapa = "infancia", texto = "Eramos nueve en dos piezas. Yo dormia atravesad{o} al pie de la cama de mis hermanos y comia rapido, porque el ultimo no comia.", da = {"familia_grande", "pobre"}, edad_min = 18, edad_max = 85 },
    { id = "l09_inf_fiebre_reumatica", etapa = "infancia", texto = "A los nueve me dio fiebre reumatica. Pase un invierno entero en cama mirando por la ventana y leyendo revistas viejas. Me quedo un soplo en el corazon.", da = {"enfermizo_nino", "corazon"}, prohibe = {"atleta"}, edad_min = 35, edad_max = 85 },
    { id = "l09_inf_gentry", etapa = "infancia", texto = "En el 63 vi a la Chela Recabarren salir por la ventana de los Gentry con un nino en brazos y el brazo cortado. Desde ese dia no le tengo miedo al humo.", da = {"valiente"}, edad_min = 33, edad_max = 40, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l09_inf_liga_infantil", etapa = "infancia", texto = "De {nino} jugue en la liga infantil. Mi padre me llevaba a todos los partidos y gritaba desde la reja mas fuerte que el arbitro.", da = {"atleta"}, prohibe = {"enfermizo_nino", "asma"}, edad_min = 18, edad_max = 85 },
    { id = "l09_inf_mina_hundida", etapa = "infancia", texto = "Una noche se hundio la casa de los vecinos, con la mina debajo y la luz prendida. Estuve semanas sin hablar.", da = {"timido"}, pide = {"minero"}, edad_min = 40, edad_max = 85 },
    { id = "l09_inf_peterbilt", etapa = "infancia", texto = "De {nino} me sentaba en la cerca a ver pasar los camiones de la 31. El gordo del Peterbilt me tocaba la bocina dos veces, siempre.", da = {"rural"}, edad_min = 18, edad_max = 24, lazo = "earl" },
    { id = "l09_inf_sobres", etapa = "infancia", texto = "De {nino} me mandaban en bicicleta a dejar sobres a los bares de la ruta 31. Nadie me explico que llevaba. Cuando lo entendi, ya era tarde para no saberlo.", da = {"culpa"}, edad_min = 25, edad_max = 85, peso = 5 },
    { id = "l09_inf_tartamudo", etapa = "infancia", texto = "De {nino} se me trababan las palabras en la puerta de la boca. Aprendi a contestar con las manos, con un martillo, con un silbido.", da = {"tartamudo", "timido"}, prohibe = {"lider"}, edad_min = 18, edad_max = 85 },
    { id = "l09_inf_tinajas", etapa = "infancia", texto = "De {nino}, al otro lado del mundo, revolvia las tinajas de pescado con sal de mi madre. Todavia tengo ese olor en las manos cuando llueve.", da = {"pobre"}, pide = {"refugiado"}, edad_min = 18, edad_max = 85 },
    { id = "l10_inf_ardillas_cena", etapa = "infancia", texto = "A los ocho cazaba ardillas con una .22 de un tiro. Si fallaba no habia cena, asi que deje de fallar.", da = {"rural", "pobre"}, prohibe = {"urbano", "acomodado"}, edad_min = 18, edad_max = 85 },
    { id = "l10_inf_asma_heno", etapa = "infancia", texto = "De {nino} el polvo del heno me cerraba el pecho. Mientras los otros jugaban, yo miraba desde el porche con el inhalador en la mano.", da = {"asma", "enfermizo_nino"}, prohibe = {"atleta", "fuerte"}, edad_min = 18, edad_max = 60 },
    { id = "l10_inf_bombera", etapa = "infancia", texto = "De {nino} se nos prendio la cocina. Una bombera de West Point, la Chela, me saco el gato de debajo de la cama y despues me reto a mi.", edad_min = 18, edad_max = 38, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l10_inf_carburador", etapa = "infancia", texto = "A los nueve desarme un carburador en el piso del taller de mi papa. Lo arme de nuevo y sobro un tornillo. Todavia no se de donde.", da = {"bromista"}, edad_min = 18, edad_max = 85 },
    { id = "l10_inf_escopeta_oido", etapa = "infancia", texto = "A los doce se me revento al lado la escopeta de mi papa. Desde entonces oigo de un solo lado y giro la cabeza para escuchar.", da = {"sordo", "rural"}, edad_min = 18, edad_max = 85 },
    { id = "l10_inf_lanza_tabaco", etapa = "infancia", texto = "A los doce me clave una lanza de ensartar tabaco en la palma. Me quedo una media luna blanca que me pica cuando va a llover.", da = {"lesion_mano", "tabaco"}, pide_alguno = {"rural", "tabaco", "granja"}, edad_min = 18, edad_max = 85 },
    { id = "l10_inf_lavandera", etapa = "infancia", texto = "Mi mama lavaba ropa ajena y yo repartia los canastos en carretilla. Sabia de cada casa de {pueblo} por sus sabanas.", da = {"pobre", "nunca_salio"}, prohibe = {"acomodado"}, edad_min = 18, edad_max = 85 },
    { id = "l10_inf_mama_pulmones", etapa = "infancia", texto = "Mi mama se murio de los pulmones cuando yo tenia seis. Me crio mi papa entre perros y redes, y aprendi a no pedir nada.", da = {"solitario"}, edad_min = 18, edad_max = 85 },
    { id = "l10_inf_tomo_g", etapa = "infancia", texto = "De {nino} mi papa me trajo de un remate un tomo suelto de enciclopedia, la letra G. Me lo aprendi entero. En la escuela me decian el de la G.", da = {"timido"}, edad_min = 18, edad_max = 85 },
    { id = "l10_inf_tonico", etapa = "infancia", texto = "De {nino} me daban una cucharada del tonico de la radio, el de la hora de la salud del Dr. Hartmann, para el animo. Sabia a fierro y a mentira.", da = {"enfermizo_nino"}, edad_min = 18, edad_max = 27, lazo = "hartmann" },
    { id = "l01_juv_cobre", etapa = "juventud", texto = "A los veinte me agarraron robando cobre de una linea vieja. Tres inviernos en La Grange me ensenaron a callarme y a pelar cables.", da = {"preso_pasado", "oficio_aprendido"}, edad_min = 25, edad_max = 65 },
    { id = "l01_juv_cohetes", etapa = "juventud", texto = "Cada verano le compraba cohetes a una muchacha flaca de Brandenburg que tenia un puesto en la 31W. Dicen que ahora es la que quema casas.", edad_min = 18, edad_max = 40, lazo = "kell" },
    { id = "l01_juv_japon", etapa = "juventud", texto = "Me llamaron cuando terminaba la Segunda Guerra y me mandaron a Japon con los ingenieros a levantar barracas. La guerra ya habia terminado; el hambre de alla, no.", da = {"militar", "veterano_wwii", "oficio_aprendido"}, edad_min = 65, edad_max = 70, sexo = "h", peso = 5 },
    { id = "l01_juv_lecheria", etapa = "juventud", texto = "A los dieciseis deje la escuela y entre a una lecheria: sacar leche a las cuatro de la manana y a las cuatro de la tarde, sin domingos.", da = {"lechero", "sin_estudios", "granja"}, prohibe = {"universidad", "urbano"}, edad_min = 18, edad_max = 85 },
    { id = "l01_juv_marina", etapa = "juventud", texto = "Me aliste en la Marina a los dieciocho. Peleaba los sabados en la cubierta de un destructor, entre cajas de municion, frente a Vietnam.", da = {"militar", "marino", "veterano_vietnam", "fuerte"}, prohibe = {"enfermizo_nino", "viejo_fragil"}, edad_min = 38, edad_max = 55, sexo = "h" },
    { id = "l01_juv_ollies", etapa = "juventud", texto = "En Louisville trabaje de noche en el Ollie's Diner de Bardstown Road. Habia una mesera de Muldraugh que daba el vuelto diciendo la hora exacta.", da = {"louisville", "trabajo_nocturno"}, edad_min = 20, edad_max = 30, lazo = "valentina" },
    { id = "l01_juv_retina", etapa = "juventud", texto = "En un sparring se me desprendio la retina y no le dije a nadie. Pelee la final igual. Perdi la pelea y la vista de ese ojo.", da = {"vista_mala"}, pide_alguno = {"fuerte", "atleta"}, quita = {"atleta"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l01_juv_spiffos", etapa = "juventud", texto = "Mi primer trabajo fue lavar platos en el Spiffo's de Muldraugh. El cocinero era un mexicano callado que me enseno a voltear huevos sin romper la yema.", da = {"secundaria"}, edad_min = 18, edad_max = 24, pueblos = {"Muldraugh"}, lazo = "julio" },
    { id = "l01_juv_supero_asma", etapa = "juventud", texto = "El asma de {nino} se me fue con el trabajo del campo, o eso dice mi mama. Me quedo un silbido cuando hiela, nada mas.", da = {"supero_enfermedad", "fuerte"}, pide = {"enfermizo_nino"}, prohibe = {"urbano"}, quita = {"enfermizo_nino"}, edad_min = 18, edad_max = 85 },
    { id = "l01_juv_telefonista", etapa = "juventud", texto = "Entre de operador{o} a la central de telefonos de Brandenburg, turno de noche. Aprendi a reconocer a medio condado por la voz.", da = {"trabajo_nocturno", "secundaria"}, edad_min = 25, edad_max = 70 },
    { id = "l01_juv_tomar_barcazas", etapa = "juventud", texto = "A los diecisiete ya tomaba con los marineros de las barcazas. Aprendi a nadar borrach{o}, que es la unica manera en que nunca me ahogue.", da = {"alcohol", "rio"}, prohibe = {"santidad"}, edad_min = 18, edad_max = 85 },
    { id = "l02_juv_bataan", etapa = "juventud", texto = "En el campo de refugiados de Filipinas aprendi ingles en seis meses y a pintarme la cara para una obra de Navidad. Ahi supe hacer reir.", da = {"bromista"}, pide = {"inmigrante"}, edad_min = 18, edad_max = 30, peso = 5 },
    { id = "l02_juv_corea", etapa = "juventud", texto = "Me reclutaron en el 51 y me pusieron de cocinero en Corea: huevos en polvo para doscientos en una olla del porte de una tina.", da = {"militar", "veterano_corea", "oficio_aprendido"}, prohibe = {"inmigrante", "cojo"}, edad_min = 60, edad_max = 66, sexo = "h" },
    { id = "l02_juv_cuba", etapa = "juventud", texto = "Mi oficio lo aprendi en Cuba y aqui no me lo reconocieron. Barri pisos de una escuela cinco temporadas antes de que me dejaran volver a trabajar.", da = {"oficio_aprendido"}, pide = {"inmigrante"}, edad_min = 32, edad_max = 85 },
    { id = "l02_juv_fuegos", etapa = "juventud", texto = "Los veranos vendia fuegos artificiales en un puesto de la 31W, al lado del puesto de la Kell, una chiquilla de Brandenburg que sabia mas de polvora que yo.", prohibe = {"inmigrante"}, edad_min = 18, edad_max = 38, lazo = "kell" },
    { id = "l02_juv_guantes", etapa = "juventud", texto = "Bote en los Guantes de Oro de Kentucky. Vi pelear a un muchacho Pegas, el que despues se hizo cura en Riverside, y supe que yo no tenia esas manos.", da = {"fuerte"}, prohibe = {"inmigrante", "cojo", "enfermizo_nino"}, edad_min = 31, edad_max = 48, lazo = "nacho" },
    { id = "l02_juv_nadar", etapa = "juventud", texto = "Me quede con la pierna flaca, pero a los quince me puse a nadar el rio todos los veranos. A los dieciocho cruzaba el Ohio ida y vuelta.", da = {"supero_enfermedad", "fuerte"}, pide = {"enfermizo_nino"}, prohibe = {"inmigrante"}, quita = {"enfermizo_nino"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l02_juv_novio", etapa = "juventud", texto = "A los veinte me subi al camion de un novio con una maleta y un frasco de pepinillos. En mi casa no me hablaron en mucho tiempo.", da = {"camionero_pasado"}, pide = {"forastero"}, edad_min = 18, edad_max = 85, sexo = "m" },
    { id = "l02_juv_ollies", etapa = "juventud", texto = "Fui mesera del turno de noche en Ollie's, en Bardstown Road. Una companera estudiaba para profesora y nos corregia las cuentas a todos.", da = {"louisville", "urbano"}, prohibe = {"inmigrante"}, edad_min = 19, edad_max = 35, lazo = "valentina" },
    { id = "l02_juv_pista", etapa = "juventud", texto = "Los viernes corria en la pista de tierra con un numero pintado en la puerta. Cuando ganaba me tiraban cerveza en la cabeza.", da = {"valiente", "bromista"}, prohibe = {"inmigrante", "viejo_fragil"}, edad_min = 35, edad_max = 85 },
    { id = "l02_juv_sastreria", etapa = "juventud", texto = "Entre joven a la sastreria del Fuerte Knox. En tiempos de Vietnam cosia doce apellidos por hora en cintas verdes, y algunos despues salian en el diario.", da = {"fort_knox", "oficio_aprendido"}, prohibe = {"inmigrante"}, edad_min = 42, edad_max = 72 },
    { id = "l02_juv_trago", etapa = "juventud", texto = "A los diecisiete ya tomaba bourbon barato detras del galpon. A los veinte tomaba delante de todos.", da = {"alcohol"}, edad_min = 18, edad_max = 85 },
    { id = "l03_juv_asma_se_fue", etapa = "juventud", texto = "A los diecisiete el asma se me fue con el trabajo de campo, o el campo me la saco a golpes. Desde entonces cargo sacos como cualquiera.", da = {"supero_enfermedad", "fuerte"}, pide_alguno = {"asma", "enfermizo_nino"}, quita = {"enfermizo_nino"}, edad_min = 18, edad_max = 85 },
    { id = "l03_juv_casada_joven", etapa = "juventud", texto = "Me case a los diecisiete con el primero que me saco a bailar en la feria de Muldraugh. A los dieciocho ya tenia una guagua en brazos.", da = {"casado", "con_hijos"}, edad_min = 20, edad_max = 85, sexo = "m" },
    { id = "l03_juv_corea_frio", etapa = "juventud", texto = "A los veinte me mandaron a Corea. El frio de alla no lo cuento: se me quedaron dos dedos del pie y la costumbre de dormir con calcetines.", da = {"militar", "veterano_corea", "lesion_pierna"}, edad_min = 60, edad_max = 63, sexo = "h" },
    { id = "l03_juv_deje_escuela", etapa = "juventud", texto = "Deje la escuela en octavo para trabajar. Mi padre dijo que con leer los precios bastaba, y le hice caso.", da = {"sin_estudios"}, prohibe = {"secundaria", "universidad"}, edad_min = 18, edad_max = 85 },
    { id = "l03_juv_guantes_oro", etapa = "juventud", texto = "Boxee en los Guantes de Oro. En la final de Lexington del 79 vi pelear al que hoy es el cura de Riverside; le quebraron la nariz y gano igual.", da = {"atleta", "fuerte"}, prohibe = {"enfermizo_nino", "asma"}, edad_min = 30, edad_max = 40, lazo = "nacho" },
    { id = "l03_juv_guerra_fabrica", etapa = "juventud", texto = "En la guerra trabaje en una fabrica de municiones de Louisville. Las mujeres hacian todo, y cuando volvieron los hombres nos mandaron a la casa.", da = {"fabrica", "louisville"}, edad_min = 66, edad_max = 85, sexo = "m" },
    { id = "l03_juv_preso_robo", etapa = "juventud", texto = "A los diecinueve me robe una camioneta con dos amigos para ir a Nashville. Me dieron dieciocho meses en La Grange. Sali sabiendo callar.", da = {"preso_pasado"}, prohibe = {"policia_pasado"}, edad_min = 18, edad_max = 85 },
    { id = "l03_juv_secundaria_primera", etapa = "juventud", texto = "Termine la secundaria con la mejor letra del curso. Fui {el} primer{o} de la familia con diploma, y mi madre lo colgo al lado del Cristo.", da = {"secundaria"}, prohibe = {"sin_estudios"}, edad_min = 18, edad_max = 85 },
    { id = "l03_juv_universidad_beca", etapa = "juventud", texto = "Me gane una beca para la universidad en Lexington. La primera semana llore de miedo en el bano; la segunda ya no me queria volver.", da = {"universidad", "secundaria"}, prohibe = {"sin_estudios"}, edad_min = 20, edad_max = 85 },
    { id = "l03_juv_vietnam_leva", etapa = "juventud", texto = "Me llego la carta de la leva a los diecinueve. Un invierno en Vietnam, en la selva, y volvi sin una muela y sin ganas de hablar de eso.", da = {"militar", "veterano_vietnam"}, edad_min = 40, edad_max = 48, sexo = "h" },
    { id = "l04_juv_casa_joven", etapa = "juventud", texto = "Me case a los diecisiete con el primero que me saco a bailar en la feria del condado. Mi mama lloro en la iglesia y no de alegria. Tenia razon, pero tarde un tiempo en darselo.", da = {"casado"}, edad_min = 18, edad_max = 85, sexo = "m" },
    { id = "l04_juv_corea_senales", etapa = "juventud", texto = "Me reclutaron para Corea y me pusieron a tender cable de telefono en postes que los chinos nos volaban de noche. Volvi sabiendo mas de corriente que de disparar.", da = {"militar", "veterano_corea"}, edad_min = 58, edad_max = 68, sexo = "h" },
    { id = "l04_juv_fabrica_ford", etapa = "juventud", texto = "Me fui a Louisville a la planta de camiones de la Ford, turno de noche. Ganaba como nunca y gastaba como siempre. Volvi a {pueblo} con un auto nuevo y sin un peso.", da = {"fabrica", "louisville", "deudas"}, edad_min = 18, edad_max = 85 },
    { id = "l04_juv_guantes_oro", etapa = "juventud", texto = "Pelee en los Guantes de Oro. No llegue lejos, pero vi la final de Lexington del 79, la del muchacho que despues se hizo cura en Riverside. Le quebraron la nariz y gano igual.", da = {"atleta", "fuerte"}, prohibe = {"enfermizo_nino", "cojo"}, edad_min = 30, edad_max = 45, lazo = "nacho" },
    { id = "l04_juv_la_grange", etapa = "juventud", texto = "A los diecisiete me mandaron once meses al reformatorio de La Grange por una camioneta que no era mia. Habia un guardia tejano que anotaba hasta las cucharas. Sali sabiendo callar.", da = {"preso_pasado"}, edad_min = 18, edad_max = 38, lazo = "vargas" },
    { id = "l04_juv_lucha_colegio", etapa = "juventud", texto = "En la secundaria fui de lucha libre, peso medio. No era rapid{o} ni bonit{o}, pero no me soltaba. Me quedo una oreja de coliflor y la costumbre de saludar apretando la mano.", da = {"atleta", "fuerte", "secundaria"}, prohibe = {"enfermizo_nino", "cojo"}, edad_min = 18, edad_max = 85 },
    { id = "l04_juv_supero_asma", etapa = "juventud", texto = "A los catorce el doctor del condado me dijo que corriera hasta ahogarme y que despues corriera otra vez. Lo hice dos inviernos. El asma se fue achicando y yo me fui agrandando.", da = {"supero_enfermedad", "atleta"}, pide = {"enfermizo_nino"}, prohibe = {"cojo"}, quita = {"enfermizo_nino"}, edad_min = 18, edad_max = 85 },
    { id = "l04_juv_vietnam_tanques", etapa = "juventud", texto = "Me llamaron en la leva de Vietnam y me mandaron a arreglar tanques. Unos fueron al arrozal; yo me quede con la grasa hasta los codos y una culpa que no se a quien devolver.", da = {"militar", "veterano_vietnam", "oficio_aprendido"}, edad_min = 38, edad_max = 55, sexo = "h" },
    { id = "l05_juv_carpa", etapa = "juventud", texto = "A los dieciseis me converti en una carpa de avivamiento. El predicador era de Knoxville y cobraba aparte por imponer las manos. Igual llore.", da = {"religioso"}, edad_min = 18, edad_max = 35, lazo = "reyes" },
    { id = "l05_juv_guantes", etapa = "juventud", texto = "En el 79 fui a Lexington a ver la final de los Guantes de Oro. A uno le pararon la pelea por un corte en la ceja; el que gano termino de cura en Riverside.", prohibe = {"nunca_salio"}, edad_min = 29, edad_max = 50, lazo = "nacho" },
    { id = "l05_juv_marines", etapa = "juventud", texto = "A los diecinueve me aliste en los Marines para no bajar a la mina. Me tuvieron treinta inviernos arreglando camiones en medio mundo.", da = {"militar", "marino", "oficio_aprendido"}, prohibe = {"nunca_salio", "enfermizo_nino"}, edad_min = 49, edad_max = 70, sexo = "h", peso = 5 },
    { id = "l05_juv_nueva_york", etapa = "juventud", texto = "A los dieciocho me fui a Nueva York con trescientos dolares cosidos en la ropa. Servi cafe tres inviernos, hice papeles chicos y volvi sin contar a que habia ido.", da = {"urbano"}, prohibe = {"nunca_salio"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l05_juv_ollies", etapa = "juventud", texto = "Estudie en Louisville y comia de noche en el Ollie's de Bardstown Road. La mesera del turno de noche era de Muldraugh y estudiaba para profesora.", da = {"louisville", "universidad"}, prohibe = {"nunca_salio", "sin_estudios"}, edad_min = 19, edad_max = 30, lazo = "valentina" },
    { id = "l05_juv_petardos", etapa = "juventud", texto = "Los veranos compraba petardos en un puesto de la 31W que atendia una muchacha de Brandenburg, hija de bombero. Nunca me cobro los que se mojaban.", da = {"bromista"}, edad_min = 18, edad_max = 40, lazo = "kell" },
    { id = "l05_juv_reformatorio", etapa = "juventud", texto = "A los diecisiete me mandaron dos inviernos al reformatorio de La Grange por robar una camioneta. Sali sabiendo de motores y de callarme.", da = {"preso_pasado", "oficio_aprendido"}, edad_min = 18, edad_max = 85 },
    { id = "l05_juv_vietnam_enfermera", etapa = "juventud", texto = "Fui enfermera del Ejercito en Vietnam, en un hospital de evacuacion. Ahi aprendi a elegir en un segundo quien entraba primero a la mesa.", da = {"militar", "veterano_vietnam"}, prohibe = {"nunca_salio"}, edad_min = 42, edad_max = 60, sexo = "m", peso = 5 },
    { id = "l05_juv_volar", etapa = "juventud", texto = "A los dieciseis vole solo. A los dieciocho fumigaba tabaco desde una pista de pasto, tan bajo que veia parpadear a las vacas.", da = {"aviador"}, pide_alguno = {"rural", "tabaco", "granja"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l06_juv_4f", etapa = "juventud", texto = "Me llamaron para Vietnam y el medico me dio 4-F. Senti alivio. Mis amigos se fueron igual, y uno no volvio. Nunca le he dicho a nadie lo del alivio.", da = {"culpa"}, pide_alguno = {"lesion_pierna", "sordo", "vista_mala", "asma", "cojo", "enfermizo_nino"}, prohibe = {"militar"}, edad_min = 39, edad_max = 49, sexo = "h" },
    { id = "l06_juv_alambique", etapa = "juventud", texto = "A los dieciseis deje la escuela para ayudar en el alambique de la familia, al fondo del hollow. El whisky pagaba los zapatos de todos.", da = {"contrabando", "sin_estudios"}, pide_alguno = {"montana", "rural"}, prohibe = {"universidad"}, edad_min = 18, edad_max = 85 },
    { id = "l06_juv_cantante", etapa = "juventud", texto = "De los dieciocho a los treinta cante los fines de semana en un bar de carretera de la 31W. Los soldados del Fuerte lloraban en la tercera cancion.", da = {"musico", "fumador"}, edad_min = 31, edad_max = 85 },
    { id = "l06_juv_enfermeria", etapa = "juventud", texto = "Estudie enfermeria en mi pais. Cuando llegue aqui me hicieron empezar de auxiliar, como si nunca hubiera cosido una herida.", da = {"oficio_aprendido"}, pide = {"inmigrante"}, edad_min = 30, edad_max = 85 },
    { id = "l06_juv_greyhound", etapa = "juventud", texto = "En {ano+18} me fui de la casa de un dia para otro, en el Greyhound de las cinco, con lo puesto y la plata del tarro del cafe.", da = {"forastero"}, prohibe = {"nunca_salio"}, edad_min = 18, edad_max = 85 },
    { id = "l06_juv_guantes", etapa = "juventud", texto = "Boxee de muchacho. En el 79 fui a la final de los Guantes de Oro en Lexington: el Martillo Duggan contra el que hoy es cura en Riverside. Pararon la pelea en el tercero.", da = {"atleta"}, prohibe = {"cojo", "enfermizo_nino"}, edad_min = 30, edad_max = 60, lazo = "duggan" },
    { id = "l06_juv_liniero", etapa = "juventud", texto = "Despues de la escuela entre a la cooperativa electrica a colgar cable por el condado. Vi a viejas llorar delante de la primera ampolleta de su casa.", da = {"oficio_aprendido"}, prohibe = {"cojo"}, edad_min = 56, edad_max = 76 },
    { id = "l06_juv_maestra", etapa = "juventud", texto = "Saque el titulo de maestra en el colegio de maestros de Bowling Green y me mandaron a una escuela de una sola sala, con una estufa a lena.", da = {"universidad"}, edad_min = 55, edad_max = 85, sexo = "m" },
    { id = "l06_juv_marina", etapa = "juventud", texto = "Me enliste en la Marina a los diecinueve. Volvi de la Segunda Guerra con un oido menos por los canones y las manos sabiendo electricidad.", da = {"militar", "marino", "veterano_wwii", "sordo", "oficio_aprendido"}, prohibe = {"cojo", "enfermizo_nino"}, edad_min = 66, edad_max = 71, sexo = "h" },
    { id = "l06_juv_nadar", etapa = "juventud", texto = "A los quince deje el aparato de la pierna y me puse a nadar en el rio todos los dias. Cojeo igual, pero aguanto mas que cualquiera.", da = {"supero_enfermedad", "fuerte"}, pide = {"cojo"}, quita = {"enfermizo_nino"}, edad_min = 18, edad_max = 85 },
    { id = "l06_juv_rodilla", etapa = "juventud", texto = "En la secundaria fui la estrella del equipo; me venian a ver de una universidad. En el ultimo partido me rompi la rodilla y se acabo todo.", da = {"lesion_pierna", "secundaria"}, pide_alguno = {"atleta", "fuerte"}, quita = {"atleta"}, edad_min = 18, edad_max = 85 },
    { id = "l07_juv_beca_perdida", etapa = "juventud", texto = "En {ano+18} me ofrecieron una beca lejos de casa y dije que no, porque alguien me necesitaba. Todavia no se si era verdad o si tenia miedo.", da = {"culpa", "timido"}, edad_min = 25, edad_max = 85 },
    { id = "l07_juv_cadetes", etapa = "juventud", texto = "Entre al cuerpo de cadetes de enfermeria en plena guerra mundial. Nos ensenaron a poner puntos con pulso firme y a llorar solo en el pasillo.", da = {"oficio_aprendido"}, edad_min = 64, edad_max = 70, sexo = "m" },
    { id = "l07_juv_cartera", etapa = "juventud", texto = "En {ano+22} entre de suplente al correo rural. Aprendi cada camino de tierra del condado, cada vado y cada perro que muerde.", da = {"conoce_caminos"}, edad_min = 25, edad_max = 85 },
    { id = "l07_juv_coro_85", etapa = "juventud", texto = "En el 85 cantaba en el coro de la secundaria de Muldraugh. La hija del cabo canto el solo, y su papa llego de uniforme cuando ya guardabamos las sillas.", da = {"secundaria"}, edad_min = 21, edad_max = 25, pueblos = {"Muldraugh"}, lazo = "valentina" },
    { id = "l07_juv_guantes_oro", etapa = "juventud", texto = "En el 79 fui a Lexington a ver la final de los Guantes de Oro. Gano un muchacho hijo de chileno con la nariz quebrada, el mismo que despues fue cura en Riverside.", edad_min = 30, edad_max = 39, lazo = "nacho" },
    { id = "l07_juv_manguera_kell", etapa = "juventud", texto = "En {ano+20} entre de voluntari{o} al cuartel de West Point. En una practica en Brandenburg, Desmond Kell me enseno a enrollar la manguera doble.", da = {"valiente"}, edad_min = 26, edad_max = 53, pueblos = {"West Point"}, lazo = "kell" },
    { id = "l07_juv_ollas", etapa = "juventud", texto = "A los dieciocho me fui a Louisville a lavar ollas en un restaurante fino. El agua hirviendo me dejo los brazos lisos y brillantes, como de cera.", da = {"louisville", "lesion_mano"}, edad_min = 18, edad_max = 85 },
    { id = "l07_juv_sherman", etapa = "juventud", texto = "En {ano+18} me llamaron al Ejercito y aprendi a apretar pernos en un tanque Sherman, en un barro de Europa que todavia huelo. De ahi me quedo sordo un oido.", da = {"militar", "veterano_wwii", "sordo", "oficio_aprendido"}, edad_min = 66, edad_max = 70, sexo = "h" },
    { id = "l07_juv_supera_desmayo", etapa = "juventud", texto = "Me obligue a trabajar los sabados en una clinica de animales grandes hasta que la sangre dejo de tumbarme. Casi del todo.", da = {"valiente"}, pide = {"se_desmaya"}, quita = {"se_desmaya"}, edad_min = 20, edad_max = 85 },
    { id = "l08_juv_bowling_green", etapa = "juventud", texto = "En mi familia nadie habia pasado de octavo. Yo me fui a la universidad en Bowling Green con una maleta de mi tia y volvi con un titulo y la costumbre de explicarlo todo.", da = {"universidad", "secundaria"}, prohibe = {"sin_estudios"}, edad_min = 22, edad_max = 85 },
    { id = "l08_juv_cambio_remedio", etapa = "juventud", texto = "A los veinte un doctor de Louisville me cambio el remedio y los ataques casi se fueron. Saque licencia de manejar a los veintidos, con la mano temblando de alegria.", da = {"supero_enfermedad"}, pide = {"epilepsia"}, quita = {"enfermizo_nino"}, edad_min = 23, edad_max = 85 },
    { id = "l08_juv_casorio", etapa = "juventud", texto = "Me case a los dieciocho, en la iglesia bautista de {pueblo}, con un vestido prestado y un muchacho que acababa de volver del Ejercito.", da = {"casado", "bautista"}, edad_min = 25, edad_max = 85, sexo = "m" },
    { id = "l08_juv_cb_19", etapa = "juventud", texto = "A los diecinueve me compre mi primera radio CB. En el canal 19 aprendi de memoria las basculas de la 31, casi todas por el Gordo Ruta.", da = {"camionero_pasado"}, edad_min = 20, edad_max = 42, lazo = "earl" },
    { id = "l08_juv_cocina_tropa", etapa = "juventud", texto = "Me enliste a los dieciocho para que mi papa dejara de decirme blando, y el Ejercito me mando a la cocina. Dos veranos en Alemania haciendo huevos para cuatrocientos.", da = {"militar", "oficio_aprendido"}, edad_min = 25, edad_max = 60 },
    { id = "l08_juv_guantes_oro", etapa = "juventud", texto = "En el setenta y nueve fui a Lexington a ver la final de los Guantes de Oro. Le aposte cinco dolares al que perdio. El que gano, con la nariz quebrada, despues se hizo cura.", da = {"apostador"}, edad_min = 30, edad_max = 70, lazo = "nacho" },
    { id = "l08_juv_la_grange", etapa = "juventud", texto = "A los veinte pase dos inviernos en el reformatorio de La Grange por robar baterias. Habia un guardia tejano que nos trataba de usted y nos contaba hasta las cucharas.", da = {"preso_pasado"}, edad_min = 22, edad_max = 41, lazo = "vargas" },
    { id = "l08_juv_lote_autos", etapa = "juventud", texto = "A los diecinueve me fui a Louisville a trabajar en un lote de autos usados de la Preston Highway. Ahi aprendi que un papel dice lo que uno quiere que diga.", da = {"louisville", "comerciante", "mentiroso"}, edad_min = 21, edad_max = 85 },
    { id = "l08_juv_objetor", etapa = "juventud", texto = "Cuando me llego la carta del Ejercito dije que no, por mi fe. Me tuvieron preso en Ashland hasta que se acabo la guerra. Ahi aprendi a desarmar un motor.", da = {"preso_pasado", "religioso", "oficio_aprendido"}, prohibe = {"militar", "veterano_wwii"}, edad_min = 66, edad_max = 85, sexo = "h", peso = 5 },
    { id = "l08_juv_vestido_gladys", etapa = "juventud", texto = "La ropa de mi graduacion me la entallaron en Arreglos Gladys, en la calle principal de Muldraugh. La senora Gladys me clavo dos alfileres y me dijo que me parara derech{o}.", da = {"secundaria"}, edad_min = 18, edad_max = 38, lazo = "gladys" },
    { id = "l08_juv_vietnam_chofer", etapa = "juventud", texto = "A los diecinueve me mandaron a Vietnam de chofer de camion. Volvi con la espalda mala y sin ganas de contarle nada a nadie.", da = {"militar", "veterano_vietnam", "lesion_espalda", "camionero_pasado"}, edad_min = 39, edad_max = 48, sexo = "h" },
    { id = "l09_juv_cobrador", etapa = "juventud", texto = "A los dieciocho entre a cobrar cuotas puerta a puerta en la Dixie Highway: televisores, sillones, autos. Aprendi a sonreir y a abrir un auto con una regla de metal.", da = {"louisville", "bromista", "mentiroso"}, edad_min = 20, edad_max = 50 },
    { id = "l09_juv_comuna", etapa = "juventud", texto = "A los veinte me fui con unos muchachos de pelo largo a una comuna de Tennessee. Aprendi a sembrar, a coser y a no pedirle permiso a nadie.", da = {"rural", "sin_fe"}, prohibe = {"nunca_salio", "militar"}, edad_min = 33, edad_max = 46, peso = 5 },
    { id = "l09_juv_corea_ingenieros", etapa = "juventud", texto = "Me reclutaron para Corea y me pusieron en los ingenieros: puentes, bunkers, picos. El invierno del 51 me dejo sin dos dedos del pie.", da = {"militar", "veterano_corea", "lesion_pierna", "oficio_aprendido"}, prohibe = {"nunca_salio"}, edad_min = 59, edad_max = 68, sexo = "h" },
    { id = "l09_juv_corista", etapa = "juventud", texto = "Me fui a Chicago a bailar con veinte dolares cosidos al forro. Fui corista, hice giras por teatros con olor a naftalina, y una tabla suelta me rompio la rodilla.", da = {"lesion_pierna", "artista_frustrado"}, pide = {"atleta"}, prohibe = {"nunca_salio"}, quita = {"atleta"}, edad_min = 45, edad_max = 85, peso = 5 },
    { id = "l09_juv_la_grange", etapa = "juventud", texto = "Pase unos meses en el reformatorio de La Grange por una pelea de bar. Habia un guardia panzon que lo anotaba todo en una libreta y nunca levantaba la voz.", da = {"preso_pasado"}, edad_min = 21, edad_max = 45, sexo = "h", lazo = "vargas" },
    { id = "l09_juv_ligas_menores", etapa = "juventud", texto = "A los dieciocho me firmo un equipo profesional y pase unas temporadas en las ligas menores, en buses de diez horas. Un hombro roto me mando de vuelta a {pueblo}.", da = {"lesion_hombro"}, pide = {"atleta"}, prohibe = {"nunca_salio", "enfermizo_nino"}, quita = {"atleta"}, edad_min = 25, edad_max = 60, sexo = "h", peso = 5 },
    { id = "l09_juv_madre_quince", etapa = "juventud", texto = "Quede embarazada a los quince. Deje la escuela y la gente de {pueblo} me miraba la panza como si fuera una deuda.", da = {"con_hijos", "madre_joven", "sin_estudios"}, edad_min = 18, edad_max = 60, sexo = "m" },
    { id = "l09_juv_ollies", etapa = "juventud", texto = "Estudiando en Louisville trabaje de noche en el Ollie's Diner de Bardstown Road. Habia una mesera seria, hija de un policia, que daba la cuenta exacta hasta el centavo.", da = {"louisville", "universidad"}, edad_min = 21, edad_max = 30, lazo = "valentina" },
    { id = "l09_juv_petardos", etapa = "juventud", texto = "Cada verano le compraba petardos a una muchacha flaca que tenia un puesto en la 31W. Me los vendia sin sonreir y me decia cuales no prender cerca de la cara.", da = {"bromista"}, edad_min = 18, edad_max = 35, lazo = "kell" },
    { id = "l09_juv_planta_ford", etapa = "juventud", texto = "A los diecinueve entre a la planta de la Ford en Louisville. Apretaba pernos de rueda y a los dos meses ya iba a las asambleas del sindicato.", da = {"fabrica", "louisville", "sindicato"}, edad_min = 35, edad_max = 85 },
    { id = "l09_juv_spiffos", etapa = "juventud", texto = "Mi primer trabajo fue lavar platos en el Spiffo's de Muldraugh. El cocinero era un mexicano flaco que cantaba bajito y me guardaba las papas que sobraban.", da = {"pobre"}, edad_min = 18, edad_max = 24, lazo = "julio" },
    { id = "l09_juv_supero_asma", etapa = "juventud", texto = "A los dieciseis el cuerpo me cambio: deje la cama y me puse a cargar sacos de forraje hasta que el pecho dejo de silbar.", da = {"supero_enfermedad", "fuerte"}, pide_alguno = {"enfermizo_nino", "asma"}, prohibe = {"corazon"}, quita = {"enfermizo_nino", "asma"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l10_juv_aserradero", etapa = "juventud", texto = "Trabaje un verano en el aserradero de la 31. Habia un muchacho de West Point, Giovanns, que cargaba el doble y se reia de todo.", da = {"fuerte"}, edad_min = 21, edad_max = 33, lazo = "eduardo" },
    { id = "l10_juv_canada", etapa = "juventud", texto = "En el 70 me fui a Canada para no ir a Vietnam. Volvi con el perdon de Carter, en el 77, y en {pueblo} me pintaron la puerta de amarillo.", da = {"evasor", "forastero"}, prohibe = {"militar", "veterano_vietnam"}, edad_min = 39, edad_max = 45, sexo = "h", peso = 5 },
    { id = "l10_juv_clarinete", etapa = "juventud", texto = "Empece a tomar a los catorce, con una botella escondida en el estuche del clarinete de la banda. Del clarinete no me acuerdo nada.", da = {"alcohol"}, prohibe = {"sobrio"}, edad_min = 18, edad_max = 85 },
    { id = "l10_juv_dmz", etapa = "juventud", texto = "Me reclutaron esperando Vietnam y me mandaron a la zona desmilitarizada de Corea. Alla decian que no habia guerra. Alla uno se moria igual.", da = {"militar", "solitario"}, prohibe = {"evasor"}, edad_min = 44, edad_max = 50, sexo = "h", peso = 5 },
    { id = "l10_juv_guantes_oro", etapa = "juventud", texto = "En el 79 fui a Lexington a ver la final de los Guantes de Oro. Gano un muchacho que despues se hizo cura; al otro le pararon la pelea por un corte.", da = {"bromista"}, edad_min = 24, edad_max = 60, lazo = "nacho" },
    { id = "l10_juv_la_grange", etapa = "juventud", texto = "A los diecinueve cai al reformatorio de La Grange por robar autos. Habia un guardia, Vargas, que anotaba todo en una libreta, hasta lo que uno debia.", da = {"preso_pasado"}, edad_min = 20, edad_max = 40, lazo = "vargas" },
    { id = "l10_juv_madre_joven", etapa = "juventud", texto = "Me case a los dieciseis porque el tenia camioneta. A los diecisiete ya era mama, y a los veinte ya no tenia camioneta ni marido.", da = {"con_hijos", "separado"}, edad_min = 25, edad_max = 85, sexo = "m" },
    { id = "l10_juv_maletin", etapa = "juventud", texto = "A los veinte me dieron un maletin y una ruta: puerta por puerta, de Hazard a Paducah. La primera palabra se dice antes que abran.", da = {"comerciante", "bromista"}, edad_min = 30, edad_max = 85 },
    { id = "l10_juv_represa", etapa = "juventud", texto = "A los veinte entre de mecanico a una represa del Cuerpo de Ingenieros. Las garzas se paraban en el vertedero como si fueran del sindicato.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 60 },
    { id = "l10_juv_spiffos", etapa = "juventud", texto = "Lave platos en el Spiffo's de Muldraugh. El cocinero era un mexicano que cantaba rancheras y me enseno a dar vuelta un huevo sin romperlo.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 27, lazo = "julio" },
    { id = "l01_adu_cobranza", etapa = "adultez", texto = "Fui de puerta en puerta cobrando seguros de entierro, veinticinco centavos a la semana. Se cuanto vale un cajon de pino y quien se va a ir en cual.", da = {"vendedor_puerta", "comerciante"}, edad_min = 45, edad_max = 85 },
    { id = "l01_adu_compra_vacas", etapa = "adultez", texto = "En el 86 el gobierno pago para que la lecheria matara todas sus vacas, porque sobraba leche en el pais. Las subi yo al camion, una por una.", da = {"perdio_todo"}, pide = {"lechero"}, edad_min = 27, edad_max = 85 },
    { id = "l01_adu_destileria", etapa = "adultez", texto = "Trabaje de noche en una destileria de la 31W, rodando barriles en las bodegas. El whisky es agua que aprendio a esperar, y yo tambien.", da = {"trabajo_nocturno", "fabrica"}, edad_min = 40, edad_max = 85 },
    { id = "l01_adu_gordo_ruta", etapa = "adultez", texto = "Muchas noches oi por el canal 19 a un camionero gordo de la 31 que contaba chistes malos de Nashville. Le decian Gordo Ruta y nadie le ganaba a hablar.", edad_min = 25, edad_max = 85, lazo = "earl" },
    { id = "l01_adu_grua", etapa = "adultez", texto = "Una noche de lluvia me fui a una zanja del camino del rio. Me saco el muchacho de la grua, el hijo de la bombera de West Point, y no me cobro ni un dolar.", edad_min = 25, edad_max = 85, lazo = "eduardo" },
    { id = "l01_adu_pulmon", etapa = "adultez", texto = "El doctor me dijo pulmon negro y me saco de la mina. Desde entonces respiro con silbido y me detengo en cada descanso de la escalera.", da = {"pulmon_negro"}, pide = {"minero"}, prohibe = {"atleta"}, quita = {"fuerte"}, edad_min = 40, edad_max = 85 },
    { id = "l01_adu_rollos_canela", etapa = "adultez", texto = "Todos los sabados iba a la panaderia Hollis de Riverside por los rollos de canela. La panadera me guardaba los de la orilla, que tienen mas azucar.", edad_min = 25, edad_max = 85, pueblos = {"Riverside"}, lazo = "yvonne_bell" },
    { id = "l01_adu_rosa_estanque", etapa = "adultez", texto = "Cuando me quede sin trabajo, la Misia Rosa me lleno el estanque en su gasolinera y me pregunto lleno o normal como si yo fuera a pagar. Le pague en tres meses. Nunca me cobro intereses.", da = {"deudas"}, edad_min = 25, edad_max = 85, lazo = "rosa" },
    { id = "l01_adu_seguro_bell", etapa = "adultez", texto = "Un vendedor de seguros de camisa celeste, un tal Bell, me vendio una poliza de vida en mi cocina. Era tan amable que me dio verguenza decirle que no.", edad_min = 25, edad_max = 85, lazo = "daniel_bell" },
    { id = "l01_adu_sobrio", etapa = "adultez", texto = "Deje de tomar el dia que mi {hijo} me miro como yo miraba a mi papa. Desde entonces tomo cafe negro hasta que me tiemblan las manos.", da = {"sobrio", "con_hijos"}, pide = {"alcohol"}, quita = {"alcohol"}, edad_min = 30, edad_max = 85 },
    { id = "l01_adu_vestido", etapa = "adultez", texto = "El vestido de mi boda me lo entallo la costurera mexicana de la calle principal de Muldraugh. Me hacia rezar mientras me clavaba los alfileres.", da = {"casado"}, edad_min = 25, edad_max = 50, sexo = "m", lazo = "gladys" },
    { id = "l01_adu_viudez_bote", etapa = "adultez", texto = "Enviude un martes. Lo encontre en el bote, a la deriva, con la cana todavia en la mano.", da = {"viudo"}, pide = {"rio"}, quita = {"casado"}, edad_min = 35, edad_max = 85, sexo = "m" },
    { id = "l02_adu_banco85", etapa = "adultez", texto = "En la crisis del 85 el banco se llevo la granja, la mula y hasta la radio de la cocina. Me quede con la ropa y la rabia.", da = {"perdio_todo", "deudas", "rencoroso"}, edad_min = 38, edad_max = 85 },
    { id = "l02_adu_bell", etapa = "adultez", texto = "Un vendedor de seguros de camisa celeste, el Bell, me vendio una poliza en la puerta de mi casa. La pague dos temporadas y la deje.", edad_min = 25, edad_max = 85, lazo = "daniel_bell" },
    { id = "l02_adu_hijos", etapa = "adultez", texto = "Tuve tres hijos seguidos, uno por invierno. En mi casa se comia por turnos y se dormia de a dos en una cama.", da = {"con_hijos", "familia_grande"}, edad_min = 30, edad_max = 85 },
    { id = "l02_adu_hijos_lejos", etapa = "adultez", texto = "Los hijos se me fueron a Indianapolis y a Chicago. Llaman en Navidad y los nietos me dicen senor.", da = {"hijos_lejos"}, pide = {"con_hijos"}, edad_min = 45, edad_max = 85 },
    { id = "l02_adu_juzgado", etapa = "adultez", texto = "Me case en el juzgado, sin fiesta, un martes. Duro lo que dura una cosecha mala.", da = {"divorciado"}, edad_min = 30, edad_max = 85 },
    { id = "l02_adu_madre", etapa = "adultez", texto = "Me hice cargo de mi mama cuando le dio el derrame. Doce inviernos le cambie las sabanas y le lei el diario de Louisville en voz alta.", da = {"cuida_a_alguien"}, edad_min = 18, edad_max = 85 },
    { id = "l02_adu_nevazon", etapa = "adultez", texto = "En la nevazon de enero del 77 quede atrapad{o} en la gasolinera de Rosewood con doce camioneros. La Misia Rosa nos frio huevos a todos y no cobro.", edad_min = 36, edad_max = 85, lazo = "rosa" },
    { id = "l02_adu_sobrio", etapa = "adultez", texto = "Deje de tomar el dia que desperte en la cuneta de la 31 con la camioneta en el arroyo. Desde entonces, cafe negro y nada mas.", da = {"sobrio"}, pide = {"alcohol"}, quita = {"alcohol"}, edad_min = 18, edad_max = 85 },
    { id = "l02_adu_tonico", etapa = "adultez", texto = "Oia la hora de la salud del doctor Hartmann en la AM de Louisville y le compre tres frascos de tonico. Sabia a fierro, pero dormia mejor.", edad_min = 35, edad_max = 85, lazo = "hartmann", peso = 5 },
    { id = "l02_adu_viudez", etapa = "adultez", texto = "Me quede viud{o} un martes cualquiera, a medio desayuno. Deje su taza colgada del mismo gancho y no la he movido.", da = {"viudo"}, prohibe = {"divorciado"}, edad_min = 35, edad_max = 85 },
    { id = "l03_adu_alcohol_aa", etapa = "adultez", texto = "Tome como mi padre hasta los cuarenta. Una manana desperte en una zanja de la 31 con el auto de lado. Desde ese dia, ni una gota, y voy a las reuniones del sotano.", da = {"sobrio", "alcohol"}, edad_min = 40, edad_max = 85 },
    { id = "l03_adu_concurso_bell", etapa = "adultez", texto = "Mi {hijo} salio segund{o} en el concurso de matematicas del condado, en abril del 93. Gano el chico de los Bell de Riverside, uno que cuenta todo.", da = {"con_hijos"}, edad_min = 30, edad_max = 55, lazo = "wade_bell" },
    { id = "l03_adu_divorcio", etapa = "adultez", texto = "Me divorcie despues de catorce inviernos. Nadie le pego a nadie: nos dejamos de hablar en la cena, y un dia ya no hubo cena.", da = {"divorciado"}, pide = {"casado"}, quita = {"casado"}, edad_min = 35, edad_max = 85 },
    { id = "l03_adu_espalda", etapa = "adultez", texto = "Me quebre la espalda cargando un ternero en la loma. Seis meses en cama y una faja de cuero para siempre. Ya no levanto nada sobre la cintura.", da = {"lesion_espalda"}, quita = {"atleta"}, edad_min = 30, edad_max = 85 },
    { id = "l03_adu_fabrica_cerro", etapa = "adultez", texto = "Trabaje en la planta de la Ford en Louisville hasta que hubo recorte. Volvi a {pueblo} con una indemnizacion, una camioneta y nada que hacer.", da = {"fabrica", "perdio_todo"}, edad_min = 35, edad_max = 65 },
    { id = "l03_adu_funeral_hector", etapa = "adultez", texto = "Fui al funeral de Hector Bencina en el 88. La viuda abrio la gasolinera al dia siguiente, y un camionero gordo le arreglo el letrero quemado.", edad_min = 30, edad_max = 85, lazo = "rosa" },
    { id = "l03_adu_gladys_vestido", etapa = "adultez", texto = "Mi vestido de novia me lo arreglo la Gladys de Muldraugh, la del taller de la calle principal. Me cobro la mitad porque llore en la prueba.", da = {"casado"}, edad_min = 25, edad_max = 50, sexo = "m", lazo = "gladys" },
    { id = "l03_adu_seguro_bell", etapa = "adultez", texto = "Un vendedor de seguros de la 31, un tal Bell, de camisa celeste, me vendio una poliza de vida. Pague cada mes. Ahora no hay a quien cobrarle.", da = {"casado"}, edad_min = 30, edad_max = 85, lazo = "daniel_bell" },
    { id = "l03_adu_viudo_joven", etapa = "adultez", texto = "Me quede viud{o} joven. Un derrame, un martes, mientras yo estaba en el trabajo. Todavia hago la cama de los dos lados.", da = {"viudo"}, pide = {"casado"}, quita = {"casado"}, edad_min = 30, edad_max = 85 },
    { id = "l04_adu_aserradero", etapa = "adultez", texto = "Trabaje en el aserradero de la 31, con el ruido metido en los dientes. Habia un muchacho de West Point, hijo de la bombera, que cargaba tablas como si no pesaran y no hablaba de nadie.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 60, lazo = "eduardo" },
    { id = "l04_adu_bingo_apuestas", etapa = "adultez", texto = "Los martes bingo, los sabados caballos, los domingos perdon. En Churchill Downs perdi el pago de la casa en una carrera de seis furlongs. Lo demas lo perdi de a poco.", da = {"apostador", "deudas"}, edad_min = 30, edad_max = 85 },
    { id = "l04_adu_cafe_tres", etapa = "adultez", texto = "Cuando manejaba de noche paraba a las tres en la bomba de Rosewood. Habia un camionero gordo que contaba chistes malos y la duena preguntaba lleno o normal hasta a los que iban a pie.", da = {"camionero_pasado"}, edad_min = 30, edad_max = 85, lazo = "earl" },
    { id = "l04_adu_coser_gladys", etapa = "adultez", texto = "Mi pareja llevaba los ruedos y las camisas al taller de costura de la calle principal de Muldraugh. La duena, una tejana mandona, le cobraba con un refran y un tamal.", da = {"casado"}, edad_min = 30, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "gladys" },
    { id = "l04_adu_cuidar_madre", etapa = "adultez", texto = "Pase diez inviernos cuidando a mi mama en la pieza del fondo: la cuchara, la sabana, la radio bajita. Cuando se murio no supe que hacer con las manos.", da = {"cuida_a_alguien", "sin_hijos"}, edad_min = 35, edad_max = 85 },
    { id = "l04_adu_divorcio", etapa = "adultez", texto = "El divorcio llego en un sobre de un abogado de Elizabethtown. Me quede con la camioneta y con las deudas; mi ex se quedo con los ninos y con la razon.", da = {"divorciado", "hijos_lejos", "deudas"}, quita = {"casado"}, edad_min = 28, edad_max = 85 },
    { id = "l04_adu_poliza_bell", etapa = "adultez", texto = "Un vendedor flaco de camisa celeste me vendio un seguro de vida en la puerta de la casa. Pague tres cuotas. Despues el seguia pasando a saludar, como si le debiera la conversacion.", da = {"deudas"}, edad_min = 28, edad_max = 85, lazo = "daniel_bell" },
    { id = "l04_adu_viudez", etapa = "adultez", texto = "Me quede viud{o} un martes cualquiera, con la radio prendida. Seguir poniendo dos platos me duro un mes; la otra almohada, todavia la tengo.", da = {"viudo"}, quita = {"casado"}, edad_min = 30, edad_max = 85 },
    { id = "l05_adu_ge", etapa = "adultez", texto = "Trabaje veinte inviernos en la linea de lavadoras de la GE en Louisville, viajando de ida y vuelta, hasta que una prensa me torcio tres dedos.", da = {"fabrica", "lesion_mano"}, edad_min = 40, edad_max = 85 },
    { id = "l05_adu_grua", etapa = "adultez", texto = "Una noche de lluvia se me fue el auto a la zanja en la 31. Me saco una grua de West Point; el chofer era el hijo de la bombera y no me quiso cobrar.", edad_min = 25, edad_max = 85, lazo = "eduardo" },
    { id = "l05_adu_libreta_cabo", etapa = "adultez", texto = "Una vez el cabo de Muldraugh me paro en la 31 por un foco quemado. No me multo: me anoto en su libreta negra y me dijo que volviera con el foco puesto.", edad_min = 25, edad_max = 85, lazo = "cabo" },
    { id = "l05_adu_lleno_normal", etapa = "adultez", texto = "Treinta inviernos cargando bencina en la bomba de los Bencina. La Misia Rosa me preguntaba lleno o normal aunque yo siempre pedia cinco dolares.", edad_min = 35, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l05_adu_loteria", etapa = "adultez", texto = "Me gane la loteria de Ohio con un boleto comprado de broma. En tres inviernos se fue todo: un bote, un auto blanco y prestamos a parientes que no volvieron.", da = {"perdio_todo", "apostador", "deudas"}, quita = {"acomodado"}, edad_min = 30, edad_max = 85, peso = 5 },
    { id = "l05_adu_madre_cadera", etapa = "adultez", texto = "Me quede a cuidar a mi madre de la cadera. La persona con quien yo salia se caso con un soldado del Fuerte y se fue a Alemania.", da = {"cuida_a_alguien", "sin_hijos"}, prohibe = {"casado"}, edad_min = 25, edad_max = 60 },
    { id = "l05_adu_pan_hollis", etapa = "adultez", texto = "Compraba el pan en la panaderia Hollis antes del turno. A las seis la panadera ya llevaba horas con las manos en la masa y me guardaba el de la orilla.", edad_min = 25, edad_max = 85, pueblos = {"Riverside"}, lazo = "yvonne_bell" },
    { id = "l05_adu_remate", etapa = "adultez", texto = "Criamos caballos de carrera baratos hasta que la ley de impuestos del 86 dejo un potrillo valiendo menos que el pasto. Vi subir mis yeguas al camion del remate.", da = {"caballos", "perdio_todo", "deudas"}, quita = {"acomodado"}, edad_min = 30, edad_max = 70 },
    { id = "l05_adu_seguro_bell", etapa = "adultez", texto = "Un vendedor de seguros de camisa celeste, Bell, me vendio un seguro de vida en la mesa de la cocina. Fue el unico que volvio tres veces a explicarme la letra chica.", edad_min = 30, edad_max = 85, lazo = "daniel_bell" },
    { id = "l05_adu_taller_boxeador", etapa = "adultez", texto = "Llevaba la camioneta al taller del ex boxeador de Riverside. Cobraba barato, no daba boleta y nunca me devolvio las mismas piezas.", edad_min = 25, edad_max = 85, pueblos = {"Riverside"}, lazo = "duggan" },
    { id = "l05_adu_tonico", etapa = "adultez", texto = "Le compre a mi madre el tonico del doctor de la radio AM. Agua con fierro, dijeron despues. Ella juraba que le habia vuelto el color a la cara.", da = {"cuida_a_alguien"}, edad_min = 30, edad_max = 85, lazo = "hartmann" },
    { id = "l05_adu_vestido_gladys", etapa = "adultez", texto = "Me case con un vestido que me entallo la senora Gladys, la de la calle principal de Muldraugh. Me cobro la mitad porque le gustaba como me reia.", da = {"casado"}, edad_min = 25, edad_max = 50, sexo = "m", pueblos = {"Muldraugh"}, lazo = "gladys" },
    { id = "l06_adu_aserradero", etapa = "adultez", texto = "Trabaje en el aserradero de la 31, en Muldraugh. El sereno nuevo habia sido guardia en La Grange, un tal Vargas, y sabia la hora sin mirar el reloj.", edad_min = 25, edad_max = 65, pueblos = {"Muldraugh"}, lazo = "vargas" },
    { id = "l06_adu_civil", etapa = "adultez", texto = "Fui civil en el Fuerte Knox: lavanderia, cocina, parque motorizado, lo que hubiera. Me sabia los toques de corneta mejor que los soldados.", da = {"fort_knox"}, edad_min = 25, edad_max = 85 },
    { id = "l06_adu_divorcio", etapa = "adultez", texto = "Mi ex se fue a Texas con su guitarra y me dejo los hijos. Lo bueno es que se llevo la guitarra.", da = {"divorciado", "con_hijos"}, prohibe = {"viudo", "sin_hijos"}, edad_min = 28, edad_max = 85 },
    { id = "l06_adu_gladys", etapa = "adultez", texto = "La ropa buena me la arreglaba la senora Gladys, en la calle principal de Muldraugh. Me tomaba las medidas sin mirarme y nunca se equivocaba.", edad_min = 25, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "gladys" },
    { id = "l06_adu_hielo", etapa = "adultez", texto = "Me quede viud{o} un invierno, por el hielo de la 31W. Al otro dia abri el negocio igual, porque cerrar era peor.", da = {"viudo"}, prohibe = {"viudo"}, edad_min = 35, edad_max = 85 },
    { id = "l06_adu_hollis", etapa = "adultez", texto = "Hice el reparto de la panaderia Hollis de Riverside. Yvonne, la panadera, me cargaba las bandejas a las cinco, y los sabados me regalaba un rollo de canela.", edad_min = 25, edad_max = 85, pueblos = {"Riverside"}, lazo = "yvonne_bell" },
    { id = "l06_adu_oxigeno", etapa = "adultez", texto = "Los ultimos inviernos los pase cuidando a alguien con el pulmon roto, contando los tanques de oxigeno que traia el camion de los jueves.", da = {"cuida_a_alguien"}, edad_min = 40, edad_max = 85 },
    { id = "l06_adu_rosa", etapa = "adultez", texto = "Hice turno de noche mucho tiempo. A las tres paraba en la gasolinera de la Misia Rosa: cafe recalentado y la pregunta de siempre, lleno o normal.", edad_min = 25, edad_max = 85, lazo = "rosa" },
    { id = "l06_adu_seguros", etapa = "adultez", texto = "Le compre un seguro de vida a un vendedor flaco de la Commonwealth Mutual que iba puerta por puerta por la 31, Daniel Bell. Me acuerdo de que pidio permiso para sentarse.", edad_min = 25, edad_max = 85, lazo = "daniel_bell" },
    { id = "l06_adu_spiffos", etapa = "adultez", texto = "Trabaje en el Spiffo's de Muldraugh con un cocinero mexicano, Julio, que freia todo con la misma cara seria y le guardaba papas a su hija.", edad_min = 25, edad_max = 70, pueblos = {"Muldraugh"}, lazo = "julio" },
    { id = "l06_adu_taller", etapa = "adultez", texto = "Con lo ahorrado abri mi propio taller en la calle de atras de la linea del tren. Pinte el letrero yo mism{o} y me quedo chueco.", da = {"comerciante", "oficio_aprendido"}, edad_min = 28, edad_max = 85 },
    { id = "l06_adu_tecolote", etapa = "adultez", texto = "Le compraba cartones de cigarros sin timbre al Tecolote, en la 31. Fumaba barato y el me contaba los chismes del canal 19 de regalo.", da = {"fumador"}, edad_min = 25, edad_max = 85, lazo = "duarte" },
    { id = "l07_adu_carpa", etapa = "adultez", texto = "Una vez fui a una carpa de avivamiento en la 31. El predicador de traje negro sano a tres en una noche y paso la canasta dos veces. Yo puse dos dolares.", da = {"religioso"}, edad_min = 30, edad_max = 85, lazo = "reyes" },
    { id = "l07_adu_fabrica_noche", etapa = "adultez", texto = "Trabaje de noche en el torno de una planta de electrodomesticos de Louisville, para mandarle plata a la familia que quedo del otro lado del mar.", da = {"fabrica"}, pide_alguno = {"refugiado", "inmigrante"}, edad_min = 18, edad_max = 85 },
    { id = "l07_adu_gladys", etapa = "adultez", texto = "Cuando hubo matrimonio en mi casa le encargue la ropa a dona Gladys, la de la calle principal de Muldraugh. La entrego un dia antes, rezando, con un alfiler en la boca.", edad_min = 40, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "gladys" },
    { id = "l07_adu_hielo", etapa = "adultez", texto = "Un invierno el auto se me fue en el hielo de un camino de tierra. Me quedo la cadera mala y desde entonces manejo lo justo y camino menos.", da = {"lesion_pierna"}, edad_min = 30, edad_max = 85 },
    { id = "l07_adu_incendio_monte", etapa = "adultez", texto = "Trabaje en las cuadrillas de incendio del bosque estatal hasta que un tronco quemado me partio la pierna en tres. Todavia suenan los clavos.", da = {"cojo", "lesion_pierna", "montana"}, prohibe = {"atleta"}, edad_min = 35, edad_max = 85 },
    { id = "l07_adu_logia", etapa = "adultez", texto = "Fui socio de la logia de los hombres de {pueblo} treinta temporadas. Me sabia el ritual entero y el brindis de las once por los hermanos ausentes.", da = {"logia", "lider"}, edad_min = 50, edad_max = 85, sexo = "h" },
    { id = "l07_adu_poliza_dan", etapa = "adultez", texto = "En el 88 un vendedor de seguros de camisa celeste me vendio una poliza en la cocina. Hablaba tan rapido que firme para que se callara. Era buena poliza.", edad_min = 25, edad_max = 85, pueblos = {"Muldraugh", "Rosewood"}, lazo = "daniel_bell" },
    { id = "l07_adu_seguro_apostado", etapa = "adultez", texto = "Una temporada se me fue la mano en la pista y perdi la plata del techo nuevo. En mi casa me lo siguen cobrando en cada gotera.", da = {"apostador", "deudas"}, edad_min = 30, edad_max = 85 },
    { id = "l07_adu_spiffos", etapa = "adultez", texto = "Mi lugar de los viernes era el Spiffo's de Muldraugh. El cocinero mexicano me hacia las papas como yo queria sin que se lo pidiera.", edad_min = 25, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "julio" },
    { id = "l07_adu_tonico_radio", etapa = "adultez", texto = "Durante temporadas le compre al doctor de la radio AM de Louisville su tonico para los nervios. Era agua con fierro, pero el hombre hablaba tan lindo.", edad_min = 35, edad_max = 85, lazo = "hartmann" },
    { id = "l07_adu_wade", etapa = "adultez", texto = "Mi {hijo} iba a la escuela de Riverside con el nino de los Bell, el que gano el concurso de matematicas y se llevo una calculadora de premio.", da = {"con_hijos"}, prohibe = {"sin_hijos"}, edad_min = 30, edad_max = 60, pueblos = {"Riverside"}, lazo = "wade_bell" },
    { id = "l08_adu_cocina_quemada", etapa = "adultez", texto = "Una vez se me quemo la cocina y llegaron los voluntarios de West Point. Una bombera bajita apago la sarten con una tapa y despues me reto por dejarla sola.", edad_min = 35, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l08_adu_divorcio_musico", etapa = "adultez", texto = "Me case con un bajista de bar y me divorcie a los dos inviernos. Fue la unica firma de verdad que puse en esos papeles.", da = {"divorciado", "sin_hijos"}, edad_min = 28, edad_max = 85, sexo = "m" },
    { id = "l08_adu_fin_setenta_cinco", etapa = "adultez", texto = "Vendi el negocio porque en mi iglesia decian que el fin llegaba en el setenta y cinco. No llego. Volvi de emplead{o} al mismo galpon que habia sido mio.", da = {"perdio_todo", "deudas"}, pide = {"religioso"}, edad_min = 45, edad_max = 85 },
    { id = "l08_adu_hijo_down", etapa = "adultez", texto = "Mi ultimo hijo nacio con sindrome de Down cuando ya eramos mayores. El doctor me hablo del hogar de Frankfort. Me lo traje a la casa y aprendi lo que es tener paciencia.", da = {"con_hijos", "cuida_a_alguien"}, prohibe = {"sin_hijos"}, edad_min = 45, edad_max = 85 },
    { id = "l08_adu_hijos_ohio", etapa = "adultez", texto = "Mis hijos se fueron a las fabricas de Ohio y de Indiana. Me llamaban los domingos a las siete, cuando la llamada salia mas barata.", da = {"con_hijos", "hijos_lejos"}, prohibe = {"sin_hijos"}, edad_min = 50, edad_max = 85 },
    { id = "l08_adu_poliza_celeste", etapa = "adultez", texto = "En el noventa y uno un vendedor de seguros de camisa celeste me toco la puerta tres veces. A la tercera le firme una poliza de vida, para que dejara de venir.", da = {"casado"}, edad_min = 25, edad_max = 85, lazo = "daniel_bell" },
    { id = "l08_adu_spiffos", etapa = "adultez", texto = "Los viernes comia en el Spiffo's de Muldraugh. El cocinero, un mexicano flaco, me ponia papas de mas porque una vez le preste una moneda para el telefono.", edad_min = 24, edad_max = 85, lazo = "julio" },
    { id = "l08_adu_tonico_radio", etapa = "adultez", texto = "Cuando a mi mama le dio la tos, le compre el tonico del doctor de la radio de Louisville. Doce botellas. No le hizo nada, y las botellas vacias todavia estan en la despensa.", da = {"culpa"}, edad_min = 35, edad_max = 85, lazo = "hartmann" },
    { id = "l08_adu_turno_noche", etapa = "adultez", texto = "Veinte inviernos en el turno de noche del hospital del Fuerte. Aprendi que la gente se muere mas a las cuatro de la manana, y que a esa hora nadie llama a la familia.", da = {"fort_knox"}, edad_min = 45, edad_max = 85 },
    { id = "l08_adu_viudez_joven", etapa = "adultez", texto = "Quede viud{o} a los treinta y tantos, con dos hijos chicos y una cuenta en el almacen. Agarre el primer trabajo que hubo y no lo solte mas.", da = {"viudo", "con_hijos", "pobre"}, prohibe = {"sin_hijos"}, edad_min = 40, edad_max = 85 },
    { id = "l09_adu_camion_marido", etapa = "adultez", texto = "Maneje trece temporadas de noche el camion de mi marido, mientras el dormia la borrachera en la litera. Cuando se fue, me quede con su deuda y con el oficio.", da = {"divorciado", "deudas", "camionero_pasado"}, edad_min = 35, edad_max = 75, sexo = "m" },
    { id = "l09_adu_cuidar_madre", etapa = "adultez", texto = "Cuide a mi madre seis inviernos, hasta que no me conocia. Cuando se murio, la casa quedo tan callada que me dio miedo salir.", da = {"solitario", "sin_hijos"}, edad_min = 35, edad_max = 80 },
    { id = "l09_adu_entierro_hector", etapa = "adultez", texto = "En octubre del 88 fui al entierro de Hector Bencina, el de la gasolinera. Al otro dia la Misia Rosa abrio la bomba como si nada, y yo le eche diez galones para que tuviera algo que hacer.", edad_min = 25, edad_max = 85, lazo = "rosa" },
    { id = "l09_adu_gladys", etapa = "adultez", texto = "Todo lo que me queda bien me lo arreglo Gladys, la del taller de la calle principal de Muldraugh. Cobra en dolares y en verdades: me dijo que habia engordado.", edad_min = 25, edad_max = 85, lazo = "gladys" },
    { id = "l09_adu_grua_hennessey", etapa = "adultez", texto = "Una noche del 92 se me murio el auto en la Preston Highway de Louisville y me remolco un muchacho de Hennessey's. Era de West Point y no me quiso cobrar los kilometros.", edad_min = 20, edad_max = 85, lazo = "eduardo" },
    { id = "l09_adu_jurado_concurso", etapa = "adultez", texto = "En abril del 93 fui de jurado del concurso de matematicas del condado, en el gimnasio de Muldraugh. Gano un nino de Riverside, pecoso, con los lentes pegados con cinta.", da = {"secundaria"}, edad_min = 30, edad_max = 85, lazo = "wade_bell" },
    { id = "l09_adu_liga_reja", etapa = "adultez", texto = "Entrene a la liga infantil de {pueblo} varias temporadas. Le grite a mi propio {hijo} desde la reja mas de lo que me gusta acordarme.", da = {"con_hijos", "culpa"}, edad_min = 30, edad_max = 60 },
    { id = "l09_adu_pan_hollis", etapa = "adultez", texto = "Muchos inviernos compre el pan a las seis en la panaderia Hollis de Riverside. La panadera de trenza me lo daba tibio y nunca me cobro el que se quemaba.", edad_min = 30, edad_max = 85, pueblos = {"Riverside"}, lazo = "yvonne_bell" },
    { id = "l09_adu_seguro_bell", etapa = "adultez", texto = "Un vendedor de seguros de camisa celeste paso tres veces por mi casa de la 31. A la tercera le firme, de puro cansancio, y despues me alegre.", edad_min = 30, edad_max = 85, lazo = "daniel_bell" },
    { id = "l09_adu_tonico_radio", etapa = "adultez", texto = "Por un tiempo le crei al doctor de la radio de Louisville, el del tonico. Compre seis frascos para los huesos. Era agua con fierro, pero las mananas que lo tomaba me sentia acompanad{o}.", edad_min = 40, edad_max = 85, lazo = "hartmann" },
    { id = "l09_adu_viudez", etapa = "adultez", texto = "Enviude joven. Me quede con los ninos, una cocina chica y la costumbre de poner un plato de mas que despues guardaba.", da = {"viudo", "con_hijos"}, edad_min = 30, edad_max = 85 },
    { id = "l10_adu_bencinita", etapa = "adultez", texto = "Manejaba de noche por la 31 con el canal 19 prendido. Un nino de la gasolinera de Rosewood, el Bencinita, contestaba con voz de grande.", da = {"camionero_pasado"}, edad_min = 30, edad_max = 85, lazo = "hector" },
    { id = "l10_adu_bisagra_bell", etapa = "adultez", texto = "En los ochenta un vendedor de seguros flaco, de camisa celeste, me quiso vender una poliza en el porche. Bell, se llamaba. No compre. Me arreglo la bisagra igual.", edad_min = 30, edad_max = 85, lazo = "daniel_bell" },
    { id = "l10_adu_camion_marido", etapa = "adultez", texto = "Cuando mi marido se cayo de un acoplado y quedo invalido, saque la licencia y me subi yo al camion. En las basculas me preguntaban por el.", da = {"camionero_pasado", "casado"}, edad_min = 40, edad_max = 85, sexo = "m" },
    { id = "l10_adu_canela_hollis", etapa = "adultez", texto = "Los sabados compraba rollos de canela en la panaderia Hollis de Riverside. La panadera entraba a las tres y media; a las seis olia toda la calle.", edad_min = 25, edad_max = 85, pueblos = {"Riverside"}, lazo = "yvonne_bell" },
    { id = "l10_adu_cuida_padre", etapa = "adultez", texto = "Deje un trabajo que queria para volver a {pueblo} a cuidar a mi papa enfermo. Algunas noches, dandole la sopa, deseaba lo que no se dice.", da = {"cuida_a_alguien", "culpa"}, edad_min = 28, edad_max = 60 },
    { id = "l10_adu_cuota", etapa = "adultez", texto = "Cuando a mi pareja le dieron una enfermedad larga, segui un mes mas en la ruta para cerrar la cuota. Ese mes se cayo en la cocina, sola.", da = {"casado", "culpa"}, edad_min = 35, edad_max = 85 },
    { id = "l10_adu_custodia", etapa = "adultez", texto = "Pasados los treinta perdi la custodia de mis hijos. Los domingos llamaba y me contestaban con una sola palabra.", da = {"divorciado", "con_hijos", "hijos_lejos"}, edad_min = 32, edad_max = 85 },
    { id = "l10_adu_lleno_normal", etapa = "adultez", texto = "En el 88 se murio el Hector de la gasolinera de Rosewood, llenando un camion de leche. Al otro dia la Rosa abrio igual y me pregunto: lleno o normal?", edad_min = 25, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l10_adu_nietos", etapa = "adultez", texto = "Pasados los cuarenta me toco criar a los hijos de mis hijos. La mesa es para siete y yo como de pie lo que queda.", da = {"cuida_a_alguien", "con_hijos", "familia_grande"}, edad_min = 45, edad_max = 85 },
    { id = "l10_adu_ruedo_gladys", etapa = "adultez", texto = "El traje de mi boda me lo entallo la Gladys, la de Arreglos Gladys en la calle principal de Muldraugh. Con tiza, en diez minutos, y no me dejo pagar el ruedo.", da = {"casado"}, edad_min = 25, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "gladys" },
    { id = "l01_vej_baston", etapa = "vejez", texto = "Me cai en la escalera del porche y desde entonces ando con baston. El doctor dijo cadera; yo digo mala suerte y tablas podridas.", da = {"cojo", "viejo_fragil"}, quita = {"fuerte", "atleta"}, edad_min = 65, edad_max = 85 },
    { id = "l01_vej_catarata", etapa = "vejez", texto = "Me operaron una catarata y la otra la deje para despues. Despues nunca llego. Ahora enhebro con lupa y leo con la luz de la ventana.", da = {"vista_mala", "viejo_fragil"}, edad_min = 65, edad_max = 85 },
    { id = "l01_vej_chimenea_chela", etapa = "vejez", texto = "Cuando se me prendio la chimenea, la Chela llego con la manguera antes que los hombres del cuartel y me reto por prender el fuego con diario mojado.", edad_min = 60, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l01_vej_lado_cama", etapa = "vejez", texto = "Enterre a mi pareja de toda la vida y deje su lado de la cama tal cual un mes entero, de pura terquedad. Despues lo hice. Despues no.", da = {"viudo", "solitario"}, quita = {"casado"}, edad_min = 60, edad_max = 85 },
    { id = "l01_vej_no_duermo", etapa = "vejez", texto = "Me jubile despues de una vida de turno de noche y ahora no se dormir. Hago porches y alacenas para no pensar en las tres de la manana.", pide = {"trabajo_nocturno"}, edad_min = 60, edad_max = 85 },
    { id = "l01_vej_pasaporte", etapa = "vejez", texto = "A los setenta y tantos saque pasaporte por primera vez para ir a ver el pueblo de mis padres. Lo tengo en un cajon, sin un solo timbre.", pide = {"inmigrante"}, edad_min = 72, edad_max = 85 },
    { id = "l02_vej_cadera", etapa = "vejez", texto = "Me cambiaron la cadera hace poco y uso de baston lo que tenga a mano: un paraguas, una luma, un palo de escoba.", da = {"cojo", "viejo_fragil"}, edad_min = 66, edad_max = 85 },
    { id = "l02_vej_campanas", etapa = "vejez", texto = "Los domingos voy a la iglesia de piedra de Riverside y me siento atras. Cuando se rajo la viga del campanario en el 91 fue como quedarme sord{o}.", da = {"religioso", "catolico"}, edad_min = 60, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l02_vej_catarata", etapa = "vejez", texto = "Me operaron la catarata de un ojo en Louisville; el otro lo deje para cuando hubiera plata. Nunca hubo.", da = {"vista_mala"}, edad_min = 62, edad_max = 85 },
    { id = "l02_vej_cb", etapa = "vejez", texto = "Mis nietos me regalaron una radio CB para que no estuviera sol{o}. De noche oia al Gordo Ruta contar chistes malos por el canal 19.", da = {"radio_cb", "solitario"}, edad_min = 60, edad_max = 85, lazo = "earl" },
    { id = "l02_vej_escolta", etapa = "vejez", texto = "Ya no manejo de noche. La ultima vez el Cabo me paro por ir a treinta por la 31 y me escolto hasta la casa con la baliza prendida.", da = {"vista_mala"}, edad_min = 65, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l02_vej_jubilacion", etapa = "vejez", texto = "Me jubilaron con un reloj chapado y una torta seca. Al mes me levantaba a la misma hora sin tener adonde ir.", edad_min = 60, edad_max = 85 },
    { id = "l03_vej_corazon", etapa = "vejez", texto = "El corazon me avisa con un dolor en el brazo izquierdo. Tengo pastillas para debajo de la lengua y una silla en cada pieza de la casa.", da = {"corazon", "viejo_fragil"}, prohibe = {"atleta"}, edad_min = 60, edad_max = 85 },
    { id = "l03_vej_jubilado_porche", etapa = "vejez", texto = "Me jubile y descubri que no sabia estar sentad{o}. Arreglaba lo que no estaba roto para tener algo en las manos.", edad_min = 62, edad_max = 85 },
    { id = "l03_vej_mesa_once", etapa = "vejez", texto = "Desde que volvio el cura nuevo a Riverside voy a la misa de las once. Nos hace reir con sus manos de boxeador y deja la puerta abierta.", da = {"religioso", "catolico"}, prohibe = {"sin_fe"}, edad_min = 60, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l03_vej_nietos", etapa = "vejez", texto = "Crie a dos nietos cuando su madre se fue a Florida. A los sesenta y tantos volvi a las tareas de la escuela y a los piojos.", da = {"cuida_a_alguien", "cuida_ninos"}, pide = {"con_hijos"}, edad_min = 60, edad_max = 80 },
    { id = "l03_vej_tonico_radio", etapa = "vejez", texto = "Compraba por correo el tonico del doctor de la radio, el de la hora de la salud en la AM de Louisville. Era agua con fierro, pero me sentia mejor igual.", da = {"viejo_fragil"}, edad_min = 60, edad_max = 85, lazo = "hartmann" },
    { id = "l03_vej_viuda_sola", etapa = "vejez", texto = "Enterre a mi marido, a mis hermanos y a casi todas mis amigas. Ahora los domingos converso con las lapidas y les cuento quien se caso.", da = {"viudo", "vive_solo"}, edad_min = 68, edad_max = 85, sexo = "m" },
    { id = "l04_vej_corazon", etapa = "vejez", texto = "El corazon me avisa con un pinchazo en el brazo izquierdo. Tengo las pastillas en el bolsillo de la camisa y una regla: no subir escaleras con rabia.", da = {"corazon", "viejo_fragil"}, prohibe = {"atleta"}, edad_min = 60, edad_max = 85 },
    { id = "l04_vej_jubilado_fuerte", etapa = "vejez", texto = "Me jubile del Fuerte con un reloj de regalo que no anda y una pension que tampoco. Ahora me siento en el porche a mirar pasar los camiones de la 31 y a adivinar que llevan.", da = {"fort_knox", "viejo_fragil"}, edad_min = 62, edad_max = 85 },
    { id = "l04_vej_lleno_normal", etapa = "vejez", texto = "Ya no manejo, pero sigo yendo a la bomba de Rosewood por un cafe. La duena me pregunta lleno o normal y yo le digo normal, como si todavia tuviera tanque.", da = {"viejo_fragil"}, edad_min = 65, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l04_vej_misa_once", etapa = "vejez", texto = "Ya no tengo iglesia propia, asi que voy a la misa de las once del Padre de Riverside, en la ultima banca. No me arrodillo, que las rodillas no vuelven. El cura no me dice nada; me deja ser.", da = {"religioso"}, edad_min = 60, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l04_vej_nietos_lejos", etapa = "vejez", texto = "Tengo nietos en Ohio que me conocen por fotos. Me llaman para los cumpleanos y yo les cuento lo mismo cada vez. Ellos se rien en el mismo lugar, como si fuera nuevo.", da = {"hijos_lejos", "con_hijos"}, edad_min = 60, edad_max = 85 },
    { id = "l05_vej_catarata", etapa = "vejez", texto = "Me operaron una catarata en Louisville. Ahora apunto con ese ojo y el otro lo guardo para mirar el rio.", da = {"vista_mala"}, edad_min = 60, edad_max = 85 },
    { id = "l05_vej_cocina_clases", etapa = "vejez", texto = "Me jubile y segui ensenando gratis en la mesa de la cocina. Los chicos del barrio venian por el algebra y se quedaban por el pie.", edad_min = 60, edad_max = 85 },
    { id = "l05_vej_esperar", etapa = "vejez", texto = "Las rodillas ya no me dan para el bosque grande. Aprendi a esperar sentad{o}, que es la mitad de cazar y la mitad de vivir.", da = {"viejo_fragil"}, quita = {"atleta"}, edad_min = 65, edad_max = 85 },
    { id = "l05_vej_mesa_dos", etapa = "vejez", texto = "Desde que enviude sigo poniendo la mesa para dos los domingos. Nadie me lo ha preguntado y no pienso explicarlo.", da = {"viudo"}, quita = {"casado"}, edad_min = 60, edad_max = 85 },
    { id = "l05_vej_temblor", etapa = "vejez", texto = "Desde los sesenta y tantos me tiemblan las manos. Trabajo con la muneca apoyada en un saquito de arena y digo que es por el frio.", da = {"viejo_fragil", "lesion_mano"}, edad_min = 60, edad_max = 85 },
    { id = "l06_vej_campanas", etapa = "vejez", texto = "De viej{o} lo que mas extrano son las campanas de la iglesia de piedra de Riverside. Desde que se rajo la viga, en el 91, los domingos suenan a nada.", edad_min = 60, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l06_vej_dayton", etapa = "vejez", texto = "Mi familia se fue a trabajar a Dayton y llama para Navidad. A los nietos los conozco por una foto en el refrigerador.", da = {"hijos_lejos"}, edad_min = 60, edad_max = 85 },
    { id = "l06_vej_medias", etapa = "vejez", texto = "Me jubile a los sesenta y cinco, pero a medias: sigo haciendo trabajitos por un pie o una docena de huevos.", edad_min = 66, edad_max = 85 },
    { id = "l06_vej_perros", etapa = "vejez", texto = "Desde que me quede sol{o} recojo los perros que botan en la curva del camino. Les pongo nombres de presidentes. Tengo a Truman, a Ike y a una perra Lady Bird.", da = {"solitario"}, edad_min = 60, edad_max = 85 },
    { id = "l06_vej_postpolio", etapa = "vejez", texto = "De viej{o} la polio volvio a cobrar: la pierna buena se cansa y a media tarde tengo que sentarme donde este.", da = {"viejo_fragil"}, pide = {"cojo"}, edad_min = 60, edad_max = 85 },
    { id = "l06_vej_tonico", etapa = "vejez", texto = "Me pase las tardes oyendo la Hora de la Salud en la AM de Louisville. Compre dos frascos del tonico del doctor de la radio. Sabian a clavo oxidado.", edad_min = 60, edad_max = 85, lazo = "hartmann" },
    { id = "l07_vej_de_pie", etapa = "vejez", texto = "Desde que enviude como de pie en la cocina, porque sentarme sol{o} a la mesa me parece una falta de respeto con el otro plato.", da = {"viudo", "solitario"}, prohibe = {"casado"}, edad_min = 60, edad_max = 85 },
    { id = "l07_vej_labios", etapa = "vejez", texto = "A mi edad todavia me pinto los labios para abrir la puerta, aunque sea al cartero. La vanidad es lo ultimo que se pierde, y yo no la pienso perder.", edad_min = 65, edad_max = 85, sexo = "m" },
    { id = "l07_vej_mocion", etapa = "vejez", texto = "Ya con canas presente en mi club una mocion para que entraran mujeres. Perdi por paliza y me fui a mi casa a cambiar un aceite.", pide_alguno = {"logia"}, edad_min = 60, edad_max = 85, sexo = "h" },
    { id = "l07_vej_otter", etapa = "vejez", texto = "En la vejez me dio por pescar en Otter Creek. Mas de una manana vi al cabo de la comisaria sacar un bagre, mirarlo serio y soltarlo.", edad_min = 60, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l07_vej_pulso", etapa = "vejez", texto = "Me jubile, pero sigo poniendo inyecciones y puntos en mi cocina. El pulso me tiembla en todas partes menos con la aguja.", pide = {"oficio_aprendido"}, edad_min = 60, edad_max = 85 },
    { id = "l07_vej_rosa", etapa = "vejez", texto = "Desde que me jubile paso las tardes en la gasolinera de Rosewood. La Misia Rosa me fia el cafe recalentado y me pregunta lleno o normal aunque llegue a pie.", edad_min = 60, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l08_vej_cataratas", etapa = "vejez", texto = "Ya no manejo. Las cataratas me pusieron neblina en los dos ojos y no me quiero operar a esta altura. Camino a todas partes, despacio y por el medio de la calle.", da = {"vista_mala", "viejo_fragil"}, edad_min = 68, edad_max = 85 },
    { id = "l08_vej_huesos_tiza", etapa = "vejez", texto = "Los huesos se me volvieron de tiza: me quebre la muneca agachandome a un balde. Ahora me agacho por partes y le pido permiso a cada rodilla.", da = {"viejo_fragil"}, prohibe = {"fuerte"}, edad_min = 70, edad_max = 85 },
    { id = "l08_vej_lleno_normal", etapa = "vejez", texto = "Cada sabado voy a la gasolinera de los Bencina aunque ya no tenga auto. La Misia Rosa me pregunta lleno o normal, yo le digo normal, y me sirve cafe recalentado.", edad_min = 60, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l08_vej_porche", etapa = "vejez", texto = "Desde que me jubile, los vecinos me traen de todo al porche: una radio, un cierre, una pena. Les cobro en tomates y en chismes.", da = {"bromista"}, edad_min = 62, edad_max = 85 },
    { id = "l08_vej_radio_cena", etapa = "vejez", texto = "Desde que enviude ceno con la radio de Louisville prendida, para oir otra voz en la cocina. Le contesto al locutor del tiempo cuando se equivoca.", da = {"viudo", "solitario"}, edad_min = 62, edad_max = 85 },
    { id = "l08_vej_tres_millas", etapa = "vejez", texto = "Sigo caminando tres millas al dia. Mis hijos dicen que me voy a caer. Yo les digo que el dia que me siente no me paro mas.", prohibe = {"viejo_fragil", "cojo"}, edad_min = 60, edad_max = 80 },
    { id = "l09_vej_cruce_escuela", etapa = "vejez", texto = "Ya viej{o}, hago el cruce de la escuela de {pueblo} con un pito y una placa vieja. Los ninos me obedecen; los grandes, no tanto.", da = {"cuida_ninos"}, edad_min = 65, edad_max = 85 },
    { id = "l09_vej_iglesia_abierta", etapa = "vejez", texto = "De viej{o} ya casi no duermo. Hay noches que camino hasta la iglesia de piedra solo porque el Padre deja la puerta abierta.", edad_min = 60, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l09_vej_jubilado_fabrica", etapa = "vejez", texto = "Me jubile despues de cuarenta inviernos de fabrica y volvi al campo de mi padre. Lo que habia olvidado de las vacas lo aprendi otra vez, a golpes.", da = {"granja"}, pide = {"fabrica"}, edad_min = 60, edad_max = 85 },
    { id = "l09_vej_madrugadas_rosewood", etapa = "vejez", texto = "De viej{o} me hice amig{o} de las madrugadas en la gasolinera de Rosewood. A las tres llegaba un camionero gordo con chistes malos y yo le contaba los mios.", edad_min = 60, edad_max = 85, lazo = "earl" },
    { id = "l09_vej_nevazon", etapa = "vejez", texto = "En la nevazon del 77 quede atrapad{o} en la 31 con doce camioneros. La senora de la gasolinera de Rosewood nos frio huevos a todos y no nos cobro ni uno.", edad_min = 60, edad_max = 85, lazo = "rosa" },
    { id = "l09_vej_tallar", etapa = "vejez", texto = "Desde que enviude hablo menos. Le digo las cosas a la madera en vez de decirlas, y la madera no me apura.", da = {"viudo", "solitario"}, edad_min = 60, edad_max = 85 },
    { id = "l10_vej_boleto", etapa = "vejez", texto = "Tenia todo listo para jubilarme el proximo verano e irme a conocer a mis nietos de cerca. El boleto estaba guardado dentro de un libro.", da = {"hijos_lejos", "con_hijos"}, edad_min = 60, edad_max = 70 },
    { id = "l10_vej_cajon", etapa = "vejez", texto = "A los setenta me hice mi propio cajon, de nogal. Lo uso de meson para los tarros de clavos hasta que sirva para lo otro.", da = {"viejo_fragil"}, edad_min = 70, edad_max = 85 },
    { id = "l10_vej_catarata", etapa = "vejez", texto = "Me operaron la catarata de un ojo y el otro lo deje para despues. Ahora enhebro de memoria.", da = {"vista_mala"}, edad_min = 65, edad_max = 85 },
    { id = "l10_vej_corazon", etapa = "vejez", texto = "El doctor me dio pastillas para el corazon y las tomo, aunque toda la vida cure con hierbas. El corazon no es cosa de hierbas.", da = {"corazon"}, edad_min = 60, edad_max = 85 },
    { id = "l10_vej_misa_once", etapa = "vejez", texto = "Ya de mayor, iba a la misa de las once del cura boxeador de Riverside. Llegaba tarde y el decia: lo que importa es que llegaste.", da = {"catolico", "religioso"}, edad_min = 60, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l10_vej_tijera_tumba", etapa = "vejez", texto = "Desde que enviude corto con tijera de podar el pasto de la tumba, todos los sabados. El cementerio de {pueblo} me conoce el paso.", da = {"viudo", "nunca_salio"}, edad_min = 60, edad_max = 85 },
    { id = "l01_ofi_camionero_luz", etapa = "oficio", texto = "Soy {oficio}. De noche, en la 31, la unica luz segura era la gasolinera de Rosewood. La Misia Rosa me preguntaba lleno o normal aunque llegara a pie.", da = {"camionero_pasado"}, edad_min = 25, edad_max = 75, oficios = {"camionero"}, lazo = "rosa" },
    { id = "l01_ofi_camionero_tecolote", etapa = "oficio", texto = "Soy {oficio} de la 31W, de Louisville a Nashville. Los Marlboro baratos se los compraba en un estacionamiento a un tal Tito, que en la radio se hacia llamar Tecolote.", da = {"camionero_pasado"}, edad_min = 25, edad_max = 75, oficios = {"camionero"}, lazo = "duarte" },
    { id = "l01_ofi_carpintero", etapa = "oficio", texto = "Soy {oficio}: porches, alacenas, bancas de iglesia y marcos de puerta. Aprendi con mi padre y con un sargento que me pegaba con la escuadra.", da = {"oficio_aprendido"}, edad_min = 30, edad_max = 85, oficios = {"carpintero"} },
    { id = "l01_ofi_cazador_trampas", etapa = "oficio", texto = "Soy {oficio}: trampas en invierno, ratas almizcleras, mapaches, castores en los tranques de las granjas. Las pieles ya no valen nada, pero el monte da.", da = {"rural"}, prohibe = {"urbano"}, edad_min = 20, edad_max = 75, oficios = {"cazador"} },
    { id = "l01_ofi_cocina_desayunos", etapa = "oficio", texto = "Soy {oficio} de desayunos: huevos, gravy de salchicha, bologna frita. Entraba a las cinco y a las once ya le habia dado de comer a medio pueblo.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 80, oficios = {"cocinera"} },
    { id = "l01_ofi_cocina_tropa", etapa = "oficio", texto = "Soy {oficio}. Aprendi en la cocina de tropa del Fuerte con un sargento de Chihuahua que le ponia chile colorado a todo. Despues supe que era el papa del Cabo.", da = {"fort_knox", "oficio_aprendido"}, edad_min = 47, edad_max = 80, oficios = {"cocinera"}, lazo = "cabo" },
    { id = "l01_ofi_costurera_rio", etapa = "oficio", texto = "Soy {oficio} de rio: lonas de bote, toldos, redes rotas y waders con hoyo. Las puntadas, por lo menos, no preguntan.", da = {"rio", "oficio_aprendido"}, edad_min = 30, edad_max = 85, oficios = {"costurera"}, pueblos = {"West Point", "Riverside"} },
    { id = "l01_ofi_electricista", etapa = "oficio", texto = "Soy {oficio}: galpones de tabaco, ventiladores, la luz de la cancha de la liga infantil. Aprendi en un curso del condado y con los dedos quemados.", da = {"oficio_aprendido"}, edad_min = 20, edad_max = 70, oficios = {"electricista"} },
    { id = "l01_ofi_enfermera_cocina", etapa = "oficio", texto = "Fui {oficio} de hospital y ahora curo en la mesa de mi cocina: rodillas, anzuelos, astillas. Inyecciones no. Para eso estaba el boticario.", da = {"oficio_aprendido"}, edad_min = 50, edad_max = 85, oficios = {"enfermera"} },
    { id = "l01_ofi_enfermera_joven", etapa = "oficio", texto = "Soy {oficio} de un hogar de ancianos. Se tomar la presion con los ojos cerrados y cambiar una sabana sin despertar a nadie.", da = {"oficio_aprendido"}, edad_min = 20, edad_max = 49, oficios = {"enfermera"} },
    { id = "l01_ofi_granjero_tabaco", etapa = "oficio", texto = "Soy {oficio}: tabaco, maiz y tres vacas que no me quieren. La tierra es arrendada; el sudor y las deudas son mios.", da = {"granja", "rural"}, edad_min = 25, edad_max = 85, oficios = {"granjero"} },
    { id = "l01_ofi_mecanico_31w", etapa = "oficio", texto = "Soy {oficio} de un taller de la 31W. Aprendi con manuales Chilton y con un viejo que alineaba a ojo. Si un motor suena raro, yo se de donde suena.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 70, oficios = {"mecanico"} },
    { id = "l01_ofi_mecanico_ekron", etapa = "oficio", texto = "Soy {oficio}. Los fines de semana ayudaba en la vulcanizacion de Ekron con el Bencinita, el sobrino de la Misia Rosa: el parchaba y yo desarmaba.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 40, oficios = {"mecanico"}, pueblos = {"Rosewood"}, lazo = "hector" },
    { id = "l01_ofi_pastora_escuela", etapa = "oficio", texto = "Soy {oficio} de mi iglesia: hago la escuela dominical, le enseno a leer la Biblia a los ninos y predico cuando el pastor no puede.", da = {"religioso", "iglesia_trabajo"}, prohibe = {"sin_fe"}, edad_min = 18, edad_max = 85, oficios = {"pastora"} },
    { id = "l01_ofi_pastora_once", etapa = "oficio", texto = "Soy {oficio} en la iglesia de piedra de Riverside: ayudo al Padre en la misa de las once y le enseno el catecismo a los ninos de la primera fila.", da = {"catolico", "iglesia_trabajo", "religioso"}, prohibe = {"santidad", "bautista", "sin_fe"}, edad_min = 18, edad_max = 85, oficios = {"pastora"}, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l01_ofi_policia_auxiliar", etapa = "oficio", texto = "Soy {oficio} auxiliar de {pueblo}: multas, perros perdidos, papeles del juzgado y visitas a los viejos que viven solos. Me dieron la placa porque conozco cada casa.", da = {"policia_pasado"}, edad_min = 50, edad_max = 85, oficios = {"policia"} },
    { id = "l01_ofi_policia_cabo", etapa = "oficio", texto = "Soy {oficio}. Hice turnos al lado del Cabo Mandados de Muldraugh: nunca llego tarde a un turno y nunca lo ascendieron. Eso tambien se aprende.", da = {"policia_pasado"}, edad_min = 25, edad_max = 60, oficios = {"policia"}, lazo = "cabo" },
    { id = "l01_ofi_profe_calculadora", etapa = "oficio", texto = "Soy {oficio} de la escuela de Riverside. Tuve en sexto a un nino de los Bell que contaba todo, las baldosas, los segundos, y le decian calculadora.", da = {"universidad"}, edad_min = 25, edad_max = 70, oficios = {"profesora"}, pueblos = {"Riverside"}, lazo = "wade_bell" },
    { id = "l01_ofi_profe_muldraugh", etapa = "oficio", texto = "Soy {oficio} de la secundaria de {pueblo}. Le ensene a leer poemas a muchachos que solo querian entrar al Fuerte, y a algunos se les pego.", da = {"universidad"}, edad_min = 25, edad_max = 85, oficios = {"profesora"} },
    { id = "l02_ofi_camionero", etapa = "oficio", texto = "Manejo camion por la 31 desde joven. En la gasolinera de Rosewood la Misia Rosa me preguntaba lleno o normal aunque solo parara por un cafe.", da = {"camionero_pasado"}, edad_min = 25, edad_max = 75, oficios = {"camionero"}, lazo = "rosa" },
    { id = "l02_ofi_camionero2", etapa = "oficio", texto = "Soy {oficio} de rutas cortas. Por el canal 19 le compraba los chismes al Tecolote, que sabia donde estaba cada bascula y cada patrulla.", da = {"camionero_pasado", "radio_cb"}, edad_min = 22, edad_max = 60, oficios = {"camionero"}, lazo = "duarte" },
    { id = "l02_ofi_carpintero", etapa = "oficio", texto = "Soy {oficio}: mido dos veces y corto una. Hacia repisas y cajones; ahora hago puertas que aguanten y ataudes que no se pidan.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 85, oficios = {"carpintero"} },
    { id = "l02_ofi_cazador", etapa = "oficio", texto = "Cazo venado en los bosques que rodean el Fuerte; conozco cada puesto de caza y cada cerco. Aprendi con mi abuelo y una escopeta de un tiro.", da = {"rural"}, edad_min = 18, edad_max = 80, oficios = {"cazador"} },
    { id = "l02_ofi_cocinera", etapa = "oficio", texto = "Fui {oficio} del Spiffo's de Muldraugh, al lado de un mexicano callado, el Julio, que hacia el arroz mejor que nadie. Ahora cocino con lena.", da = {"oficio_aprendido"}, edad_min = 22, edad_max = 65, oficios = {"cocinera"}, lazo = "julio" },
    { id = "l02_ofi_cocinera2", etapa = "oficio", texto = "Soy {oficio} de un grill de la calle principal: huevos, papas y cafe de olla grande. El que trae lena come.", edad_min = 30, edad_max = 85, oficios = {"cocinera"} },
    { id = "l02_ofi_constable", etapa = "oficio", texto = "En Kentucky el constable se elige. A mi me eligieron en {pueblo}: entrego citaciones, hago la trampa de velocidad y resuelvo peleas por cercas.", da = {"policia_pasado"}, edad_min = 40, edad_max = 85, oficios = {"policia"} },
    { id = "l02_ofi_costurera", etapa = "oficio", texto = "Cosi ruedos y vestidos de novia veinte temporadas. En Muldraugh la competencia era Arreglos Gladys, que entallaba hasta las camisas de la policia.", da = {"oficio_aprendido"}, edad_min = 35, edad_max = 85, oficios = {"costurera"}, lazo = "gladys" },
    { id = "l02_ofi_electricista", etapa = "oficio", texto = "Soy {oficio}; aprendi en la escuela vocacional de Elizabethtown. Ahora armo bancos de baterias con alternadores de autos muertos.", da = {"oficio_aprendido"}, edad_min = 20, edad_max = 75, oficios = {"electricista"} },
    { id = "l02_ofi_enfermera", etapa = "oficio", texto = "Soy {oficio} del turno de noche. Aprendi en Elizabethtown y en las camillas del hospital del Fuerte; tomo el pulso antes de saludar.", da = {"fort_knox", "oficio_aprendido"}, edad_min = 22, edad_max = 70, oficios = {"enfermera"} },
    { id = "l02_ofi_granjero", etapa = "oficio", texto = "Tengo unos acres de burley y unas vacas. La cuota de tabaco es lo unico que el banco no me pudo quitar.", da = {"tabaco", "granja", "rural"}, edad_min = 18, edad_max = 85, oficios = {"granjero"} },
    { id = "l02_ofi_mecanico", etapa = "oficio", texto = "Soy {oficio}. Trabaje un tiempo en el taller del Martillo Duggan en Riverside; ahi aprendi motores y a no preguntar de donde venian los autos.", da = {"oficio_aprendido"}, edad_min = 22, edad_max = 60, oficios = {"mecanico"}, lazo = "duggan" },
    { id = "l02_ofi_mecanico2", etapa = "oficio", texto = "Arreglo lo que tenga motor en un galpon de la 31W. Aprendi mirando, con las manos llenas de grasa ajena.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 80, oficios = {"mecanico"} },
    { id = "l02_ofi_pastora", etapa = "oficio", texto = "Soy {oficio} de una capilla chica. No soy como los predicadores de carpa de la 31 que cobran por imponer las manos; aqui la cena del Senor es gratis.", da = {"religioso", "iglesia_trabajo"}, edad_min = 25, edad_max = 85, oficios = {"pastora"}, lazo = "reyes" },
    { id = "l02_ofi_pastora2", etapa = "oficio", texto = "Soy {oficio}, pero ahora mas que predicar enseno a leer a los ninos con la Biblia. Ellos leen, yo escucho, y Dios corrige.", da = {"religioso", "iglesia_trabajo"}, edad_min = 30, edad_max = 85, oficios = {"pastora"} },
    { id = "l02_ofi_policia", etapa = "oficio", texto = "Soy {oficio}. Hice la academia de Richmond, igual que el Cabo de Muldraugh, pero muchas promociones despues. Dirijo funerales, entrego citaciones y ahora reparto el agua.", da = {"policia_pasado", "oficio_aprendido"}, edad_min = 22, edad_max = 45, oficios = {"policia"}, lazo = "cabo" },
    { id = "l02_ofi_profesora", etapa = "oficio", texto = "Fui {oficio} de la escuela de Riverside. El hijo de los Bell, el que cuenta todo, me corregia las cuentas en sexto y tenia razon.", da = {"secundaria"}, edad_min = 25, edad_max = 70, oficios = {"profesora"}, pueblos = {"Riverside"}, lazo = "wade_bell" },
    { id = "l02_ofi_profesora2", etapa = "oficio", texto = "Soy {oficio} de secundaria. A los chicos les enseno la tabla, la ortografia y a no copiar; ahora doy clases con una puerta pintada de pizarra.", da = {"secundaria"}, edad_min = 24, edad_max = 80, oficios = {"profesora"} },
    { id = "l03_ofi_camionero_bencinita", etapa = "oficio", texto = "Manejo camion por la 31 desde joven. De noche, por el canal 19, contestaba el Bencinita desde la gasolinera de Rosewood: lleno o normal.", da = {"camionero_pasado", "oficio_aprendido"}, edad_min = 25, edad_max = 85, oficios = {"camionero"}, lazo = "hector" },
    { id = "l03_ofi_carpintero_bisagra", etapa = "oficio", texto = "Soy carpintero desde los quince. Porches, gabinetes, cajones de muerto. La madera avisa antes de romperse; la gente no.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 85, oficios = {"carpintero"} },
    { id = "l03_ofi_cazador_cueros", etapa = "oficio", texto = "Cazo desde los ocho: ardilla, conejo, venado. Vendo cueros en Brandenburg y carne ahumada a quien tenga con que pagar.", da = {"oficio_aprendido", "rural"}, prohibe = {"urbano"}, edad_min = 18, edad_max = 85, oficios = {"cazador"} },
    { id = "l03_ofi_cocinera_spiffos", etapa = "oficio", texto = "Cocine en el Spiffo's de Muldraugh con un mexicano callado que freia hamburguesas sin mirarlas. Yo hacia los pies; el, todo lo demas.", da = {"oficio_aprendido"}, edad_min = 20, edad_max = 60, oficios = {"cocinera"}, pueblos = {"Muldraugh"}, lazo = "julio" },
    { id = "l03_ofi_costurera_singer", etapa = "oficio", texto = "Coso con una Singer de pedal que era de mi madre. Ruedos, cierres, vestidos de novia. Le mido el brazo a la gente con la vista.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 85, oficios = {"costurera"} },
    { id = "l03_ofi_electricista_cuadrilla", etapa = "oficio", texto = "Fui liniero de la cooperativa, colgado de los postes en las tormentas de hielo. Ahora hago casas: enchufes, tableros, la bomba del pozo.", da = {"oficio_aprendido"}, edad_min = 28, edad_max = 85, oficios = {"electricista"} },
    { id = "l03_ofi_enfermera_titulo", etapa = "oficio", texto = "Saque el titulo de enfermera en Elizabethtown. Me daba rabia oir en la AM al doctor del tonico vendiendo agua con fierro a mis pacientes.", da = {"oficio_aprendido"}, edad_min = 24, edad_max = 85, oficios = {"enfermera"}, lazo = "hartmann" },
    { id = "l03_ofi_granjero_hollis", etapa = "oficio", texto = "Tengo una granja chica: maiz, gallinas, tres vacas. Le vendia los huevos a la panaderia de Walt Hollis, en Riverside, a las cuatro de la manana.", da = {"granja", "rural"}, edad_min = 18, edad_max = 85, oficios = {"granjero"}, pueblos = {"Riverside", "Rosewood"}, lazo = "yvonne_bell" },
    { id = "l03_ofi_mecanico_joven", etapa = "oficio", texto = "Soy {oficio} de taller chico. Desarmo un motor con los ojos cerrados y lo armo con los ojos abiertos, que es mas dificil.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 40, oficios = {"mecanico"} },
    { id = "l03_ofi_mecanico_lucille", etapa = "oficio", texto = "Aprendi la mecanica con mi tio, debajo de los camiones de la 31. Mas de una vez le cambie el aceite al Peterbilt de Earl, el Gordo, que pagaba con chistes y a veces con plata.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 85, oficios = {"mecanico"}, lazo = "earl" },
    { id = "l03_ofi_pastora_catecismo", etapa = "oficio", texto = "Ensenaba el catecismo los domingos en la iglesia de piedra de Riverside. El Padre me paso unas llaves que nunca hicieron falta: la puerta esta siempre abierta.", da = {"iglesia_trabajo", "religioso", "catolico"}, prohibe = {"sin_fe"}, edad_min = 18, edad_max = 85, oficios = {"pastora"}, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l03_ofi_policia_richmond", etapa = "oficio", texto = "Hice la academia de policia en Richmond. En Knox hay mas perros sueltos que ladrones, y mas papeles que perros.", da = {"oficio_aprendido", "policia_pasado"}, prohibe = {"preso_pasado"}, edad_min = 22, edad_max = 85, oficios = {"policia"} },
    { id = "l03_ofi_profesora_crescent", etapa = "oficio", texto = "Estudie Educacion en la Universidad de Louisville, en el mismo curso que la hija del Cabo de Muldraugh. Ella se quedo en la ciudad; yo volvi a ensenar a {pueblo}.", da = {"universidad", "oficio_aprendido"}, prohibe = {"sin_estudios"}, edad_min = 22, edad_max = 29, oficios = {"profesora"}, lazo = "valentina" },
    { id = "l04_ofi_camionero_19", etapa = "oficio", texto = "Soy {oficio}, de la 31 y la I-65. Tengo una CB con antena de dos metros. En el canal 19 contestaba un nino de la bomba de Rosewood, el Bencinita, que se sabia todas las patentes.", da = {"oficio_aprendido", "camionero_pasado"}, edad_min = 30, edad_max = 85, oficios = {"camionero"}, lazo = "hector" },
    { id = "l04_ofi_carpintero_nogal", etapa = "oficio", texto = "Soy {oficio}. Lo aprendi de un viejo que media dos veces y cortaba una, y que golpeaba la madera con los nudillos para saber si estaba viva. Hago porches, cocinas y, cuando toca, cajones.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 85, oficios = {"carpintero"} },
    { id = "l04_ofi_cazador_ardillas", etapa = "oficio", texto = "Soy {oficio}. Mi papa me dio una veintidos de un tiro a los siete y una regla: una bala, una ardilla, y lo que se mata se come. Ahora pongo trampas y curto pieles.", da = {"oficio_aprendido", "rural"}, edad_min = 18, edad_max = 85, oficios = {"cazador"} },
    { id = "l04_ofi_cocinera_spiffos", etapa = "oficio", texto = "Soy {oficio}. Frei papas en el Spiffo's de Muldraugh al lado de un mexicano callado que hacia el arroz mejor que nadie. Aprendi a cocinar para treinta sin que se note el apuro.", da = {"oficio_aprendido"}, edad_min = 20, edad_max = 50, oficios = {"cocinera"}, lazo = "julio" },
    { id = "l04_ofi_costurera_gladys", etapa = "oficio", texto = "Soy {oficio}. Me enseno dona Gladys, la de Arreglos Gladys en Muldraugh: el ruedo invisible, la tiza de sastre y a no botar ningun boton. Cobraba barato y rezaba rapido.", da = {"oficio_aprendido"}, edad_min = 20, edad_max = 60, oficios = {"costurera"}, lazo = "gladys" },
    { id = "l04_ofi_electricista_sindicato", etapa = "oficio", texto = "Soy {oficio}. Hice el aprendizaje del sindicato en Louisville, cuatro inviernos subiendo postes con el viento en contra. Media {pueblo} tiene cables puestos por mis manos.", da = {"oficio_aprendido", "louisville"}, edad_min = 25, edad_max = 85, oficios = {"electricista"} },
    { id = "l04_ofi_enfermera_noche", etapa = "oficio", texto = "Soy {oficio}. Hice la escuela en Louisville y treinta turnos de noche seguidos en un hogar de ancianos. Se tomar el pulso en la oscuridad y mentir con calma cuando no hay remedio.", da = {"oficio_aprendido", "universidad"}, edad_min = 24, edad_max = 85, oficios = {"enfermera"} },
    { id = "l04_ofi_granjero_burley", etapa = "oficio", texto = "Soy {oficio}: tabaco burley, maiz, unas vacas flacas. El tabaco se planta en abril, se corta en agosto y se vende en diciembre, y entre medio uno reza para que no granice.", da = {"oficio_aprendido", "granja", "tabaco"}, edad_min = 18, edad_max = 85, oficios = {"granjero"} },
    { id = "l04_ofi_mecanico_peterbilt", etapa = "oficio", texto = "Soy {oficio} desde que tengo memoria de grasa. Le cambie la caja de cambios a medio camion de la 31, incluido el Peterbilt de un camionero gordo que me pagaba con chistes y a fin de mes.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 85, oficios = {"mecanico"}, lazo = "earl" },
    { id = "l04_ofi_pastora_dominical", etapa = "oficio", texto = "Soy {oficio} de mi iglesia: llevo la escuela dominical, abro el templo, visito a los enfermos y le enseno el Salmo 23 a cualquier {nino} que se quede quieto un minuto.", da = {"oficio_aprendido", "iglesia_trabajo", "religioso"}, edad_min = 18, edad_max = 85, oficios = {"pastora"} },
    { id = "l04_ofi_policia_richmond", etapa = "oficio", texto = "Soy {oficio}. Hice la academia de Richmond, la misma del Cabo de Muldraugh, con muchachos que se planchaban hasta los calcetines. Patrulle la 31 de noche, que es donde se conoce a la gente.", da = {"oficio_aprendido", "policia_pasado"}, edad_min = 24, edad_max = 85, oficios = {"policia"}, lazo = "cabo" },
    { id = "l04_ofi_profesora_cuenta", etapa = "oficio", texto = "Soy {oficio} de la escuela de Riverside. Tuve un alumno de sexto, flaquito, con los lentes con cinta, que contaba todo: las baldosas, los pasos, mis errores en la pizarra.", da = {"oficio_aprendido", "universidad"}, edad_min = 26, edad_max = 70, oficios = {"profesora"}, pueblos = {"Riverside"}, lazo = "wade_bell" },
    { id = "l05_ofi_arriendo", etapa = "oficio", texto = "Soy {oficio} de arriendo: trabajo cuarenta acres de tabaco y soya en tierra que una vez fue mia, para un abogado que nunca la ha pisado.", da = {"tabaco", "granja"}, pide_alguno = {"perdio_todo", "deudas", "pobre"}, edad_min = 30, edad_max = 85, oficios = {"granjero"} },
    { id = "l05_ofi_aserrin", etapa = "oficio", texto = "Aprendi la carpinteria barriendo aserrin en el taller de mi padre. La aprendi de verdad cuando me despidieron y tuve que comer de ella.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 85, oficios = {"carpintero"} },
    { id = "l05_ofi_catequesis", etapa = "oficio", texto = "Hago la catequesis de los domingos. Les hablo a los ninos de frente, despacio, y les hago repetir las oraciones en voz alta hasta que les salen solas.", da = {"iglesia_trabajo", "religioso"}, edad_min = 25, edad_max = 85, oficios = {"pastora"} },
    { id = "l05_ofi_gordo_ruta", etapa = "oficio", texto = "Hice la Louisville-Nashville por la 31. El Gordo Ruta me corregia los cambios por el canal 19 y me avisaba cuando la bascula estaba abierta.", da = {"camionero_pasado"}, edad_min = 25, edad_max = 70, oficios = {"camionero"}, lazo = "earl" },
    { id = "l05_ofi_llave_templo", etapa = "oficio", texto = "La llave del templo la tengo yo desde que se murio el pastor. Llevo el coro, barro el piso y los domingos leo la palabra con mis anteojos de farmacia.", da = {"iglesia_trabajo", "religioso"}, edad_min = 35, edad_max = 85, oficios = {"pastora"} },
    { id = "l05_ofi_motores_viejos", etapa = "oficio", texto = "Arreglo lo que tenga motor. Le hablo a cada uno por su nombre, y si falta una herramienta al cerrar el taller, no me voy a la casa.", da = {"oficio_aprendido"}, edad_min = 30, edad_max = 85, oficios = {"mecanico"} },
    { id = "l05_ofi_noche_fuerte", etapa = "oficio", texto = "Hice catorce inviernos de turno de noche en el hospital del Fuerte. Aprendi que la calma se actua, y que si la actuas bien, los heridos respiran contigo.", da = {"fort_knox", "oficio_aprendido"}, edad_min = 30, edad_max = 70, oficios = {"enfermera"} },
    { id = "l05_ofi_partes", etapa = "oficio", texto = "Entre a la policia porque nadie mas postulo. Escribo los partes a mano, con letra de escuela, y nunca he sacado el revolver de la funda.", da = {"policia_pasado"}, edad_min = 28, edad_max = 70, oficios = {"policia"} },
    { id = "l05_ofi_pendulos", etapa = "oficio", texto = "Ensene fisica treinta inviernos en la secundaria. Explicaba con pendulos y engranajes; los alumnos se olvidaban las formulas pero no el ruido de un reloj abierto.", da = {"universidad"}, edad_min = 55, edad_max = 85, oficios = {"profesora"} },
    { id = "l05_ofi_plancha_pie", etapa = "oficio", texto = "Cocino de pie en la plancha de un diner, con el baston colgado de la barra. La plancha es como manejar de noche: si te distraes, te quemas.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 60, oficios = {"cocinera"} },
    { id = "l05_ofi_por_patas", etapa = "oficio", texto = "Cazo ardillas en agosto y venados en noviembre, y reparto la carne por patas. Me ensenaron a matar limpio antes que a leer.", edad_min = 18, edad_max = 85, oficios = {"cazador"} },
    { id = "l05_ofi_postes", etapa = "oficio", texto = "Aprendi electricidad en un curso de un invierno en Louisville y el resto subiendo a los postes detras de un electricista viejo que no me dejaba hablar.", da = {"oficio_aprendido"}, edad_min = 20, edad_max = 70, oficios = {"electricista"} },
    { id = "l05_ofi_ruedos", etapa = "oficio", texto = "Coso ruedos y parches para soldados del Fuerte en la mesa de la cocina. Antes cosia mantas para caballos, que tienen que calzar como un guante.", da = {"fort_knox", "oficio_aprendido"}, edad_min = 25, edad_max = 85, oficios = {"costurera"} },
    { id = "l05_ofi_spiffos", etapa = "oficio", texto = "Fui ayudante en la cocina del Spiffo's de Muldraugh, al lado de un mexicano callado que hacia el arroz para todos y cantaba bajito.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 50, oficios = {"cocinera"}, pueblos = {"Muldraugh"}, lazo = "julio" },
    { id = "l05_ofi_vulcanizacion", etapa = "oficio", texto = "Soy {oficio} de manos negras. Parchaba neumaticos los fines de semana en la vulcanizacion de Ekron, al lado del sobrino de los Bencina, que hablaba con camioneros por radio.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 45, oficios = {"mecanico"}, lazo = "hector" },
    { id = "l06_of_camionero", etapa = "oficio", texto = "Soy {oficio} de la 31. En el canal 19 me conocen por el apodo y nadie pregunta el resto. Con Earl y su Lucille comparti mas de una bascula.", da = {"camionero_pasado"}, edad_min = 23, edad_max = 85, oficios = {"camionero"}, lazo = "earl" },
    { id = "l06_of_carpintero", etapa = "oficio", texto = "Soy {oficio}. Mide dos veces, corta una. Hago escaleras, porches y, cuando me lo piden, cajones de pino.", da = {"oficio_aprendido"}, edad_min = 20, edad_max = 85, oficios = {"carpintero"} },
    { id = "l06_of_cazador", etapa = "oficio", texto = "Soy {oficio}. Cazo temprano y sol{o}. En el monte nadie me ve antes de que yo lo vea a el.", pide_alguno = {"tirador", "rural", "montana"}, edad_min = 18, edad_max = 85, oficios = {"cazador"} },
    { id = "l06_of_cocinera", etapa = "oficio", texto = "Soy {oficio}. Lo primero que sale de la olla lo boto: el primer panqueque, el primer chorro de cafe. Mania vieja, de la familia.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 85, oficios = {"cocinera"} },
    { id = "l06_of_costurera", etapa = "oficio", texto = "Soy {oficio}. Aprendi con la senora Gladys en Muldraugh, que te daba con la tiza de sastre en los nudillos si cosias chueco.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 55, oficios = {"costurera"}, lazo = "gladys" },
    { id = "l06_of_electricista", etapa = "oficio", texto = "Soy {oficio}. La linea nunca esta muerta: toco cada cable con el dorso de la mano, por si acaso. Si te agarra, la mano se cierra para afuera.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 85, oficios = {"electricista"} },
    { id = "l06_of_enfermera", etapa = "oficio", texto = "Soy {oficio} titulada. Curo quemaduras con miel y gasa, como se hacia en el campo, y a mi no me tiembla la aguja.", da = {"oficio_aprendido"}, edad_min = 24, edad_max = 85, oficios = {"enfermera"} },
    { id = "l06_of_granjero", etapa = "oficio", texto = "Soy {oficio}: tabaco burley y unas vacas Hereford. Aprendi tarde, de un capataz que solo le hablaba al ganado.", da = {"granja", "tabaco"}, edad_min = 25, edad_max = 85, oficios = {"granjero"} },
    { id = "l06_of_mecanico", etapa = "oficio", texto = "Soy {oficio}: si suena, lo arreglo; si no suena, lo hago sonar. Los fines de semana parchaba neumaticos en Ekron, al lado del Bencinita.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 40, oficios = {"mecanico"}, lazo = "hector" },
    { id = "l06_of_pastora", etapa = "oficio", texto = "Soy {oficio} en mi iglesia: hago la escuela dominical, toco el organo y, cuando falta el pastor, predico yo. Dios camina al paso del mas lento.", da = {"iglesia_trabajo", "religioso"}, edad_min = 25, edad_max = 85, oficios = {"pastora"} },
    { id = "l06_of_policia", etapa = "oficio", texto = "Soy {oficio} de {pueblo}. A los borrachos del asiento de atras les canto bajito y se calman. Siempre funciona.", da = {"oficio_aprendido"}, edad_min = 21, edad_max = 65, oficios = {"policia"} },
    { id = "l06_of_policia_cabo", etapa = "oficio", texto = "Soy {oficio}. Hice turnos con la comisaria de Muldraugh: el Cabo Mandados lo anotaba todo en una libreta negra y nunca lo subieron de cabo.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 65, oficios = {"policia"}, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l06_of_profesora", etapa = "oficio", texto = "Soy {oficio} suplente en la primaria de {pueblo}. Los ninos se rien de mi letra en la pizarra, pero a fin de mes todos leen.", edad_min = 18, edad_max = 40, oficios = {"profesora"} },
    { id = "l06_of_profesora_val", etapa = "oficio", texto = "Soy {oficio}. La hija del Cabo, la que se fue a ensenar a Louisville, me dejo sus apuntes de cuarto basico. Todavia les copio los dibujos.", edad_min = 20, edad_max = 40, oficios = {"profesora"}, pueblos = {"Muldraugh"}, lazo = "valentina" },
    { id = "l07_ofi_camionero_19", etapa = "oficio", texto = "Soy {oficio}: la 31 de Louisville a Nashville me la se de memoria. En el canal 19 siempre me contestaba el Gordo Ruta, con un chiste peor que el anterior.", da = {"camionero_pasado"}, edad_min = 25, edad_max = 85, oficios = {"camionero"}, lazo = "earl" },
    { id = "l07_ofi_carpintero_guardabosques", etapa = "oficio", texto = "Soy {oficio}. Antes fui guardabosques y todavia explico a la gente con arboles: el pino miente, el nogal te avisa con la veta.", da = {"oficio_aprendido"}, edad_min = 35, edad_max = 85, oficios = {"carpintero"} },
    { id = "l07_ofi_cazador_faena", etapa = "oficio", texto = "Soy {oficio}: faeno venados en el garaje para los soldados del Fuerte y le tomo el pulso a cualquiera que me de la mano. Antes cuide viejos en un asilo.", da = {"fort_knox"}, prohibe = {"se_desmaya"}, edad_min = 25, edad_max = 60, oficios = {"cazador"} },
    { id = "l07_ofi_cocinera_himnos", etapa = "oficio", texto = "Soy {oficio} del grill de Riverside. Mido los huevos en estrofas de himno: blando dos, duro tres. A las cinco pasaba por los bollos a la panaderia de Walt Hollis.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 85, oficios = {"cocinera"}, pueblos = {"Riverside"}, lazo = "yvonne_bell" },
    { id = "l07_ofi_costurera_4h", etapa = "oficio", texto = "Soy {oficio} de {pueblo}. Aprendi en el club 4-H y coso sentad{o}. El hilo bueno se lo compraba a dona Gladys en Muldraugh, aunque eso no se lo digo a la competencia.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 85, oficios = {"costurera"}, lazo = "gladys" },
    { id = "l07_ofi_electricista_hollis", etapa = "oficio", texto = "Soy {oficio} porque hacia los trabajos de mi papa. Con el le arreglamos el horno a la panaderia Hollis de Riverside. Lo que yo queria estudiar era otra cosa.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 40, oficios = {"electricista"}, pueblos = {"Riverside"}, lazo = "hector" },
    { id = "l07_ofi_enfermera_fuerte", etapa = "oficio", texto = "Soy {oficio}: treinta temporadas en el hospital del Fuerte Knox. Desde que me jubile coso en mi cocina a los voluntarios del cuartel que se cortan.", da = {"fort_knox", "oficio_aprendido"}, edad_min = 55, edad_max = 85, oficios = {"enfermera"}, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l07_ofi_granjero", etapa = "oficio", texto = "Soy {oficio}: vacas, un tractor que arranca cuando quiere y un galpon donde mi abuelo destilaba. Lo que no se de animales lo pregunto, y lo que se lo cobro en leche.", da = {"granja", "rural"}, edad_min = 18, edad_max = 85, oficios = {"granjero"} },
    { id = "l07_ofi_mecanico_gomeria", etapa = "oficio", texto = "Soy {oficio}. Empece en la gomeria de West Point, donde trabajo el hijo de la Chela antes de irse a Louisville. El cargaba las ruedas de camion como si fueran de bicicleta.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 40, oficios = {"mecanico"}, pueblos = {"West Point"}, lazo = "eduardo" },
    { id = "l07_ofi_mecanico_vulcanizacion", etapa = "oficio", texto = "Soy {oficio}: aprendi debajo de camiones ajenos. Los fines de semana me prestaba herramientas con el Bencinita, que parchaba neumaticos en la vulcanizacion de Ekron.", da = {"oficio_aprendido"}, edad_min = 22, edad_max = 60, oficios = {"mecanico"}, lazo = "hector" },
    { id = "l07_ofi_pastora_sentada", etapa = "oficio", texto = "Soy {oficio} de una capilla chica de {pueblo}. Predico sentad{o} en un piso de cocina, porque las rodillas no me obedecen, y le enseno la Biblia a los ninos.", da = {"iglesia_trabajo", "religioso"}, edad_min = 55, edad_max = 85, oficios = {"pastora"} },
    { id = "l07_ofi_policia_tarde", etapa = "oficio", texto = "Soy {oficio} de {pueblo}. Llegue tarde al uniforme, despues de otra vida, y pase el tiro al segundo intento. Mando como en una cocina: cada cosa en su lugar.", da = {"oficio_aprendido"}, edad_min = 40, edad_max = 70, oficios = {"policia"} },
    { id = "l07_ofi_profesora_banda", etapa = "oficio", texto = "Soy {oficio} de musica. Tenia una banda de veintitantos ninos que tocaba en los partidos de los viernes y nunca se aprendio el final de una cancion.", da = {"universidad", "musico"}, edad_min = 24, edad_max = 65, oficios = {"profesora"} },
    { id = "l08_of_camionero", etapa = "oficio", texto = "Soy {oficio} de la 31: forraje para arriba, tabaco para abajo. En el canal 19 me conocen por el apodo, y al Gordo Ruta le debo mas de una bascula avisada.", da = {"camionero_pasado"}, edad_min = 21, edad_max = 85, oficios = {"camionero"}, lazo = "earl" },
    { id = "l08_of_carpintero", etapa = "oficio", texto = "Soy {oficio}. Hice la mitad de los porches de {pueblo}. Una vez le arregle la escalera a la iglesia de piedra de Riverside y el Padre me pago con cafe y una bendicion.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 85, oficios = {"carpintero"}, lazo = "nacho" },
    { id = "l08_of_cazador", etapa = "oficio", texto = "Soy {oficio} desde {nino}. Ardillas en el otono, venado en noviembre, y un sendero por el monte que no le muestro a nadie, ni a mi familia.", da = {"rural"}, edad_min = 18, edad_max = 85, oficios = {"cazador"} },
    { id = "l08_of_cocinera", etapa = "oficio", texto = "Soy {oficio} de meson: bizcochos con salsa a las seis, chili los miercoles, pie de nuez el domingo. El pan me lo traian de la panaderia Hollis, todavia tibio.", da = {"oficio_aprendido", "comerciante"}, edad_min = 25, edad_max = 85, oficios = {"cocinera"}, lazo = "yvonne_bell" },
    { id = "l08_of_costurera", etapa = "oficio", texto = "Soy {oficio}: ruedos, cierres, vestidos de novia y parches de uniforme. La senora Gladys de Muldraugh cobra mas, pero entalla mejor, eso hay que decirlo.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 85, oficios = {"costurera"}, lazo = "gladys" },
    { id = "l08_of_electricista", etapa = "oficio", texto = "Soy {oficio}. Un circuito es como el ajedrez: si lo calculas antes, no te quema. Recablee media {pueblo}; la otra media esta mal hecha y no fui yo.", da = {"oficio_aprendido"}, edad_min = 22, edad_max = 85, oficios = {"electricista"} },
    { id = "l08_of_enfermera", etapa = "oficio", texto = "Soy {oficio} de las de antes: aprendi con cofia y termometro de vidrio. Los martes tomo la presion en mi porche y nadie se va sin que le mire la lengua.", da = {"oficio_aprendido"}, edad_min = 35, edad_max = 85, oficios = {"enfermera"} },
    { id = "l08_of_granjero", etapa = "oficio", texto = "Soy {oficio} de tabaco y vacas: doce acres de burley con cuota y veinte Angus. Lo que la radio no sabe del precio del tabaco en Lexington, lo se yo.", da = {"tabaco", "granja", "rural"}, edad_min = 25, edad_max = 85, oficios = {"granjero"} },
    { id = "l08_of_mecanico_neumaticos", etapa = "oficio", texto = "Soy {oficio} de taller chico. Los neumaticos parchados se los compraba al Junior Bencina, el de la vulcanizacion de Ekron, los sabados en la tarde.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 60, oficios = {"mecanico"}, lazo = "hector" },
    { id = "l08_of_mecanico_viejo", etapa = "oficio", texto = "Soy {oficio} desde hace treinta inviernos. Le he arreglado carburadores a medio {pueblo} y todavia me acuerdo de cada motor por el ruido.", da = {"oficio_aprendido"}, edad_min = 48, edad_max = 85, oficios = {"mecanico"} },
    { id = "l08_of_pastora", etapa = "oficio", texto = "Soy {oficio} de mi capilla: enseno el catecismo a los ninos y abro la puerta los domingos. El predicador de la carpa de la salida de Riverside cobra por rezar. Yo no.", da = {"religioso", "iglesia_trabajo"}, edad_min = 18, edad_max = 85, oficios = {"pastora"}, lazo = "reyes" },
    { id = "l08_of_policia", etapa = "oficio", texto = "Soy {oficio} de pueblo chico: borrachos, vacas sueltas, viejitos perdidos. Llevo yerbas en la guantera y un revolver que casi no he sacado de la funda.", da = {"policia_pasado"}, edad_min = 30, edad_max = 85, oficios = {"policia"} },
    { id = "l08_of_policia_traslado", etapa = "oficio", texto = "Soy {oficio}. Cuando habia que llevar un preso a Muldraugh, el Cabo Mandados lo recibia en la comisaria y lo anotaba en la libreta, con tinta, nunca con lapiz.", da = {"policia_pasado"}, edad_min = 28, edad_max = 85, oficios = {"policia"}, pueblos = {"Rosewood", "West Point", "Riverside"}, lazo = "cabo" },
    { id = "l08_of_profesora", etapa = "oficio", texto = "Soy {oficio} de ciencias en la secundaria. Sapos en formol, celulas con tiza verde y una pregunta que repito cien veces al dia: me siguen?", da = {"universidad"}, pide_alguno = {"universidad", "secundaria"}, edad_min = 23, edad_max = 85, oficios = {"profesora"} },
    { id = "l09_ofi_camionero_bascula", etapa = "oficio", texto = "Llevo vacas y grano por la 31 en mi propio camion. Paro en la bascula aunque este cerrada: ni una libra de mas, que de trampas ya vi bastantes.", da = {"camionero_pasado"}, edad_min = 30, edad_max = 75, oficios = {"camionero"} },
    { id = "l09_ofi_camionero_tecolote", etapa = "oficio", texto = "Manejo la 31 desde joven. En el 19 todos conocen al Tecolote: vende chismes y cigarros sin timbre. Yo le compro los chismes, nunca los cigarros.", da = {"camionero_pasado"}, edad_min = 25, edad_max = 70, oficios = {"camionero"}, lazo = "duarte" },
    { id = "l09_ofi_carpintero_porches", etapa = "oficio", texto = "Hago porches, escaleras y marcos para medio {pueblo}. Mido dos veces, corto una y cuento tres. La madera no me apura.", da = {"oficio_aprendido"}, edad_min = 30, edad_max = 85, oficios = {"carpintero"} },
    { id = "l09_ofi_cazador_espera", etapa = "oficio", texto = "Cazo ardilla, conejo, pavo y venado en temporada. Los hombres de aqui disparan a la primera hoja que se mueve; yo espero, y por eso traigo mas.", da = {"oficio_aprendido"}, edad_min = 20, edad_max = 75, oficios = {"cazador"} },
    { id = "l09_ofi_cocinera_casino", etapa = "oficio", texto = "Aprendi a cocinar para cien en el casino del Fuerte Knox. Ahi conoci a la Chela Recabarren, que pelaba papas mas rapido que nadie y nunca se sentaba a comer.", da = {"fort_knox", "oficio_aprendido"}, edad_min = 48, edad_max = 85, oficios = {"cocinera"}, lazo = "chela" },
    { id = "l09_ofi_costurera_fuerte", etapa = "oficio", texto = "Les subo el ruedo a los soldados del Fuerte, hago vestidos de novia y colchas para la feria de Brandenburg. Cada prenda tiene su vida, y yo se la escucho.", da = {"fort_knox", "oficio_aprendido"}, edad_min = 25, edad_max = 85, oficios = {"costurera"} },
    { id = "l09_ofi_electricista_licencia", etapa = "oficio", texto = "Hice cuatro inviernos de aprendiz con un electricista viejo y saque la licencia del estado. Galpones de tabaco, bombas de pozo, tableros: trabajo con la mano que me quedo buena.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 65, oficios = {"electricista"} },
    { id = "l09_ofi_enfermera_hogar", etapa = "oficio", texto = "Saque la licencia de enfermera auxiliar en una vocacional de Louisville y trabaje de noche en un hogar de ancianos. Se cerrar ojos a las cuatro y llamar a la familia a las siete.", da = {"oficio_aprendido"}, edad_min = 20, edad_max = 60, oficios = {"enfermera"} },
    { id = "l09_ofi_granjero_hereford", etapa = "oficio", texto = "Tengo unos acres, unas vacas Hereford y un huerto que me pelea. El cupo de tabaco lo vendi cuando las rodillas dijeron basta.", da = {"granja", "tabaco"}, edad_min = 45, edad_max = 85, oficios = {"granjero"} },
    { id = "l09_ofi_mecanico_31w", etapa = "oficio", texto = "Aprendi mecanica de abajo, limpiando carburadores en un taller de la 31W. Los autos americanos viejos los entiendo; los japoneses son otra religion.", da = {"oficio_aprendido"}, edad_min = 18, edad_max = 60, oficios = {"mecanico"} },
    { id = "l09_ofi_mecanico_duggan", etapa = "oficio", texto = "Trabaje un tiempo en el taller de Frank Duggan en Riverside, el boxeador. Me fui cuando vi lo que entraba de noche y no quise preguntar de donde.", da = {"oficio_aprendido"}, edad_min = 22, edad_max = 50, oficios = {"mecanico"}, pueblos = {"Riverside"}, lazo = "duggan" },
    { id = "l09_ofi_pastora_capilla", etapa = "oficio", texto = "Predico en una capilla de madera de {pueblo} sin mas ordenacion que la de mi abuela. Los domingos somos tres bancos y un perro, y alcanza.", da = {"iglesia_trabajo", "religioso"}, edad_min = 30, edad_max = 85, oficios = {"pastora"} },
    { id = "l09_ofi_policia_menores", etapa = "oficio", texto = "Fui policia de menores en Louisville casi treinta inviernos: fugados, ladronas de tienda, ninas en la calle. Se quitarle una navaja a un muchacho sin que se de cuenta.", da = {"policia_pasado", "louisville"}, edad_min = 58, edad_max = 85, oficios = {"policia"} },
    { id = "l09_ofi_profesor_mapas", etapa = "oficio", texto = "Enseno historia y geografia en la secundaria de {pueblo} hace mas de veinte inviernos. Les muestro el mundo con mapas y revistas viejas.", da = {"universidad"}, edad_min = 42, edad_max = 70, oficios = {"profesora"} },
    { id = "l10_ofi_camionero_earl", etapa = "oficio", texto = "Soy {oficio} de la 31. Paraba a las tres en la bomba de Rosewood; el Gordo Whitaker se tomaba ahi el cafe con tres cucharadas y contaba chistes malos.", edad_min = 25, edad_max = 85, oficios = {"camionero"}, lazo = "earl" },
    { id = "l10_ofi_carpintero", etapa = "oficio", texto = "Soy {oficio} desde que tenia catorce. Mida dos veces, corte una: me lo dijo mi papa y lo repito yo, aunque ya me falten dos puntas de dedos.", da = {"lesion_mano", "oficio_aprendido"}, edad_min = 30, edad_max = 85, oficios = {"carpintero"} },
    { id = "l10_ofi_cazador", etapa = "oficio", texto = "Soy {oficio}. Pongo trampas y vendo la carne y los cueros en Brandenburg los sabados; el guarda de caza hace como que no me ve.", da = {"rural"}, edad_min = 18, edad_max = 85, oficios = {"cazador"} },
    { id = "l10_ofi_cocinera_wade", etapa = "oficio", texto = "Soy {oficio} de escuela. En el concurso de matematicas del condado, en abril, le servi el almuerzo al nino Bell, el que gano. Contaba los tater tots.", edad_min = 25, edad_max = 85, oficios = {"cocinera"}, lazo = "wade_bell" },
    { id = "l10_ofi_costurera", etapa = "oficio", texto = "Soy {oficio}. Coso ruedos, vestidos de novia y la ropa de los muertos para la funeraria. A los muertos no les importa una puntada torcida; a las viudas si.", edad_min = 30, edad_max = 85, oficios = {"costurera"} },
    { id = "l10_ofi_costurera_gladys", etapa = "oficio", texto = "Soy {oficio}. Aprendi mirando por la vitrina de Arreglos Gladys, en Muldraugh: tiza, alfileres en la boca y la Singer sonando hasta tarde.", edad_min = 18, edad_max = 45, oficios = {"costurera"}, lazo = "gladys" },
    { id = "l10_ofi_electricista", etapa = "oficio", texto = "Soy {oficio} con licencia del sindicato de Louisville. Le puse luz a medio {pueblo}. El cable hace lo que dice el plano; la gente no.", da = {"oficio_aprendido"}, edad_min = 25, edad_max = 85, oficios = {"electricista"} },
    { id = "l10_ofi_enfermera", etapa = "oficio", texto = "Fui {oficio} de noche en un hogar de ancianos. Se me murieron mas viejos tomados de mi mano que de la de nadie.", edad_min = 25, edad_max = 85, oficios = {"enfermera"} },
    { id = "l10_ofi_granjero", etapa = "oficio", texto = "Soy {oficio}: unos acres de burley y treinta vacas. Ahora el tabaco vale mas que un billete y la leche vale mas que el tabaco.", da = {"granja", "tabaco"}, edad_min = 18, edad_max = 85, oficios = {"granjero"} },
    { id = "l10_ofi_mecanico_duggan", etapa = "oficio", texto = "Soy {oficio} en {pueblo}. El taller del Martillo Duggan, en Riverside, arreglaba autos sin preguntar de donde venian; el mio preguntaba, y tenia menos clientes.", edad_min = 18, edad_max = 85, oficios = {"mecanico"}, lazo = "duggan" },
    { id = "l10_ofi_mecanico_vulca", etapa = "oficio", texto = "Soy {oficio}. Los fines de semana parchaba neumaticos en la vulcanizacion de Ekron, al lado del sobrino de la Misia Rosa, que hablaba poco y arreglaba todo.", edad_min = 18, edad_max = 50, oficios = {"mecanico"}, lazo = "hector" },
    { id = "l10_ofi_pastora_reyes", etapa = "oficio", texto = "Soy {oficio} de una iglesia chica con campanario de lata. No cobro el rezo; el predicador de la carpa a la salida de Riverside si cobraba, y llenaba mas.", da = {"iglesia_trabajo", "religioso"}, edad_min = 25, edad_max = 85, oficios = {"pastora"}, lazo = "reyes" },
    { id = "l10_ofi_policia_richmond", etapa = "oficio", texto = "Soy {oficio}. Hice la academia en Richmond, la misma del Cabo de Muldraugh, y escribo los partes como si alguien los fuera a leer en cien inviernos.", edad_min = 21, edad_max = 85, oficios = {"policia"}, lazo = "cabo" },
    { id = "l10_ofi_profesora", etapa = "oficio", texto = "Soy {oficio} de cuarto grado. Los ninos aprenden a restar contando porotos, y yo aprendo a no gritar contando hasta diez.", da = {"universidad"}, edad_min = 22, edad_max = 85, oficios = {"profesora"} },
    { id = "l01_pn_bascula", etapa = "primera_noche", texto = "La primera noche quede atrapad{o} en la 31, cerca de la bascula. Detras de la caseta habia un Peterbilt escondido con las luces apagadas. Hice lo mismo.", edad_min = 18, edad_max = 85, lazo = "earl" },
    { id = "l01_pn_calle_main", etapa = "primera_noche", texto = "La primera noche vi arder la calle Main de West Point desde mi ventana. Nadie la apago, con el cuartel a unas cuadras. Ahi entendi que no era un incendio.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l01_pn_fosa", etapa = "primera_noche", texto = "La primera noche me meti a la fosa de un taller, debajo de un auto, y mire pies por la rendija de la cortina hasta que aclaro.", edad_min = 18, edad_max = 65 },
    { id = "l01_pn_iglesia_abierta", etapa = "primera_noche", texto = "Al amanecer del sabado vi la iglesia de piedra de Riverside con las puertas abiertas de par en par. Entre a sentarme y el cura me puso a cargar agua.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l01_pn_megafono", etapa = "primera_noche", texto = "La primera noche corri a la comisaria de Muldraugh. Una sargento de verde gritaba por megafono que nadie salia. Me devolvi a mi casa por las calles de atras.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "pereira" },
    { id = "l01_pn_radio_casa", etapa = "primera_noche", texto = "La primera noche la radio repetia que nos quedaramos en casa con las puertas cerradas. Me quede. Conte los tiros hasta las tres y despues deje de contar.", edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l01_pn_techo", etapa = "primera_noche", texto = "La primera noche me subi al techo con la escopeta. El primero que subio por el camino era un vecino. Le dispare igual. Fue lo mas facil y lo peor.", da = {"mato_transformado"}, prohibe = {"viejo_fragil"}, edad_min = 18, edad_max = 85 },
    { id = "l01_pn_telefono", etapa = "primera_noche", texto = "La primera noche el telefono no paro de sonar hasta las dos y media. Era gente pidiendo ayuda que yo no tenia. Despues se murio la linea y el silencio fue peor.", edad_min = 18, edad_max = 85 },
    { id = "l02_pn_barricada", etapa = "primera_noche", texto = "Tome la camioneta para salir del condado y en la 31W habia una barricada de la Guardia. Un soldado me apunto y me grito que me devolviera.", edad_min = 18, edad_max = 85 },
    { id = "l02_pn_camara", etapa = "primera_noche", texto = "Me encerre en la camara de frio del supermercado con dos cajeras y un repartidor. Contamos las cajas de leche hasta que se aclaro la puerta.", da = {"vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l02_pn_canal19", etapa = "primera_noche", texto = "Esa noche oi por el canal 19 a medio condado gritando nombres de calles. A las dos se fue callando. A las cuatro no quedaba nadie.", da = {"radio_cb"}, edad_min = 18, edad_max = 85 },
    { id = "l02_pn_comisaria", etapa = "primera_noche", texto = "Fui a la comisaria de Muldraugh a pedir ayuda. Una sargento de verde gritaba por megafono que nadie salia. Me devolvi por los patios.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "pereira" },
    { id = "l02_pn_entretecho", etapa = "primera_noche", texto = "La radio pedia quedarse en casa y cerrar las puertas. Me subi al entretecho con una linterna y lo que mas queria, como en las inundaciones.", edad_min = 18, edad_max = 85 },
    { id = "l02_pn_gasolinera", etapa = "primera_noche", texto = "En Rosewood la unica luz prendida era la de la gasolinera. La mire toda la noche desde el porche, como una polilla que no se atreve.", edad_min = 18, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l02_pn_iglesia", etapa = "primera_noche", texto = "En Riverside la iglesia de piedra tenia la puerta abierta. Me quede en una banca de atras hasta que amanecio, sin rezar, solo mirando la puerta.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l02_pn_main", etapa = "primera_noche", texto = "Desde mi ventana vi arder la calle Main de West Point de punta a punta. Nadie la apagaba. Conte las casas para no oir los gritos.", edad_min = 18, edad_max = 85, pueblos = {"West Point"} },
    { id = "l03_pn_barricada_31", etapa = "primera_noche", texto = "La noche del 9 quise salir por la 31 hacia Louisville. En la barricada un soldado de la Guardia me apunto con el fusil y me grito que me devolviera. Me devolvi.", da = {"sin_noticias"}, edad_min = 18, edad_max = 85 },
    { id = "l03_pn_calle_main", etapa = "primera_noche", texto = "La noche del 9 vi arder la calle Main desde mi ventana. La gente corria al cuartel de bomberos, y nadie apagaba nada.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l03_pn_dormi", etapa = "primera_noche", texto = "La primera noche me tome dos pastillas para dormir y no me entere de nada. Desperte el sabado con el pueblo cambiado y el perro del vecino comiendose a alguien.", da = {"culpa"}, edad_min = 18, edad_max = 85 },
    { id = "l03_pn_luz_rosa", etapa = "primera_noche", texto = "La noche del 9 mire hasta el amanecer la ampolleta de la gasolinera de la Misia Rosa. Mientras estuviera prendida, pense, alguien estaba despierto.", edad_min = 18, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l03_pn_mate_vecino", etapa = "primera_noche", texto = "La primera noche mate a mi vecino con una pala. Ya no era el: tenia la boca negra y caminaba torcido. Lo enterre al amanecer, debajo del manzano.", da = {"mato_transformado"}, edad_min = 18, edad_max = 85 },
    { id = "l03_pn_megafono_comisaria", etapa = "primera_noche", texto = "La noche del 9 una sargento de verde gritaba ordenes con un megafono en la puerta de la comisaria. Me fui a mi casa y no sali en tres dias.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "pereira" },
    { id = "l03_pn_radio_casa", etapa = "primera_noche", texto = "El 9 de julio la radio repetia que nos quedaramos en casa. Me quede. A las once empece a oir los gritos de la calle y le subi el volumen a la radio para no oirlos.", edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l03_pn_river_view", etapa = "primera_noche", texto = "A las tres de la manana del 10 vi arder el motel River View desde el camino. Nadie fue a apagarlo. Adentro se movian sombras.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "kell" },
    { id = "l04_pn_barricada", etapa = "primera_noche", texto = "Esa noche fuimos con otros cuarenta hacia el cordon por la 31W, al sur de Muldraugh. El teniente grito fuego. Uno de los soldados no levanto el fusil. A ese le debo estar aqui.", da = {"herido_brote"}, edad_min = 18, edad_max = 85, lazo = "ray" },
    { id = "l04_pn_calle_main", etapa = "primera_noche", texto = "La noche del 9 vi desde la loma arder la calle Main de West Point, casa por casa, como una mecha. La radio decia que nos quedaramos adentro. Me quede, mirando el humo hasta que aclaro.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l04_pn_carpa", etapa = "primera_noche", texto = "El 9 estaba bajo la carpa del predicador, en el potrero a la salida de Riverside. Entro un hombre mordiendo y el predicador fue el primero en correr, con la caja del diezmo bajo el brazo.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "reyes" },
    { id = "l04_pn_luz_bomba", etapa = "primera_noche", texto = "La primera noche, desde mi ventana, la luz de la bomba de la Misia Rosa se veia prendida. Mientras esa ampolleta siguiera ahi, pense, el pueblo no se habia terminado.", edad_min = 18, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l04_pn_megafono", etapa = "primera_noche", texto = "La noche del 9 fui a la comisaria de Muldraugh a pedir ayuda. Una sargento de verde gritaba por megafono que nadie salia. Me volvi a la casa caminando de espaldas, sin creerlo.", da = {"vive_con_otros"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "pereira" },
    { id = "l04_pn_radio_casa", etapa = "primera_noche", texto = "La radio repetia que nos quedaramos en casa, con las puertas cerradas. Corri los muebles contra las ventanas, llene la tina y oi toda la noche a los perros del barrio callarse uno por uno.", da = {"vive_solo"}, edad_min = 18, edad_max = 85 },
    { id = "l04_pn_spiffos", etapa = "primera_noche", texto = "El 9 estaba comiendo en el Spiffo's de Muldraugh cuando un soldado mordio a la cajera en el cuello. El cocinero salio corriendo por las vias con el delantal puesto, y yo corri para el otro lado.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "julio" },
    { id = "l05_pn_barra", etapa = "primera_noche", texto = "Estaba en un bar de la 31W con el tercer trago cuando el cantinero se cayo detras de la barra. Sali por la cocina y llegue tarde a todo lo demas.", pide = {"alcohol"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l05_pn_calle_main", etapa = "primera_noche", texto = "Desde mi ventana vi arder la calle Main de West Point. La bombera estaba ahi parada y la calle se quemo igual; nadie tiro agua esa noche.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l05_pn_guardia", etapa = "primera_noche", texto = "A la madrugada pasaron por la 31 los camiones de la Guardia, con los focos apagados. Al otro dia ya habia barricada y nadie salia del condado.", edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l05_pn_luz_bomba", etapa = "primera_noche", texto = "Pase la noche mirando por una rendija la luz de la gasolinera de los Bencina. Mientras siguiera prendida, me dije, el mundo no se habia acabado.", edad_min = 18, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l05_pn_megafono", etapa = "primera_noche", texto = "Fui a la comisaria de Muldraugh a pedir ayuda. Una sargento de verde gritaba por megafono desde la puerta que nadie saliera. Me di vuelta y corri a mi casa.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "pereira" },
    { id = "l05_pn_radio", etapa = "primera_noche", texto = "Esa noche la radio repetia que nos quedaramos en casa con las puertas cerradas. Le hice caso hasta que la voz se corto, a la mitad de un himno.", edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l05_pn_silencio", etapa = "primera_noche", texto = "Esa noche apague todo lo que hacia ruido: el refrigerador, el reloj de la cocina. Al perro le amarre el hocico con un panuelo y me quede abrazad{o} a el.", edad_min = 18, edad_max = 85 },
    { id = "l06_pn_barricada", etapa = "primera_noche", texto = "La madrugada del sabado fui con otros a la barricada sur de la 31W. Gritamos que estabamos sanos. Dispararon. Un soldado no disparo: lo vi bajar el fusil.", da = {"culpa"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "ray", peso = 5 },
    { id = "l06_pn_bote", etapa = "primera_noche", texto = "La primera noche me meti al Ohio en un bote y ancle en la mitad del rio hasta que salio el sol. Desde el agua se veia arder la calle Main de West Point.", da = {"rio"}, edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l06_pn_canal19", etapa = "primera_noche", texto = "Esa noche el canal 19 se volvio loco: choferes gritando, uno rezando. Y un muchacho de la gasolinera de Rosewood contestandole a todos, tranquilo.", edad_min = 18, edad_max = 85, lazo = "hector" },
    { id = "l06_pn_ganado", etapa = "primera_noche", texto = "Esa noche el ganado mugia todo junto hacia la loma. Un vecino subio por la entrada con la mano mordida. A los veinte minutos de caerse, se paro.", da = {"mato_transformado"}, pide_alguno = {"granja", "rural"}, edad_min = 18, edad_max = 85 },
    { id = "l06_pn_gasolinera", etapa = "primera_noche", texto = "Esa noche, desde la 31, vi la unica luz prendida de Rosewood: la ampolleta de la gasolinera de la Misia Rosa. Segui de largo y todavia me acuerdo.", edad_min = 18, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l06_pn_gimnasio", etapa = "primera_noche", texto = "El viernes 9 estaba en el bingo del gimnasio de la escuela. Cuando entro el primero, nos metimos a la cocina y bajamos la cortina de fierro. Alguien canto bajito hasta las cuatro.", da = {"vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l06_pn_megafono", etapa = "primera_noche", texto = "Esa noche fui a la comisaria de Muldraugh a pedir ayuda. Una sargento de verde gritaba con un megafono desde la puerta que todos se fueran a sus casas.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "pereira" },
    { id = "l06_pn_radio", etapa = "primera_noche", texto = "La radio repetia que nos quedaramos en casa. Le hice caso. Pase la noche a oscuras oyendo a los perros ladrar todos hacia el mismo lado.", edad_min = 18, edad_max = 85 },
    { id = "l06_pn_riverview", etapa = "primera_noche", texto = "A las tres de la madrugada vi arder el motel River View de West Point desde mi ventana. Nadie fue a apagarlo. Todavia me llega el olor cuando llueve.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "kell" },
    { id = "l06_pn_softbol", etapa = "primera_noche", texto = "El viernes 9 jugaba la liga de verano con los focos prendidos. Entro uno corriendo por el jardin izquierdo con la garganta abierta, y detras venian otros.", edad_min = 18, edad_max = 85 },
    { id = "l07_pn_calle_main", etapa = "primera_noche", texto = "El 9 de julio oi arder la calle Main de West Point desde el cuarto de atras de un local, sin luz, contando los vidrios que reventaban uno por uno.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l07_pn_canal19", etapa = "primera_noche", texto = "Esa noche oi el canal 19 hasta las cuatro: camioneros preguntando por la 31 y un muchacho de la gasolinera de Rosewood que les contestaba a todos.", edad_min = 18, edad_max = 85, lazo = "hector" },
    { id = "l07_pn_cocina_heridos", etapa = "primera_noche", texto = "La primera noche cosi heridos en la mesa de mi cocina con una lampara de parafina. Cuando se acabo el hilo segui con hilo de pescar.", da = {"vive_con_otros"}, pide = {"oficio_aprendido"}, edad_min = 18, edad_max = 85 },
    { id = "l07_pn_fosa", etapa = "primera_noche", texto = "La primera noche dormi en la fosa de un taller, con una llave de cruz y el agua de lluvia de un tambor. Comi mani de la maquina hasta el lunes.", da = {"vive_solo", "hambre"}, edad_min = 18, edad_max = 85 },
    { id = "l07_pn_galpon_tabaco", etapa = "primera_noche", texto = "Me agarro en la 31: una fila de autos parada y gente corriendo entre los focos. Me meti por un camino de tierra y apague todo dentro de un galpon de tabaco.", edad_min = 18, edad_max = 85 },
    { id = "l07_pn_megafono", etapa = "primera_noche", texto = "Esa noche una sargento de verde gritaba por megafono en la puerta de la comisaria que nadie saliera. Yo estaba en la calle, y en la calle me quede.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "pereira" },
    { id = "l07_pn_quieto", etapa = "primera_noche", texto = "La primera noche me quede quiet{o} detras de la cortina hasta el amanecer, sin mover ni los ojos. Pasaban por la calle arrastrando los pies. Ninguno subio.", da = {"valiente"}, edad_min = 18, edad_max = 85 },
    { id = "l07_pn_radio_cocina", etapa = "primera_noche", texto = "La radio de Louisville pedia que nos quedaramos en casa. Hice caso a medias: abri la cocina y les di de comer toda la noche a vecinos que llegaban sin hambre.", da = {"vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l08_pn_barricada_norte", etapa = "primera_noche", texto = "Quise salir por la 31 hacia Louisville. En la entrada norte de Muldraugh habia una barricada y una sargento de verde con un megafono. Me hizo dar la vuelta.", edad_min = 18, edad_max = 85, lazo = "pereira" },
    { id = "l08_pn_barricada_sur", etapa = "primera_noche", texto = "A la una quisimos pasar la barricada sur de la 31W. Gritamos que estabamos sanos y el teniente dio la orden. Vi a un soldado bajar el fusil. Corri por el maizal.", da = {"herido_brote"}, edad_min = 18, edad_max = 85, lazo = "ray", peso = 5 },
    { id = "l08_pn_calle_main", etapa = "primera_noche", texto = "Esa noche ardio la calle Main de West Point, con la casa de la bombera adentro. Desde mi ventana el cielo estaba naranja y la gente corria hacia el rio.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l08_pn_comisaria_fila", etapa = "primera_noche", texto = "A medianoche fui a la comisaria de Muldraugh a pedir ayuda. Por la puerta de atras salia gente en fila y un policia de bigote los contaba en voz alta.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l08_pn_hospital_fuerte", etapa = "primera_noche", texto = "Estaba de turno en el hospital del Fuerte cuando entraron los primeros mordidos. A las dos ya no quedaban camillas ni guantes, y un doctor lloraba en la escalera.", pide_alguno = {"fort_knox", "oficio_aprendido"}, edad_min = 22, edad_max = 85 },
    { id = "l08_pn_luz_bencina", etapa = "primera_noche", texto = "Esa noche lo unico prendido en Rosewood era la gasolinera de los Bencina. Pase de largo. Desde la calle se oia algo golpeando adentro, en el bano.", edad_min = 18, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l08_pn_potrero", etapa = "primera_noche", texto = "Las vacas bramaron toda la noche. A las once vi a un vecino caminando por el potrero con la boca negra. Le pegue con lo primero que tuve a mano y no se paro mas.", da = {"mato_transformado"}, pide_alguno = {"granja", "rural"}, edad_min = 18, edad_max = 85 },
    { id = "l08_pn_radio_casa", etapa = "primera_noche", texto = "El viernes nueve la radio repetia que nos quedaramos en las casas. Me quede, con la escopeta en las rodillas y la luz apagada, oyendo pasos en la grava hasta que aclaro.", edad_min = 18, edad_max = 85 },
    { id = "l09_pn_barricada_31", etapa = "primera_noche", texto = "La noche del 9 iba por la 31 al norte y antes de Muldraugh una barricada de la Guardia con focos me hizo dar vuelta. En la cuneta, detras del soldado, habia gente tirada.", da = {"sin_noticias"}, edad_min = 18, edad_max = 85 },
    { id = "l09_pn_calle_main", etapa = "primera_noche", texto = "Desde mi porche vi arder la calle Main de West Point toda la noche del 9. Nadie la apagaba. Olia a madera y a pelo quemado, y yo no me movi de la silla.", da = {"cobarde"}, prohibe = {"valiente"}, edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l09_pn_canal19", etapa = "primera_noche", texto = "La noche del 9 me pase horas con la CB en el canal 19. Un muchacho de Rosewood, el Bencinita, repetia que la 31 estaba cerrada al norte y que nadie se acercara a la Guardia.", edad_min = 18, edad_max = 85, lazo = "hector" },
    { id = "l09_pn_cruce", etapa = "primera_noche", texto = "El 9 de julio me fui a la esquina de la escuela con una linterna y dirigi el trafico de los que huian, tres horas, hasta que no quedo nadie a quien dirigir.", da = {"valiente", "lider"}, prohibe = {"cobarde"}, edad_min = 18, edad_max = 85 },
    { id = "l09_pn_hogar", etapa = "primera_noche", texto = "La primera noche estaba de turno con un monton de viejitos. Los junte en el comedor y les cante hasta que amanecio, para que no oyeran lo de la pieza del fondo.", da = {"valiente", "cuida_a_alguien"}, edad_min = 18, edad_max = 70 },
    { id = "l09_pn_megafono", etapa = "primera_noche", texto = "La noche del 9 oi desde mi casa un megafono en la comisaria de Muldraugh: una voz de mujer dando ordenes. No entendi las palabras, pero entendi que no habia que salir.", da = {"vive_solo"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "pereira" },
    { id = "l09_pn_porche", etapa = "primera_noche", texto = "La primera noche estaba en el porche cuando subio por la calle un hombre caminando chueco. No alcance a gritarle. Le di con lo que tenia en la mano y clave las ventanas hasta el amanecer.", da = {"mato_transformado"}, edad_min = 18, edad_max = 85 },
    { id = "l09_pn_radio_casa", etapa = "primera_noche", texto = "La radio decia que nos quedaramos en casa. Apague las luces y me sente en el suelo de la cocina con un papel en el bolsillo que ya no iba a servir de nada.", da = {"cobarde"}, prohibe = {"valiente"}, edad_min = 18, edad_max = 85 },
    { id = "l10_pn_altillo", etapa = "primera_noche", texto = "La noche del 9 me sente en el altillo con un martillo en la rodilla. A las tres paso un hombre en bata de hospital por los rieles, caminando como borracho.", da = {"vive_solo"}, edad_min = 18, edad_max = 85 },
    { id = "l10_pn_bar_31", etapa = "primera_noche", texto = "La noche del 9 estaba en el bar de la 31 cuando un hombre le mordio el cuello al cantinero encima del meson. Sali por la ventana del bano y me corte el brazo.", da = {"herido_brote"}, edad_min = 18, edad_max = 85 },
    { id = "l10_pn_bote", etapa = "primera_noche", texto = "A las dos de la manana subi a los mios a un bote y reme hasta el medio del rio. Los muertos no nadan. Los vivos casi tampoco.", da = {"familia_viva"}, pide_alguno = {"rio"}, edad_min = 18, edad_max = 85 },
    { id = "l10_pn_calle_main", etapa = "primera_noche", texto = "La noche del 9 la calle Main de West Point ardia y nadie la apagaba; se quemo hasta la casa de la bombera. Baje a buscar a los mios entre el humo.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l10_pn_canal19", etapa = "primera_noche", texto = "La noche del 9 escuche el canal 19 hasta las tres: camioneros gritando, uno rezando hasta que dejo de rezar. La bomba de Rosewood seguia con la luz prendida.", edad_min = 18, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l10_pn_cocina_ninos", etapa = "primera_noche", texto = "La noche del 9 me pillo trabajando. A medianoche tenia ninos ajenos en la cocina, entrados por la ventana que nunca cierra. A sus papas no los volvi a ver.", da = {"cuida_ninos"}, edad_min = 25, edad_max = 85 },
    { id = "l10_pn_megafono", etapa = "primera_noche", texto = "La noche del 9 una sargento de verde grito por megafono desde la puerta de la comisaria de Muldraugh. No entendi la orden; entendi el miedo.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "pereira" },
    { id = "l10_pn_puertas_iglesia", etapa = "primera_noche", texto = "Al amanecer del 10 vi al cura de Riverside abrir de par en par las puertas de la iglesia de piedra. Fui de los primeros en entrar, sin saber rezar.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l10_pn_radio_casa", etapa = "primera_noche", texto = "La noche del 9 la radio repetia que nos quedaramos en casa. Me quede, con la escopeta en las rodillas y la luz apagada, contando los disparos del lado del Fuerte.", edad_min = 18, edad_max = 85 },
    { id = "l01_des_biblioteca", etapa = "despues", texto = "Me encerre en la biblioteca de la escuela con los estantes clavados en las ventanas. Los libros no se comen, pero tapan bien.", da = {"vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l01_des_canal19", etapa = "despues", texto = "Por el canal 19 hablo con el Bencinita de Rosewood. El me dice donde hay muertos en la 31 y yo le digo donde quedan baterias.", da = {"trueque"}, edad_min = 18, edad_max = 85, lazo = "hector" },
    { id = "l01_des_cobro_viernes", etapa = "despues", texto = "Los viernes pasan los del Martillo a cobrar. Les doy dos latas y me dejan tranquil{o}. Todo Riverside lo sabe y nadie lo dice.", da = {"hambre"}, edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "duggan" },
    { id = "l01_des_diezmo", etapa = "despues", texto = "En el puente de Riverside predica un diacono que cobra el diezmo casa por casa. Le pague una vez. Rece lo mismo que antes, sin recibo.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "reyes" },
    { id = "l01_des_espineles", etapa = "despues", texto = "Desde julio vivo del rio: espineles de noche y bagre ahumado de dia. El agua hervida y la sal las cambio por pescado.", da = {"trueque", "vive_solo"}, pide = {"rio"}, edad_min = 18, edad_max = 85 },
    { id = "l01_des_olla", etapa = "despues", texto = "Cocino para la cuadra en una olla grande: seis bocas, a veces ocho. No sera mucho, pero nadie se ha quedado sin plato.", da = {"vive_con_otros", "lider"}, edad_min = 18, edad_max = 85 },
    { id = "l01_des_radio_domingo", etapa = "despues", texto = "Los domingos en la noche escucho la radio por si habla el muchacho de West Point que saca gente. Dice estoy bien, mama, y yo le creo como si fuera mio.", da = {"sin_noticias"}, edad_min = 18, edad_max = 85, lazo = "eduardo" },
    { id = "l01_des_recados", etapa = "despues", texto = "Dicen que en San Judas de March Ridge una monja canta a las cinco los recados que le dejan en la puerta. Fui y le deje el nombre de mi madre.", da = {"perdio_familia"}, edad_min = 18, edad_max = 85, lazo = "lucia" },
    { id = "l02_des_bencinita", etapa = "despues", texto = "Por el canal 19 el Bencinita de Rosewood avisa de noche. Le hice caso una vez, no pase por la 31, y aqui estoy.", da = {"radio_cb"}, edad_min = 18, edad_max = 85, lazo = "hector" },
    { id = "l02_des_cartas", etapa = "despues", texto = "De mi gente de afuera del cordon no se nada. Les escribo cartas que no tengo como mandar y las guardo en una caja de galletas.", da = {"sin_noticias", "hijos_lejos"}, edad_min = 18, edad_max = 85 },
    { id = "l02_des_eduardo", etapa = "despues", texto = "Los domingos oigo por la radio a un bombero que le habla a su mama: si me oyes, estoy bien. No es para mi, pero me hace bien.", da = {"sin_noticias"}, edad_min = 18, edad_max = 85, lazo = "eduardo" },
    { id = "l02_des_gimnasio", etapa = "despues", texto = "Vivo con otros en un gimnasio de escuela. Repartimos las latas con una tabla en la pizarra y nadie sale solo.", da = {"vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l02_des_gladys", etapa = "despues", texto = "Le cambio hilo y botones a la Gladys de Muldraugh por un plato. La aguja no pregunta, dice ella.", da = {"trueque"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "gladys" },
    { id = "l02_des_mano", etapa = "despues", texto = "En julio me corte con un vidrio rompiendo una ventana para salir. Se me infecto y la mano no me cerro mas; trabajo con la otra.", da = {"herido_brote", "lesion_mano"}, edad_min = 18, edad_max = 85 },
    { id = "l02_des_ninos", etapa = "despues", texto = "Cuido a dos ninos que no son mios; los padres se quedaron caminando en el potrero. Los cuento cada noche antes de dormir.", da = {"cuida_ninos", "vive_con_otros"}, edad_min = 25, edad_max = 85 },
    { id = "l02_des_sanjudas", etapa = "despues", texto = "Dicen que en San Judas de March Ridge una monja canta los recados que le dejan en la puerta. Fui a dejar el nombre de mi hermana.", da = {"perdio_familia"}, edad_min = 18, edad_max = 85, lazo = "lucia" },
    { id = "l02_des_solo", etapa = "despues", texto = "Vivo sol{o}. Cambio huevos y lena por sal y pilas, y hablo con las gallinas para no perder la voz.", da = {"vive_solo", "trueque"}, edad_min = 18, edad_max = 85 },
    { id = "l03_des_banda_duggan", etapa = "despues", texto = "En Riverside una banda de nueve cobra por dejarte tranquilo. El jefe es un boxeador viejo con una maza. Pago lo que puedo y no lo miro a los ojos.", da = {"deudas"}, edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "duggan" },
    { id = "l03_des_cuida_ninos", etapa = "despues", texto = "En agosto me quede con dos ninos de la cuadra que nadie vino a buscar. Les ensene a no gritar y a caminar por el pasto, no por el ripio.", da = {"cuida_ninos", "vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l03_des_diezmo_avivamiento", etapa = "despues", texto = "Pasa una camioneta blanca que dice AVIVAMIENTO. El predicador cobra el diezmo para los del patio de trenes y bendice al que paga.", edad_min = 18, edad_max = 85, lazo = "reyes" },
    { id = "l03_des_radio_domingos", etapa = "despues", texto = "Los domingos en la noche oigo por la radio a un muchacho que le habla a su mama en West Point. No dice mucho, pero la gente se junta a oirlo.", edad_min = 18, edad_max = 85, lazo = "eduardo" },
    { id = "l03_des_san_judas", etapa = "despues", texto = "Dicen que en San Judas, en March Ridge, hay una monjita que canta para los muertos con la puerta abierta. Fui una vez a dejarle un recado para mi madre.", da = {"perdio_familia"}, edad_min = 18, edad_max = 85, lazo = "lucia" },
    { id = "l03_des_solo_hambre", etapa = "despues", texto = "Vivo sol{o}. En octubre comi una paloma y sopa de corteza. Aprendi que el hambre se va a los tres dias y vuelve al cuarto.", da = {"vive_solo", "hambre"}, prohibe = {"vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l03_des_tecolote_19", etapa = "despues", texto = "Me entero de todo por el canal 19: el Tecolote vende chismes a cambio de cigarros, y uno nunca sabe cuanto es verdad.", edad_min = 18, edad_max = 85, lazo = "duarte" },
    { id = "l03_des_trueque", etapa = "despues", texto = "Desde agosto vivo del trueque: cambio lo que se hacer por latas, velas y cartuchos. La plata ya sirve para prender la estufa.", da = {"trueque"}, edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l04_des_canal19", etapa = "despues", texto = "Las noticias las compro por el canal 19 al Tecolote, que vende chismes a cambio de cigarros. Mitad mentira, mitad verdad; el truco es saber cual mitad.", da = {"trueque"}, edad_min = 18, edad_max = 85, lazo = "duarte" },
    { id = "l04_des_familia_entera", etapa = "despues", texto = "Somos seis en la casa y estamos todos. Eso no se lo digo a nadie en voz alta, que da mala suerte. Cocinamos en el patio, dormimos por turnos y los ninos ya saben cargar una escopeta.", da = {"familia_viva", "vive_con_otros", "cuida_ninos"}, prohibe = {"perdio_familia"}, edad_min = 18, edad_max = 85 },
    { id = "l04_des_hambre_solo", etapa = "despues", texto = "Desde agosto vivo de lo que encuentro en las casas de la loma: avena con gusanos, sopa de sobre, una lata de jamon sin etiqueta. Hablo sol{o} con la radio apagada.", da = {"vive_solo", "hambre", "sin_noticias"}, edad_min = 18, edad_max = 85 },
    { id = "l04_des_lista_padre", etapa = "despues", texto = "Desde julio me anote en la lista del Padre de Riverside: nombre, dia y que hice. El cura no deja a nadie sentado; me mando a cargar agua y con eso como.", da = {"vive_con_otros", "trueque"}, edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l04_des_parche_lata", etapa = "despues", texto = "Me remiendo con dona Gladys, en la calle principal de Muldraugh: un parche por una lata, un ruedo por un balde de agua. Les da los buenos dias a los muertos de la vitrina.", da = {"trueque"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "gladys" },
    { id = "l04_des_radio_domingos", etapa = "despues", texto = "Los domingos prendemos la radio a pilas y buscamos al muchacho que habla desde Louisville. No dice su nombre. Dicen que es el de la leyenda, el que anda sacando gente. Con oirlo nos basta.", da = {"vive_con_otros"}, edad_min = 18, edad_max = 85, lazo = "eduardo" },
    { id = "l04_des_recado_sanjudas", etapa = "despues", texto = "Deje un recado para mi gente en la puerta de San Judas, en March Ridge. Dicen que la monja de ahi canta los recados de noche. Si alguien de los mios pasa, lo va a oir.", da = {"sin_noticias"}, edad_min = 18, edad_max = 85, lazo = "lucia" },
    { id = "l05_des_cuartel", etapa = "despues", texto = "Cuando no hay nada en la casa, como en el cuartel de bomberos. La Chela no pregunta: te pone a pelar papas y te sirve igual.", da = {"vive_con_otros"}, edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l05_des_iglesia_abierta", etapa = "despues", texto = "En Riverside la iglesia de piedra nunca cierra la puerta. Cuando hiela voy a dormir en el ultimo banco y el cura boxeador hace como que no me ve.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l05_des_radio_domingo", etapa = "despues", texto = "Los domingos en la noche giro la perilla hasta encontrar a un muchacho que le habla a su mama por la radio. No es mi {hijo}, pero lo escucho entero.", edad_min = 18, edad_max = 85, lazo = "eduardo" },
    { id = "l05_des_san_judas", etapa = "despues", texto = "Fui hasta San Judas de March Ridge a dejar un nombre en la puerta. Dicen que la monjita de adentro les canta los nombres a los muertos.", da = {"perdio_familia"}, edad_min = 18, edad_max = 85, lazo = "lucia" },
    { id = "l05_des_silo", etapa = "despues", texto = "Vivimos arriba de un silo de granos. Desde ahi se ve venir a los muertos con una hora de ventaja, y el maiz humedo alcanza para el invierno.", da = {"vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l05_des_solo", etapa = "despues", texto = "Vivo sol{o} desde agosto. Hablo en voz alta en la cocina para no olvidarme de como suena una persona.", da = {"vive_solo", "perdio_familia"}, prohibe = {"familia_viva"}, edad_min = 18, edad_max = 85 },
    { id = "l05_des_tambores", etapa = "despues", texto = "De noche veo los tambores prendidos alrededor del patio de trenes. Ahi manda una mujer de verde. Yo bajo la cortina y no prendo ni una vela.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "pereira" },
    { id = "l05_des_trueque", etapa = "despues", texto = "Cambio lo que se hacer por comida: un ruedo por un tarro de porotos, un corte de pelo por dos huevos, un consejo por nada.", da = {"trueque"}, edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l05_des_viernes", etapa = "despues", texto = "Los viernes pasan los del taller del Martillo cobrando. Uno lleva la cuenta con tiza en la puerta; la mia tiene tres rayas y una cruz.", da = {"deudas"}, edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "duggan" },
    { id = "l06_des_cabina", etapa = "despues", texto = "Vivo en la cabina de mi camion, estacionado detras de un galpon. Una hora de generador por noche y el seguro siempre puesto.", da = {"vive_solo"}, edad_min = 18, edad_max = 85, oficios = {"camionero"} },
    { id = "l06_des_chela", etapa = "despues", texto = "La Chela dice que en el cuartel de West Point tengo plato. Voy los jueves por la sopa y vuelvo antes de que oscurezca.", da = {"trueque"}, edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l06_des_cinturon", etapa = "despues", texto = "Baje tanto de peso que me sobran dos hoyos del cinturon. Como la mitad y la otra mitad se la doy a los chicos de la casa.", da = {"hambre", "cuida_ninos"}, edad_min = 18, edad_max = 85 },
    { id = "l06_des_cobro", etapa = "despues", texto = "En Riverside los viernes cobra la banda del Martillo. Aprendi a esconder la mitad de la cosecha bajo el piso del granero y a sonreir cuando cuentan.", da = {"hambre"}, edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "duggan" },
    { id = "l06_des_eduardo", etapa = "despues", texto = "Los domingos me siento junto a la radio a oir al muchacho que le habla a su mama en West Point. Dicen que es Eduardo, el de la leyenda. Me hace bien oir a alguien que vuelve.", da = {"sin_noticias"}, edad_min = 18, edad_max = 85, lazo = "eduardo" },
    { id = "l06_des_iglesia", etapa = "despues", texto = "Paso por la iglesia de piedra de Riverside: la puerta sigue abierta de dia y de noche. No entro, pero me hace bien saber que esta abierta.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l06_des_lucia", etapa = "despues", texto = "Cuando busco comida por March Ridge, al atardecer, se oye a la monjita de San Judas cantandoles a los muertos. No me acerco. Me hace bien igual.", da = {"vive_solo"}, edad_min = 18, edad_max = 85, lazo = "lucia" },
    { id = "l06_des_pescado", etapa = "despues", texto = "Vivo del pescado seco y de lo que cambio: un pescado por dos pilas, tres por una caja de cartuchos.", da = {"trueque"}, pide_alguno = {"rio"}, edad_min = 18, edad_max = 85 },
    { id = "l07_des_bicicleta", etapa = "despues", texto = "Ando en bicicleta llevando papelitos entre buzones: la gente levanta la bandera roja y yo paso. Me pagan con hilo, huevos o una lata.", da = {"trueque"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l07_des_duggan", etapa = "despues", texto = "Los viernes le pagamos a los del taller soldado de Riverside. El Martillo cobra sin mirar, y uno se va pensando que tuvo suerte de que no lo mirara.", da = {"hambre"}, edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "duggan" },
    { id = "l07_des_elevador", etapa = "despues", texto = "Duermo en la cabina de un camion subido a tacos, dentro de un taller cerrado. Para subir uso una escalera de tres peldanos que despues me llevo arriba.", da = {"vive_solo"}, prohibe = {"cuida_ninos"}, edad_min = 18, edad_max = 85 },
    { id = "l07_des_garita", etapa = "despues", texto = "Hice una garita en el techo con rampa, porque no subo escaleras. Miro el humo todas las tardes y le aviso a la cuadra con un trapo rojo.", da = {"vive_con_otros"}, pide_alguno = {"cojo", "lesion_pierna"}, edad_min = 18, edad_max = 85 },
    { id = "l07_des_granja_ajena", etapa = "despues", texto = "Me recibio una familia en su granja. Ordeno, curo animales y duermo en el galpon con un perro que se me pego la primera noche.", da = {"vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l07_des_libreta_cabo", etapa = "despues", texto = "En septiembre paso el cabo de Muldraugh con su libreta negra y me pregunto por los mios. Anoto una cruz y dos signos de pregunta, con tinta.", da = {"perdio_familia", "sin_noticias"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l07_des_luz_rosa", etapa = "despues", texto = "Desde mi ventana se ve la luz de la gasolinera de Rosewood, que no se apaga nunca. Mientras este prendida, duermo.", edad_min = 18, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l07_des_nina_ajena", etapa = "despues", texto = "Cuido a una nina de la cuadra que se quedo sin nadie. Le enseno a leer y a contar con palmas, y en la noche le dejo la vela prendida hasta que se duerme.", da = {"cuida_ninos", "vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l07_des_radio_domingo", etapa = "despues", texto = "Los domingos en la noche prendo la radio por si habla el hijo de la Chela. Dicen que anda sacando gente por todo Knox. Yo nomas quiero oir a alguien vivo.", edad_min = 18, edad_max = 85, lazo = "eduardo" },
    { id = "l08_des_junior_radio", etapa = "despues", texto = "Junior, el sobrino de la Misia Rosa, me arreglo la radio con una bateria de auto. Me la devolvio sin cobrarme nada y con las perillas limpias.", da = {"trueque"}, edad_min = 18, edad_max = 85, pueblos = {"Rosewood"}, lazo = "hector" },
    { id = "l08_des_misa_once", etapa = "despues", texto = "Los domingos camino a la misa de las once en la iglesia de piedra. Somos tres y un perro, pero la puerta esta abierta y el cura no pregunta nada.", da = {"religioso"}, edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l08_des_ninos_ajenos", etapa = "despues", texto = "Me quede con dos ninos que nadie vino a buscar. Les enseno a contar latas y a caminar sin hacer ruido, como si fuera un juego.", da = {"cuida_ninos", "vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l08_des_olla_cuadra", etapa = "despues", texto = "Cocino para la cuadra con lo que traen: una lata, una papa, una gallina flaca. Nadie se va sin comer, aunque yo coma ultim{o}.", da = {"vive_con_otros", "trueque"}, edad_min = 18, edad_max = 85 },
    { id = "l08_des_sotano", etapa = "despues", texto = "Vivo de lo que guarde en el sotano: frascos de pepinillos, papas, una tinaja de chucrut. Salgo poco y cuento todo dos veces antes de dormir.", da = {"vive_solo", "hambre"}, edad_min = 18, edad_max = 85 },
    { id = "l08_des_tambores", etapa = "despues", texto = "Desde la loma se ven los tambores encendidos del patio de trenes de Muldraugh. Dicen que los prende una muchacha que vendia fuegos artificiales en la 31W. Yo no bajo.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "kell" },
    { id = "l08_des_tecolote", etapa = "despues", texto = "De noche oigo el canal 19. El Tecolote vende chismes a cambio de diesel y yo le creo la mitad, que ya es mucho.", da = {"trueque"}, edad_min = 18, edad_max = 85, lazo = "duarte" },
    { id = "l08_des_tiza_viernes", etapa = "despues", texto = "En Riverside la banda del taller cobra los viernes. Yo pago con lo que tengo y no le miro la cara al que anota con tiza.", da = {"hambre"}, edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "duggan" },
    { id = "l08_des_vidrio_miel", etapa = "despues", texto = "En agosto me corte con un vidrio buscando comida y se me infecto la pierna. Una vecina me la lavo con agua hervida. Desde entonces cojeo.", da = {"herido_brote", "cojo", "lesion_pierna"}, prohibe = {"atleta"}, edad_min = 18, edad_max = 85 },
    { id = "l08_des_voz_bombero", etapa = "despues", texto = "Los domingos en la noche prendo la radio a pilas. A veces habla un muchacho con voz de bombero que dice donde hay gente atrapada. Dicen que es el hijo de la Chela.", edad_min = 18, edad_max = 85, lazo = "eduardo" },
    { id = "l09_des_agua_colorina", etapa = "despues", texto = "Cambio lo que cazo o lo que cultivo por agua de la Colorina. La Chela del cuartel no regala nada, pero tampoco deja a nadie con sed.", da = {"trueque"}, edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l09_des_chaquetas", etapa = "despues", texto = "Coso chaquetas acolchadas, tres capas de mezclilla con relleno de colcha, que un diente no atraviesa de una vez. Me las pagan en latas.", da = {"trueque"}, edad_min = 18, edad_max = 85 },
    { id = "l09_des_donde_trabajaba", etapa = "despues", texto = "Vivo en el lugar donde trabajaba, con los mios y los pocos que quedaron. Comemos de la despensa: pure en polvo, compotas, gelatina. Se acaba en enero.", da = {"vive_con_otros", "cuida_a_alguien", "hambre"}, edad_min = 18, edad_max = 85 },
    { id = "l09_des_encerrado", etapa = "despues", texto = "No he salido de mi casa desde el 9 de julio. Como de la despensa y tomo agua de lluvia de la tina. Los vecinos me hablan por la ventana.", da = {"vive_solo", "hambre"}, prohibe = {"valiente"}, edad_min = 18, edad_max = 85 },
    { id = "l09_des_grua_cabo", etapa = "despues", texto = "Le saco autos de la calle al Cabo con una grua y el me paga en gasolina. Me anota en su libreta con tinta, que dice que vale mas que una medalla.", da = {"trueque"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l09_des_puerta_cocina", etapa = "despues", texto = "Los domingos llevo lo que tengo a la puerta de la cocina de la iglesia de piedra. Lo recibe una senora que teje frazadas; al Padre lo veo de lejos.", da = {"religioso"}, edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l09_des_radio_domingo", etapa = "despues", texto = "Los domingos de noche busco en la radio la voz de un muchacho que dice que anda sacando gente. Dicen que es el hijo de la bombera de West Point. Yo le creo.", da = {"sin_noticias"}, edad_min = 18, edad_max = 85, lazo = "eduardo" },
    { id = "l09_des_taller_soldado", etapa = "despues", texto = "Desde julio vivo en el taller con los portones soldados. Como de lo que traigo de las casas vacias: abrir un auto o una casa es casi lo mismo.", da = {"vive_solo", "trueque"}, edad_min = 18, edad_max = 85 },
    { id = "l10_dsp_bomba_rosa", etapa = "despues", texto = "Dos veces por semana como en la bomba de Rosewood. La Misia Rosa no pregunta nada antes del plato: primero da de comer.", da = {"hambre"}, edad_min = 18, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l10_dsp_canal19", etapa = "despues", texto = "De noche hablo por el canal 19 y paso los nombres de quien busca a quien. A veces contesta el muchacho de la gasolinera de Rosewood.", da = {"vive_con_otros"}, edad_min = 18, edad_max = 85, lazo = "hector" },
    { id = "l10_dsp_casa_flotante", etapa = "despues", texto = "Vivo en el agua, anclad{o} lejos de la orilla. Pesco bagre, cazo lo que baja a tomar agua y hiervo el rio.", da = {"vive_con_otros"}, pide_alguno = {"rio"}, edad_min = 18, edad_max = 85 },
    { id = "l10_dsp_cerco", etapa = "despues", texto = "Conecte baterias de auto a un energizador de granja y puse un alambre alrededor de la casa. El zumbido no me deja dormir; a los muertos tampoco.", da = {"vive_con_otros", "familia_viva"}, edad_min = 18, edad_max = 85 },
    { id = "l10_dsp_cruces_cabo", etapa = "despues", texto = "Hago cruces y cajones para los muertos de Muldraugh, sin cobrar. El Cabo me anoto en su libreta y me deja latas en la escalera.", da = {"vive_solo", "trueque"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l10_dsp_escuela", etapa = "despues", texto = "Vivo en una escuela con ninos que nadie vino a buscar. Comemos el queso del gobierno y la mantequilla de mani de la despensa, mientras dure.", da = {"vive_con_otros"}, pide_alguno = {"cuida_ninos"}, edad_min = 18, edad_max = 85 },
    { id = "l10_dsp_patio", etapa = "despues", texto = "Vivo a unas cuadras del patio de trenes. De noche se oye a la Sargento pasar lista en voz alta; de dia, mejor no mirar para alla.", da = {"vive_solo"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "pereira" },
    { id = "l10_dsp_plato_cuartel", etapa = "despues", texto = "Los domingos alguien del cuartel de bomberos me trae un plato. La Chela no deja a nadie sin comer, aunque a ella nadie la ha visto sentada.", da = {"vive_solo"}, edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l10_dsp_radio_domingo", etapa = "despues", texto = "Los domingos en la noche prendo la radio de pilas. A veces se oye un muchacho con voz de bombero: Mama, si me oyes, estoy bien.", da = {"sin_noticias"}, edad_min = 18, edad_max = 85, lazo = "eduardo" },
    { id = "l10_dsp_tabaco_plata", etapa = "despues", texto = "El tabaco se volvio plata. Un atado de burley paga mas que un billete; con eso compro sal, cartuchos y que me dejen tranquil{o}.", da = {"trueque"}, pide_alguno = {"tabaco", "granja"}, edad_min = 18, edad_max = 85 },
    { id = "l01_sec_calendario", etapa = "secreto", texto = "Llevo la cuenta de los dias rayando la pared. En octubre me salte una semana a proposito para que los ninos creyeran que faltaba menos para la primavera.", diario = "El calendario de la pared va una semana adelantado. {el} lo adelanto para los ninos. No pienso corregirlo.", da = {"mentiroso", "cuida_ninos"}, edad_min = 18, edad_max = 85 },
    { id = "l01_sec_cicatriz", etapa = "secreto", texto = "La cicatriz que muestro como la mordida que sobrevivi es un corte de alambre. Desde que creen que no me pasa nada, me dan la mejor cama y el primer plato.", diario = "La mordida que sobrevivio es un corte de alambre. Todos le dan el primer plato. No se como decirles.", da = {"mentiroso"}, edad_min = 18, edad_max = 85 },
    { id = "l01_sec_diarios", etapa = "secreto", texto = "En las casas vacias busco los diarios de vida de los muertos. Los leo enteros y despues los uso para prender la estufa. Se mas de {pueblo} que sus familias.", diario = "{el} quema los diarios de los muertos despues de leerlos. Dice que asi por lo menos alguien los leyo.", da = {"solitario", "culpa"}, edad_min = 18, edad_max = 85 },
    { id = "l01_sec_papas", etapa = "secreto", texto = "Desde agosto saco de noche las papas del huerto de los vecinos. En la manana les ayudo a buscar al ladron y hasta pongo trampas.", diario = "Le ayude a buscar a quien robaba las papas del huerto. Era {el}, con barro hasta las rodillas.", da = {"mentiroso", "hambre"}, edad_min = 18, edad_max = 85 },
    { id = "l01_sec_puesto", etapa = "secreto", texto = "La primera noche estaba de guardia en la planta de agua del pueblo y me fui a mi casa. Dicen que por eso se quemo la bomba. Yo digo que llegue y ya estaba quemada.", diario = "Dejo su puesto en la planta de agua la primera noche. Dice que no habria cambiado nada. A lo mejor tiene razon.", da = {"cobarde", "culpa"}, edad_min = 18, edad_max = 85 },
    { id = "l01_sec_radio", etapa = "secreto", texto = "Tengo una radio a pilas que funciona y digo que se rompio. De noche oigo sol{o} lo que dice la Guardia, para que nadie se ilusione ni se desespere.", diario = "La radio rota funciona. {el} decide sol{o} que noticias merece oir el resto. Hasta ahora, ninguna.", da = {"mentiroso", "solitario"}, edad_min = 18, edad_max = 85 },
    { id = "l01_sec_rifa", etapa = "secreto", texto = "Los domingos hago una rifa de una lata para levantar el animo de la cuadra. Siempre gana alguien de mi familia. Nadie ha revisado nunca los papelitos.", diario = "La rifa de los domingos esta arreglada. {el} se rio cuando se lo dije y me ofrecio un numero ganador.", da = {"mentiroso", "bromista"}, edad_min = 18, edad_max = 85 },
    { id = "l02_sec_cartas", etapa = "secreto", texto = "En el 79 mande cartas sin firma al consejo de la iglesia contra el pastor nuevo. Se fue del pueblo con su familia. Era inocente y yo lo sabia.", diario = "Me confeso las cartas sin firma que echaron a un pastor inocente. Quiere saber si esta vivo para escribirle una firmada.", da = {"culpa", "rencoroso"}, edad_min = 35, edad_max = 85 },
    { id = "l02_sec_deuda", etapa = "secreto", texto = "El 9 de julio se me borro la deuda con el banco, el juicio y el hombre que me cobraba. A veces, cuando nadie mira, me alegro del fin del mundo.", diario = "Me dijo que el fin del mundo le saco una deuda de encima y que a veces se alegra. Lo dijo bajito, como quien pide perdon.", da = {"culpa"}, pide_alguno = {"deudas", "perdio_todo"}, edad_min = 18, edad_max = 85 },
    { id = "l02_sec_hijo_cunada", etapa = "secreto", texto = "El muchacho que me cuida es mi hijo. Lo tuve con la mujer de mi hermano y mi hermano lo crio sin saber. Ahora me da la sopa y me dice tio.", diario = "El hombre al que su sobrino le da la sopa me dijo que no es su sobrino: es su hijo. Me pidio que no se lo cuente al muchacho.", da = {"culpa"}, edad_min = 45, edad_max = 85, sexo = "h" },
    { id = "l02_sec_leer", etapa = "secreto", texto = "No se leer. Toda la vida fingi con los lentes en la mano y el diario abierto. Ahora me toca leer las etiquetas de las latas del refugio y adivino.", diario = "Me confeso que no sabe leer y que las latas del refugio las elegia por el dibujo. Le ensene la A con una etiqueta de porotos.", da = {"mentiroso", "sin_estudios"}, prohibe = {"universidad", "secundaria"}, edad_min = 18, edad_max = 85 },
    { id = "l02_sec_otra", etapa = "secreto", texto = "La manana del 10 deje a los mios en la casa y sali a buscar a otra persona, la que de verdad queria. No la encontre. Cuando volvi, la casa estaba vacia.", diario = "Me conto que el dia 10 salio a buscar a su amante y dejo a su familia en la casa. Volvio tarde. Lleva la llave de esa casa en el cuello.", da = {"culpa", "perdio_familia"}, edad_min = 25, edad_max = 85 },
    { id = "l02_sec_reformatorio", etapa = "secreto", texto = "A los quince robe la caja del almacen y culparon al hijo del vecino. Lo mandaron al reformatorio de La Grange. Yo me calle y fui a su despedida.", diario = "Me conto que dejo que otro muchacho pagara por su robo en La Grange. Todavia guarda una moneda de esa caja.", da = {"culpa", "mentiroso"}, edad_min = 25, edad_max = 85 },
    { id = "l02_sec_sordo", etapa = "secreto", texto = "No fui a Vietnam porque le pague a un medico para que me declarara sordo de un oido. Todavia finjo no oir bien del izquierdo, por costumbre y por miedo.", diario = "Me conto que se salvo de Vietnam con un papel comprado. Despues me hablo por el lado del oido 'sordo' y me oyo perfecto.", da = {"mentiroso", "cobarde"}, prohibe = {"militar", "veterano_vietnam"}, edad_min = 40, edad_max = 50, sexo = "h" },
    { id = "l03_sec_ahorros_botes", etapa = "secreto", texto = "Me jugue los ahorros de la familia en los casinos flotantes del Ohio. Dije que nos robaron en la casa. Nadie le creyo a la policia que no encontro la ventana rota.", diario = "Se jugo los ahorros de su familia en los botes del Ohio y culpo a un ladron que nunca existio. Me pidio que no lo cuente.", da = {"apostador", "mentiroso", "deudas"}, edad_min = 30, edad_max = 85 },
    { id = "l03_sec_carta_cordon", etapa = "secreto", texto = "En septiembre un soldado del cordon me paso una carta de mi {hijo}, que esta afuera. Le pague con una botella de whisky. A los demas les digo que no se nada de los mios.", diario = "Tiene una carta de su familia de afuera del cordon y la paga escondiendola. Dice a todos que no sabe nada de los suyos.", da = {"familia_viva", "mentiroso"}, pide = {"con_hijos"}, edad_min = 18, edad_max = 85 },
    { id = "l03_sec_certificado_leva", etapa = "secreto", texto = "Cuando llego la leva, mi padre le pago a un doctor un certificado de soplo en el corazon. Mi primo fue a Vietnam en mi lugar y volvio en un cajon.", diario = "Un certificado comprado lo salvo de Vietnam y mando a su primo. Desde entonces le pide perdon a una foto.", da = {"culpa", "mentiroso"}, prohibe = {"militar", "veterano_vietnam"}, edad_min = 40, edad_max = 55, sexo = "h" },
    { id = "l03_sec_chancho_sotano", etapa = "secreto", texto = "Tengo un chancho escondido en el sotano. Lo engordo con las sobras que la gente me da para los perros. Lo vamos a matar en Navidad, si nadie lo oye antes.", diario = "Engorda un chancho en el sotano con las sobras ajenas. Dice que es para Navidad. No se para quien.", da = {"comida_escondida"}, edad_min = 18, edad_max = 85 },
    { id = "l03_sec_finge_no_disparar", etapa = "secreto", texto = "Le dije a todos que no se disparar para que no me pusieran de guardia. Cazo desde {nino}. Cuando hay que defender la casa, me escondo detras de esa mentira.", diario = "Dice que no sabe disparar para no hacer guardia. Caza desde {nino}. Le pase la escopeta y le acerte a la primera.", da = {"cobarde", "mentiroso"}, prohibe = {"valiente"}, edad_min = 18, edad_max = 85 },
    { id = "l03_sec_firma_testamento", etapa = "secreto", texto = "Fui testigo del testamento de mi tia y firme sabiendo que ella ya no reconocia a nadie. La casa quedo para mi hermano. El me dio la mitad de lo que vendio.", diario = "Firmo de testigo un testamento de una tia que ya no sabia quien era. Se quedo con media casa. No se le olvida.", da = {"culpa", "acomodado"}, edad_min = 30, edad_max = 85 },
    { id = "l03_sec_hijo_otro_pueblo", etapa = "secreto", texto = "Tengo un hijo de otra mujer en Elizabethtown. Le mande plata cada mes desde que nacio y mi familia nunca supo. Ahora el cordon nos separa a todos por igual.", diario = "Tiene un hijo en Elizabethtown que su familia no conoce. Le pago la vida a escondidas. El cordon les cerro a los dos la misma puerta.", da = {"hijo_secreto", "culpa"}, edad_min = 40, edad_max = 85, sexo = "h" },
    { id = "l03_sec_no_se_leer", etapa = "secreto", texto = "Nunca aprendi a leer. Toda la vida dije que se me olvidaron los anteojos. Los papeles los firmo con la misma raya, y en el fin del mundo nadie me lo ha notado.", diario = "No sabe leer. Lo escondio toda la vida detras de unos anteojos olvidados. Le lei en voz alta lo que tenia que firmar.", da = {"analfabeto", "mentiroso"}, pide = {"sin_estudios"}, prohibe = {"universidad", "secundaria"}, edad_min = 18, edad_max = 85 },
    { id = "l04_sec_cartas_pastor", etapa = "secreto", texto = "Las cartas sin firma que le llegaban al pastor en los ochenta, contando quien no pagaba el diezmo, las escribia yo, con la mano izquierda. Nunca lo supo nadie.", diario = "Escribia cartas anonimas al pastor contando los pecados del pueblo. Con la mano izquierda, para que nadie le conociera la letra.", da = {"rencoroso", "religioso"}, edad_min = 30, edad_max = 85 },
    { id = "l04_sec_deuda_gordo", etapa = "secreto", texto = "Le debo cuarenta dolares al camionero gordo del canal 19 desde una partida de domino, y a todos les digo que el me los debe a mi. Como debe a medio Kentucky, me creen.", diario = "Le debe plata al camionero gordo del 19 y cuenta al reves que el se la debe. Como el Gordo le debe a todos, le creen.", da = {"mentiroso", "apostador"}, edad_min = 25, edad_max = 85, lazo = "earl" },
    { id = "l04_sec_falsa_sordera", etapa = "secreto", texto = "Desde agosto finjo que no oigo, para que no me toquen las guardias de noche. Oigo todo: los pasos, los chistes que hacen de mi, la noche entera. Lo que no oigo es mi nombre.", diario = "Finge que no oye para no hacer guardia de noche. Oye todo, incluso lo que dicen a sus espaldas.", da = {"cobarde", "mentiroso"}, prohibe = {"sordo"}, edad_min = 18, edad_max = 85 },
    { id = "l04_sec_no_leer", etapa = "secreto", texto = "No se leer. Llevo toda la vida fingiendo con los anteojos, pidiendo que me lean porque se me olvidaron en la casa. Los letreros los conozco por el color.", diario = "No sabe leer. Toda la vida fingio que se le quedaban los anteojos. Le prometi ensenarle las letras de su nombre.", da = {"sin_estudios", "mentiroso"}, prohibe = {"universidad"}, edad_min = 18, edad_max = 85 },
    { id = "l04_sec_radio_rota", etapa = "secreto", texto = "La radio del grupo no se quemo sola. La rompi yo, con un destornillador, porque las noticias de Louisville hacian llorar a mi gente toda la noche y nadie dormia.", diario = "Rompio la radio del grupo a proposito para que dejaran de oir las noticias de Louisville. Dice que fue por el sueno de todos.", da = {"culpa", "mentiroso"}, edad_min = 18, edad_max = 85 },
    { id = "l04_sec_reloj_casa", etapa = "secreto", texto = "El reloj de oro que digo que era de mi papa lo saque en agosto de una casa vacia de la loma. Mi papa nunca tuvo reloj. Yo nunca tuve a quien heredarle nada.", diario = "El reloj del abuelo no es del abuelo: lo saco de una casa vacia. Necesitaba que algo en su vida viniera de alguien.", da = {"mentiroso"}, edad_min = 18, edad_max = 85 },
    { id = "l04_sec_tia_censo", etapa = "secreto", texto = "En la libreta del Cabo sigo anotad{o} con una tia que se murio en agosto. Asi recibo dos raciones. La tia era buena; seguro no le importaria.", diario = "Sigue anotando en la libreta del Cabo a una tia muerta para cobrar su racion. Dice que la tia no se enojaria.", da = {"mentiroso", "hambre"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l05_sec_avisos", etapa = "secreto", texto = "Los papeles del correo que dicen que la Guardia va a abrir el cordon en primavera los escribo yo, con letra distinta cada vez. La gente los lee y aguanta un mes mas.", diario = "Los avisos de la primavera los escribe {el}. Tiene tres lapices y tres letras. Dice que la esperanza tambien es comida.", da = {"mentiroso"}, edad_min = 18, edad_max = 85 },
    { id = "l05_sec_carburador", etapa = "secreto", texto = "Le saque una pieza al carburador de la unica camioneta del grupo. Si arranca, se van sin mi. La pieza la llevo en el bolsillo, envuelta en un panuelo.", diario = "Me mostro la pieza del carburador que lleva en el bolsillo. La camioneta del grupo no arranca por eso. No se que hacer con lo que se.", da = {"vive_con_otros", "cobarde"}, edad_min = 18, edad_max = 85 },
    { id = "l05_sec_diploma", etapa = "secreto", texto = "El diploma que cuelga en mi pared tiene mi nombre pegado encima del de mi prima. Reprobe el examen dos veces y nadie me lo pidio nunca.", diario = "El diploma de la pared es de su prima. Lo supe por el pegamento. Igual me curo bien.", da = {"mentiroso"}, edad_min = 25, edad_max = 85 },
    { id = "l05_sec_doble_libreta", etapa = "secreto", texto = "En la libreta del cabo estoy anotad{o} dos veces: con mi nombre y con el de mi hermano, que murio en agosto. Me toca doble racion y nadie revisa.", diario = "Esta anotad{o} dos veces en la libreta del cabo. Una es un muerto. Le pregunte si pensaba decirlo. Me dijo que el muerto tambien come.", da = {"mentiroso", "hambre"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l05_sec_maleta", etapa = "secreto", texto = "A mi padre le digo que el bus de la evacuacion pasa el jueves. Todos los jueves le hago la maleta y todos los viernes se la deshago.", diario = "No hay bus de evacuacion. Su padre hace la maleta todos los jueves. Esta semana la ayude a deshacerla.", da = {"cuida_a_alguien", "mentiroso"}, edad_min = 25, edad_max = 65 },
    { id = "l05_sec_pension", etapa = "secreto", texto = "Cobre tres inviernos la pension de mi padre muerto, firmando con su nombre. La deuda con el gobierno se acabo junto con el gobierno.", diario = "Supe que cobraba la pension de su padre muerto. Se rio al contarlo. Despues no.", da = {"mentiroso"}, edad_min = 30, edad_max = 85 },
    { id = "l05_sec_tos", etapa = "secreto", texto = "Finjo la tos de las noches para que no me toquen guardias. Los demas creen que me estoy muriendo y me sirven la sopa mas espesa.", diario = "La tos de las noches es mentira. Lo supe porque dejo de toser cuando creyo que yo dormia.", da = {"cobarde", "mentiroso"}, prohibe = {"valiente"}, edad_min = 18, edad_max = 85 },
    { id = "l06_sec_bencina", etapa = "secreto", texto = "De noche le saco bencina al generador del vecino con una manguera. De dia lo ayudo a buscar la fuga. Ya le cambiamos dos empaquetaduras.", diario = "Le roba bencina de noche al generador del vecino y de dia lo ayuda a buscar la fuga. Dice que el vecino tiene mas que el.", da = {"mentiroso"}, edad_min = 18, edad_max = 85 },
    { id = "l06_sec_casa", etapa = "secreto", texto = "Esta casa no es mia. La encontre vacia en julio. Di vuelta las fotos de la pared y digo que era de mi tia. A veces les hablo a las fotos.", diario = "Vive en una casa ajena desde julio y dice que era de su tia. Las fotos de los duenos estan dadas vuelta en la pared.", da = {"mentiroso"}, edad_min = 18, edad_max = 85 },
    { id = "l06_sec_censo", etapa = "secreto", texto = "El Cabo me anoto en su censo con dos que vivian conmigo. Los dos murieron en agosto y no se lo he dicho: la comisaria me sigue dando latas para tres.", diario = "Cobra en la comisaria las raciones de dos muertos que el Cabo tiene anotados como vivos en su censo.", da = {"mentiroso", "hambre"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l06_sec_letrero", etapa = "secreto", texto = "Pinte MORDIDOS ADENTRO en mi puerta para que la banda no entre. Funciona. Lo malo es que los vecinos tambien me creen muert{o}, y no los he sacado del error.", diario = "Pinto MORDIDOS ADENTRO en su puerta para espantar a la banda. Sus vecinos lo dan por muerto y no los ha desmentido.", da = {"vive_solo", "solitario"}, edad_min = 18, edad_max = 85 },
    { id = "l06_sec_lunes", etapa = "secreto", texto = "Todos los lunes digo que salgo a buscar a mi gente a Louisville. Camino hasta el puente, me siento, cuento hasta mil y vuelvo. Hace meses que no busco.", diario = "Dice que sale a buscar a su familia cada lunes. Se sienta en el puente, cuenta hasta mil y vuelve. Ya no busca.", da = {"culpa"}, pide_alguno = {"sin_noticias", "perdio_familia"}, edad_min = 18, edad_max = 85 },
    { id = "l06_sec_paramedico", etapa = "secreto", texto = "Digo que fui paramedico en Louisville. Lo vi en la tele. Ya cosi a cuatro personas con hilo de pescar y ninguna se me ha muerto. Todavia.", diario = "Nunca fue paramedico. Cose heridas con hilo de pescar y la gente cree que sabe. Hasta ahora le ha salido bien.", da = {"mentiroso"}, edad_min = 18, edad_max = 85, oficios = {"mecanico", "granjero", "policia", "carpintero", "costurera", "cocinera", "camionero", "profesora", "cazador", "electricista", "pastora"} },
    { id = "l06_sec_perro", etapa = "secreto", texto = "Me robe el perro de los vecinos la noche que les oi decir que se lo iban a comer. Lo tengo en el sotano. Ellos creen que se lo llevo la banda.", diario = "Se robo el perro de los vecinos para que no se lo comieran. Lo esconde en el sotano y ellos culpan a la banda.", da = {"mentiroso"}, edad_min = 18, edad_max = 85 },
    { id = "l06_sec_reloj", etapa = "secreto", texto = "Cuando le toca guardia a mi muchacho, adelanto media hora el reloj de la cocina. Los demas hacen guardias mas largas y no lo saben.", diario = "Adelanta el reloj para que la guardia de su hijo sea mas corta. Los demas hacen la diferencia sin saberlo.", da = {"mentiroso"}, pide = {"con_hijos"}, edad_min = 36, edad_max = 85 },
    { id = "l07_sec_apuestas_fiebre", etapa = "secreto", texto = "Con otro viejo del campamento apostamos fichas a quien le baja la fiebre y a quien no. Llevamos la cuenta en una libreta de carreras. Ya gane cuatro veces.", diario = "Apostaba en secreto a la fiebre de los heridos. Rompio la libreta delante de mi. Dice que ya no le quedan ganas de ganar.", pide_alguno = {"apostador"}, edad_min = 40, edad_max = 85 },
    { id = "l07_sec_camioneta", etapa = "secreto", texto = "Tengo una camioneta con medio estanque tapada con fardos en un granero. No se la he dicho a nadie, por si un dia me tengo que ir sol{o}.", diario = "Tenia una camioneta escondida con medio estanque para irse sol{o}. Hoy la saco del granero y la puso al servicio de todos.", da = {"solitario", "mentiroso"}, edad_min = 18, edad_max = 85 },
    { id = "l07_sec_enamorado", etapa = "secreto", texto = "Estoy enamorad{o} de alguien del campamento que espera a su pareja de afuera. Le guardo la mejor parte de la olla y le arreglo cosas que no se han roto.", diario = "Le guardaba la mejor parte de la olla a alguien que espera a otro. Se lo dijo. No paso nada, pero ahora come en la misma mesa.", edad_min = 18, edad_max = 85 },
    { id = "l07_sec_llave_farmacia", etapa = "secreto", texto = "Tengo la llave de la farmacia del pueblo desde antes de todo, porque hacia el aseo. Saco remedios de a poco y digo que los encuentro en casas vacias.", diario = "Tenia la llave de la farmacia y sacaba remedios diciendo que los encontraba. Hoy entrego la llave. Adentro quedaba mas de lo que nadie creia.", da = {"mentiroso"}, edad_min = 18, edad_max = 85 },
    { id = "l07_sec_no_leo", etapa = "secreto", texto = "No se leer. Llevo toda la vida fingiendo con los anteojos en la punta de la nariz, y en el campamento me pasan las listas y yo digo que estan bien.", diario = "No sabe leer. Firmaba las listas sin entenderlas. Le lei la suya en voz alta y se rio de lo que le habian anotado.", da = {"mentiroso"}, prohibe = {"universidad", "secundaria"}, edad_min = 18, edad_max = 85 },
    { id = "l07_sec_perro_racion", etapa = "secreto", texto = "Desde agosto le doy a mi perro la mitad de mi racion y digo que la como yo. Por eso estoy flac{o}. Por eso el perro no.", diario = "Se estaba muriendo de hambre para darle la mitad a su perro. Le conseguimos comida para los dos.", da = {"hambre"}, edad_min = 18, edad_max = 85 },
    { id = "l07_sec_semilla", etapa = "secreto", texto = "Me como a escondidas la semilla de maiz que guardamos para la primavera: un punado cada noche. Ya va media bolsa. Nadie ha contado todavia.", diario = "Se estaba comiendo la semilla de maiz de la primavera. Lo confeso delante de todos y prometio reponerla con lo que cace.", da = {"hambre", "culpa"}, edad_min = 18, edad_max = 85 },
    { id = "l08_sec_esa_noche", etapa = "secreto", texto = "La noche del nueve yo no estaba en mi casa, estaba con alguien que no era mi pareja. Mi pareja salio a buscarme esa noche y no volvio. En el pueblo creen que yo lo estaba esperando.", diario = "La primera noche estaba con otra persona. Su pareja salio a buscarl{o} y no volvio. Todo el pueblo cree lo contrario.", da = {"culpa", "mentiroso", "sin_noticias"}, pide = {"casado"}, edad_min = 18, edad_max = 85 },
    { id = "l08_sec_escaner", etapa = "secreto", texto = "Tenia un escaner de la policia. El viernes a las nueve oi que la Guardia iba a cerrar los caminos al amanecer. Saque a los mios por el camino de tierra y no le avise a nadie mas de la cuadra.", diario = "Supo del cordon antes que nadie por un escaner y saco solo a los suyos. A la cuadra no le aviso. Ahora cuida a los que quedaron.", da = {"culpa", "familia_viva"}, edad_min = 18, edad_max = 85 },
    { id = "l08_sec_llave_despensa", etapa = "secreto", texto = "Tengo copia de la llave de la despensa del campamento. Cada domingo saco una lata para mi mama, que no quiso venir y vive sola en la casa vieja. Nadie la tiene en la cuenta.", diario = "Saca una lata por semana de la despensa comun para su madre, que vive sola y nadie sabe que existe. Fui con {el} a dejarsela.", da = {"cuida_a_alguien", "mentiroso"}, pide = {"vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l08_sec_palito_largo", etapa = "secreto", texto = "En el campamento sorteamos con palitos quien sale a buscar agua. Desde agosto corto el mio mas largo, a escondidas. Han salido otros por mi once veces.", diario = "Hace trampa en el sorteo del agua desde agosto. Otros salieron once veces en su lugar y uno no volvio.", da = {"cobarde", "culpa"}, pide = {"vive_con_otros"}, edad_min = 18, edad_max = 85 },
    { id = "l08_sec_papel_casa", etapa = "secreto", texto = "Cuando murio el vecino de al lado, escribi un papel con su firma donde me dejaba la casa y el pozo. Me quedo igualito. Nadie lo ha discutido porque ya no queda nadie de su familia.", diario = "El papel que dice que le dejaron la casa y el pozo lo escribio el mismo, con la firma del muerto. No hay nadie que lo reclame.", da = {"mentiroso"}, edad_min = 18, edad_max = 85 },
    { id = "l08_sec_perro_monte", etapa = "secreto", texto = "El perro no se escapo. En agosto lo lleve al monte y lo deje amarrado a un arbol con un plato de agua, porque no me alcanzaba para los dos. Los ninos todavia lo llaman de noche.", diario = "El perro que los ninos llaman cada noche no se escapo: lo amarro en el monte en agosto. Me pidio que no se lo dijera a ellos.", da = {"culpa"}, edad_min = 18, edad_max = 85 },
    { id = "l08_sec_tranca", etapa = "secreto", texto = "La noche que entraron los muertos al corral fui yo quien dejo la tranca abierta. Estaba cansad{o} y no volvi a revisar. Dije que la habian roto desde afuera.", diario = "La tranca de la noche de los muertos la dejo abierta {el}. Culpo a los de afuera. Desde entonces revisa todas las trancas tres veces.", da = {"culpa", "mentiroso"}, edad_min = 18, edad_max = 85 },
    { id = "l09_sec_bomba_pozo", etapa = "secreto", texto = "Rompi a proposito la bomba del pozo de mi calle para que la gente que llegaba se fuera a otra parte. Se fueron. Una familia con una guagua tambien.", diario = "Rompio la bomba del pozo de su calle para que los que llegaban se fueran. Se fue tambien una familia con una guagua.", da = {"culpa", "rencoroso"}, edad_min = 18, edad_max = 85 },
    { id = "l09_sec_dientes_oro", etapa = "secreto", texto = "Les saco los dientes de oro a los muertos de la cuneta y los cambio en Louisville por remedios. Digo que el oro era de mi abuela.", diario = "Les sacaba los dientes de oro a los muertos de la cuneta y decia que el oro era de su abuela.", da = {"mentiroso", "trueque"}, edad_min = 18, edad_max = 85 },
    { id = "l09_sec_falso_paramedico", etapa = "secreto", texto = "Digo que fui paramedico en Louisville. Nunca lo fui: aprendi mirando la tele y un manual de la biblioteca. Ya cosi a tres, y uno se me infecto.", diario = "Nunca fue paramedico. Aprendio de un manual y de la tele, y cose a la gente igual. Uno se le infecto.", da = {"mentiroso"}, prohibe = {"oficio_aprendido"}, edad_min = 18, edad_max = 85 },
    { id = "l09_sec_firma_cabo", etapa = "secreto", texto = "Copie la firma del Cabo en un vale de raciones: Mandados, R., Cabo. Hattie me dio el doble de porotos una semana. Al Cabo no le cuadro la libreta.", diario = "Falsifico la firma del Cabo en un vale de raciones. La libreta no le cuadro al Cabo y todavia no sabe por que.", da = {"mentiroso", "hambre"}, edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l09_sec_hermano_heroe", etapa = "secreto", texto = "Les digo a todos que mi hermano murio defendiendo la casa. No es verdad: se fue la primera noche en la camioneta con la comida de todos.", diario = "El hermano heroe que nombra en cada comida no murio defendiendo nada: se fue con la camioneta y la comida de todos.", da = {"mentiroso", "perdio_familia"}, edad_min = 18, edad_max = 85 },
    { id = "l09_sec_no_manejo", etapa = "secreto", texto = "Digo que no se manejar para que no me manden de chofer a Louisville. Se manejar desde los catorce. Otro fue en mi lugar.", diario = "Sabe manejar desde los catorce y dice que no, para que no lo manden a Louisville. Otro fue en su lugar.", da = {"cobarde", "mentiroso"}, prohibe = {"camionero_pasado"}, edad_min = 18, edad_max = 85 },
    { id = "l09_sec_sorteo", etapa = "secreto", texto = "Cuando sorteamos quien sale a buscar agua, hago trampa con los papelitos. Nunca me toca. Los demas salen, y uno no volvio.", diario = "Hacia trampa en el sorteo de las salidas para que nunca le tocara. Uno de los que salio en su lugar no volvio.", da = {"cobarde", "culpa"}, prohibe = {"valiente"}, edad_min = 18, edad_max = 85 },
    { id = "l09_sec_voto", etapa = "secreto", texto = "Cuando el refugio voto si dejabamos entrar a una familia de Louisville, vote que no. Perdieron por uno. Despues dije que yo habia votado que si.", diario = "Voto que no cuando el refugio decidio si entraba una familia. Perdieron por uno. Despues dijo que habia votado que si.", da = {"mentiroso", "culpa"}, edad_min = 18, edad_max = 85 },
    { id = "l10_sec_apellido_falso", etapa = "secreto", texto = "En la libreta del Cabo di otro apellido. Tengo una orden de arresto en Tennessee desde el 90, por cheques sin fondos. Si anota mi nombre verdadero, alguien lo va a leer.", diario = "Le dio un apellido falso al Cabo por una orden de arresto de Tennessee. Cree que el fin del mundo no cancela los cheques.", da = {"mentiroso", "buscado"}, edad_min = 24, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "cabo" },
    { id = "l10_sec_bicicleta", etapa = "secreto", texto = "En julio me robe la bicicleta de un vecino para ir a buscar a los mios. El salio a pie al otro dia, con una maleta. No lo volvi a ver. La bicicleta la tengo yo.", diario = "Se robo la bicicleta de un vecino que despues salio a pie con una maleta. No sabe si llego. La bicicleta sigue en su galpon.", da = {"culpa"}, edad_min = 18, edad_max = 70 },
    { id = "l10_sec_carta_hermano", etapa = "secreto", texto = "En el 68 escondi debajo del linoleo la carta de reclutamiento de mi hermano. Igual lo vinieron a buscar, como si hubiera desertado. Nunca le dije que la carta llego.", diario = "Escondio la carta de reclutamiento de su hermano en el 68 y dejo que lo trataran de desertor. El hermano nunca supo. Ya no se puede preguntar.", da = {"culpa"}, edad_min = 40, edad_max = 58 },
    { id = "l10_sec_cigarrillos", etapa = "secreto", texto = "Tengo una caja de cigarrillos enterrada detras de la iglesia de piedra. Digo que salgo a rezar y salgo a fumar sol{o}. Es lo unico que no reparto.", diario = "Dice que sale a rezar detras de la iglesia y sale a fumar de una caja enterrada. Me convido uno. No se lo conte al Padre.", da = {"fumador", "mentiroso"}, edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l10_sec_informante", etapa = "secreto", texto = "En los setenta le pasaba nombres al sheriff: quien destilaba, quien vendia sin licencia. Ninguno supo que era yo. Dos de ellos viven hoy en mi misma calle.", diario = "Fue soplon del sheriff en los setenta. Dos de los que delato son sus vecinos y le traen agua. No se lo piensa decir.", da = {"mentiroso", "culpa"}, edad_min = 42, edad_max = 85 },
    { id = "l10_sec_no_leer", etapa = "secreto", texto = "No se leer. En el cuaderno de la Misia Rosa firme con una cruz y dije que se me quedaron los anteojos. Toda la vida aprendi de oido.", diario = "No sabe leer. Firma con una cruz y culpa a los anteojos. Me pidio que le leyera una carta vieja. Se la lei dos veces.", da = {"analfabeto", "sin_estudios", "mentiroso"}, prohibe = {"universidad", "secundaria"}, edad_min = 18, edad_max = 85, pueblos = {"Rosewood"}, lazo = "rosa" },
    { id = "l10_sec_pension", etapa = "secreto", texto = "Por siete inviernos cobre los cheques de la pension de mi mama muerta. La enterre sin avisarle al gobierno. Con esa plata pague la casa donde hoy duermen otros.", diario = "Cobro siete inviernos la pension de su madre muerta. Con eso pago la casa que hoy le presta a otros. No sabe si es deuda o regalo.", da = {"mentiroso", "culpa"}, edad_min = 35, edad_max = 85 },
    { id = "l10_sec_valvula", etapa = "secreto", texto = "Le saque una valvula a la radio para que mi muchacho no oyera al de los domingos, el que dicen que salva gente. Queria irse con el. Le dije que la radio se murio sola.", diario = "Le rompio la radio a su hijo para que no se fuera detras de la leyenda de los domingos. El muchacho todavia trata de arreglarla.", da = {"mentiroso"}, pide_alguno = {"con_hijos"}, edad_min = 36, edad_max = 85, lazo = "eduardo" },
    { id = "l01_dese_baile", etapa = "deseo", texto = "Quiero bailar una vez mas con musica de verdad, con una banda y un piso de madera, no con una radio a pilas.", edad_min = 18, edad_max = 85 },
    { id = "l01_dese_campanas", etapa = "deseo", texto = "Quiero oir sonar las campanas de la iglesia de piedra de Riverside, que estan calladas desde que se rajo la viga en el 91.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l01_dese_carta", etapa = "deseo", texto = "Quiero una carta, una sola, de los que quedaron afuera del cordon. Aunque diga que estan bien y nada mas.", pide_alguno = {"sin_noticias", "hijos_lejos"}, edad_min = 18, edad_max = 85 },
    { id = "l01_dese_colorina", etapa = "deseo", texto = "Quiero subirme una vez a la Colorina, el camion de bomberos de West Point, ahora que por fin la maneja la Chela, y que no frene.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l01_dese_lilo", etapa = "deseo", texto = "Quiero llegar a la primavera para ver si florece el lilo del patio. Si florece, sigo un invierno mas.", edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l01_dese_tierra", etapa = "deseo", texto = "Quiero un pedazo de tierra que sea mio, aunque sea un potrero con una vaca que me mire feo.", prohibe = {"acomodado"}, edad_min = 18, edad_max = 85 },
    { id = "l02_deseo_afuera", etapa = "deseo", texto = "Quiero saber si mi gente de afuera del cordon esta viva. Nada mas. Con eso me basta para el resto.", pide_alguno = {"sin_noticias", "hijos_lejos"}, edad_min = 18, edad_max = 85 },
    { id = "l02_deseo_campanas", etapa = "deseo", texto = "Quiero oir otra vez las campanas de la iglesia de piedra de Riverside, que estan mudas desde que se rajo la viga.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho", peso = 5 },
    { id = "l02_deseo_devolver", etapa = "deseo", texto = "Quiero devolver algo que me prestaron hace mucho y nunca devolvi. Lo tengo envuelto en un trapo, por si el dueno aparece.", edad_min = 18, edad_max = 85 },
    { id = "l02_deseo_libreta", etapa = "deseo", texto = "Quiero que alguien diga mi nombre completo en voz alta y lo anote en una libreta que no se pierda, como dicen que hace el Cabo.", edad_min = 18, edad_max = 85, lazo = "cabo" },
    { id = "l02_deseo_mesa", etapa = "deseo", texto = "Quiero sentarme a comer con mi gente en una mesa larga, como en el cuartel de la Chela, donde dicen que hay plato para el que llegue.", edad_min = 18, edad_max = 85, lazo = "chela" },
    { id = "l02_deseo_pan", etapa = "deseo", texto = "Quiero comer pan de verdad otra vez, de masa madre, como el de la panaderia Hollis que amasaba la panadera de las tres y media.", edad_min = 18, edad_max = 85, lazo = "yvonne_bell" },
    { id = "l03_dse_campanas", etapa = "deseo", texto = "Quiero oir otra vez las campanas de la iglesia de piedra de Riverside. Desde que murio el sacristan nadie las toca.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l03_dse_colorina", etapa = "deseo", texto = "Quiero ver pasar la Colorina por la calle de West Point con la sirena prendida, aunque sea una vez, para saber que alguien manda todavia.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l03_dse_comer_sentado", etapa = "deseo", texto = "Quiero comer sentad{o} a una mesa, con mantel y sin escopeta al lado. Lo demas me da lo mismo.", edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l03_dse_cosecha", etapa = "deseo", texto = "Quiero sembrar en marzo y cosechar en agosto, como si el mundo siguiera. Con eso me conformo.", pide_alguno = {"rural", "granja", "tabaco"}, edad_min = 18, edad_max = 85 },
    { id = "l03_dse_familia_afuera", etapa = "deseo", texto = "Quiero que abran el cordon una sola manana, para ir a ver si mi gente sigue en la misma casa.", pide_alguno = {"sin_noticias", "hijos_lejos", "familia_viva"}, edad_min = 18, edad_max = 85, peso = 20 },
    { id = "l03_dse_lleno", etapa = "deseo", texto = "Quiero llegar a la gasolinera de Rosewood, que la Misia Rosa me pregunte lleno o normal, y poder decirle lleno.", edad_min = 18, edad_max = 85, lazo = "rosa" },
    { id = "l04_dese_aprender", etapa = "deseo", texto = "Quiero aprender algo nuevo antes de que se acabe todo: leer bien, tocar un instrumento, curar una herida sin temblar. Algo que no me haya ensenado nadie de los que se murieron.", edad_min = 18, edad_max = 85 },
    { id = "l04_dese_campanas", etapa = "deseo", texto = "Quiero oir otra vez las campanas de la iglesia de piedra de Riverside, que no suenan desde que se rajo la viga. Una vez, un domingo, y me puedo morir tranquil{o}.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l04_dese_cruzar_cordon", etapa = "deseo", texto = "Quiero cruzar el cordon y llegar donde mis hijos, al otro lado. No para quedarme. Para verlos comer y contarles que aqui tambien hubo gente buena.", pide_alguno = {"hijos_lejos", "sin_noticias"}, edad_min = 18, edad_max = 85 },
    { id = "l04_dese_enterrar", etapa = "deseo", texto = "Quiero enterrar a los mios como se debe, con nombre, cruz y alguien que cante. Los deje donde cayeron y eso no me deja dormir.", pide_alguno = {"perdio_familia", "mato_transformado"}, edad_min = 18, edad_max = 85 },
    { id = "l04_dese_volver_casa", etapa = "deseo", texto = "Quiero volver a mi casa, aunque este quemada, y sentarme en el porche una tarde entera sin mirar el camino. Solo una tarde.", edad_min = 18, edad_max = 85 },
    { id = "l05_dso_caballo", etapa = "deseo", texto = "Quiero un caballo, uno solo, para que alguien chico aprenda a montar como aprendi yo.", pide = {"caballos"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l05_dso_lleno", etapa = "deseo", texto = "Quiero sentarme una noche en la gasolinera de Rosewood, donde la luz no se apaga, y que alguien me pregunte lleno o normal.", edad_min = 18, edad_max = 85, lazo = "rosa" },
    { id = "l05_dso_primavera", etapa = "deseo", texto = "Quiero ver una primavera mas con los ojos buenos, y hacer con mis manos la ultima cosa que se hacer bien.", edad_min = 50, edad_max = 85 },
    { id = "l05_dso_ruta", etapa = "deseo", texto = "Quiero hacer una vez mas una ruta larga, de punta a punta, con la radio prendida y alguien que me hable al lado.", edad_min = 18, edad_max = 85 },
    { id = "l05_dso_volar", etapa = "deseo", texto = "Quiero volar una vez mas, bajito, sin veneno en el tanque, y aterrizar donde haya gente esperando.", pide = {"aviador"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l06_deseo_carta", etapa = "deseo", texto = "Quiero una carta, una sola, de los que quedaron del otro lado del cordon. Aunque diga que no me esperen.", pide_alguno = {"sin_noticias", "hijos_lejos"}, edad_min = 18, edad_max = 85 },
    { id = "l06_deseo_colorina", etapa = "deseo", texto = "Quiero oir otra vez la sirena de la Colorina pasando por West Point. Si suena, es que alguien todavia va a apagar algo.", edad_min = 18, edad_max = 85, pueblos = {"West Point"}, lazo = "chela" },
    { id = "l06_deseo_escenario", etapa = "deseo", texto = "Quiero cantar una vez mas en un escenario, aunque sea el del gimnasio de la escuela, aunque sea con esta voz que me quedo.", pide_alguno = {"musico"}, edad_min = 18, edad_max = 85 },
    { id = "l06_deseo_nombre", etapa = "deseo", texto = "Quiero que alguien me llame por mi nombre verdadero y que no pase nada.", pide_alguno = {"mentiroso", "forastero"}, edad_min = 18, edad_max = 85 },
    { id = "l06_deseo_nombres", etapa = "deseo", texto = "Quiero enterrar a los mios con nombre, uno por uno, cuando se ablande la tierra. Nada de pozos comunes.", pide_alguno = {"perdio_familia", "mato_transformado"}, edad_min = 18, edad_max = 85 },
    { id = "l06_deseo_rosa", etapa = "deseo", texto = "Quiero entrar a la gasolinera de Rosewood a las tres de la manana y que la Misia Rosa me pregunte lleno o normal, como antes de todo.", edad_min = 18, edad_max = 85, lazo = "rosa" },
    { id = "l07_dese_club", etapa = "deseo", texto = "Quiero que lo que queda de mi club llegue a la proxima fecha redonda, aunque seamos tres y tomemos agua de lluvia en tazas del taller.", pide_alguno = {"logia"}, edad_min = 18, edad_max = 85 },
    { id = "l07_dese_gordo_ruta", etapa = "deseo", texto = "Quiero oir otra vez al Gordo Ruta por el canal 19, contando un chiste malo. Si el sigue en la ruta, la ruta sigue.", edad_min = 18, edad_max = 85, lazo = "earl" },
    { id = "l07_dese_lucia", etapa = "deseo", texto = "Quiero ver una vez a la monjita de March Ridge que canta para los muertos. Dicen que canta para todos, y yo tengo a varios sin cancion.", edad_min = 18, edad_max = 85, lazo = "lucia" },
    { id = "l07_dese_recuperar", etapa = "deseo", texto = "Quiero recuperar algo de mi papa que vendi por necesidad. Se exactamente quien lo tiene y cuanto pide. Lo que no se es si queda alguien vivo para pagarle.", edad_min = 18, edad_max = 85 },
    { id = "l07_dese_restos", etapa = "deseo", texto = "Quiero llevar los restos de mi marido a su tierra antes de morirme. Mis hijos dicen que es una locura. Mis hijos no estan aqui.", pide_alguno = {"viudo"}, edad_min = 50, edad_max = 85, sexo = "m" },
    { id = "l07_dese_tocar", etapa = "deseo", texto = "Quiero tocar una vez un instrumento de verdad delante de gente, fuerte, sin esconderme detras de nada.", pide_alguno = {"musico"}, edad_min = 18, edad_max = 85 },
    { id = "l08_des_campanas", etapa = "deseo", texto = "Quiero oir sonar una vez las campanas de la iglesia de piedra. Dicen que la viga esta rajada desde el noventa y uno y que la cuerda sigue engrasada.", edad_min = 18, edad_max = 85, pueblos = {"Riverside"}, lazo = "nacho" },
    { id = "l08_des_dormir", etapa = "deseo", texto = "Quiero dormir una noche entera sin oir nada. Una sola. Despues de eso, lo que venga.", edad_min = 18, edad_max = 85 },
    { id = "l08_des_escuela", etapa = "deseo", texto = "Quiero que los ninos vuelvan a tener clases. Dicen que la hija del Cabo, la profesora de Louisville, les ensena en la comisaria. Ojala.", edad_min = 18, edad_max = 85, pueblos = {"Muldraugh"}, lazo = "valentina" },
    { id = "l08_des_heredero", etapa = "deseo", texto = "Quiero que alguien se quede con lo mio cuando me muera: las herramientas, la casa, el perro. Que no se pierda todo en el pasto.", edad_min = 18, edad_max = 85 },
    { id = "l08_des_llamada", etapa = "deseo", texto = "Quiero cruzar el cordon y llamar por telefono a alguien a quien le corte hace mucho. No se que le voy a decir. Algo.", edad_min = 18, edad_max = 85 },
    { id = "l09_dso_cantar_madre", etapa = "deseo", texto = "Quiero que la monjita de March Ridge, la que canta para los muertos, le cante a mi madre, que se murio sin nadie al lado.", da = {"perdio_familia"}, edad_min = 18, edad_max = 85, lazo = "lucia" },
    { id = "l09_dso_enterrar", etapa = "deseo", texto = "Quiero enterrar a los mios en el cementerio de {pueblo}, con nombre y fecha, y no en el patio de atras.", da = {"perdio_familia"}, edad_min = 18, edad_max = 85 },
    { id = "l09_dso_esperen", etapa = "deseo", texto = "Quiero que alguien me espere una frase entera sin terminarmela.", pide = {"tartamudo"}, edad_min = 18, edad_max = 85, peso = 5 },
    { id = "l09_dso_lleno", etapa = "deseo", texto = "Quiero que la Misia Rosa me pregunte lleno o normal un dia, y poder contestarle lleno, con un estanque de verdad.", edad_min = 18, edad_max = 85, lazo = "rosa" },
    { id = "l09_dso_mama", etapa = "deseo", texto = "Quiero que mi {hijo} me llame como me tiene que llamar, y no por mi nombre.", pide = {"con_hijos"}, edad_min = 18, edad_max = 85 },
    { id = "l09_dso_primavera", etapa = "deseo", texto = "Quiero llegar a la primavera con un animal vivo y volver a sembrar con los vecinos, todos juntos, como antes.", pide = {"granja"}, edad_min = 18, edad_max = 85 },
    { id = "l10_dse_chiste_19", etapa = "deseo", texto = "Quiero oir otra vez, de madrugada, al Gordo de la 31 contar un chiste malo por el canal 19. Uno de los peores. Con eso me conformo.", edad_min = 18, edad_max = 85, lazo = "earl" },
    { id = "l10_dse_cura", etapa = "deseo", texto = "Dicen que un doctor de la radio de Louisville tiene una cura. Quiero que sea verdad; y si no, que alguien me lo diga con pruebas.", edad_min = 18, edad_max = 85, lazo = "hartmann" },
    { id = "l10_dse_mesa", etapa = "deseo", texto = "Quiero llegar a la primavera con todos los mios enteros, y comer una vez sentad{o} sin contar los platos.", pide_alguno = {"familia_viva", "cuida_ninos", "cuida_a_alguien"}, edad_min = 18, edad_max = 85 },
    { id = "l10_dse_numero", etapa = "deseo", texto = "Quiero decir en voz alta un numero verdadero: los dias, los muertos, lo que debo. Uno solo, sin adornos.", pide_alguno = {"mentiroso", "culpa"}, edad_min = 18, edad_max = 85 },
    { id = "l10_dse_verdad_nietos", etapa = "deseo", texto = "Quiero que los ninos sepan la verdad de su madre contada por mi, antes de que se la cuente otro.", pide_alguno = {"con_hijos", "cuida_ninos"}, edad_min = 40, edad_max = 85 },
    { id = "l10_dse_volver", etapa = "deseo", texto = "Quiero volver a donde trabajaba antes, aunque ahora quede del otro lado del cordon y me lo cuenten las garzas.", edad_min = 25, edad_max = 85 },
    { id = "l01_voz_iglesia", etapa = "voz", llegada = "Paz, hermano. Pase y limpiese los pies, que aqui el piso es de Dios.", rescate = "Gloria a Dios. Yo esperando un milagro y era usted.", gracias = "Lo voy a nombrar en la oracion del domingo, aunque no le guste.", muerte = "Se fue rezando, o eso parecia. Le termine el salmo yo, en voz baja.", pide_alguno = {"religioso", "iglesia_trabajo"}, edad_min = 18, edad_max = 85 },
    { id = "l01_voz_joven", etapa = "voz", llegada = "Uf, me asusto. Pase, pero avise la proxima vez: aqui uno pega primero y pregunta despues.", rescate = "Llego justo. Yo ya me estaba haciendo el muerto, y no me sale tan bien.", gracias = "Eso es. Facil. Le debo una, y las anoto todas.", muerte = "Era tan joven que todavia se reia de todo. Me rio por los dos cuando me acuerdo.", edad_min = 18, edad_max = 35 },
    { id = "l01_voz_mina", etapa = "voz", llegada = "Pues fijese. Sientese, que hay frijoles. Yo hablo con pausas; no es por pensar, es el pulmon.", rescate = "Gracias, compadre. Yo no corro desde hace rato. Usted corrio por los dos.", gracias = "Mire usted. Esta noche duermo tranquilo, calculo yo.", muerte = "Se le apago la lampara, como dicen alla arriba. Le cerre los ojos con los dedos negros de carbon.", pide = {"minero"}, edad_min = 18, edad_max = 85 },
    { id = "l01_voz_seca", etapa = "voz", llegada = "Aja. Las manos donde las vea. Si viene por comida, hablamos. Si viene a ayudar, pase y cierre.", rescate = "Como sea. Me salvo el pellejo. Se lo debo, y yo pago lo que debo.", gracias = "Justo lo que hacia falta. Le guardo algo, todavia no se que.", muerte = "Murio sin dar las gracias, como vivio. Pero se le notaba en la cara que las daba.", prohibe = {"urbano"}, edad_min = 18, edad_max = 85 },
    { id = "l01_voz_vendedor", etapa = "voz", llegada = "Pase, sientese. Primero cuenteme de su familia, despues hablamos de lo que vino a buscar.", rescate = "Fijese usted. Esto no lo cubria ninguna poliza.", gracias = "Dios se lo pague, que yo ya no cobro ni pago.", muerte = "Se fue con la libreta al dia. La fecha se la anote yo, con su lapiz.", edad_min = 40, edad_max = 85 },
    { id = "l02_voz_chistoso", etapa = "voz", llegada = "Pasa, pasa, que en el fin del mundo no se cobra la entrada. Todavia.", rescate = "Uy, ese estuvo cerca. Te debo una, y yo pago: tarde, pero pago.", gracias = "Gracias, de verdad. Si tuviera una medalla te la daba. Tengo una lata.", muerte = "Murio contando un chiste. No alcanzo a decir el final.", da = {"bromista"}, edad_min = 18, edad_max = 85 },
    { id = "l02_voz_creyente", etapa = "voz", llegada = "Paz, hermano. Si viene con hambre, primero coma; despues hablamos.", rescate = "Dios proveyo, y esta vez tenia sus manos.", gracias = "Bendito sea. Que el Senor se lo pague, porque yo no tengo con que.", muerte = "Murio rezando bajito. Pidio que no le cerraran los ojos todavia.", pide_alguno = {"religioso", "iglesia_trabajo", "santidad", "bautista", "metodista", "catolico"}, edad_min = 18, edad_max = 85 },
    { id = "l02_voz_miedo", etapa = "voz", llegada = "No me haga dano, por favor. Yo no tengo nada... bueno, tengo un poco.", rescate = "Gracias, gracias. Perdone que tiemble. No paro de temblar.", gracias = "Esto es mucho. No se como devolverselo. Le juro que voy a pensar en algo.", muerte = "Murio con miedo, pero no sol{o}. Le tome la mano hasta el final.", da = {"timido"}, edad_min = 18, edad_max = 85 },
    { id = "l02_voz_radio", etapa = "voz", llegada = "Te copio, fuerte y claro. Pasa y no pises los cables.", rescate = "Diez-cuatro. Me sacaste del lio. Cambio y fuera del peligro.", gracias = "Recibido y confirmado. Gracias, de mi frecuencia a la tuya.", muerte = "Murio con el microfono en la mano. La radio quedo prendida, soplando ruido.", pide = {"radio_cb"}, edad_min = 18, edad_max = 85 },
    { id = "l02_voz_seco", etapa = "voz", llegada = "Diga lo que quiere y rapido, que se me enfria el agua.", rescate = "Bueno. Me salvo. No le voy a hacer un discurso.", gracias = "Gracias. Lo anoto. No se me olvida.", muerte = "Murio sin decir mucho, como vivio. Dejo todo ordenado en una caja.", edad_min = 18, edad_max = 85 },
    { id = "l03_voz_chistoso", etapa = "voz", llegada = "Epa! Si viene a robar, llego tarde: ya me robaron todo menos el humor.", rescate = "Uf. Casi me voy al otro mundo sin despedirme. Gracias, de verdad.", gracias = "Esto vale un abrazo y una lata. El abrazo es gratis.", muerte = "Murio contando un chiste que nadie alcanzo a terminar de oir.", edad_min = 18, edad_max = 85 },
    { id = "l03_voz_mandon", etapa = "voz", llegada = "Llego tarde. Lavese las manos y sientese, que hay trabajo.", rescate = "Ya, ya, estoy bien. Ahora deje de mirarme y siga caminando.", gracias = "Asi se hacen las cosas. Bien. Ahora la otra.", muerte = "Murio dando ordenes. Las vamos a seguir un tiempo, por costumbre.", edad_min = 18, edad_max = 85 },
    { id = "l03_voz_religioso", etapa = "voz", llegada = "Dios lo trajo. Pase, que en esta casa hay un plato aunque sea de sopa de nada.", rescate = "El Senor me mando un angel y le puso botas. Gracias, hijo.", gracias = "Que Dios se lo pague. Yo le pago con oraciones, que es lo que tengo.", muerte = "Murio rezando. Pidio que no lo lloraran mucho.", edad_min = 18, edad_max = 85 },
    { id = "l03_voz_seco", etapa = "voz", llegada = "Quieto ahi. Diga quien es y que quiere, en ese orden.", rescate = "Bien. No lo digo dos veces. Vamos.", gracias = "Cumplio. Aqui se paga lo que se debe.", muerte = "Murio sin quejarse. Asi vivio tambien.", edad_min = 18, edad_max = 85 },
    { id = "l03_voz_timido", etapa = "voz", llegada = "Ah... hola. Perdon. No esperaba a nadie. Pase, si quiere.", rescate = "Gracias. No... no se que decir. Gracias.", gracias = "Le guarde esto. No es mucho. Es lo que habia.", muerte = "Murio en silencio, como hacia todo. Nadie sabia su segundo nombre.", edad_min = 18, edad_max = 85 },
    { id = "l04_voz_bromista", etapa = "voz", llegada = "Pasa, pasa, que el fin del mundo esta mas entretenido acompanado. Traes algo para comer o solo la cara?", rescate = "Me salvaste. Ahora te debo una, y yo pago mis deudas... en chistes, que es lo unico que me queda.", gracias = "Esto vale oro. Bueno, no; el oro ya no vale nada. Esto vale una lata de porotos, que es mas.", muerte = "Murio contando un chiste que no alcanzo a terminar. Nadie sabe el final, y eso es lo que mas duele.", da = {"bromista"}, prohibe = {"timido"}, edad_min = 18, edad_max = 85 },
    { id = "l04_voz_creyente", etapa = "voz", llegada = "Dios te trajo, o te trajo el camino. Da lo mismo: pasa y sientate, que aqui hay sitio.", rescate = "Le rece a Dios toda la noche y Dios te mando a ti. No te rias, que asi trabaja El.", gracias = "Dios te lo pague, que yo no tengo con que. Pero te nombro en la oracion de la noche, eso si.", muerte = "Murio rezando bajito. Le cerramos los ojos y le dejamos las manos juntas, como las tenia.", da = {"religioso"}, prohibe = {"sin_fe"}, edad_min = 18, edad_max = 85 },
    { id = "l04_voz_seco", etapa = "voz", llegada = "Hable claro y rapido. Aqui no se gasta saliva ni luz.", rescate = "Mm. Estaba bien. Pero gracias igual.", gracias = "Sirve. No le voy a decir mas, que no se usa.", muerte = "Murio sin quejarse, como vivio. Dejo todo ordenado, por si acaso.", da = {"solitario"}, prohibe = {"bromista"}, edad_min = 18, edad_max = 85 },
    { id = "l04_voz_timido", etapa = "voz", llegada = "Perdon... no lo vi llegar. Pase, si quiere. No tengo mucho, pero lo que tengo se comparte.", rescate = "Gracias. Gracias. No se que decir. Perdon por el susto.", gracias = "Esto es justo lo que necesitaba. Perdon que no tenga como devolverselo.", muerte = "Murio sin hacer ruido, pidiendo perdon hasta el final. No tenia nada que perdonarse.", da = {"timido"}, prohibe = {"bromista", "lider"}, edad_min = 18, edad_max = 85 },
    { id = "l05_voz_caballeriza", etapa = "voz", llegada = "Al paso, al paso. No me asuste los animales. Asi. Ahora si, buenas tardes.", rescate = "Mire, eso estuvo cerca. Usted llego como caballo bueno: sin que lo llamaran.", gracias = "Con esto pasamos el invierno, los animales y yo. Usted no sabe lo que vale.", muerte = "Murio en el encargo. Su caballo volvio solo, con la montura puesta.", edad_min = 18, edad_max = 85 },
    { id = "l05_voz_profesor", etapa = "voz", llegada = "Veamos. Llego usted a la hora que llego; yo lo anoto. Pase y no toque nada.", rescate = "Un minuto mas y no lo cuento. Un minuto, que en un reloj es una verguenza.", gracias = "Bien. Muy bien. Le pondria un siete, y yo no pongo sietes.", muerte = "Murio a la hora exacta, como le habria gustado. Pare su reloj y se lo deje en el bolsillo.", edad_min = 50, edad_max = 85 },
    { id = "l05_voz_sargento", etapa = "voz", llegada = "Hable por la derecha, recluta, que la izquierda no oye. Que se le rompio?", rescate = "Copiado, recluta. Me saco de esa. Otra vez estaba donde no debia.", gracias = "Buen trabajo, recluta. Copiado. Un motor no pregunta y yo tampoco.", muerte = "Murio en el encargo, de pie. Le deje la caja de herramientas cerrada al lado.", edad_min = 40, edad_max = 85 },
    { id = "l05_voz_teatral", etapa = "voz", llegada = "Pasa, corazon, pasa. Sientate, que el fin del mundo no es excusa para quedarse de pie.", rescate = "Ay, cielo, que entrada. Llegaste justo antes del telon. Dame la mano.", gracias = "Esto no lo actua nadie, corazon. Gracias. De verdad, sin publico.", muerte = "Murio en el encargo. Sin telon y sin publico. Le deje los labios pintados.", edad_min = 18, edad_max = 85 },
    { id = "l06_voz_campeon", etapa = "voz", llegada = "Campeon! Pasa, pasa. Cuidado con el tablon suelto, que la rodilla mia ya lo conoce.", rescate = "En serio te digo, otra jugada asi y no la cuento. Te debo una.", gracias = "Te juro que esto vale un partido entero. Mide dos veces, corta una.", muerte = "Murio de pie, como en la cancha. Le pusimos su numero en la cruz.", edad_min = 18, edad_max = 85 },
    { id = "l06_voz_compadre", etapa = "voz", llegada = "Mira quien llego. Sientate, compadre, que la sopa esta caliente.", rescate = "Te debo una olla entera, compadre. Cuando quieras, pasa por la cocina.", gracias = "Sal! Mira, esto vale mas que la plata de antes.", muerte = "Se murio con el delantal puesto. Esa semana nadie supo hacer la sopa.", edad_min = 18, edad_max = 85 },
    { id = "l06_voz_corazon", etapa = "voz", llegada = "Pasa, corazon, pero habla bajito, que aqui duermen los ninos.", rescate = "Ay, corazon, te debo una cancion entera. Y con esta voz, eso es mucho.", gracias = "Con esto come mi cuadra una semana. Dios te lo pague, corazon.", muerte = "Se fue tarareando bajito, como siempre. Nadie supo terminarle la cancion.", edad_min = 18, edad_max = 85 },
    { id = "l06_voz_respeto", etapa = "voz", llegada = "Buenas tardes. Con todo respeto, digame primero su nombre. Despues el resto.", rescate = "Muy amable. Por un momento pense que iba a tener que escribir mi propia tarjeta.", gracias = "Con todo respeto, es lo mejor que me han traido en meses.", muerte = "Murio con las manos limpias. Le escribimos el nombre en una tarjeta, como {el} hacia.", edad_min = 18, edad_max = 85 },
    { id = "l06_voz_seca", etapa = "voz", llegada = "Quieto ahi. Diga algo. Fuerte. Bueno, pase.", rescate = "No se que decir. Gracias. Da igual... no, no da igual. Gracias.", gracias = "Esto sirve. No me pregunte de donde saque lo otro.", muerte = "Murio sin decir su nombre completo. Lo enterramos con el que nos dio.", edad_min = 18, edad_max = 85 },
    { id = "l07_voz_cocina", etapa = "voz", llegada = "Limpiese los pies y saque los codos de mi mesa. Ahora si: que necesita?", rescate = "Bien hecho. Manos rapidas y sin temblar: usted serviria para una cocina.", gracias = "Justo lo que faltaba. Hoy la sopa queda en su punto, y usted come primero.", muerte = "Murio con el delantal puesto. Dejo una nota al lado de la olla: le falta sal.", edad_min = 18, edad_max = 85 },
    { id = "l07_voz_hermano", etapa = "voz", llegada = "Escuche, hermano, hableme fuerte y de frente, que el oido ya no es lo que era.", rescate = "Me saco como quien saca un perno oxidado, hermano. Queda en el acta.", gracias = "Anotado con su nombre completo. Aqui eso todavia vale algo.", muerte = "Murio con la herramienta en la mano. Pidio que nadie diera discursos. Se los dimos igual.", edad_min = 18, edad_max = 85 },
    { id = "l07_voz_madera", etapa = "voz", llegada = "Buenas, compadre. Hable bajo y mire donde pisa: esa tabla la clave yo.", rescate = "No es la primera vez que me agarra el fuego. Es la primera vez que me sacan.", gracias = "Con esto hago una tranca y dos muletas. La madera rinde si uno la respeta.", muerte = "Murio mirando el humo desde su garita. Alguien dijo su nombre bien alto, por fin.", edad_min = 18, edad_max = 85 },
    { id = "l07_voz_potrillo", etapa = "voz", llegada = "Pasa, potrillo. Si sangras, a la silla de la cocina. Si tienes fiebre, a la del patio.", rescate = "Me sacaste por una cabeza. Foto final. Te debo dos dolares.", gracias = "Le aposte a que volvias, y gane. Con esto aguanto otra semana.", muerte = "Murio apostando a que el otro vivia. Y gano.", edad_min = 18, edad_max = 85 },
    { id = "l08_voz_bencina", etapa = "voz", llegada = "Pase, pase. Como dice la Misia Rosa: lleno o normal? Yo le doy lo que hay.", rescate = "Ay, Dios. Gracias. Sientese en el cajon y no se me mueva, que le miro eso.", gracias = "Dios se lo pague. Yo no tengo con que, pero le anoto en el cuaderno.", muerte = "Murio en el camino. Esa noche alguien dejo una luz prendida por el.", edad_min = 18, edad_max = 85, lazo = "rosa" },
    { id = "l08_voz_carino", etapa = "voz", llegada = "Vaya, cara nueva. Pase, carino, y cuenteme algo que no sepa todo el pueblo.", rescate = "Ay, carino, llego justo. Le debo una, y yo pago siempre. Tarde, pero pago.", gracias = "Eso es. Lo anoto con mi mejor letra, que es la de verdad.", muerte = "Murio en el camino con un chiste a medias. Lo termine yo, y me salio peor.", edad_min = 18, edad_max = 85 },
    { id = "l08_voz_formal", etapa = "voz", llegada = "Buenas tardes. Usted esta vivo y eso ya es una buena noticia. En que le puedo servir?", rescate = "Muy amable. No crea que fue suerte, pero tampoco fue merito mio.", gracias = "Se lo agradezco de verdad. Que Dios le pague lo que yo no alcanzo.", muerte = "Murio en el camino con la corbata puesta. Le dejamos el sombrero encima, como el queria.", edad_min = 18, edad_max = 85 },
    { id = "l08_voz_seco", etapa = "voz", llegada = "Quieto ahi. Diga a que viene y despues hablamos. Asi es la cosa.", rescate = "Ya. Gracias. No soy de decirlo dos veces, asi que guardeselo.", gracias = "Bien hecho. Lleve algo de comer, que aqui sobra mas que palabras.", muerte = "Murio en el camino sin quejarse, como vivio. Le cerre los ojos con el sombrero.", edad_min = 18, edad_max = 85 },
    { id = "l09_voz_cb", etapa = "voz", llegada = "Diez-cuatro, carino. Cuanto pesas y que traes? Ni una libra de mas en mi patio.", rescate = "Copiado. Te debo una, carino, y yo pago lo que debo.", gracias = "Esto pesa lo justo. Ni una libra de mas, ni una de menos.", muerte = "Murio con las manos en el volante. El motor siguio andando un rato.", pide = {"camionero_pasado"}, edad_min = 18, edad_max = 85 },
    { id = "l09_voz_reglamento", etapa = "voz", llegada = "Alto ahi, jovencito. Pies juntos. Asi. Ahora digame quien es y que quiere.", rescate = "Cinco, seis, siete, ocho... Gracias. No me ofrezca el brazo. Bueno, ofrezcamelo.", gracias = "Asi. Bien hecho. Usted tiene buenos pies.", muerte = "Murio derech{o}, contando en ocho. No alcanzo a llegar al ocho.", edad_min = 55, edad_max = 85 },
    { id = "l09_voz_sindicato", etapa = "voz", llegada = "Hable fuerte, companero, que este oido me lo dejo la fabrica. Que trae y quien lo manda?", rescate = "Por Dios. Gracias, companero. Ayudeme a pararme, que el pecho no me da.", gracias = "Trato cumplido. Eso decia el papel y esta vez el papel no miente.", muerte = "Murio discutiendo, con la libreta abierta.", pide_alguno = {"fabrica", "sindicato"}, edad_min = 50, edad_max = 85 },
    { id = "l09_voz_tartamudo", etapa = "voz", llegada = "P-pase. Despacito. No me apure la palabra, que la madera tampoco se apura.", rescate = "D-dos golpes es si. Gracias. Escrito se lo digo mejor.", gracias = "Esto vale. Se lo dejo anotado en la madera, que dura mas que yo.", muerte = "Murio silbando, con una tabla a medio tallar.", pide = {"tartamudo"}, edad_min = 18, edad_max = 85 },
    { id = "l09_voz_turno_noche", etapa = "voz", llegada = "Corazon, sientate. Te tomo el pulso mientras me cuentas. Comiste algo hoy?", rescate = "Gracias, mi amor. Para ser exacta, me salvaste la vida.", gracias = "Esto me alcanza para una semana, para ser exacta. Gracias.", muerte = "Murio cuidando a otro. Tenia el reloj de enfermera prendido al reves.", edad_min = 18, edad_max = 60, sexo = "m" },
    { id = "l10_voz_carino", etapa = "voz", llegada = "Ay, carino, sube despacito, que aqui se cuida la radio y se cuida la chiquilla.", rescate = "Me sacaste del barro, carino. El que para, para. Gracias por parar.", gracias = "Pilas para la radio. Vuelve la chismosa al aire. Cambio, carino.", muerte = "Murio con el microfono en la mano. Alguien tiene que decir cambio y fuera por ella.", edad_min = 18, edad_max = 85, sexo = "m" },
    { id = "l10_voz_laconico", etapa = "voz", llegada = "Alto. No toque el alambre. Ahora si. Pase.", rescate = "Gracias. Siguiente. Vamos a la casa.", gracias = "Sirve. Gracias. Eso es todo.", muerte = "Murio sin decir mucho. Nunca dijo mucho. Dejo todo ordenado.", pide_alguno = {"solitario", "militar", "timido"}, edad_min = 18, edad_max = 85 },
    { id = "l10_voz_mi_alma", etapa = "voz", llegada = "Por la puerta de atras, mi alma, que la de adelante es para las visitas.", rescate = "Gracias, mi alma. Una vieja de los cerros no se cae dos veces. Calculo yo.", gracias = "Con esto me aguanta el corazon hasta la Navidad. Y le coso lo que quiera.", muerte = "Se fue a los cerros, como decia. Que la entierren con su colcha.", edad_min = 55, edad_max = 85, sexo = "m" },
